#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define ADS1115_CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200  // +/- 4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0060   // 128 SPS
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Sensitivity of MLX91219 (40mV/A)
#define MLX91219_SENSITIVITY 0.040

// Zero-current offset of MLX91219 (mid-supply)
#define MLX91219_ZERO_CURRENT 2.5

int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115_register(int handle, int reg, int value)
{
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;        // LSB

    int result = i2cWriteI2CBlockData(handle, reg, buf + 1, 2); // Write MSB and LSB
    if (result != 2) {
        fprintf(stderr, "Error writing to ADS1115 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_ads1115_register(int handle, int reg)
{
    int result = i2cReadI2CBlockData(handle, reg, (char *)&reg, 1); // Read register address
    if (result != 1) {
        fprintf(stderr, "Error reading register address from ADS1115 register 0x%02X: %d\n", reg, result);
        return -1;
    }

    char buf[2];
    result = i2cReadI2CBlockData(handle, reg, buf, 2); // Read 2 bytes
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 register 0x%02X: %d\n", reg, result);
        return -1;
    }

    return (buf[0] << 8) | buf[1]; // Combine MSB and LSB
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Configure ADS1115
    int config = ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_MUX_SINGLE_0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE;

    while (1)
    {
        // Start a single conversion
        if (write_ads1115_register(i2c_handle, ADS1115_REG_CONFIG, config | ADS1115_CONFIG_OS_SINGLE) != 0) {
            fprintf(stderr, "Failed to start conversion\n");
            continue; // Retry
        }

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        gpioDelay(10000); // 10ms

        // Read the conversion result
        int raw_value = read_ads1115_register(i2c_handle, ADS1115_REG_CONVERT);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read conversion result\n");
            continue; // Retry
        }

        // Convert raw value to voltage
        float voltage = (float)raw_value * MLX91219_SENSITIVITY * MLX91219_ZERO_CURRENT;

        // Convert voltage to current
        float current = voltage / MLX91219_SENSITIVITY;

        // Print the current value
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500000); // 500ms
    }

    // Cleanup (never reached in this example due to the infinite loop, but included for completeness)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

