#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4       // GPIO4 (BCM)
#define SPI_CHANNEL 0             // SPI0 (CE0)
#define SPI_SPEED 1000000          // 1 MHz
#define ADC_CHANNEL 0            // MCP3008 Channel 0
#define TEMP_MIN 10.0             // Minimum temperature (10°C)
#define TEMP_MAX 40.0             // Maximum temperature (40°C)
#define ADC_MIN 0                 // ADC Minimum value
#define ADC_MAX 1023              // ADC Maximum value

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor();
int read_adc(int channel);
float approximate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlameDetected,Temperature\n");
    }

    return 0;
}

// Reads the flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Reads the ADC value from the specified channel
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Approximates the ambient temperature from the ADC value
float approximate_temperature(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -100.0; // Indicate an error
    }

    float temperature = TEMP_MIN + ((float)(adc_value - ADC_MIN) / (ADC_MAX - ADC_MIN)) * (TEMP_MAX - TEMP_MIN);
    return temperature;
}

// Logs the data to the CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s,%d,%.2f\n", timestamp, flame_detected, temperature);
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Flame sensor data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_adc(ADC_CHANNEL);

        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, skipping logging.\n");
        } else {
            float temperature = approximate_temperature(adc_value);
            if (temperature == -100.0) {
                fprintf(stderr, "Failed to approximate temperature, skipping logging.\n");
            } else {
                log_data(flame_detected, temperature);
            }
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

