void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("%s,%d,%.2f\n", timestamp, flame_detected, temperature);
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Flame sensor data logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_adc(ADC_CHANNEL);

        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value, skipping logging.\n");
        } else {
            float temperature = approximate_temperature(adc_value);
            if (temperature == -100.0) {
                fprintf(stderr, "Failed to approximate temperature, skipping logging.\n");
            } else {
                log_data(flame_detected, temperature);
            }
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

