#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27

// Define I2C parameters
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00

// Define temperature thresholds
#define TEMP_THRESHOLD_LOW 60.0
#define TEMP_THRESHOLD_HIGH 80.0

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1; // Flag to control the main loop
static volatile unsigned int last_flame_time = 0; // Last flame event time
static int i2c_handle; // I2C handle
static FILE *log_file; // Log file pointer

// Function prototypes
int init_gpio();
int init_i2c();
int read_temperature(float *temperature);
void flame_detected_isr(int gpio, int level, unsigned int tick, void *user_data);
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }

    // Configure ADS1115 for single-shot mode, channel AIN0, gain ±4.096V, 128 SPS
    char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0xC3; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config[2] = 0x83; // MSB of config register (start single conversion)

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Function to read temperature from ADS1115
int read_temperature(float *temperature) {
    char buf[2];
    int16_t adc_value;

    // Read conversion register
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return 1;
    }

    adc_value = (buf[0] << 8) | buf[1];

    // Convert ADC value to voltage (assuming gain ±4.096V)
    float voltage = (float)adc_value * 3.3 / 32768.0;

    // Convert voltage to temperature (linear mapping: 0V = 20°C, 3.3V = 80°C)
    *temperature = 20.0 + (voltage - 0.5) * (80.0 - 20.0) / (3.3 - 0.5);

    return 0;
}

// Interrupt service routine for flame sensor debouncing
void flame_detected_isr(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned int now = gpioTick();
    if (level == 0 && (now - last_flame_time) > DEBOUNCE_TIME * 1000) { // Falling edge and debounce time passed
        last_flame_time = now;
    }
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fire_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt for flame sensor debouncing
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_detected_isr, NULL);

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    float temperature;
    int flame_detected;

    while (running) {
        // Read flame sensor
        flame_detected = gpioRead(FLAME_SENSOR_PIN) == 0; // Assuming LOW indicates flame

        // Read temperature
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f°C\n", temperature);

            // Check for fire condition
            if (flame_detected && (temperature > TEMP_THRESHOLD_LOW && temperature <= TEMP_THRESHOLD_HIGH)) {
                log_event("Both flame and high temperature detected!");
                gpioWrite(BUZZER_PIN, 1); // Activate buzzer
                gpioDelay(2000);          // Buzz for 2 seconds
                gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
            } else if (flame_detected) {
                log_event("Flame detected!");
            } else if (temperature > TEMP_THRESHOLD_HIGH) {
                char message[64];
                snprintf(message, sizeof(message), "Temperature exceeded %.2f°C: %.2f°C", TEMP_THRESHOLD_HIGH, temperature);
                log_event(message);
            }
        } else {
            log_event("Error reading temperature");
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL); // Deregister ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

