#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V
#define SENSITIVITY 0.0001 // 100mV/RC = 0.1V/RC, where R is the sensor resistance
#define LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int raw_adc;
    float co_ppm;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_ads1115(int handle, uint16_t *adc_value);
float convert_adc_to_resistance(uint16_t adc_value);
float calculate_co_ppm(float resistance);
int log_co_ppm(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection to ADS1115
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int handle, uint16_t *adc_value) {
    char buf[2];
    int result;

    // Configure ADS1115 for single-ended channel 0, 16-bit resolution, single conversion
    buf[0] = CONFIG_REG;
    buf[1] = 0x83; // 0b10000011 (Single-ended AIN0, 16-bit, Single conversion)
    result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 16-bit)
    gpioDelay(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    *adc_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert ADC value to sensor resistance
float convert_adc_to_resistance(uint16_t adc_value) {
    float voltage = (float)adc_value / 32768.0 * REF_VOLTAGE;
    return (voltage - 0.5) / SENSITIVITY;
}

// Calculate CO concentration in PPM using a logarithmic curve
float calculate_co_ppm(float resistance) {
    // Example logarithmic curve (replace with your sensor's calibration data)
    // This is a placeholder and needs to be calibrated with the sensor's datasheet.
    float ppm = 100 * pow(resistance, -1.5); // Example: PPM = 100 * R^-1.5
    return ppm;
}

// Log CO concentration to file
int log_co_ppm(float co_ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f PPM\n", timestamp, co_ppm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("CO sensor logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t adc_value;
        float resistance;
        float co_ppm;

        // Read ADC value
        if (read_ads1115(i2c_handle, &adc_value) == 0) {
            // Convert ADC value to resistance
            resistance = convert_adc_to_resistance(adc_value);

            // Calculate CO concentration
            co_ppm = calculate_co_ppm(resistance);

            // Log CO concentration
            log_co_ppm(co_ppm);

            printf("CO Concentration: %.2f PPM\n", co_ppm);
        } else {
            fprintf(stderr, "Failed to read CO sensor data\n");
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

