#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x49
#define CO_REG 0x00 // Example register address for CO
#define NO2_REG 0x02 // Example register address for NO2
#define CO_SCALE 0.1 // Example scaling factor for CO (PPM/ADC unit)
#define NO2_SCALE 0.1 // Example scaling factor for NO2 (PPM/ADC unit)

// Global variables for I2C handle and program state
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor_data(uint16_t *co_adc, uint16_t *no2_adc);
float calculate_co_ppm(uint16_t co_adc);
float calculate_no2_ppm(uint16_t no2_adc);
int log_data(float co_ppm, float no2_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data from the MICS-4514
int read_sensor_data(uint16_t *co_adc, uint16_t *no2_adc) {
    char buf[4];
    int result;

    // Read CO data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine bytes to form 16-bit ADC values
    *co_adc = (buf[0] << 8) | buf[1];
    *no2_adc = (buf[2] << 8) | buf[3];

    return 0;
}

// Function to calculate CO level in PPM
float calculate_co_ppm(uint16_t co_adc) {
    return co_adc * CO_SCALE;
}

// Function to calculate NO2 level in PPM
float calculate_no2_ppm(uint16_t no2_adc) {
    return no2_adc * NO2_SCALE;
}

// Function to log data to a file
int log_data(float co_ppm, float no2_ppm) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen("co_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening co_log.txt for writing\n");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f PPM, NO2: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            co_ppm, no2_ppm);

    fclose(fp);
    return 0;
}

// Function to log alerts to a file
int log_alert(float co_ppm) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen("alert_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert_log.txt for writing\n");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO level exceeded threshold (25 PPM)! CO: %.2f PPM\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            co_ppm);

    fclose(fp);
    return 0;
}

int main() {
    uint16_t co_adc, no2_adc;
    float co_ppm, no2_ppm;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&co_adc, &no2_adc) == 0) {
            // Calculate PPM values
            co_ppm = calculate_co_ppm(co_adc);
            no2_ppm = calculate_no2_ppm(no2_adc);

            // Log data
            if (log_data(co_ppm, no2_ppm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Check for alert condition
            if (co_ppm > 25.0) {
                log_alert(co_ppm);
            }

            printf("CO: %.2f PPM, NO2: %.2f PPM\n", co_ppm, no2_ppm);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

