#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Define I2C addresses for the microphones
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49

// Define the I2C bus
#define I2C_BUS 1

// Define the reference pressure for the microphones
#define REFERENCE_PRESSURE 20.0e-6 // 20 microPascals

// Define the sensitivity of the microphones (dBV/Pa)
#define SENSITIVITY -38.0

// Define the sampling rate (Hz)
#define SAMPLING_RATE 100

// Define the log file name
#define LOG_FILE "audio_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t raw_data;
    double db;
} MicrophoneData;

// Function prototypes
int initialize_i2c();
int read_microphone_data(int i2c_handle, int16_t *raw_data);
double convert_to_db(int16_t raw_data);
double calculate_average_db(double db1, double db2);
int log_data(double average_db);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for microphone 1: %d\n", i2c_handle1);
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for microphone 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        return -1;
    }

    return 0;
}

// Function to read data from a microphone
int read_microphone_data(int i2c_handle, int16_t *raw_data) {
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    *raw_data = (int16_t)((buffer[1] << 8) | buffer[0]);

    return 0;
}

// Function to convert raw data to dB
double convert_to_db(int16_t raw_data) {
    double voltage = (double)raw_data / 32768.0 * 3.3; // Assuming 3.3V reference
    double pressure = pow(10, (double)SENSITIVITY / 20.0) * voltage / REFERENCE_PRESSURE;
    double db = 20 * log10(pressure / REFERENCE_PRESSURE);
    return db;
}

// Function to calculate the average dB
double calculate_average_db(double db1, double db2) {
    if (db1 == -999.0 && db2 == -999.0) {
        return -999.0; // Return error value if both are errors
    }
    if (db1 == -999.0) {
        return db2; // Return the non-error value
    }
    if (db2 == -999.0) {
        return db1; // Return the non-error value
    }
    return (db1 + db2) / 2.0;
}

// Function to log the data to a file
int log_data(double average_db) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, average_db);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Acoustic Leak Detection System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_data1, raw_data2;
        double db1, db2, average_db;

        // Read data from microphones
        if (read_microphone_data(i2c_handle1, &raw_data1) != 0) {
            db1 = -999.0; // Error value
        } else {
            db1 = convert_to_db(raw_data1);
        }

        if (read_microphone_data(i2c_handle2, &raw_data2) != 0) {
            db2 = -999.0; // Error value
        } else {
            db2 = convert_to_db(raw_data2);
        }

        // Calculate average dB
        average_db = calculate_average_db(db1, db2);

        // Log the data
        if (log_data(average_db) != 0) {
            fprintf(stderr, "Error logging data!\n");
        }

        // Wait for the next sample
        gpioDelay(1000000 / SAMPLING_RATE); // microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

