#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define THRESHOLD 0.7
#define SAMPLE_RATE 10000 // 10 kHz
#define SAMPLE_WINDOW 100 // 100 ms
#define NUM_SAMPLES 2

// Global variables
int spi_handle_0, spi_handle_1;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int channel0_samples[NUM_SAMPLES];
    int channel1_samples[NUM_SAMPLES];
    double rms_channel0;
    double rms_channel1;
} MicrophoneData;

MicrophoneData mic_data;

// Function prototypes
int read_mcp3008(int spi_handle, int channel);
double calculate_rms(int *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
