#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_LED 17
#define OVERCURRENT_THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer current_buffer;

// Function prototypes
int init_i2c();
int16_t read_adc();
float convert_to_current(int16_t adc_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        cb->buffer[i] = 0.0;
    }
}

// Add value to circular buffer
void add_to_buffer(float current) {
    current_buffer.buffer[current_buffer.head] = current;
    current_buffer.head = (current_buffer.head + 1) % BUFFER_SIZE;
    if (current_buffer.count < BUFFER_SIZE) {
        current_buffer.count++;
    }
}

// Calculate average of circular buffer
float calculate_average() {
    if (current_buffer.count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < current_buffer.count; i++) {
        sum += current_buffer.buffer[i];
    }
    return sum / current_buffer.count;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, 128 SPS
    uint16_t config = 0x4083; // 0b0100000010000011
    uint8_t write_buffer[3];
    write_buffer[0] = ADS1115_REG_CONFIG;
    write_buffer[1] = (config >> 8) & 0xFF; // MSB
    write_buffer[2] = config & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, (char *)write_buffer, 3) != 0) {
        fprintf(stderr, "Error writing to I2C config register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read ADC value
int16_t read_adc() {
    uint8_t read_buffer[2];
    read_buffer[0] = ADS1115_REG_CONVERT;

    if (i2cWriteDevice(i2c_handle, (char *)read_buffer, 1) != 0) {
        fprintf(stderr, "Error writing to I2C convert register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)read_buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C convert register\n");
        return -1;
    }

    int16_t adc_value = (read_buffer[0] << 8) | read_buffer[1];
    return adc_value;
}

// Convert ADC value to current (Amps)
float convert_to_current(int16_t adc_value) {
    // Assuming 4.096V reference, 16-bit ADC
    float voltage = (float)adc_value * 4.096 / 32768.0;
    float current = voltage / 0.0045; // 0.0045V/A per A
    return current;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert ADC value to current
        float current = convert_to_current(adc_value);

        // Add to circular buffer
        add_to_buffer(current);

        // Calculate average current
        float average_current = calculate_average();

        // Control LED
        control_led(average_current);

        // Print current and average current (for debugging)
        printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

        // Delay for sample rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

