#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // Chip Select pin (GPIO8)

// Define moisture sensor calibration values
#define DRY_VALUE 700      // ADC value for dry soil (example)
#define WET_VALUE 300      // ADC value for wet soil (example)

// Define moisture scale
#define MOISTURE_SCALE 100

// Define log file name
#define LOG_FILE "moisture_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void log_data(float moisture1, float moisture2);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Ensure CS is initially high

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }
    fflush(log_file);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01;                           // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;                           // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    spiWrite(spi_handle, (char *)spi_data, 3);
    spiRead(spi_handle, (char *)spi_data, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    float moisture = 100.0 - ((float)(adc_value - WET_VALUE) / (float)(DRY_VALUE - WET_VALUE)) * 100.0;

    // Clamp the moisture value to the range 0-100
    if (moisture < 0.0) {
        moisture = 0.0;
    }
    if (moisture > 100.0) {
        moisture = 100.0;
    }

    return moisture;
}

// Function to log data to CSV file
void log_data(float moisture1, float moisture2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Moisture sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value1 = read_mcp3008(0);
        int adc_value2 = read_mcp3008(1);

        if (adc_value1 == -1 || adc_value2 == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds.\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        float moisture1 = calculate_moisture(adc_value1);
        float moisture2 = calculate_moisture(adc_value2);

        log_data(moisture1, moisture2);

        gpioDelay(5000000); // Sample every 5 seconds
    }

    cleanup();
    return 0;
}

