#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define PRESSURE_SCALE_FACTOR 500.0
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    double pressure_scale;
} sensor_config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_pressure(int handle, uint16_t *pressure);
double convert_to_kPa(uint16_t raw_pressure);
int log_data(FILE *fp, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read pressure data from the sensor
int read_pressure(int handle, uint16_t *pressure) {
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            *pressure = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", i + 1, result);
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }
    return -1; // Failure after multiple retries
}

// Convert raw pressure value to kPa
double convert_to_kPa(uint16_t raw_pressure) {
    return (raw_pressure / 65535.0) * PRESSURE_SCALE_FACTOR;
}

// Log data to CSV file
int log_data(FILE *fp, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, MLX90817_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t raw_pressure;
    double pressure_kPa;

    while (!terminate) {
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            if (log_data(log_file, pressure_kPa) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure after multiple retries\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

