#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0
#define MOTOR_SHUTDOWN_GPIO 27
#define OVERCURRENT_THRESHOLD 10.0 // Amps
#define VCC 3.3 // Supply voltage
#define SENSOR_SENSITIVITY 0.066 // V/A

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int spi_flags;
    float vcc;
    float sensitivity;
} config_t;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vcc);
float voltage_to_current(float voltage, float sensitivity);
void log_current(float current);
void overcurrent_handler();
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(MOTOR_SHUTDOWN_GPIO, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_GPIO, 0); // Ensure it starts LOW

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vcc) {
    return (adc_value / 1023.0) * vcc;
}

// Function to convert voltage to current
float voltage_to_current(float voltage, float sensitivity) {
    return voltage / sensitivity;
}

// Function to log current reading with timestamp
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle overcurrent condition
void overcurrent_handler() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, OVERCURRENT\n", timestamp);
    fflush(log_file);

    gpioWrite(MOTOR_SHUTDOWN_GPIO, 1); // Assert GPIO HIGH
    fprintf(stderr, "OVERCURRENT detected! Motor shutdown initiated.\n");
    terminate = 1; // Set terminate flag
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(MOTOR_SHUTDOWN_GPIO, 0); // Reset GPIO to LOW
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float voltage = adc_to_voltage(adc_value, VCC);
        float current = voltage_to_current(voltage, SENSOR_SENSITIVITY);

        log_current(current);

        if (current > OVERCURRENT_THRESHOLD) {
            overcurrent_handler();
        }

        gpioDelay(100); // Sample every 100ms
    }

    cleanup();
    return 0;
}

