#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096 // +/- 4.096V
#define SENSOR_OFFSET 0.5 // 0.5V
#define SENSOR_SENSITIVITY 0.1 // 0.1 V/kPa
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_RATE_HZ 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double ref_voltage;
    double sensor_offset;
    double sensor_sensitivity;
    double pressure_min;
    double pressure_max;
    char *log_file_name;
    int sample_rate_hz;
} Config;

// Function prototypes
int init_i2c(int bus, int addr);
int16_t read_adc(int handle);
double adc_to_voltage(int16_t adc_value, double ref_voltage);
double voltage_to_pressure(double voltage, double offset, double sensitivity);
int log_pressure(double pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read ADC value from ADS1115
int16_t read_adc(int handle) {
    char buf[2];
    int16_t adc_value;

    // Set configuration register for single-ended AIN0, 16-bit, single conversion
    buf[0] = CONFIG_REG;
    buf[1] = 0x40 | 0x80; // Start single conversion, AIN0, 16-bit, disable comparator
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 16-bit)
    gpioDelay(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for read\n");
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    adc_value = (buf[0] << 8) | buf[1];
    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int16_t adc_value, double ref_voltage) {
    return ((double)adc_value / 32768.0) * ref_voltage;
}

// Convert voltage to pressure
double voltage_to_pressure(double voltage, double offset, double sensitivity) {
    return (voltage - offset) / sensitivity;
}

// Log pressure data to file
int log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    Config config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .ref_voltage = REF_VOLTAGE,
        .sensor_offset = SENSOR_OFFSET,
        .sensor_sensitivity = SENSOR_SENSITIVITY,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .log_file_name = LOG_FILE,
        .sample_rate_hz = SAMPLE_RATE_HZ
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.ads1115_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_name);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t adc_value = read_adc(i2c_handle);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        double voltage = adc_to_voltage(adc_value, config.ref_voltage);
        double pressure = voltage_to_pressure(voltage, config.sensor_offset, config.sensor_sensitivity);

        if (pressure >= config.pressure_min && pressure <= config.pressure_max) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure data.\n");
            }
        } else {
            fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        }

        gpioDelay(1000000 / config.sample_rate_hz); // Delay to achieve desired sample rate
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exited cleanly.\n");
    return 0;
}

