// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3208_CHANNEL_HUMIDITY 0
#define MCP3208_CHANNEL_THERMISTOR 1
#define HIH4602_VOUT_AT_RH_0 0.824
#define HIH4602_SLOPE 0.0315
#define HIH4602_VSUPPLY 5.0
#define BETA 3950.0
#define R0 10000.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void log_data(float humidity, float temperature);
void send_email_alert(float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read data from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate relative humidity from ADC value
float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * HIH4602_VSUPPLY;
    float humidity = (voltage - HIH4602_VOUT_AT_RH_0) / HIH4602_SLOPE;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / 4095.0 * HIH4602_VSUPPLY;
    float temperature = (BETA / R0) * (1.0 - pow(voltage / HIH4602_VSUPPLY, -1.0 / 3.95));
    return temperature;
}

