    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity exceeds 80%%! Humidity: %.2f%%\" | ssmtp recipient@example.com", humidity);
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send email alert (ssmtp returned %d)\n", result);
    }
}

