    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("humidity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity and Temperature Monitoring Started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(MCP3208_CHANNEL_HUMIDITY);
        int thermistor_adc = read_mcp3208(MCP3208_CHANNEL_THERMISTOR);

        if (humidity_adc == -1 || thermistor_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(thermistor_adc);

        // Log data
        log_data(humidity, temperature);

        // Check for humidity alert
        if (humidity > 80.0) {
            send_email_alert(humidity);
        }

        // Print data to console
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        // Wait for 5 seconds
        gpioDelay(5000); // 5000 milliseconds = 5 seconds
    }

    // Clean up
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

