#define MCP3208_CHANNEL 0
#define VREF 3.3
#define TMP36_MIN_VOLTAGE 0.5
#define TMP36_MAX_VOLTAGE 4.95
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_celsius(float voltage);
void log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 4095.0) * VREF;
}

// Function to convert voltage to Celsius
float voltage_to_celsius(float voltage) {
    if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP36_MAX_VOLTAGE) {
        fprintf(stderr, "Error: Voltage out of range (%f V)\n", voltage);
        return -1000.0; // Indicate an error
    }
    return (voltage - 0.5) / 0.01;
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    if (fprintf(log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
    }
    fflush(log_file); // Ensure data is written to disk
}

