#define SPI_MODE 0
#define CS_PIN 8
#define VREF 3.3
#define ADXL335_SENSITIVITY 0.300 // 300mV/g
#define ADXL335_ZERO_G_VOLTAGE 1.65 // Volts
#define IMPACT_THRESHOLD 2.0 // g

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_g(int adc_value);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC reading
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value %d (channel %d)\n", adc_value, channel);
        return -1;
    }

    return adc_value;
}

// Function to convert ADC value to g-force
float adc_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float g = (voltage - ADXL335_ZERO_G_VOLTAGE) / ADXL335_SENSITIVITY;
    return g;
}

