void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    if (x * x + y * y + z * z > IMPACT_THRESHOLD * IMPACT_THRESHOLD) {
        fprintf(log_file, "IMPACT DETECTED\n");
        fflush(log_file);
    }
}

