        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float x_g = adc_to_g(x_adc);
        float y_g = adc_to_g(y_adc);
        float z_g = adc_to_g(z_adc);

        log_data(x_g, y_g, z_g);

        gpioDelay(10); // 100 Hz sampling rate
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Data logging stopped.\n");
    return 0;
}

