#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x49

// Define register addresses
#define SI1172_REG_COMMAND 0xC0
#define SI1172_REG_FIFO_DATA_0 0xC1
#define SI1172_REG_FIFO_DATA_1 0xC2
#define SI1172_REG_FIFO_DATA_2 0xC3
#define SI1172_REG_FIFO_DATA_3 0xC4

// Define command to trigger a measurement (example, adjust as needed)
#define SI1172_COMMAND_MEASURE 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t ir_adc;
    uint16_t red_adc;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    printf("I2C device initialized successfully.\n");
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[8]; // Buffer to hold the data
    int result;

    // Trigger a measurement
    result = i2cWriteByteData(i2c_handle, SI1172_REG_COMMAND, SI1172_COMMAND_MEASURE);
    if (result < 0) {
        fprintf(stderr, "Error writing to command register: %d\n", result);
        data->error_flag = 1; // Transient I2C error
        return -1;
    }

    // Read data from FIFO registers
    result = i2cReadI2CBlockData(i2c_handle, SI1172_REG_FIFO_DATA_0, buf, 8);
    if (result < 0) {
        fprintf(stderr, "Error reading from FIFO registers: %d\n", result);
        data->error_flag = 1; // Transient I2C error
        return -1;
    }

    // Extract IR and RED ADC values (adjust byte order if needed)
    data->ir_adc = (buf[1] << 8) | buf[0];
    data->red_adc = (buf[3] << 8) | buf[2];

    // Basic data validation
    if (data->ir_adc > 65535 || data->red_adc > 65535) {
        fprintf(stderr, "Error: Invalid sensor data (out of range).\n");
        data->error_flag = 1; // Invalid sensor data
        return -1;
    }

    data->error_flag = 0; // No error
    return 0;
}

// Function to log the data to a file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%d\n", timestamp, data.ir_adc, data.red_adc, data.error_flag);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IR_ADCMV,RED_ADCMV,ErrorFlag\n");
        fflush(log_file);
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            // Log error if read fails
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s,ERROR,ERROR,%d\n", timestamp, sensor_data.error_flag);
            fflush(log_file);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

