#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define ICP10125_ADDR 0x67

// Define the measurement command
#define MEASURE_CMD 0x6845

// Define the number of bytes to read
#define BYTES_TO_READ 6

// Define the log file name
#define LOG_FILE "environmental_data.csv"

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_ioctl(int fd, unsigned int cmd);
int i2c_write(int fd, const uint8_t *buf, int len);
int i2c_read(int fd, uint8_t *buf, int len);
int i2c_close(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, uint8_t *data);
sensor_data_t convert_data(uint8_t *raw_data);
int log_data(sensor_data_t data);
void display_data(sensor_data_t data);
void signal_handler(int sig);

// Function to open the I2C device
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to perform I2C ioctl
int i2c_ioctl(int fd, unsigned int cmd) {
    if (ioctl(fd, cmd) < 0) {
        perror("Error performing I2C ioctl");
        return -1;
    }
    return 0;
}

// Function to write data to the I2C device
int i2c_write(int fd, const uint8_t *buf, int len) {
    ssize_t bytes_written = write(fd, buf, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C device
int i2c_read(int fd, uint8_t *buf, int len) {
    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to close the I2C device
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int fd) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    if (i2c_write(fd, cmd, 2) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    if (i2c_read(fd, data, BYTES_TO_READ) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and pressure
sensor_data_t convert_data(uint8_t *raw_data) {
    sensor_data_t data;
    // Extract raw ADC values
    int32_t raw_pressure = (raw_data[0] << 16) | (raw_data[1] << 8) | raw_data[2];
    int32_t raw_temperature = (raw_data[3] << 16) | (raw_data[4] << 8) | raw_data[5];

    // Apply calibration formulas (from ICP-10125 datasheet)
    // These are simplified examples.  Refer to the datasheet for the complete formulas.
    data.temperature = (float)raw_temperature / 100.0; // Example conversion
    data.pressure = (float)raw_pressure / 10.0;       // Example conversion

    return data;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to display data on the console
void display_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", data.temperature, data.pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = i2c_open(I2C_BUS, ICP10125_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Wait for conversion to complete (adjust delay as needed)
        usleep(10000); // 10ms

        // Read sensor data
        uint8_t raw_data[BYTES_TO_READ];
        if (read_sensor_data(i2c_fd, raw_data) < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Convert data
        sensor_data_t data = convert_data(raw_data);

        // Log data
        if (log_data(data) < 0) {
            fprintf(stderr, "Failed to log data. \n");
        }

        // Display data
        display_data(data);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up resources
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

