#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define GPIO pins for SPI communication
#define CS_PIN 8

// Define ADC channel for each microphone
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define gain control parameter
float gain = 1.0;

// Global variable for SPI handle
int spi_handle;

// Function prototypes
int read_adc(int channel);
float process_audio_data(int mic1_value, int mic2_value);
void output_data(float noise_cancelled_audio);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1; // Indicate error
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to process audio data (noise cancellation)
float process_audio_data(int mic1_value, int mic2_value) {
    return (float)(mic1_value - mic2_value) * gain;
}

// Function to output data to the terminal
void output_data(float noise_cancelled_audio) {
    printf("%f\n", noise_cancelled_audio);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Error: Invalid gain value. Using default gain of 1.0\n");
            gain = 1.0;
        }
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC values from both microphones
        int mic1_value = read_adc(MIC1_CHANNEL);
        int mic2_value = read_adc(MIC2_CHANNEL);

        if (mic1_value == -1 || mic2_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Process audio data
        float noise_cancelled_audio = process_audio_data(mic1_value, mic2_value);

        // Output data
        output_data(noise_cancelled_audio);

        // Delay for a short period
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

