#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define NUM_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_temperature();
float voltage_conversion(int raw_adc, float temperature);
int detect_flame(float compensated_voltage);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int count, adc_value;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    for (count = 0; count < NUM_RETRIES; count++) {
        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 0) {
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
                log_data(-1, 0.0, 0.0, -1.0, -1); // Log error
                gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
                return -1; // Indicate failure
            }
        } else {
            fprintf(stderr, "Error: SPI transfer failed (attempt %d). Retrying...\n", count + 1);
            log_data(-1, 0.0, 0.0, -1.0, -1); // Log error
            gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: SPI transfer failed after multiple retries.\n");
    log_data(-1, 0.0, 0.0, -1.0, -1); // Log error
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    return -1; // Indicate failure
}

// Function to read ambient temperature from file
float read_temperature() {
    FILE *fp;
    char temp_str[10];
    float temperature = 25.0; // Default temperature

    fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open ambient temperature file.\n");
        return temperature;
    }

    if (fgets(temp_str, sizeof(temp_str), fp) != NULL) {
        temperature = atof(temp_str);
    } else {
        fprintf(stderr, "Error: Could not read ambient temperature from file.\n");
    }

    fclose(fp);
    return temperature;
}

// Function to convert raw ADC value to voltage
float voltage_conversion(int raw_adc, float temperature) {
    return (raw_adc * 3.3) / 1024.0 + (temperature - 25.0) * 0.001;
}

// Function to detect flame based on compensated voltage
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > 1.0) ? 1 : 0;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.1f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int raw_adc;
    float voltage, compensated_voltage, temperature;
    int flame_detected;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        raw_adc = read_mcp3008(0); // Channel 0
        if (raw_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Read ambient temperature
        temperature = read_temperature();

        // Convert raw ADC to voltage
        voltage = voltage_conversion(raw_adc, temperature);

        // Compensate voltage
        compensated_voltage = voltage + (temperature - 25.0) * 0.001;

        // Detect flame
        flame_detected = detect_flame(compensated_voltage);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        // Wait 500ms
        gpioDelay(500);
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

