#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define WATER_LEVEL_FILE "water_levels.json"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_to_json(float percentage);
void control_led(float percentage);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        pigpio_error(result);
        return -1; // Indicate error
    }

    // Parse ADC value
    adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to JSON file
void log_to_json(float percentage) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char json_string[100];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    // Create JSON object
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, percentage);

    // Open file in append mode
    fp = fopen(WATER_LEVEL_FILE, "a");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    // Write JSON object to file
    fprintf(fp, "%s", json_string);
    fflush(fp);

    // Close file
    fclose(fp);
}

// Function to control LED based on water level
void control_led(float percentage) {
    static int led_state = 0; // 0 = off, 1 = on

    if (percentage > 75.0 && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
    } else if (percentage < 70.0 && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
    }
}

int main() {
    int adc_value;
