int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int adc_value;

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        pigpio_error(result);
        return -1; // Indicate error
    }

    // Parse ADC value
    adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];

    return adc_value;
}

