#define ADC_CHANNEL 0
#define VREF 3.3
#define MAX_FLOW 20.0 // LPM
#define ADC_MAX 1023.0
#define LOG_FILE "airflow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_flow(float voltage, float vref, float max_flow, int adc_max);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Reads data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Converts ADC reading to voltage
float adc_to_voltage(int adc_value, float vref) {
    return (adc_value / ADC_MAX) * vref;
}

// Converts voltage to flow rate
float voltage_to_flow(float voltage, float vref, float max_flow, int adc_max) {
    return (voltage / vref) * max_flow;
}

// Gets the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Logs data to the CSV file
int log_data(const char *timestamp, float flow_rate) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,FlowRate(LPM)\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to flow rate
        float flow_rate = voltage_to_flow(voltage, VREF, MAX_FLOW, ADC_MAX);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(timestamp, flow_rate) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        free(timestamp); // Free the allocated memory

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Airflow monitoring stopped.\n");
    return 0;
}

