#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw;
    int max_raw;
    int moisture_threshold;
    int logging_frequency;
    char recipient_email[100];
    char msmtp_config_file[100];
} Config;

// Global variables
int spi_handle;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int read_mcp3008(int spi_handle, int channel);
float calibrate_moisture(int raw_value, int min_raw, int max_raw);
int log_data(const char *filename, float moisture_percent);
int send_email_alert(const char *recipient_email, float moisture_percent);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_channel") == 0) {
            config->spi_channel = atoi(value);
        } else if (strcmp(key, "adc_channel") == 0) {
            config->adc_channel = atoi(value);
        } else if (strcmp(key, "min_raw") == 0) {
            config->min_raw = atoi(value);
        } else if (strcmp(key, "max_raw") == 0) {
            config->max_raw = atoi(value);
        } else if (strcmp(key, "moisture_threshold") == 0) {
            config->moisture_threshold = atoi(value);
        } else if (strcmp(key, "logging_frequency") == 0) {
            config->logging_frequency = atoi(value);
        } else if (strcmp(key, "recipient_email") == 0) {
            strncpy(config->recipient_email, value, sizeof(config->recipient_email) - 1);
            config->recipient_email[sizeof(config->recipient_email) - 1] = '\0';
        } else if (strcmp(key, "msmtp_config_file") == 0) {
            strncpy(config->msmtp_config_file, value, sizeof(config->msmtp_config_file) - 1);
            config->msmtp_config_file[sizeof(config->msmtp_config_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate moisture percentage
float calibrate_moisture(int raw_value, int min_raw, int max_raw) {
    float moisture_percent = 100.0 - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw) * 100.0);
    if (moisture_percent < 0.0) moisture_percent = 0.0;
    if (moisture_percent > 100.0) moisture_percent = 100.0;
    return moisture_percent;
}

// Function to log data to file
int log_data(const char *filename, float moisture_percent) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percent);
    fclose(fp);
    return 0;
}

// Function to send email alert using msmtp
int send_email_alert(const char *recipient_email, float moisture_percent) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Soil moisture is below threshold (%.2f%%). Please water the plant.\" | msmtp -f %s %s", moisture_percent, config.msmtp_config_file, recipient_email);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        perror("Error sending email");
        return -1;
    }

    int status = pclose(fp);
    if (status != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", status);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Default configuration values
    config.spi_channel = 0;
    config.adc_channel = 0;
    config.min_raw = 300;
    config.max_raw = 700;
    config.moisture_threshold = 30;
    config.logging_frequency = 60;
    strcpy(config.recipient_email, "recipient@example.com");
    strcpy(config.msmtp_config_file, "~/.msmtprc");

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:f:r:x:y:")) != -1) {
        switch (opt) {
            case 'c':
                config.spi_channel = atoi(optarg);
                break;
            case 'a':
                config.adc_channel = atoi(optarg);
                break;
            case 'm':
                config.min_raw = atoi(optarg);
                break;
            case 'M':
                config.max_raw = atoi(optarg);
                break;
            case 't':
                config.moisture_threshold = atoi(optarg);
                break;
            case 'f':
                config.logging_frequency = atoi(optarg);
                break;
            case 'r':
                strncpy(config.recipient_email, optarg, sizeof(config.recipient_email) - 1);
                config.recipient_email[sizeof(config.recipient_email) - 1] = '\0';
                break;
            case 'x':
                strncpy(config.msmtp_config_file, optarg, sizeof(config.msmtp_config_file) - 1);
                config.msmtp_config_file[sizeof(config.msmtp_config_file) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw] [-M max_raw] [-t moisture_threshold] [-f logging_frequency] [-r recipient_email] [-x msmtp_config_file]\n", argv[0]);
                return 1;
        }
    }

    // Read configuration from file
    if (read_config("plant_monitor.conf", &config) != 0) {
        fprintf(stderr, "Failed to read config file. Using default values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, 500000, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read raw ADC value
        int raw_value = read_mcp3008(spi_handle, config.adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", config.logging_frequency);
            sleep(config.logging_frequency);
            continue;
        }

        // Calibrate moisture percentage
        float moisture_percent = calibrate_moisture(raw_value, config.min_raw, config.max_raw);

        // Log data
        if (log_data("plant_data.txt", moisture_percent) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Check moisture threshold and send email alert
        if (moisture_percent < config.moisture_threshold) {
            printf("Moisture level below threshold (%.2f%% < %d%%). Sending email alert.\n", moisture_percent, config.moisture_threshold);
            if (send_email_alert(config.recipient_email, moisture_percent) != 0) {
                fprintf(stderr, "Failed to send email alert.\n");
            }
        }

        // Wait before next reading
        sleep(config.logging_frequency);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Plant monitor stopped.\n");
    return 0;
}

