    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Sampling every %d seconds. Press Ctrl+C to exit.\n", sample_interval);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Warning: Failed to read ADC value. Continuing...\n");
            fprintf(log_file, "Warning: Failed to read ADC value. Continuing...\n");
        } else {
            // Calculate moisture percentage
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage == -1.0) {
                fprintf(stderr, "Warning: Invalid moisture percentage. Continuing...\n");
                fprintf(log_file, "Warning: Invalid moisture percentage. Continuing...\n");
            } else {
                // Log data
                log_data(adc_value, moisture_percentage);
                printf("ADC Value: %d, Moisture: %.2f%%\n", adc_value, moisture_percentage);
            }
        }

        // Wait for the specified interval
        gpioDelay(sample_interval * 1000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

