#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define SPI device and GPIO pins
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4 // Example GPIO pin for chip select (CS)

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define calibration values
#define DRY_ADC_VALUE 700
#define WET_ADC_VALUE 300

// Define SPI mode and speed
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int spi_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Signal handler function
void signal_handler(int sig)
{
    printf("Caught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the GPIO line
int gpio_init(const char *chipname, int pin, struct gpiod_line **line)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line = gpiod_chip_get_line(chip, pin);
    if (!*line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "soil_moisture_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(*line, &config, 0) != 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to initialize the SPI device
int spi_init(const char *device, int mode, int speed)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int spi_fd, int channel)
{
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message for single-ended conversion
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended, channel select
    tx_buf[2] = 0x00;                  // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate the moisture percentage
float calculate_moisture_percentage(int adc_value, int dry_value, int wet_value)
{
    float percentage = 100.0 - ((float)(adc_value - wet_value) / (float)(dry_value - wet_value) * 100.0);

    // Clamp the percentage between 0 and 100
    if (percentage < 0.0) {
        percentage = 0.0;
    } else if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN, &gpio_line) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    printf("Soil Moisture Sensor Program\n");

    // Main loop
    while (!terminate) {
        // Set GPIO line low to activate the chip select
        if (gpiod_line_set_value(gpio_line, 0) != 0) {
            perror("Error setting GPIO line low");
            break;
        }

        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value, DRY_ADC_VALUE, WET_ADC_VALUE);

        // Get current time
        time_t rawtime;
