#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MLX90823 connected to MCP3008 channel 0
#define VREF 3.3 // Reference voltage of MCP3008
#define PRESSURE_MIN 10.0 // Minimum pressure in kPa
#define PRESSURE_MAX 150.0 // Maximum pressure in kPa
#define VOLTAGE_MIN 0.5 // Minimum voltage
#define VOLTAGE_MAX 4.5 // Maximum voltage

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float vref;
    float pressure_min;
    float pressure_max;
    float voltage_min;
    float voltage_max;
} config_t;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_pressure(float voltage, float pressure_min, float pressure_max, float voltage_min, float voltage_max);
void log_pressure(float pressure);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Open SPI channel
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage, float pressure_min, float pressure_max, float voltage_min, float voltage_max) {
    if (voltage < voltage_min || voltage > voltage_max) {
        fprintf(stderr, "Error: Voltage out of range (%f V)\n", voltage);
        return -1.0; // Indicate error
    }

    return pressure_min + (voltage - voltage_min) * (pressure_max - pressure_min) / (voltage_max - voltage_min);
}

// Function to log pressure reading with timestamp
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Function to cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and SPI
    if (initialize()) {
        return 1;
    }

    config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_baud = SPI_BAUD,
        .mcp3008_channel = MCP3008_CHANNEL,
        .vref = VREF,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .voltage_min = VOLTAGE_MIN,
        .voltage_max = VOLTAGE_MAX
    };

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        float voltage = adc_to_voltage(adc_value, config.vref);
        float pressure = voltage_to_pressure(voltage, config.pressure_min, config.pressure_max, config.voltage_min, config.voltage_max);

        if (pressure >= 0) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Failed to convert voltage to pressure\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

