#define GPIO_PIN 8 // CE0

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *fp = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

// Function prototypes
int spi_init(void);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
float read_mcp3008_channel(int fd, int channel);
