// Structure to hold sensor data
typedef struct {
    float channel0;
    float channel1;
    float channel2;
    float channel3;
} sensor_data_t;


int main(void) {
    sensor_data_t sensor_values;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("environmental_data.csv", "a");
    if (fp == NULL) {
        perror("Failed to open environmental_data.csv");
        gpio_cleanup();
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read sensor values
        sensor_values.channel0 = read_mcp3008_channel(spi_fd, 0);
        sensor_values.channel1 = read_mcp3008_channel(spi_fd, 1);
        sensor_values.channel2 = read_mcp3008_channel(spi_fd, 2);
        sensor_values.channel3 = read_mcp3008_channel(spi_fd, 3);

        // Log data to CSV file
        if (log_data(fp, sensor_values.channel0, sensor_values.channel1, sensor_values.channel2, sensor_values.channel3) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up and exiting...\n");
    fclose(fp);
    close(spi_fd);
    gpio_cleanup();

    return 0;
}

// Initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return 0;
}

// Read from MCP3008 channel
float read_mcp3008_channel(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed for channel %d\n", channel);
        return -1.0;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Convert ADC value to voltage
    return ((float)adc_value / 1023.0) * VREF;
}

// Log data to CSV file
int log_data(FILE *fp, float channel0, float channel1, float channel2, float channel3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, channel0, channel1, channel2, channel3) < 0) {
        perror("Failed to write to CSV file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    printf("Signal received (%d).  Shutting down...\n", sig);
    keep_running = 0;
}

// Initialize GPIO
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "spi_cs", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup
void gpio_cleanup(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

