// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, MAX30102_MODECONFIG, 0x40) < 0) {
        fprintf(stderr, "Error: Failed to reset MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure SpO2 mode
    if (i2cWriteByteData(i2c_handle, MAX30102_MODECONFIG, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to configure SpO2 mode\n");
        return -1;
    }

    // Configure SPO2_CONFIG
    if (i2cWriteByteData(i2c_handle, MAX30102_SPO2CONFIG, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to configure SPO2_CONFIG\n");
        return -1;
    }

    // Configure LED pulse amplitudes
    if (i2cWriteByteData(i2c_handle, MAX30102_LED1PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to configure LED1_PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MAX30102_LED2PA, 0x24) < 0) {
        fprintf(stderr, "Error: Failed to configure LED2_PA\n");
        return -1;
    }

    return 0;
}

// Read FIFO data from the MAX30102
int read_fifo_data(uint32_t *red, uint32_t *ir) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, MAX30102_FIFODATA, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read FIFO data\n");
        return -1;
    }

    *red = (uint32_t)buffer[0] | ((uint32_t)buffer[1] << 8) | ((uint32_t)buffer[2] << 16);
    *ir = (uint32_t)buffer[3] | ((uint32_t)buffer[4] << 8) | ((uint32_t)buffer[5] << 16);

    return 0;
}

