    int part_id = i2cReadByteData(i2c_handle, MAX30102_PARTID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Could not read Part ID\n");
        fprintf(log_file, "Error: Could not read Part ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    if (part_id != 0x15) {
        fprintf(stderr, "Error: Incorrect Part ID: 0x%02X\n", part_id);
        fprintf(log_file, "Error: Incorrect Part ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

