        fprintf(log_file, "Error: MAX30102 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint32_t red_data, ir_data;
    float spo2;
    int heart_rate;

    // Main loop
    while (!terminate) {
        // Read FIFO data
        if (read_fifo_data(&red_data, &ir_data) == 0) {
            // Calculate SpO2 and heart rate
            spo2 = calculate_spo2(red_data, ir_data);
            calculate_heart_rate(&ir_data, 6, &heart_rate);

            // Log data
            log_data(spo2, heart_rate);

            // Check for alarm conditions
            if (spo2 < 95.0 || heart_rate > 100) {
                fprintf(stderr, "Alarm: SpO2 = %.2f%%, Heart Rate = %d BPM\n", spo2, heart_rate);
                fprintf(log_file, "Alarm: SpO2 = %.2f%%, Heart Rate = %d BPM\n", spo2, heart_rate);
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
            fprintf(log_file, "Error: Failed to read sensor data\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

