#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define RELAY_GPIO 17
#define REED_SENSOR_GPIO 27
#define LOG_FILE "/var/log/door_events.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int i2c_handle);
float calculate_distance(int adc_value);
float calibrate_threshold(int i2c_handle);
void control_relay(int gpio_pin, int state);
int read_reed_sensor(int gpio_pin);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read ADC value from ADS1115
int read_adc(int i2c_handle) {
    char buf[3];
    int16_t adc_value;

    // Configure ADS1115 for single-ended A0 reading, 4.096V range, continuous conversion
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = 0xC3; // 0b11000011: Single-ended A0, 4.096V, Continuous conversion
    buf[2] = 0x83; // 0b10000011: 128 SPS, Disable comparator

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_event("Error writing to I2C device.");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read ADC value
    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_event("Error writing to I2C device for conversion read.");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        log_event("Error reading from I2C device.");
        return -1;
    }

    adc_value = (buf[0] << 8) | buf[1];
    adc_value = adc_value >> 4; // Right align 12-bit value

    return adc_value;
}

// Function to calculate distance from ADC value (example calibration)
float calculate_distance(int adc_value) {
    // This is a placeholder.  Calibration is highly recommended.
    // The GP2Y0A21YK0F has a non-linear output.
    // A more accurate approach would involve a lookup table or a polynomial fit.
    // Example:  Distance = A * adc_value^2 + B * adc_value + C
    // You'll need to determine A, B, and C through calibration.
    float distance = 100.0 / (adc_value + 1); // Example inverse relationship
    return distance;
}

// Function to calibrate the threshold
float calibrate_threshold(int i2c_handle) {
    int adc_value;
    float sum = 0.0;
    for (int i = 0; i < 10; i++) {
        adc_value = read_adc(i2c_handle);
        if (adc_value == -1) {
            log_event("Error reading ADC during calibration.");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        gpioDelay(50000); // 50ms delay
    }
    return sum / 10.0 * 0.8; // 80% of the average
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to read the reed sensor
int read_reed_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log events
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        log_event("Error opening I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off

    // Set reed sensor GPIO as input
    gpioSetMode(REED_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(REED_SENSOR_GPIO, PI_PUD_UP); // Pull-up resistor

    // Calibrate the threshold
    float threshold = calibrate_threshold(i2c_handle);
    if (threshold < 0) {
        log_event("Threshold calibration failed.");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    printf("Threshold: %.2f\n", threshold);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(i2c_handle);
        if (adc_value == -1) {
            log_event("Error reading ADC value.");
        } else {
            float distance = calculate_distance(adc_value);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %.2f cm, ADC Value: %d", distance, adc_value);
            log_event(log_message);

            if (distance < threshold) {
                log_event("Distance below threshold.");
                control_relay(RELAY_GPIO, 1); // Activate relay
                gpioDelay(3000000); // 3 seconds
                control_relay(RELAY_GPIO, 0); // Deactivate relay

                int reed_state = read_reed_sensor(REED_SENSOR_GPIO);
                if (reed_state == 0) {
                    log_event("Door opened.");
                } else {
                    log_event("Door not opened.");
                }
            }
        }

        gpioDelay(200000); // 200ms delay
    }

    // Cleanup
    control_relay(RELAY_GPIO, 0); // Ensure relay is off
    i2cClose(i2c_handle);
    gpioTerminate();
    log_event("Shutdown complete.");

    return 0;
}

