FILE *log_file;

// Function prototypes
int read_mcp3008(int cs_pin, int channel);
int log_data(int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int cs_pin, int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int count;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Select the chip
    gpioWrite(cs_pin, 0); // CS low

    // Transfer the data
    count = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (count != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", count);
        gpioWrite(cs_pin, 1); // CS high
        return -1; // Indicate error
    }

    // Deselect the chip
    gpioWrite(cs_pin, 1); // CS high

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

