        sensor2_value = read_mcp3008(CS1, 0);
        if (sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor 2\n");
        }

        // Read data from sensor 3
        sensor3_value = read_mcp3008(CS2, 0);
        if (sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor 3\n");
        }

        // Log the data
