#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_DRY 200
#define MCP3008_WET 800
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP 60

// Global variables
int spi_handle;
int threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_adc_to_moisture(int adc_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int spi_result;
    for (int i = 0; i < 3; ++i) {
        spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (spi_result == 0) {
            break; // Success
        } else {
            log_event("SPI transfer failed. Retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    if (spi_result != 0) {
        log_event("SPI transfer failed after multiple retries.");
        return -1; // Indicate failure
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    if (adc_value < MCP3008_DRY) {
        return 0.0;
    } else if (adc_value > MCP3008_WET) {
        return 100.0;
    } else {
        return 100.0 - ((float)(adc_value - MCP3008_WET) / (float)(MCP3008_DRY - MCP3008_WET) * 100.0);
    }
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[100];
    sprintf(message, "Pump turned %s", state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Error: Invalid threshold value. Must be between 0 and 100.\n");
                    return 1;
                }
                break;
            case 'd':
                duration = atoi(optarg);
                if (duration < 1 || duration > 60) {
                    fprintf(stderr, "Error: Invalid duration value. Must be between 1 and 60 seconds.\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval < 1 || sleep_interval > 60) {
                    fprintf(stderr, "Error: Invalid sleep interval value. Must be between 1 and 60 seconds.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value, skipping irrigation cycle.");
            gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
            continue;
        }

        float moisture_percentage = map_adc_to_moisture(adc_value);
        char message[100];
        sprintf(message, "Moisture: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
        log_event(message);

        // Control pump based on moisture threshold
        if (moisture_percentage < threshold) {
            log_event("Moisture below threshold, activating pump.");
            control_pump(1); // Turn on pump
            gpioDelay(duration * 1000); // Wait for configured duration
            control_pump(0); // Turn off pump
            log_event("Pump deactivated.");
        }

        gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    log_event("System stopped");
    return 0;
}

