        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_event("Error reading ADC value, skipping irrigation cycle.");
            gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
            continue;
        }

        float moisture_percentage = map_adc_to_moisture(adc_value);
        char message[100];
        sprintf(message, "Moisture: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
        log_event(message);

        // Control pump based on moisture threshold
        if (moisture_percentage < threshold) {
            log_event("Moisture below threshold, activating pump.");
            control_pump(1); // Turn on pump
            gpioDelay(duration * 1000); // Wait for configured duration
            control_pump(0); // Turn off pump
            log_event("Pump deactivated.");
        }

        gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    gpioTerminate();
    log_event("System stopped");
    return 0;
}

