#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_CHANNELS 8
#define EMA_WINDOW 10
#define PEAK_THRESHOLD 1.2
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// EMA filter state
float ema_values[NUM_CHANNELS][EMA_WINDOW];
int ema_index[NUM_CHANNELS] = {0};

// Function prototypes
int read_mcp3008(int channel);
float calculate_ema(int new_value, float current_ema, float *ema_history);
void detect_peak(int channel, float ema_value, float threshold);
void log_event(int channel, int value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                  // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                  // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate EMA
float calculate_ema(int new_value, float current_ema, float *ema_history) {
    // 1 - Alpha
    float alpha = 0.1; // Adjust for desired smoothing

    // Update EMA history
    ema_history[ema_index[channel]] = current_ema;
    ema_index[channel] = (ema_index[channel] + 1) % EMA_WINDOW;

    // Calculate new EMA
    float sum = 0.0;
    for (int i = 0; i < EMA_WINDOW; i++) {
        sum += ema_history[i] * (alpha * (1 - pow(alpha, i)));
    }
    float new_ema = alpha * new_value + (1 - alpha) * sum;

    return new_ema;
}

// Function to detect peak
void detect_peak(int channel, float ema_value, float threshold) {
    if (ema_value > threshold * ema_value) {
        int value = read_mcp3008(channel);
        if (value != -1) {
            log_event(channel, value);
        }
    }
}

// Function to log event
void log_event(int channel, int value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s - Channel %d: %d\n", buf, channel, value);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int channel = 0; channel < NUM_CHANNELS; channel++) {
            int raw_value = read_mcp3008(channel);
            if (raw_value != -1) {
                float current_ema = ema_values[channel][ema_index[channel]] * (1 - pow(0.1, ema_index[channel])); // Calculate current EMA
                detect_peak(channel, current_ema, PEAK_THRESHOLD);
            }
        }

        gpioDelay(10); // Sample every 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Sound level monitoring stopped.\n");
    return 0;
}

