#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define AIN0_CONTROL 0x40 // Single-ended AIN0, disable output
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int i2c_read_byte(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    unsigned char buf[1];
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // Convert ms to ns

    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize PCF8591 with dummy read
    if (i2c_write_byte(i2c_fd, AIN0_CONTROL, 0) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (i2c_read_byte(i2c_fd, AIN0_CONTROL) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO for interrupt (if needed)
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 0); // Assuming line 0 is available
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_input(gpio_line, "gpio_interrupt") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = i2c_read_byte(i2c_fd, AIN0_CONTROL);
        if (adc_value >= 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

