#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_MOTOR_SHUTDOWN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define AIN0_OFFSET 0x4000 // Single-ended AIN0
#define VCC 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize();
int read_adc(int channel);
float voltage_to_gauss(float voltage);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void motor_shutdown();
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

int main() {
    openlog("magnetic_field_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (initialize() != 0) {
        syslog(LOG_ERR, "Initialization failed. Exiting.");
        closelog();
        return 1;
    }

    CircularBuffer gauss_buffer;
    init_circular_buffer(&gauss_buffer);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        float voltage = (float)read_adc(0) / 32768.0 * VCC;
        float gauss = voltage_to_gauss(voltage);

        add_to_buffer(&gauss_buffer, gauss);
        float average_gauss = calculate_average(&gauss_buffer);

        syslog(LOG_INFO, "Voltage: %.3f V, Magnetic Field: %.3f Gauss, Average: %.3f Gauss", voltage, gauss, average_gauss);

        if (average_gauss > THRESHOLD_GAUSS) {
            syslog(LOG_WARNING, "Threshold exceeded! Motor shutdown.");
            motor_shutdown();
            break; // Stop the loop after shutdown
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay for 1 second
    }

    cleanup();
    closelog();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(GPIO_MOTOR_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Ensure motor is initially off

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "I2C open failed: %d", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for single-ended AIN0, 128 SPS, +/- 4.096V
    uint16_t config = 0x4083; // 0b0100000010000011
    uint8_t write_buffer[3];
    write_buffer[0] = ADS1115_REG_CONFIG;
    write_buffer[1] = (config >> 8) & 0xFF; // MSB
    write_buffer[2] = config & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, (char *)write_buffer, 3) != 0) {
        syslog(LOG_ERR, "ADS1115 configuration failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    uint8_t read_buffer[2];
    uint16_t raw_value;

    // Set the ADS1115 to start a single conversion
    uint16_t config = 0x8083; // 0b1000000010000011
    uint8_t write_buffer[3];
    write_buffer[0] = ADS1115_REG_CONFIG;
    write_buffer[1] = (config >> 8) & 0xFF; // MSB
    write_buffer[2] = config & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, (char *)write_buffer, 3) != 0) {
        syslog(LOG_ERR, "Failed to start ADC conversion");
        return 0; // Return 0 on error
    }

    gpioDelay(10000); // Wait for conversion to complete (adjust as needed)

    // Read the conversion result
    write_buffer[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, (char *)write_buffer, 1) != 0) {
        syslog(LOG_ERR, "Failed to set register for reading");
        return 0; // Return 0 on error
    }

    if (i2cReadDevice(i2c_handle, (char *)read_buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADC value");
        return 0; // Return 0 on error
    }

    raw_value = (read_buffer[0] << 8) | read_buffer[1];

    // The ADS1115 returns the MSB first, so we need to swap bytes
    raw_value = (raw_value << 8) | (raw_value >> 8);

    return raw_value;
}

float voltage_to_gauss(float voltage) {
    // Check for valid voltage range
    if (voltage < 0.0 || voltage > VCC) {
        syslog(LOG_ERR, "Invalid voltage reading: %.3f V", voltage);
        return 0.0; // Return 0 Gauss on error
    }

    // Convert voltage to Gauss using the SS49E transfer function
    float gauss = (voltage - 2.5) / 0.0014 * 1000.0;
    return gauss;
}

void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

void motor_shutdown() {
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 1); // Set GPIO HIGH
    syslog(LOG_INFO, "Motor shutdown signal sent.");
}

void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
