#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MOISTURE_THRESHOLD 300
#define PUMP_DURATION 10 // seconds
#define READ_INTERVAL 60 // seconds
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log watering events
void log_event(int moisture_level) {
    FILE *fp = fopen("watering_events.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Moisture Level: %d\n", s, moisture_level);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO18 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read soil moisture level
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            control_pump(0); // Ensure pump is off
            break; // Exit loop on error
        }

        printf("Moisture Level: %d\n", moisture_level);

        // Control water pump
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating pump.\n");
            control_pump(1); // Turn pump on
            gpioDelay(PUMP_DURATION * 1000000); // Wait for pump duration (microseconds)
            control_pump(0); // Turn pump off
            printf("Pump deactivated.\n");
            log_event(moisture_level);
        }

        // Wait before next reading
        gpioDelay(READ_INTERVAL * 1000000); // microseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();
    printf("Watering system stopped.\n");
    return 0;
}

