// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set PWM duty cycle
void set_pwm_dutycycle(int dutycycle) {
    if (dutycycle < 0 || dutycycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid PWM duty cycle %d\n", dutycycle);
        return;
    }

    gpioPWM(PWM_GPIO, dutycycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        // Set PWM duty cycle based on ADC value
        set_pwm_dutycycle(adc_value);

        // Print ADC value and PWM duty cycle
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, adc_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    set_pwm_dutycycle(0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

