#include <unistd.h>
#include <signal.h>
#include <getopt.h>
#include <math.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// GPIO pin for LED
#define LED_PIN 17

// Default threshold (Gauss)
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_adc();
double adc_to_gauss(int adc_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc() {
    // Configure ADS1115 for single-ended AIN0, 4.096V gain, continuous conversion
    uint16_t config = 0x4083; // 0b0100000010000011
    uint8_t write_buffer[3];
    write_buffer[0] = ADS1115_REG_CONFIG;
    write_buffer[1] = (config >> 8) & 0xFF; // MSB
    write_buffer[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, (char *)write_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 4.096V gain)
    gpioDelay(10000); // 10ms

    // Read conversion register
    uint8_t read_buffer[2];
    read_buffer[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, (char *)read_buffer, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C for read: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, (char *)read_buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    int16_t adc_value = (read_buffer[0] << 8) | read_buffer[1];
    return adc_value;
}

// Convert ADC value to Gauss
double adc_to_gauss(int adc_value) {
    // Assuming 3.3V reference, 4.096V gain, and 1.65V zero-gauss output
    double v_out = (adc_value * 4.096) / 32768.0; // Convert ADC value to voltage
    double gauss = (v_out - 1.65) / 0.001;       // Convert voltage to Gauss
    return gauss;
}

// Blink LED for a given duration
void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay in microseconds
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring magnetic field... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_adc();
        if (adc_value >= 0) {
            double gauss = adc_to_gauss(adc_value);
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            if (gauss > threshold) {
                printf("Threshold exceeded! Blinking LED...\n");
                blink_led(1000); // Blink for 1 second
            }
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

