#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x11
#define CSV_FILE "tamper_log.csv"

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_bh1750();
void log_data(int sound_level, float light_level, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to read from BH1750 sensor
float read_bh1750() {
    char buf[2];
    int result;

    // Write measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed with code %d\n", result);
        return -1.0;
    }

    // Wait for measurement (at least 180ms)
    gpioDelay(180000); // 180 ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed with code %d\n", result);
        return -1.0;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to log data to CSV file
void log_data(int sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fp != NULL) {
        fprintf(fp, "%s,%d,%.2f,%d\n", timestamp, sound_level, light_level, error_code);
        fflush(fp); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: File pointer is NULL in log_data\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // /dev/i2c-1, address 0x23, flags 0
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed with code %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file %s\n", CSV_FILE);
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    rewind(fp);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int sound_level = -1;
        float light_level = -1.0;
        int error_code = 0;

        // Read sound level
        sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            error_code = 1; // ADC read error
            fprintf(stderr, "Error: Failed to read sound level\n");
        }

        // Read light level
        light_level = read_bh1750();
        if (light_level < 0) {
            error_code = 2; // I2C read error
            fprintf(stderr, "Error: Failed to read light level\n");
        }

        // Log data
        log_data(sound_level, light_level, error_code);

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up resources before exiting
    printf("Cleaning up...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

