#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 30
#define READ_INTERVAL 60 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int pump_state);
void log_data(int adc_value, float moisture);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
    printf("Pump set to: %s\n", pump_state ? "ON" : "OFF");
}

// Function to log data to the console
void log_data(int adc_value, float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation Control\n");

    // Main loop
    while (1) {
        int adc_value = -1;
        float moisture = -1.0;
        int retries = 3;

        // Read soil moisture sensor with retries
        while (retries > 0) {
            adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value >= 0) {
                moisture = calculate_moisture(adc_value);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error: Failed to read ADC value, retrying... (%d retries left)\n", retries - 1);
                retries--;
                sleep(1); // Wait before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value after multiple retries. Skipping this iteration.\n");
            sleep(READ_INTERVAL);
            continue;
        }

        // Control the pump based on moisture level
        if (moisture < MOISTURE_THRESHOLD) {
            control_pump(1); // Turn pump ON
        } else {
            control_pump(0); // Turn pump OFF
        }

        // Log the data
        log_data(adc_value, moisture);

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    return 0;
}

