float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;
    int i, result;

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value from response
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI communication error (attempt %d): %d\n", i + 1, result);
            gpioDelay(BACKOFF_DELAY * 1000); // Exponential backoff
            BACKOFF_DELAY *= 2;
        }
    }

    fprintf(stderr, "Failed to read from MCP3008 after %d attempts.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value (%d) is out of range (0-1023).\n", adc_value);
        return -1.0; // Indicate error
    }
    return ((float)adc_value / 1023.0) * 100.0;
}

