        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Failed to read ADC value. Skipping logging.\n");
        } else {
            // Convert to moisture percentage
            moisture_percentage = convert_to_moisture_percentage(adc_value);
            if (moisture_percentage == -1.0) {
                fprintf(stderr, "Failed to convert ADC value to moisture percentage. Skipping logging.\n");
            } else {
                // Log data
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);
            }
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

