#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define PWM parameters
#define PWM_FREQUENCY 4000 // 4 kHz
#define PWM_RANGE 1000

// Define constants
#define SOUND_SPEED 34300 // cm/s
#define MIN_FREQUENCY 220
#define MAX_FREQUENCY 880
#define MIN_DISTANCE 10  // cm
#define MAX_DISTANCE 100 // cm
#define MIN_VOLUME 50
#define MAX_VOLUME 100

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Calibration data
static float distance_calibration[10] = {0.0}; // 10 distance points
static float volume_calibration[10] = {0.0};  // 10 volume points

// Function prototypes
void signal_handler(int signal);
int init_gpio();
int init_spi();
int init_pwm();
void cleanup();
float read_distance();
int read_photoresistor();
float map_distance_to_frequency(float distance);
int map_photoresistor_to_volume(int photoresistor_value);
void save_calibration_data();
void load_calibration_data();

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    gpioWrite(TRIG_PIN, 0);
    gpioWrite(PWM_PIN, 0);

    return 0;
}

// Function to initialize SPI communication
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize PWM
int init_pwm() {
    char buffer[64];
    int fd;

    // Export PWM channel
    fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM export file\n");
        return -1;
    }
    write(fd, "0", 1);
    close(fd);

    // Set PWM period
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/period");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period file\n");
        return -1;
    }
    write(fd, "1000000", 10); // 1 ms period (1 kHz)
    close(fd);

    // Set PWM duty cycle (initially 0)
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty_cycle file\n");
        return -1;
    }
    write(fd, "0", 1);
    close(fd);

    // Enable PWM
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM enable file\n");
        return -1;
    }
    write(fd, "1", 1);
    close(fd);

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Disable PWM
    char buffer[64];
    int fd;
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fd = open(buffer, O_WRONLY);
    if (fd >= 0) {
        write(fd, "0", 1);
        close(fd);
    }

    // Unexport PWM channel
    fd = open("/sys/class/pwm/pwmchip0/unexport", O_WRONLY);
    if (fd >= 0) {
        write(fd, "0", 1);
        close(fd);
    }

    // Close SPI
    spiClose(spi_handle);

    // Stop pigpio
    gpioTerminate();

    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    int start = gpioTick();
    while (gpioRead(ECHO_PIN) == 0 && (gpioTick() - start) < 50000) {} // Wait for echo start, timeout after 50ms
    int echo_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 1 && (gpioTick() - echo_start) < 50000) {} // Wait for echo end, timeout after 50ms
    int echo_end = gpioTick();

    int pulse_width = echo_end - echo_start;

    if (pulse_width < 0 || pulse_width > 50000) {
        fprintf(stderr, "Error: Invalid pulse width: %d\n", pulse_width);
        return -1.0; // Indicate error
    }

    float distance = (pulse_width / 1000000.0) * SOUND_SPEED / 2.0; // Distance in cm
    return distance;
}

// Function to read photoresistor value from MCP3008
int read_photoresistor() {
    unsigned char spi_data[3];
    int adc_value;

    // MCP3008 command: start bit (1), single-ended mode (1), channel 0 (000), don't care (0)
    spi_data[0] = 0x01;
    spi_data[1] = 0x80; // 10000000
    spi_data[2] = 0x00;

    if (spiXfer(spi_handle, spi_data, spi_data, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];

    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
