int init_pwm() {
    char buffer[64];
    int fd;

    // Export PWM channel
    fd = open("/sys/class/pwm/pwmchip0/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM export file\n");
        return -1;
    }
    write(fd, "0", 1);
    close(fd);

    // Set PWM period
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/period");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM period file\n");
        return -1;
    }
    write(fd, "1000000", 10); // 1 ms period (1 kHz)
    close(fd);

    // Set PWM duty cycle (initially 0)
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/duty_cycle");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM duty_cycle file\n");
        return -1;
    }
    write(fd, "0", 1);
    close(fd);

    // Enable PWM
    snprintf(buffer, sizeof(buffer), "/sys/class/pwm/pwmchip0/pwm0/enable");
    fd = open(buffer, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Failed to open PWM enable file\n");
        return -1;
    }
    write(fd, "1", 1);
    close(fd);

