#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8 // CE0 on GPIO8
#define LOG_FILE "alcohol_log.txt"
#define RETRY_COUNT 3
#define SLEEP_SECONDS 1

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_adc(int channel);
float adc_to_ppm(int adc_value);
void log_data(int adc_value, float ppm, const char *classification);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void)
{
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len)
{
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int retries = RETRY_COUNT;
    int result = -1;

    while (retries > 0) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) >= 0) {
            result = 0; // Success
            break;
        } else {
            perror("SPI transfer failed");
            retries--;
            usleep(100000); // 100 ms delay
        }
    }

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read ADC function
int read_adc(int channel)
{
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (channel << 4) | 0x80; // Single-ended + channel
    tx_buf[2] = 0x00;

    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed for ADC read.\n");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Convert ADC value to PPM
float adc_to_ppm(int adc_value)
{
    return (adc_value * 0.5) - 10.0;
}

// Log data function
void log_data(int adc_value, float ppm, const char *classification)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, ADC: %d, PPM: %.2f, %s\n", timestamp, adc_value, ppm, classification);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void)
{
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void)
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(gpio_line, "alcohol_monitor", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            log_data(-1, -1.0, "Error: Failed to read ADC value.");
        } else {
            float ppm = adc_to_ppm(adc_value);
            const char *classification;

            if (ppm > 50.0) {
                classification = "Alcohol detected! Limit exceeded.";
            } else if (ppm < 20.0) {
                classification = "Sobriety confirmed.";
            } else {
                classification = "Alcohol level within acceptable range.";
            }

            log_data(adc_value, ppm, classification);
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

