    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_MODE, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set pump pin as output
    gpioSetMode(PUMP_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read soil moisture value
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            fprintf(stderr, "Error: Failed to read soil moisture\n");
            log_data(-1, -1); // Log error
        } else {
            printf("Moisture: %d\n", moisture);

            // Control pump based on moisture level
            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture below threshold. Activating pump.\n");
                control_pump(1); // Turn pump ON
                log_data(moisture, 1);
                sleep(PUMP_ACTIVATION_TIME);
                control_pump(0); // Turn pump OFF
                log_data(moisture, 0);
            } else {
                control_pump(0); // Ensure pump is OFF
                log_data(moisture, 0);
            }
        }

        sleep(60); // Wait 60 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Ensure pump is OFF
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

