// Define GPIO pins
#define LED_PIN 17
#define SPI_CE 8 // Chip Enable for MCP3008 (CS)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define noise threshold (10% above average)
#define NOISE_THRESHOLD 107

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calibrate_noise_level(int duration_seconds);
void control_led(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calibrate noise level
int calibrate_noise_level(int duration_seconds) {
    int sum = 0;
    int num_samples = 0;
    int start_time = time(NULL);

    printf("Calibrating noise level for %d seconds...\n", duration_seconds);

    while (time(NULL) - start_time < duration_seconds) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            sum += adc_value;
            num_samples++;
        } else {
            fprintf(stderr, "Error reading ADC during calibration\n");
            return -1; // Indicate calibration failure
        }
        gpioDelay(1000); // 1 ms delay
    }

    if (num_samples > 0) {
        int average_ambient_level = sum / num_samples;
        printf("Calibration complete. Average ambient level: %d\n", average_ambient_level);
        return average_ambient_level;
    } else {
        fprintf(stderr, "Error: No valid samples collected during calibration\n");
        return -1; // Indicate calibration failure
    }
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int average_ambient_level = calibrate_noise_level(5);
    if (average_ambient_level < 0) {
        fprintf(stderr, "Error: Noise level calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set noise threshold
    int noise_threshold = average_ambient_level + NOISE_THRESHOLD;
    printf("Noise threshold set to %d\n", noise_threshold);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Check if noise level exceeds threshold
        if (adc_value > noise_threshold) {
            control_led(1); // Turn LED on
            gpioDelay(10000); // 10 ms debounce
            control_led(0); // Turn LED off
        }

        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

