#include <time.h>
#include <string.h>
#include <errno.h>
#include <signal.h>

// Define constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 24 // CS pin (GPIO8)
#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD_NS (1000000000 / SAMPLE_RATE)
#define LOG_FILE "audio_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_ioctl(int fd, uint8_t request, uint8_t arg);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int gpio_request_line(struct gpiod_chip *chip, int line, struct gpiod_line **line, const char *consumer, int request_type);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_release_line(struct gpiod_line *line);
int log_write(FILE *file, const char *data);
void signal_handler(int sig);

// SPI open function
int spi_open(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI ioctl function
int spi_ioctl(int fd, uint8_t request, uint8_t arg) {
    uint8_t buf[2];
    buf[0] = request;
    buf[1] = arg;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), buf) < 0) {
        perror("Error performing SPI ioctl");
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error performing SPI transfer");
        return -1;
    }

    return 0;
}

// GPIO request line function
int gpio_request_line(struct gpiod_chip *chip, int line, struct gpiod_line **line, const char *consumer, int request_type) {
    *line = gpiod_chip_get_line(chip, line);
    if (!*line) {
        perror("Error getting GPIO line");
        return -1;
    }

    if (gpiod_line_request(*line, consumer, request_type) < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_release(*line);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO release line function
int gpio_release_line(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Log write function
int log_write(FILE *file, const char *data) {
    if (fwrite(data, 1, strlen(data), file) != strlen(data)) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

int main() {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct timespec ts;
    char timestamp_str[64];
    char log_data[128];
    int adc_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device. Exiting.\n");
        return 1;
    }

    // Request GPIO line
    if (gpio_request_line(GPIO_CHIP, GPIO_LINE, &gpio_line, "audio_sampler", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request GPIO line. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Error opening log file");
        gpio_release_line(gpio_line);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("Error getting timestamp");
            break;
        }
        snprintf(timestamp_str, sizeof(timestamp_str), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

        // Construct SPI message
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = (0x08 | 0) << 4; // Single-ended channel 0
        tx_buf[2] = 0x00; // Dummy byte

        // Set CS low
        if (gpio_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Failed to set CS low. Exiting.\n");
            break;
        }

        // Transfer SPI data
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "Failed to transfer SPI data. Exiting.\n");
            break;
        }

        // Set CS high
        if (gpio_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Failed to set CS high. Exiting.\n");
            break;
        }

        // Parse ADC value
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Format log data
        snprintf(log_data, sizeof(log_data), "%s|%d\n", timestamp_str, adc_value);

        // Write to log file
        if (log_write(log_file, log_data) < 0) {
            fprintf(stderr, "Failed to write to log file. Exiting.\n");
            break;
        }
        fflush(log_file);

        // Sleep until next sample deadline
        nanosleep(&(struct timespec){0, SAMPLE_PERIOD_NS}, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (gpio_line) {
        gpio_release_line(gpio_line);
    }
    if (spi_fd > 0) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

