#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *sensor1_line, *sensor2_line, *sensor3_line;

// Function prototypes
int read_sensor(struct gpiod_line *line);
float calculate_magnetic_field(int sensor_value, float v_quiescent, float sensitivity);
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Release GPIO lines
        if (sensor1_line) {
            gpiod_line_release(sensor1_line);
        }
        if (sensor2_line) {
            gpiod_line_release(sensor2_line);
        }
        if (sensor3_line) {
            gpiod_line_release(sensor3_line);
        }

        // Close the GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Function to read the digital value from a GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = -1; // Initialize to an error value
    struct timespec delay = {0, 10000000}; // 100 milliseconds

    if (!line) {
        fprintf(stderr, "Error: Invalid line pointer.\n");
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1;
    }

    return value;
}

// Function to calculate the magnetic field strength in millitesla
float calculate_magnetic_field(int sensor_value, float v_quiescent, float sensitivity) {
    float voltage_diff = (float)sensor_value * 3.3; // Assuming HIGH is 3.3V
    float magnetic_field = (voltage_diff - v_quiescent) / sensitivity;
    return magnetic_field;
}

// Function to log the magnetic field data to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Flush the file after each write
    fflush(fp);

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fclose(fp);
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the lines for each sensor
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    sensor3_line = gpiod_chip_get_line(chip, SENSOR3_GPIO);

    if (!sensor1_line || !sensor2_line || !sensor3_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines as inputs
    if (gpiod_line_request_input(sensor1_line, "magnetic_sensor") < 0) {
        fprintf(stderr, "Error requesting sensor1 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(sensor2_line, "magnetic_sensor") < 0) {
        fprintf(stderr, "Error requesting sensor2 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(sensor3_line, "magnetic_sensor") < 0) {
        fprintf(stderr, "Error requesting sensor3 line: %s\n", strerror(errno));
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(sensor1_line);
        int sensor2_value = read_sensor(sensor2_line);
        int sensor3_value = read_sensor(sensor3_line);

        float v_quiescent = 1.65; // Voltage at which the sensor is quiescent
        float sensitivity = 0.025; // Sensitivity of the sensor in V/mT

        float sensor1_mT = calculate_magnetic_field(sensor1_value, v_quiescent, sensitivity);
        float sensor2_mT = calculate_magnetic_field(sensor2_value, v_quiescent, sensitivity);
        float sensor3_mT = calculate_magnetic_field(sensor3_value, v_quiescent, sensitivity);

        // Check for out-of-range values
        if (sensor1_mT < -100 || sensor1_mT > 100) {
            fprintf(stderr, "Warning: Sensor 1 reading out of range: %.2f mT\n", sensor1_mT);
        }
        if (sensor2_mT < -100 || sensor2_mT > 100) {
            fprintf(stderr, "Warning: Sensor 2 reading out of range: %.2f mT\n", sensor2_mT);
        }
        if (sensor3_mT < -100 || sensor3_mT > 100) {
            fprintf(stderr, "Warning: Sensor 3 reading out of range: %.2f mT\n", sensor3_mT);
        }

        // Log the data
        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Delay for 100 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

