#include <unistd.h>
#include <time.h>
#include <signal.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 70
#define ADC_CHANNEL 0
#define ADC_VREF 3.3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int pump_state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid ADC channel");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        log_event("Error: SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    float moisture = ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the water pump relay
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
    log_event(pump_state ? "Pump ON" : "Pump OFF");
}

// Function to log events to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("watering.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            log_event("Error: ADC read failed");
        } else {
            // Calculate moisture percentage
            float moisture = calculate_moisture(adc_value);

            // Control pump based on moisture level
            if (moisture < MOISTURE_THRESHOLD_LOW) {
                control_pump(1); // Turn pump ON
            } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
                control_pump(0); // Turn pump OFF
            }

            // Log moisture level
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Moisture level: %.2f%% (ADC: %d)", moisture, adc_value);
            log_event(log_message);
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Clean up
    control_pump(0); // Ensure pump is OFF on exit
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated");
    return 0;
}

