#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    running = 0;
    printf("Received signal, exiting gracefully...\n");
}

// Function to initialize pigpio
int initialize_pigpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup
    return 0;
}

// Function to parse JSON payload
int parse_json_payload(const char *payload, boolean *led_state)
{
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL)
    {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL)
        {
            fprintf(stderr, "Error before: %s\n", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBoolean(led_state_json))
    {
        fprintf(stderr, "Error: 'led_state' is not a boolean\n");
        cJSON_Delete(json);
        return -1;
    }

    *led_state = cJSON_GetBooleanValue(led_state_json);
    cJSON_Delete(json);
    return 0;
}

// Function to control the LED
void control_led(boolean led_state)
{
    gpioWrite(GPIO_PIN, led_state ? 1 : 0);
}

// Function to reconnect to MQTT broker
void reconnect_mqtt()
{
    int rc;
    int reconnect_delay = 1; // Initial delay in seconds

    printf("Attempting to reconnect to MQTT broker...\n");

    while (running && mosq == NULL)
    {
