#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    int rc;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);

    // Set GPIO18 as an output
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the digital value from GPIO17
        int sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Print the sound level to the console
        printf("Sound Level: %d\n", sound_level);

        // Check if sound is detected (DO is LOW)
        if (sound_level == 0) {
            // Blink the alarm LED for 1 second
            gpioWrite(ALARM_LED_PIN, 1); // Turn LED ON
            gpioDelay(1000);             // Wait for 1 second
            gpioWrite(ALARM_LED_PIN, 0); // Turn LED OFF
            gpioDelay(1000);             // Wait for 1 second
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Clean up GPIO resources before exiting
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate();             // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

