#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "Signal received, exiting...\n");
}

int main() {
    struct timespec ts;
    char timestamp[30];
    int ret;
    struct gpiod_line_event event;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request falling edge events
    ret = gpiod_line_request_events(line, "vibration-monitor", GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);
    if (ret < 0) {
        perror("gpiod_line_request_events");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Vibration monitor started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Wait for a falling edge event
        ret = gpiod_line_event_wait(line, -1); // Wait indefinitely
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }

        // Read the event
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

        // Log the event
        fprintf(log_fp, "%s Vibration detected! Shutting down...\n", timestamp);
        fflush(log_fp);

        // Print to stdout
        printf("%s Vibration detected! Shutting down...\n", timestamp);

        // Shutdown the system
        ret = system("sudo shutdown -h now");
        if (ret != 0) {
            fprintf(stderr, "system(sudo shutdown -h now) failed with %d\n", ret);
        }

        break; // Exit the loop after the first event
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    printf("Vibration monitor stopped.\n");

    return EXIT_SUCCESS;
}

