#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) != 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

int log_event(int pin, int state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (!log_fp) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_fp, "%s,%d,%d\n", timestamp, pin, state);
    fflush(log_fp);
    return 0;
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        if (log_event(GPIO_PIN, sensor_value) != 0) {
            fprintf(stderr, "Failed to log event. \n");
        }

        if (sensor_value == 1) {
            printf("Flame detected!\n");
        }

        sleep(1);
    }

    printf("Cleaning up GPIO resources...\n");

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

