// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
int map_temperature_to_voltage(float temperature);
int write_dac_voltage(int voltage);
void log_data(int adc_value, float temperature, int dac_voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to map temperature to DAC voltage
int map_temperature_to_voltage(float temperature) {
    if (temperature < TEMP_MIN) {
        temperature = TEMP_MIN;
    } else if (temperature > TEMP_MAX) {
        temperature = TEMP_MAX;
    }

    float voltage = (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * VOLT_MAX;
    return (int)(voltage * 10000); // DAC voltage is in 0.001V increments
}

// Function to write DAC voltage
int write_dac_voltage(int voltage) {
    if (i2cWriteByteData(i2c_handle, 0x40, voltage) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
void log_data(int adc_value, float temperature, int dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, (float)dac_voltage / 10000.0);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, DAC_I2C_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Map to DAC voltage
        int dac_voltage = map_temperature_to_voltage(temperature);

        // Write to DAC
        if (write_dac_voltage(dac_voltage) != 0) {
            fprintf(stderr, "Error: Failed to write DAC voltage\n");
        }

        // Log data
        log_data(adc_value, temperature, dac_voltage);

        // Print to stdout
        printf("ADC: %d, Temperature: %.2f C, DAC Voltage: %.2f V\n", adc_value, temperature, (float)dac_voltage / 10000.0);

        // Wait 0.5 seconds
        gpioDelay(500000); // 0.5 seconds = 500000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

