#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Signal handler function
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    if (relay1_line) gpiod_line_set_value(relay1_line, 0);
    if (relay2_line) gpiod_line_set_value(relay2_line, 0);
    if (relay3_line) gpiod_line_set_value(relay3_line, 0);
    if (relay4_line) gpiod_line_set_value(relay4_line, 0);

    // Release GPIO lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close the GPIO chip
    if (chip) gpiod_chip_close(chip);

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO lines for the relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line)
    {
        perror("Error getting GPIO line");
        signal_handler(SIGTERM); // Clean up and exit
        return 1;
    }

    // Request the GPIO lines as outputs
    if (gpiod_line_request_output(relay1_line, "relay_sequencer", 0) < 0) {
        perror("Error requesting relay1_line as output");
        signal_handler(SIGTERM);
        return 1;
    }
    if (gpiod_line_request_output(relay2_line, "relay_sequencer", 0) < 0) {
        perror("Error requesting relay2_line as output");
        signal_handler(SIGTERM);
        return 1;
    }
    if (gpiod_line_request_output(relay3_line, "relay_sequencer", 0) < 0) {
        perror("Error requesting relay3_line as output");
        signal_handler(SIGTERM);
        return 1;
    }
    if (gpiod_line_request_output(relay4_line, "relay_sequencer", 0) < 0) {
        perror("Error requesting relay4_line as output");
        signal_handler(SIGTERM);
        return 1;
    }

    // Main loop
    while (1)
    {
        // Activate relay 1
        if (gpiod_line_set_value(relay1_line, 1) < 0) {
            perror("Error setting relay1_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Deactivate relay 1
        if (gpiod_line_set_value(relay1_line, 0) < 0) {
            perror("Error setting relay1_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Activate relay 2
        if (gpiod_line_set_value(relay2_line, 1) < 0) {
            perror("Error setting relay2_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Deactivate relay 2
        if (gpiod_line_set_value(relay2_line, 0) < 0) {
            perror("Error setting relay2_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Activate relay 3
        if (gpiod_line_set_value(relay3_line, 1) < 0) {
            perror("Error setting relay3_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Deactivate relay 3
        if (gpiod_line_set_value(relay3_line, 0) < 0) {
            perror("Error setting relay3_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Activate relay 4
        if (gpiod_line_set_value(relay4_line, 1) < 0) {
            perror("Error setting relay4_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);

        // Deactivate relay 4
        if (gpiod_line_set_value(relay4_line, 0) < 0) {
            perror("Error setting relay4_line value");
            signal_handler(SIGTERM);
            return 1;
        }
        sleep(1);
    }

    return 0;
}

