#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for motor control
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor run time
#define MOTOR_RUN_TIME 3 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_rain_level(int adc_value);
void control_motor(int rain_level);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];
    int adc_value;

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1; // Indicate error
    }

    // Parse ADC value from response
    adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to calculate rain level
int calculate_rain_level(int adc_value) {
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the DC motor
void control_motor(int rain_level) {
    if (rain_level >= RAIN_THRESHOLD) {
        // Close window
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 150); // PWM duty cycle = 150
        printf("Closing window...\n");
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for 3 seconds
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0); // Stop PWM
        printf("Window closed.\n");
    } else {
        // Open window
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, 150); // PWM duty cycle = 150
        printf("Opening window...\n");
        gpioDelay(MOTOR_RUN_TIME * 1000000); // Run for 3 seconds
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0); // Stop PWM
        printf("Window opened.\n");
    }
}

// Function to log rain data to file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Flush the buffer to ensure data is written to file
}

int main() {
    int adc_value, rain_level;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from rain sensor
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate rain level
        rain_level = calculate_rain_level(adc_value);

        // Control motor based on rain level
        control_motor(rain_level);

        // Log rain data
        log_rain_data(rain_level);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0); // Stop PWM
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

