#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define constants
#define THRESHOLD 700
#define DEBOUNCE_TIME 50
#define LED_ON_TIME 500

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read the ADC value using bit-banging
int read_adc()
{
    int adc_value = 0;
    // Set ADC_PIN as output
    gpioSetMode(ADC_PIN, PI_OUTPUT);

    // Discharge capacitor
    gpioWrite(ADC_PIN, 0);
    gpioDelay(1); // Wait 1 ms

    // Set ADC_PIN as input
    gpioSetMode(ADC_PIN, PI_INPUT);

    // Read 10 bits of ADC value
    for (int i = 0; i < 10; i++)
    {
        // Wait for the pin to go high
        while (gpioRead(ADC_PIN) == 0) {
            // Optionally add a timeout here to prevent infinite loop
        }

        // Wait for the pin to go low
        while (gpioRead(ADC_PIN) == 1) {
            // Optionally add a timeout here to prevent infinite loop
        }

        // Accumulate the ADC value
        adc_value <<= 1; // Shift left by 1 bit
        if (gpioRead(ADC_PIN) == 1) // Check if the pin is high
        {
            adc_value |= 1; // Set the least significant bit to 1
        }
    }

    return adc_value;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED_PIN as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate)
    {
        // Read ADC value
        int adc_value = read_adc();

        // Check if the ADC value exceeds the threshold
        if (adc_value > THRESHOLD)
        {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Turn on the LED
            gpioWrite(LED_PIN, 1);

            // Print the detection message
            printf("%s - Clap detected! ADC value: %d\n", timestamp, adc_value);

            // Debounce
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds

            // Turn off the LED
            gpioWrite(LED_PIN, 0);

            // Wait for a short period to avoid multiple triggers
            gpioDelay(LED_ON_TIME * 1000); // Convert ms to microseconds
        }

        // Small delay to reduce CPU usage
        gpioDelay(1000); // 1 ms delay
    }

    // Clean up and terminate pigpio
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    fprintf(stderr, "Clap detector terminated.\n");
    return 0;
}

