void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int gpio_export(int pin) {
    int fd;
    char buf[3];

    fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        perror("gpio_export: open(/sys/class/gpio/export)");
        return -1;
    }

    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        perror("gpio_export: write()");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    int fd;
    char buf[3];

    fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        perror("gpio_unexport: open(/sys/class/gpio/unexport)");
        return -1;
    }

    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        perror("gpio_unexport: write()");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    int fd;
    char path[64];

    snprintf(path, sizeof(path), GPIO_DIRECTION_PATH);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio_set_direction: open(/sys/class/gpio/gpio17/direction)");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("gpio_set_direction: write()");
        close(fd);
        return -1;
