#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 17
#define DRY_ADC 800
#define WET_ADC 300
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_data(float moisture_percentage, int pump_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = 100.0 - ((float)(adc_value - WET_ADC) / (float)(DRY_ADC - WET_ADC) * 100.0);

    // Clamp the percentage to the range [0, 100]
    if (percentage < 0.0) {
        percentage = 0.0;
    }
    if (percentage > 100.0) {
        percentage = 100.0;
    }

    return percentage;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Function to log data to file
void log_data(float moisture_percentage, int pump_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_percentage, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI_MODE_0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int pump_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Attempt to recover (e.g., re-initialize SPI)
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialisation failed\n");
                break; // Exit loop if recovery fails
            }
            gpioDelay(1000); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Control pump based on moisture level
        if (moisture_percentage < MOISTURE_THRESHOLD) {
            if (pump_state == 0) {
                control_pump(1); // Turn pump ON
                pump_state = 1;
                printf("Moisture low (%.2f%%), turning pump ON\n", moisture_percentage);
            }
        } else {
            if (pump_state == 1) {
                control_pump(0); // Turn pump OFF
                pump_state = 0;
                printf("Moisture OK (%.2f%%), turning pump OFF\n", moisture_percentage);
            }
        }

        // Log data
        log_data(moisture_percentage, pump_state);

        // Wait for 60 seconds
        gpioDelay(60000); // pigpioDelay takes milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn pump OFF
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

