#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MCP3008_CS   8
#define MCP3008_CLK  11
#define MCP3008_DIN  9
#define MCP3008_DOUT 10

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    0

// DRV5055-A1 parameters
#define SENSITIVITY 100.0 // mV/mT
#define QUIESCENT_VOLTAGE 1650.0 // mV

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int cs_pin;
    int clk_pin;
    int din_pin;
    int dout_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    double sensitivity;
    double quiescent_voltage;
    char *log_file_name;
} Config;

// Function prototypes
int initialize_gpio(Config *config);
int initialize_spi(Config *config);
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value);
double voltage_to_magnetic_field(double voltage);
int log_data(double magnetic_field);
void signal_handler(int signal);
void cleanup(Config *config);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio(Config *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->cs_pin, PI_OUTPUT);
    gpioSetMode(config->clk_pin, PI_OUTPUT);
    gpioSetMode(config->din_pin, PI_OUTPUT);
    gpioSetMode(config->dout_pin, PI_INPUT);

    gpioWrite(config->cs_pin, 1); // Ensure CS is initially high

    return 0;
}

// Initialize SPI interface
int initialize_spi(Config *config) {
    spi_handle = spiOpen(config->spi_channel, config->spi_speed, config->spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(MCP3008_CS, 0); // Select MCP3008
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Convert ADC value to voltage
double adc_to_voltage(int adc_value) {
    return (double)adc_value * 3300.0 / 1023.0;
}

// Convert voltage to magnetic field (mT)
double voltage_to_magnetic_field(double voltage) {
    return (voltage - 1650.0) / 100.0;
}

