// DRV5055-A1 parameters
#define SENSITIVITY 100.0 // mV/mT
#define QUIESCENT_VOLTAGE 1650.0 // mV

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int cs_pin;
    int clk_pin;
    int din_pin;
    int dout_pin;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    double sensitivity;
    double quiescent_voltage;
