// Structure to hold SPI data
typedef struct {
    unsigned char tx[3];
    unsigned char rx[3];
} spi_data_t;

// Function prototypes
int init_gpio();
int open_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int raw_value);
float convert_to_current(float voltage);
int log_current(float current);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi() {
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return spi_handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    spi_data_t spi_data;

    // Construct SPI message
    spi_data.tx[0] = 0x01; // Start bit
    spi_data.tx[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    spi_data.tx[2] = 0x00; // Don't care

    // Perform SPI transfer
    int result = spiXfer(SPI_CHANNEL, (char *)spi_data.tx, (char *)spi_data.rx, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract raw value
    int raw_value = ((spi_data.rx[1] & 0x03) << 8) | spi_data.rx[2];
    return raw_value;
}

// Convert raw value to voltage
float convert_to_voltage(int raw_value) {
    return (float)raw_value * VREF / 1023.0;
}

// Convert voltage to current
float convert_to_current(float voltage) {
    return (voltage - 2.5) * (FULL_SCALE_CURRENT / 2.5.0);
}

