    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        return 1;
    }

    // Open SPI channel
    int spi_handle = open_spi();
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw value from MCP3008
        int raw_value = read_mcp3008(MCP3008_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read MCP3008\n");
            continue; // Skip to the next iteration
        }

        // Convert to voltage and current
        float voltage = convert_to_voltage(raw_value);
        float current = convert_to_current(voltage);

        // Validate voltage
        if (voltage < 0.0 || voltage > VREF) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
            continue; // Skip logging
        }

        // Log current
        if (log_current(current) != 0) {
            fprintf(stderr, "Failed to log current\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

