    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int sensor1_value, sensor2_value;
    int i;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Debounce sensor 1
        int sensor1_debounced = 1;
        for (i = 0; i < 5; i++) {
            gpioDelay(2000); // 2ms delay
            sensor1_value = gpioRead(SENSOR1_GPIO);
            if (sensor1_value == 0) {
                sensor1_debounced = 0;
                break;
            }
        }

        // Debounce sensor 2
        int sensor2_debounced = 1;
        for (i = 0; i < 5; i++) {
            gpioDelay(2000); // 2ms delay
