    tx_buf[2] = 0x00; // Dummy byte

    // Transfer data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d). Retrying in 1 second.\n", result);
        gpioDelay(1000); // Wait 1 second before retrying
        return -1; // Indicate failure
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate moisture level percentage
double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;

    // Clamp the moisture level to [0, 100]
    if (moisture_level < 0.0) {
        moisture_level = 0.0;
    } else if (moisture_level > 100.0) {
        moisture_level = 100.0;
    }

