    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Retrying in %d seconds.\n", READ_DELAY);
            gpioDelay(READ_DELAY * 1000); // Wait before retrying
            continue; // Skip to the next iteration
