#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

#define PIR_GPIO 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define CAPTURE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    int pir_value;
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char command[256];
    FILE *fp;

    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Starting security camera system...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        pir_value = gpioRead(PIR_GPIO);

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected!");

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.jpg", timeinfo);

            snprintf(command, sizeof(command), "libcamera-still -o %s -n -w %d -h %d -q 85", CAPTURE_DIR, IMAGE_WIDTH, IMAGE_HEIGHT);

            pid_t pid = fork();

            if (pid == 0) {
                // Child process
                if (execvp(command, (char *[]){command, NULL}) == -1) {
                    syslog(LOG_ERR, "Failed to execute libcamera-still");
                    exit(1);
                }
            } else if (pid > 0) {
                // Parent process
                int status;
                waitpid(pid, &status, 0);
                if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                    syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
                } else {
                    syslog(LOG_INFO, "Image captured successfully.");
                }
            } else {
                syslog(LOG_ERR, "Fork failed");
            }

            gpioDelay(200); // Debounce
            if (gpioRead(PIR_GPIO) == 1) {
                syslog(LOG_INFO, "Motion still detected after debounce.");
            }
        }

        gpioDelay(50); // Poll every 50ms
    }

    syslog(LOG_INFO, "Terminating security camera system...");

    gpioTerminate();
    closelog();

    return 0;
}

