} device_info_t;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to open the V4L2 device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to initialize the V4L2 device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set image format to grayscale
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    // Map the first buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    device_info_t *dev_info = (device_info_t *)malloc(sizeof(device_info_t));
    if (!dev_info) {
        fprintf(stderr, "Error allocating device info\n");
        return -1;
    }
    dev_info->fd = fd;
    dev_info->buf = buf;

    // Map the buffer
    dev_info->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (dev_info->buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        free(dev_info);
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    struct v4l2_buffer buf;
    struct v4l2_streamparm streamparm;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 1;
    streamparm.parm.capture.timeperframe.denominator = 30; // 30 fps

    if (ioctl(fd, VIDIOC_S_PARM, &streamparm) < 0) {
        fprintf(stderr, "Error setting frame rate: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error enqueuing buffer: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(device_info_t *dev_info) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(dev_info->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(dev_info->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    } else {
        if (ioctl(dev_info->fd, VIDIOC_DQBUF, &dev_info->buf) < 0) {
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }
}

// Function to save the frame as a PGM file
int save_pgm_image(const void *image_data, size_t image_size) {
    FILE *fp;
    char filename[10];
    int image_number = 1;

    while (!terminate) {
        snprintf(filename, sizeof(filename), "image_%03d.pgm", image_number++);
        fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
            return -1;
        }

        // Write PGM header
        fwrite("P2\n", 1, PGM_HEADER_SIZE, fp);
        fwrite("# Generated by V4L2 PGM Saver\n", 1, strlen("# Generated by V4L2 PGM Saver\n"), fp);
        fwrite("# Image Number: ", 1, strlen("# Image Number: "), fp);
        fprintf(fp, "%d\n", image_number - 1);

        // Write image data
        fwrite(image_data, 1, image_size, fp);

        fclose(fp);
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to unmap buffers
int unmap_buffers(device_info_t *dev_info) {
    if (dev_info->buffer != NULL && dev_info->buffer != MAP_FAILED) {
        if (munmap(dev_info->buffer, dev_info->buf.length) < 0) {
            fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
            return -1;
        }
        dev_info->buffer = NULL;
    }
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int fd;
    device_info_t *dev_info = NULL;
    struct v4l2_format fmt;
    struct v4l2_streamparm streamparm;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }
    dev_info = (device_info_t *)malloc(sizeof(device_info_t));
    if (!dev_info) {
        fprintf(stderr, "Error allocating device info\n");
        close_device(fd);
        return EXIT_FAILURE;
    }
    dev_info->fd = fd;
    dev_info->buf = (struct v4l2_buffer){0};

    // Start streaming
    if (start_streaming(fd) < 0) {
        unmap_buffers(dev_info);
        close_device(fd);
        free(dev_info);
        return EXIT_FAILURE;
    }

    // Capture and save frames
    while (!terminate) {
        if (capture_frame(dev_info) == 0) {
            // Access the image data directly from the mapped buffer
            const void *image_data = dev_info->buffer;
            size_t image_size = dev_info->buf.length;

            if (save_pgm_image(image_data, image_size) != 0) {
                fprintf(stderr, "Error saving PGM image\n");
                break;
            }
        } else {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }
    }

    // Stop streaming
    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Error stopping streaming during cleanup\n");
    }

    // Unmap buffers
    if (unmap_buffers(dev_info) < 0) {
        fprintf(stderr, "Error unmapping buffers during cleanup\n");
    }

    // Close the device
    if (close_device(fd) < 0) {
        fprintf(stderr, "Error closing device during cleanup\n");
    }

    // Free allocated memory
    free(dev_info);

    return EXIT_SUCCESS;
}

