            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(device_info_t *dev, void **frame_buffer, size_t *frame_size) {
