int log_frame_timestamp(void *frame_buffer, size_t frame_size) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long timestamp = (long long)tv.tv_sec * 1000000 + (long long)tv.tv_usec;

    if (log_timestamp(FRAME_LOG_FILE, timestamp) != 0) {
        fprintf(stderr, "Error logging timestamp\n");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(device_info_t *dev) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

