int uninit_device(device_info_t *dev) {
    for (int i = 0; i < dev->req.count; i++) {
        if (munmap(dev->buffer, dev->buf.length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    close(dev->fd);
    return 0;
}

