    device_info_t dev;
    void *frame_buffer = NULL;
    size_t frame_size = 0;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize device
    if (init_device(&dev) != 0) {
        fprintf(stderr, "Device initialization failed\n");
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(&dev) != 0) {
        fprintf(stderr, "Capturing failed to start\n");
        uninit_device(&dev);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Capture frame
        if (capture_frame(&dev, &frame_buffer, &frame_size) == 0) {
            // Log timestamp
            if (log_frame_timestamp(frame_buffer, frame_size) != 0) {
                fprintf(stderr, "Failed to log frame timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to capture frame\n");
        }
    }

    // Stop capturing
    if (stop_capturing(&dev) != 0) {
        fprintf(stderr, "Capturing failed to stop\n");
    }

    // Uninitialize device
    if (uninit_device(&dev) != 0) {
        fprintf(stderr, "Device uninitialization failed\n");
    }

    return EXIT_SUCCESS;
}

