#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int                  fd                  = -1;
static struct buffer         *buffers            = NULL;
static unsigned int          n_buffers          = 0;
static int                  udp_socket          = -1;
static struct sockaddr_in    server_addr;
static volatile sig_atomic_t keep_running       = 1;

static int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

static int init_v4l2(const char *dev_name, unsigned int *n_buffers, struct buffer **buffers)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;
    struct v4l2_buffer buf;

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", dev_name, errno, strerror(errno));
        return -1;
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        fprintf(stderr, "VIDIOC_QUERYCAP error\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        close(fd);
        return -1;
    }

    CLEAR(fmt);
    fmt.type               = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width      = 640;
    fmt.fmt.pix.height     = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        fprintf(stderr, "VIDIOC_S_FMT error\n");
        close(fd);
        return -1;
    }

    CLEAR(req);
    req.count               = 4; // Number of buffers
    req.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory              = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        fprintf(stderr, "VIDIOC_REQBUFS error\n");
        close(fd);
        return -1;
    }

    *buffers = calloc(req.count, sizeof(**buffers));
    if (!*buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return -1;
    }

    for (*n_buffers = 0; *n_buffers < req.count; ++*n_buffers) {
        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = *n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QUERYBUF error\n");
            close(fd);
            free(*buffers);
            return -1;
        }

        (*buffers)[*n_buffers].length = buf.length;
        (*buffers)[*n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == (*buffers)[*n_buffers].start) {
            fprintf(stderr, "mmap error\n");
            close(fd);
            free(*buffers);
            return -1;
        }
    }

    for (*n_buffers = 0; *n_buffers < req.count; ++*n_buffers) {
        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = *n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            fprintf(stderr, "VIDIOC_QBUF error\n");
            close(fd);
            free(*buffers);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        fprintf(stderr, "VIDIOC_STREAMON error\n");
        close(fd);
        free(*buffers);
        return -1;
    }

    return 0;
}

static int init_udp(const char *server_ip, int server_port)
{
    int sockfd;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (-1 == sockfd) {
        fprintf(stderr, "Socket creation error: %s\n", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (-1 == inet_pton(AF_INET, server_ip, &server_addr.sin_addr)) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", server_ip);
        close(sockfd);
        return -1;
    }

    return sockfd;
}

static int send_udp_packet(int sockfd, const void *data, size_t data_len, int frame_index, int fragment_index, int total_fragments, size_t payload_size)
{
    char header[20];
    size_t header_len = sizeof(header);
    size_t total_len = header_len + data_len;

    memcpy(header, &frame_index, sizeof(frame_index));
    memcpy(header + sizeof(frame_index), &fragment_index, sizeof(fragment_index));
    memcpy(header + sizeof(frame_index) + sizeof(fragment_index), &total_fragments, sizeof(total_fragments));
    memcpy(header + sizeof(frame_index) + sizeof(fragment_index) + sizeof(total_fragments), &payload_size, sizeof(payload_size));

    ssize_t bytes_sent = sendto(sockfd, header, header_len, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (-1 == bytes_sent) {
        fprintf(stderr, "Sendto error: %s\n", strerror(errno));
        return -1;
    }

    bytes_sent = sendto(sockfd, data, data_len, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (-1 == bytes_sent) {
        fprintf(stderr, "Sendto error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup()
{
    unsigned int i;

    if (fd != -1) {
        for (i = 0; i < n_buffers; ++i) {
            if (buffers && buffers[i].start) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }

        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);

        close(fd);
        fd = -1;
    }

    if (udp_socket != -1) {
        close(udp_socket);
        udp_socket = -1;
    }

    if (buffers) {
        free(buffers);
        buffers = NULL;
    }
}

static void signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Received signal %d, stopping...\n", signum);
        keep_running = 0;
    }
}

int main(int argc, char *argv[])
{
    const char *dev_name = "/dev/video0";
    const char *server_ip = NULL;
    int server_port = 0;
    int opt;
    unsigned int n_buffers = 0;
    struct buffer *buffers = NULL;
    int i;
    struct v4l2_buffer buf;
    unsigned char *frame_buffer = NULL;
    size_t frame_size = 0;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid server port: %d\n", server_port);
        return EXIT_FAILURE;
    }

    if (server_ip == NULL) {
        fprintf(stderr, "Invalid server IP address\n");
        return EXIT_FAILURE;
    }

    if (init_v4l2(dev_name, &n_buffers, &buffers) != 0) {
        return EXIT_FAILURE;
    }

    udp_socket = init_udp(server_ip, server_port);
    if (udp_socket == -1) {
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        for (i = 0; i < n_buffers; ++i) {
            CLEAR(buf);
            buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory      = V4L2_MEMORY_MMAP;
            buf.index       = i;

            if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
                fprintf(stderr, "VIDIOC_DQBUF error\n");
                cleanup();
                return EXIT_FAILURE;
            }

            frame_buffer = buffers[i].start;
            frame_size = buffers[i].length;

            // Fragmentation logic
            size_t max_fragment_size = 65000 - 20; // 20 bytes for header
            size_t current_fragment_size = frame_size;
            int total_fragments = 1;

            while (current_fragment_size > max_fragment_size) {
                total_fragments++;
                current_fragment_size /= max_fragment_size;
            }

            if (current_fragment_size > max_fragment_size) {
                current_fragment_size = max_fragment_size;
                total_fragments = (frame_size / max_fragment_size) + 1;
            }

            for (int j = 0; j < total_fragments; ++j) {
                if (-1 == send_udp_packet(udp_socket, frame_buffer + (j * max_fragment_size), current_fragment_size, i, j, total_fragments, current_fragment_size)) {
                    cleanup();
                    return EXIT_FAILURE;
                }
            }

            if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
                fprintf(stderr, "VIDIOC_QBUF error\n");
                cleanup();
                return EXIT_FAILURE;
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

