    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Failed to stop streaming.\n");
    }

    // Uninitialize the device
    if (uninit_device(fd, buffers, n_buffers) < 0) {
        fprintf(stderr, "Failed to uninitialize device.\n");
    }

