#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define PAN_UP_BUTTON 6
#define PAN_DOWN_BUTTON 7
#define TILT_UP_BUTTON 8
#define TILT_DOWN_BUTTON 9

// Define servo limits
#define SERVO_MIN 25
#define SERVO_MAX 125

// Define PWM frequency and period
#define PWM_FREQUENCY 50
#define PWM_PERIOD 20000 // microseconds (50 Hz)

// Global variables
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set servo position using software PWM
void set_servo_position(int gpio, int position)
{
    if (position < SERVO_MIN || position > SERVO_MAX) {
        fprintf(stderr, "Error: Invalid servo position: %d\n", position);
        return;
    }

    int pulse_width = 1000 - position; // Map position (0-125) to pulse width (1000-1)
    if (pulse_width < 1) pulse_width = 1;
    if (pulse_width > 1000) pulse_width = 1000;

    gpioPWM(gpio, pulse_width);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PAN_UP_BUTTON, PI_INPUT);
    gpioSetMode(PAN_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(PAN_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);

    // Initialize servo positions
    int pan_position = 75;
    int tilt_position = 75;

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    // Set PWM frequency for servos
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-1000)
    gpioSetPWMrange(PAN_SERVO_PIN, 1000);
    gpioSetPWMrange(TILT_SERVO_PIN, 1000);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read button states
        int pan_up_pressed = gpioRead(PAN_UP_BUTTON) == 0;
        int pan_down_pressed = gpioRead(PAN_DOWN_BUTTON) == 0;
        int tilt_up_pressed = gpioRead(TILT_UP_BUTTON) == 0;
        int tilt_down_pressed = gpioRead(TILT_DOWN_BUTTON) == 0;

        // Adjust servo positions
        if (pan_up_pressed) {
            pan_position += 5;
            if (pan_position > SERVO_MAX) pan_position = SERVO_MAX;
            set_servo_position(PAN_SERVO_PIN, pan_position);
        }
        if (pan_down_pressed) {
            pan_position -= 5;
            if (pan_position < SERVO_MIN) pan_position = SERVO_MIN;
            set_servo_position(PAN_SERVO_PIN, pan_position);
        }
        if (tilt_up_pressed) {
            tilt_position += 5;
            if (tilt_position > SERVO_MAX) tilt_position = SERVO_MAX;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
        }
        if (tilt_down_pressed) {
            tilt_position -= 5;
            if (tilt_position < SERVO_MIN) tilt_position = SERVO_MIN;
            set_servo_position(TILT_SERVO_PIN, tilt_position);
        }

        // Delay for 50 ms
        gpioDelay(50000); // microseconds
    }

    // Stop servos and terminate pigpio
    set_servo_position(PAN_SERVO_PIN, 0); // Stop pan servo
    set_servo_position(TILT_SERVO_PIN, 0); // Stop tilt servo
    gpioTerminate();

    return 0;
}

