#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define JPEG_QUALITY 75

struct buffer {
    void   *start;
    size_t  length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static unsigned int n_buffers = 0;
static FILE *jpeg_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig)
{
    if (sig == SIGINT) {
        fprintf(stderr, "SIGINT received, stopping...\n");
        stop_flag = 1;
    }
}

int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int init_device(int *fd_ptr, unsigned int *n_buffers_ptr, struct buffer **buffers_ptr)
{
    int fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", DEVICE_NAME, errno, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP error: %d, %s\n", errno, strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT error: %d, %s\n", errno, strerror(errno));
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4; // Request 4 buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS error: %d, %s\n", errno, strerror(errno));
        close(fd);
        return -1;
    }

    n_buffers_ptr[0] = req.count;
    buffers_ptr[0] = calloc(req.count, sizeof(struct buffer));
    if (!buffers_ptr[0]) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return -1;
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF error: %d, %s\n", errno, strerror(errno));
            close(fd);
            free(buffers_ptr[0]);
            return -1;
        }

        buffers_ptr[0][i].length = buf.length;
        buffers_ptr[0][i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers_ptr[0][i].start) {
            fprintf(stderr, "mmap error: %d, %s\n", errno, strerror(errno));
            close(fd);
            free(buffers_ptr[0]);
            return -1;
        }
    }

    for (unsigned int i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF error: %d, %s\n", errno, strerror(errno));
            close(fd);
            free(buffers_ptr[0]);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON error: %d, %s\n", errno, strerror(errno));
        close(fd);
        free(buffers_ptr[0]);
        return -1;
    }

    *fd_ptr = fd;
    *n_buffers_ptr = req.count;
    *buffers_ptr = buffers_ptr[0];

    return 0;
}

int capture_frame(int fd, struct buffer *buffers, unsigned int n_buffers, FILE **jpeg_file_ptr)
{
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        if (EINTR == errno) {
            fprintf(stderr, "select() interrupted by signal\n");
            return -1;
        }
        fprintf(stderr, "select() error: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    if (0 == r) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF error: %d, %s\n", errno, strerror(errno));
        return -1;
    }

    *jpeg_file_ptr = fopen("capture_%04d%02d%02d_%02d%02d%02d.jpg", "wb");
    if (!*jpeg_file_ptr) {
        fprintf(stderr, "Cannot open jpeg file: %s\n", strerror(errno));
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF error: %d, %s\n", errno, strerror(errno));
        }
        return -1;
    }

    return buf.index;
}

void convert_yuyv_to_rgb24(unsigned char *yuyv, unsigned char *rgb24, int width, int height)
{
    int i, j, r, g, b, y, u, v;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j += 2) {
            y = yuyv[0];
            u = yuyv[1];
            v = yuyv[3];

            r = y + (1.370705 * (v - 128));
            g = y - (0.698001 * (v - 128)) - (0.336331 * (u - 128));
            b = y + (1.732446 * (u - 128));

            r = (r < 0) ? 0 : ((r > 255) ? 255 : r);
            g = (g < 0) ? 0 : ((g > 255) ? 255 : g);
            b = (b < 0) ? 0 : ((b > 255) ? 255 : b);

            rgb24[(i * width + j) * 3 + 0] = r;
            rgb24[(i * width + j) * 3 + 1] = g;
            rgb24[(i * width + j) * 3 + 2] = b;

            yuyv += 4;
        }
    }
}

void apply_box_blur(unsigned char *rgb24, int width, int height, int radius)
{
    int i, j, x, y, r, g, b, sum_r, sum_g, sum_b;
    unsigned char *pixel;

    for (i = 0; i < height; i++) {
        for (j = 0; j < width; j++) {
            sum_r = sum_g = sum_b = 0;
            for (x = -radius; x <= radius; x++) {
                for (y = -radius; y <= radius; y++) {
                    if (x + j >= 0 && x + j < width && y + i >= 0 && y + i < height) {
                        pixel = &rgb24[(i * width + j) * 3];
                        sum_r += pixel[0];
                        sum_g += pixel[1];
                        sum_b += pixel[2];
                    }
                }
            }
            r = (sum_r / (radius * radius + 1)) > 255 ? 255 : (sum_r / (radius * radius + 1));
            g = (sum_g / (radius * radius + 1)) > 255 ? 255 : (sum_g / (radius * radius + 1));
            b = (sum_b / (radius * radius + 1)) > 255 ? 255 : (sum_b / (radius * radius + 1));

            rgb24[(i * width + j) * 3 + 0] = r;
            rgb24[(i * width + j) * 3 + 1] = g;
            rgb24[(i * width + j) * 3 + 2] = b;
        }
    }
}

int save_jpeg(FILE *jpeg_file, unsigned char *rgb24, int width, int height)
{
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_stdio_dest(&cinfo, jpeg_file);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb24[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

void uninit_device(int fd, struct buffer *buffers, unsigned int n_buffers)
{
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }

    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
}

int main()
{
    unsigned char *yuyv = NULL;
    unsigned char *rgb24 = NULL;
    int frame_index;

    signal(SIGINT, signal_handler);

    if (init_device(&fd, &n_buffers, &buffers) < 0) {
        return EXIT_FAILURE;
    }

    yuyv = calloc(WIDTH * HEIGHT * 2, 1);
    rgb24 = calloc(WIDTH * HEIGHT * 3, 1);
    if (!yuyv || !rgb24) {
        fprintf(stderr, "Out of memory\n");
        uninit_device(fd, buffers, n_buffers);
        return EXIT_FAILURE;
    }

    frame_index = capture_frame(fd, buffers, n_buffers, &jpeg_file);
    if (frame_index < 0) {
        fprintf(stderr, "Capture failed\n");
        uninit_device(fd, buffers, n_buffers);
        free(yuyv);
        free(rgb24);
        return EXIT_FAILURE;
    }

    convert_yuyv_to_rgb24(buffers[frame_index].start, rgb24, WIDTH, HEIGHT);
    apply_box_blur(rgb24, WIDTH, HEIGHT, 2);
    save_jpeg(jpeg_file, rgb24, WIDTH, HEIGHT);

    fprintf(stderr, "Frame captured, converted, blurred, and saved as jpeg\n");

    uninit_device(fd, buffers, n_buffers);
    free(yuyv);
    free(rgb24);

    return EXIT_SUCCESS;
}

