        perror("Error opening device");
        return 1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);

    printf("Supported Formats:\n");
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) == 0) {
        printf("\t%d. %s\n", fmtdesc.index + 1, fmtdesc.description);
        fmtdesc.index++;
    }

    printf("Supported Resolutions:\n");
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Example format
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("\t%d. Width: %d, Height: %d\n", frmsize.index + 1, frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    printf("Supported Frame Intervals:\n");
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Example format
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("\t%d. Numerator: %d, Denominator: %d\n", frmival.index + 1, frmival.discrete.numerator, frmival.discrete.denominator);
        frmival.index++;
    }

    printf("Autofocus Support:\n");
    focus_ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &focus_ctrl) == 0) {
        printf("\tYes\n");
    } else {
        printf("\tNo\n");
    }

    close(fd);
    return 0;
}

