#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Servo center pulse width (microseconds)
#define SERVO_CENTER_PULSE_WIDTH 1500

// PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Global variables for servo pulse widths
int pan_servo_pulse_width = SERVO_CENTER_PULSE_WIDTH;
int tilt_servo_pulse_width = SERVO_CENTER_PULSE_WIDTH;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_servo_pulse_width(int gpio_pin, int pulse_width);
int read_button(int gpio_pin);
void move_servo(int gpio_pin, int direction);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_servo_pulse_width(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    set_servo_pulse_width(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Initialize GPIO pins and pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as output (servo control) or input (button control)
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for servos
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set initial servo positions
    set_servo_pulse_width(PAN_SERVO_PIN, pan_servo_pulse_width);
    set_servo_pulse_width(TILT_SERVO_PIN, tilt_servo_pulse_width);

    printf("GPIO initialization complete.\n");
    return 0; // Indicate success
}

// Set servo pulse width
void set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d)\n", pulse_width);
        return;
    }
    gpioPWM(gpio_pin, pulse_width);
}

// Read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Move servo in a given direction
void move_servo(int gpio_pin, int direction) {
    int current_pulse_width;

    if (gpio_pin == PAN_SERVO_PIN) {
        current_pulse_width = pan_servo_pulse_width;
    } else if (gpio_pin == TILT_SERVO_PIN) {
        current_pulse_width = tilt_servo_pulse_width;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin specified in move_servo\n");
        return;
    }

    if (direction == 1) { // Increment
        current_pulse_width += 10;
        if (current_pulse_width > SERVO_MAX_PULSE_WIDTH) {
            current_pulse_width = SERVO_MAX_PULSE_WIDTH;
        }
    } else if (direction == -1) { // Decrement
        current_pulse_width -= 10;
        if (current_pulse_width < SERVO_MIN_PULSE_WIDTH) {
            current_pulse_width = SERVO_MIN_PULSE_WIDTH;
        }
    } else {
        fprintf(stderr, "Error: Invalid direction specified in move_servo\n");
        return;
    }

    set_servo_pulse_width(gpio_pin, current_pulse_width);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO and pigpio
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Pan-Tilt Camera Control System\n");
    printf("Press UP to tilt up, DOWN to tilt down, LEFT to pan left, RIGHT to pan right.\n");

    // Main loop
    while (1) {
        // Read button states
        int up_button_pressed = read_button(UP_BUTTON_PIN) == 0;
        int down_button_pressed = read_button(DOWN_BUTTON_PIN) == 0;
        int left_button_pressed = read_button(LEFT_BUTTON_PIN) == 0;
        int right_button_pressed = read_button(RIGHT_BUTTON_PIN) == 0;

        // Move servos based on button presses
        if (up_button_pressed) {
            move_servo(TILT_SERVO_PIN, 1); // Tilt up
        }
        if (down_button_pressed) {
            move_servo(TILT_SERVO_PIN, -1); // Tilt down
        }
        if (left_button_pressed) {
            move_servo(PAN_SERVO_PIN, -1); // Pan left
        }
        if (right_button_pressed) {
            move_servo(PAN_SERVO_PIN, 1); // Pan right
        }

        // Delay for 50ms (20 Hz loop rate)
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

