#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define DEBOUNCE_DELAY 2000 // milliseconds
#define UPLOAD_URL "http://<server_ip>:<server_port>/upload"
#define LOG_FILE "motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold curl data
struct string {
  char *ptr;
  size_t len;
};

void init_string(struct string *s) {
  s->len = 0;
  s->ptr = malloc(s->len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s)
{
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
  running = 0;
  printf("Caught signal %d, exiting...\n", signal);
}

// Function to initialize the log file
int initialize_log_file() {
  log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    perror("Error opening log file");
    return -1;
  }
  return 0;
}

// Function to log messages with timestamps
void log_message(const char *message) {
  if (log_file != NULL) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
  }
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
  char command[256];
  snprintf(command, sizeof(command), "libcamera-still -o %s -n -w %d -h %d -q %d", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);
  int status = system(command);
  if (status == -1) {
    perror("Error executing libcamera-still");
    return -1;
  }
  return status;
}

// Function to create the motion_captures directory
int create_directory(const char *directory_name) {
  struct stat st = {0};

  if (stat(directory_name, &st) == -1) {
    if (mkdir(directory_name, 0777) == -1) {
      perror("Error creating directory");
      return -1;
    }
  }
  return 0;
}

// Function to format the JSON payload
int format_json_payload(char *json_buffer, size_t buffer_size, const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
  int ret = snprintf(json_buffer, buffer_size, 
                     "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": \"%s\", \"gpio_pin\": %d}",
                     filename, timestamp, motion_status, gpio_pin);
  if (ret < 0 || ret >= buffer_size) {
    fprintf(stderr, "Error formatting JSON payload\n");
    return -1;
  }
  return 0;
}

// Function to send the JSON payload to the server
int send_data_to_server(const char *json_payload) {
  CURL *curl;
  CURLcode res;
  struct curl_slist *headers = NULL;

  curl_global_init(CURL_GLOBAL_DEFAULT);
  curl = curl_easy_init();
  if (curl) {
    curl_easy_setopt(curl, CURLOPT_URL, UPLOAD_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

    // Set content type to application/json
    headers = curl_slist_append(headers, "Content-Type: application/json");
