#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(50 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 50, "%Y%m%d_%H%M%S_%03d.jpg", timeinfo);
    char *milliseconds = (char*)malloc(4 * sizeof(char)); // Allocate memory for milliseconds
    if (milliseconds == NULL) {
        perror("Failed to allocate memory for milliseconds");
        free(filename);
        return NULL;
    }
    snprintf(milliseconds, 4, "_%03d", (int)(timeinfo->tm_sec / 10));
    strcat(filename, milliseconds);
    free(milliseconds);

    return filename;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[200];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute libcamera-still");
        return -1;
    }
    return WIFEXITED(status) ? WEXITSTATUS(status) : -1; // Return exit status or -1 on error
}

// Function to log events to a file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    log_event("Received signal, shutting down...");
}

int main() {
    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    log_event("Starting motion capture program...");

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        log_event("Failed to open GPIO chip");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Get the line for GPIO17
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        log_event("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Request the line as an input
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as input");
        log_event("Failed to request GPIO line as input");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set edge detection to falling edge
    ret = gpiod_line_request_rising_edge_events(line, "motion_capture");
    if (ret < 0) {
        perror("Failed to request rising edge events");
        log_event("Failed to request rising edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Motion capture program started, waiting for events...");

    // Main loop
    while (!terminate) {
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1000 * 1000; // 50ms

        int ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Error waiting for event");
            log_event("Error waiting for event");
            break;
        }

        if (ret > 0) {
            log_event("Motion detected!");

            // Generate filename
            char *filename = generate_filename();
            if (filename == NULL) {
                log_event("Failed to generate filename");
                continue; // Skip image capture if filename generation fails
            }

            // Capture image
            int status = capture_image(filename);
            if (status == 0) {
                log_event("Image captured successfully.");
            } else {
                char error_message[100];
                snprintf(error_message, sizeof(error_message), "Failed to capture image (status %d)", status);
                log_event(error_message);
            }

            free(filename);
        }
    }

    // Clean up
    log_event("Cleaning up...");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    log_event("Exiting.");
    return EXIT_SUCCESS;
}

