#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define angle increment (degrees)
#define ANGLE_INCREMENT 5

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the pan angle
void set_pan_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180 degrees).\n");
        return;
    }

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(PAN_GPIO, pulse_width);
}

// Function to set the tilt angle
void set_tilt_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180 degrees).\n");
        return;
    }

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)(angle) / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(TILT_GPIO, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set initial pan and tilt angles to 90 degrees
    set_pan_angle(90);
    set_tilt_angle(90);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        char input;
        printf("Enter arrow keys (up, down, left, right) or 'q' to quit: ");
        scanf(" %c", &input);

        // Handle user input
        if (input == 'u' || input == 'U') {
            set_tilt_angle(90 + ANGLE_INCREMENT);
        } else if (input == 'd' || input == 'D') {
            set_tilt_angle(90 - ANGLE_INCREMENT);
        } else if (input == 'l' || input == 'L') {
            set_pan_angle(90 - ANGLE_INCREMENT);
        } else if (input == 'r' || input == 'R') {
            set_pan_angle(90 + ANGLE_INCREMENT);
        } else if (input == 'q') {
            // Set both servos to neutral position (90 degrees)
            set_pan_angle(90);
            set_tilt_angle(90);
            program_running = 0; // Exit the loop
        } else {
            printf("Invalid input. Please enter arrow keys or 'q'.\n");
        }

        // Delay to prevent excessive CPU usage
        gpioDelay(100000); // 100 ms
    }

    // Set both servos to neutral position (90 degrees) before exiting
    set_pan_angle(90);
    set_tilt_angle(90);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

