int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OLED_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    if (oled_init() != 0) {
        fprintf(stderr, "OLED initialization failed\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    CpuStats prev_stats, curr_stats;
    prev_stats = read_cpu_stats();

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        float temperature = read_cpu_temp();

        // Read CPU usage
        curr_stats = read_cpu_stats();
        float cpu_usage = calculate_cpu_usage(prev_stats, curr_stats);

        // Display data on OLED
        display_data(temperature, cpu_usage);

        // Update previous stats
        prev_stats = curr_stats;

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// OLED initialization function
int oled_init() {
    // Initialization sequence (SSD1306 datasheet)
    oled_write_command(0xAE); // Display off
    oled_write_command(0xD5); // Set display clock divide ratio/oscillator frequency
    oled_write_command(0x80); // --ratio
    oled_write_command(0xA8); // Set multiplex ratio
    oled_write_command(0x3F); // --ratio
    oled_write_command(0xD3); // Set display offset
    oled_write_command(0x00); // --offset
    oled_write_command(0x40); // Set display start line
    oled_write_command(0x8D); // Charge pump setting
    oled_write_command(0x14); // --enable
    oled_write_command(0x20); // Set memory addressing mode
    oled_write_command(0x00); // --horizontal addressing mode
    oled_write_command(0xA1); // Set segment re-map
    oled_write_command(0xC8); // Set COM output scan direction
    oled_write_command(0xDA); // Set COM pins hardware configuration
    oled_write_command(0x12); // --configuration
    oled_write_command(0x81); // Set contrast control
    oled_write_command(0xCF); // --contrast
    oled_write_command(0xD9); // Set pre-charge period
    oled_write_command(0xF1); // --period
    oled_write_command(0xDB); // Set VCOM deselect level
    oled_write_command(0x40); // --level
    oled_write_command(0xA4); // Entire display ON/OFF
    oled_write_command(0xA6); // Set normal display
    oled_write_command(0xAF); // Display on

    oled_clear();
    return 0;
}

// OLED clear display function
void oled_clear() {
    // Set column and page address to 0
    oled_write_command(0x21); // Column start/end address
    oled_write_command(0x00); // Start at column 0
    oled_write_command(0x7F); // End at column 127

    oled_write_command(0x22); // Page start/end address
    oled_write_command(0x00); // Start at page 0
    oled_write_command(0x07); // End at page 7

    // Write 0 to all memory locations
    for (int i = 0; i < OLED_WIDTH * OLED_HEIGHT / 8; i++) {
        oled_write_data(0x00);
    }
}

// OLED write command function
void oled_write_command(unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write command failed: %s\n", strerror(errno));
        cleanup();
        exit(1);
    }
}

// OLED write data function
void oled_write_data(unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write data failed: %s\n", strerror(errno));
        cleanup();
        exit(1);
    }
}

