// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temperature = -1.0; // Default value in case of error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature file: %s\n", strerror(errno));
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temperature = atoi(buffer) / 1000.0;
    } else {
        fprintf(stderr, "Failed to read temperature from file: %s\n", strerror(errno));
    }

    fclose(fp);
    return temperature;
}

// Function to read CPU stats from /proc/stat
CpuStats read_cpu_stats() {
    CpuStats stats;
    FILE *fp;
    char buffer[256];

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open /proc/stat: %s\n", strerror(errno));
        // Return default values in case of error
        stats.user = 0; stats.nice = 0; stats.system = 0; stats.idle = 0; stats.iowait = 0; stats.irq = 0; stats.softirq = 0;
        return stats;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (strncmp(buffer, "cpu ", 4) == 0) {
            sscanf(buffer, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu",
                   &stats.user, &stats.nice, &stats.system, &stats.idle, &stats.iowait, &stats.irq, &stats.softirq, &stats.idle);
        }
    } else {
        fprintf(stderr, "Failed to read CPU stats from file: %s\n", strerror(errno));
        // Return default values in case of error
        stats.user = 0; stats.nice = 0; stats.system = 0; stats.idle = 0; stats.iowait = 0; stats.irq = 0; stats.softirq = 0;
    }

    fclose(fp);
    return stats;
}

// Function to calculate CPU usage percentage
float calculate_cpu_usage(CpuStats prev, CpuStats curr) {
    unsigned long prev_idle = prev.idle + prev.iowait;
    unsigned long curr_idle = curr.idle + curr.iowait;

    unsigned long prev_non_idle = prev.user + prev.nice + prev.system + prev.irq + prev.softirq;
    unsigned long curr_non_idle = curr.user + curr.nice + curr.system + curr.irq + curr.softirq;

    unsigned long prev_total = prev_idle + prev_non_idle;
    unsigned long curr_total = curr_idle + curr_non_idle;

    unsigned long totald = curr_total - prev_total;
    unsigned long idled = curr_idle - prev_idle;

    float cpu_usage = (float)(totald - idled) / totald * 100.0;

    return cpu_usage;
}

// Function to display data on OLED
void display_data(float temperature, float cpu_usage) {
    char temp_str[20];
    char usage_str[20];

    snprintf(temp_str, sizeof(temp_str), "Temp: %.1f C", temperature);
    snprintf(usage_str, sizeof(usage_str), "Usage: %.1f%%", cpu_usage);

    oled_clear();
    oled_write_string(0, 0, temp_str);
    oled_write_string(0, 16, usage_str);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

// Cleanup function
void cleanup() {
    oled_clear();
    close(i2c_fd);
    gpioTerminate();
}

