    if (i2c_result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_result);
        return;
    }
    gpioDelay(2); // Delay for the clear command to execute

    // Format and display data for Sensor 1
    sprintf(buffer, "Sensor 1: %.2f L/min", sensor1_volume);
