    i2c_result = i2cWriteByteData(i2c_handle, 0x00, 0x80); // Set cursor to the beginning of the first line
    if (i2c_result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_result);
        return;
    }
    for (int i = 0; buffer[i] != '\0'; i++) {
