    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the sensors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handlers for the sensors
    gpioSetISRFuncEx(SENSOR1_GPIO, RISING_EDGE, 0, pulse_counter, NULL);
    gpioSetISRFuncEx(SENSOR2_GPIO, RISING_EDGE, 0, pulse_counter, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_lcd_update = 0;

    // Main loop
    while (1) {
        // Calculate flow rates and total volumes
        sensor1_volume = (double)sensor1_pulses / 450.0;
        sensor2_volume = (double)sensor2_pulses / 450.0;

        // Reset pulse counts for the next interval
        sensor1_pulses = 0;
        sensor2_pulses = 0;

        // Print to console
        printf("Sensor 1: %.2f L/min, Total: %.2f L\n", sensor1_volume, sensor1_volume);
        printf("Sensor 2: %.2f L/min, Total: %.2f L\n", sensor2_volume, sensor2_volume);

        // Update LCD every 10 seconds
        time_t current_time = time(NULL);
        if (current_time - last_lcd_update >= 10) {
            update_lcd();
            last_lcd_update = current_time;
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    gpioTerminate();
    i2cClose(i2c_handle);
    return 0;
}

