#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LCD I2C address
#define LCD_ADDR 0x27

// LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Anemometer GPIO
#define ANEMOMETER_GPIO 17

// MCP3008 SPI channel
#define MCP3008_CHANNEL 0

// SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Wind vane calibration offsets
#define WIND_VANE_OFFSET 100
#define WIND_VANE_SCALE 500

// Global variables
volatile int pulse_count = 0;
int spi_handle;
int i2c_handle;

// Function prototypes
void anemometer_interrupt(int gpio, int level, uint32_t tick, void *user);
int read_mcp3008(int channel);
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void display_wind_data(float wind_speed, int wind_direction);
void signal_handler(int signal);

// Anemometer interrupt handler
void anemometer_interrupt(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7)
    {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01;                           // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
