    usleep(50000); // Wait for more than 40 ms after VCC rises to 4.5V
    lcd_byte(0x33, LCD_CMD);
    usleep(5000); // Wait for more than 4.1 ms
    lcd_byte(0x32, LCD_CMD);
    usleep(1000); // Wait for more than 100 us
    lcd_byte(0x28, LCD_CMD); // 4-bit mode, 2 lines, 5x8 font
    usleep(1000);
    lcd_byte(0x0C, LCD_CMD); // Display on, cursor off, blink off
    usleep(1000);
    lcd_byte(0x06, LCD_CMD); // Increment cursor, no shift
    usleep(1000);
    lcd_clear();
    usleep(1000);
}

// Send byte to LCD in 4-bit mode
void lcd_byte(int bits, int mode)
{
    // High bits
    int bits_high = mode | (bits & 0xF0) | LCD_DISPLAYON;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_DISPLAYON;

    // High bits
    if (i2cWriteByte(i2c_fd, bits_high) < 0) {
        perror("Error writing to I2C device (high bits)");
        exit(1);
    }
    usleep(100); // Delay 100 us

    // Low bits
    if (i2cWriteByte(i2c_fd, bits_low) < 0) {
        perror("Error writing to I2C device (low bits)");
        exit(1);
    }
    usleep(100); // Delay 100 us
}

// Send string to LCD
void lcd_string(const char *s)
{
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Clear LCD display
void lcd_clear()
{
    lcd_byte(LCD_CLEARDISPLAY, LCD_CMD);
    usleep(2000); // Delay 2 ms
}

// Set cursor position on LCD
void lcd_set_cursor(int col, int row)
{
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(0x80 | (col + row_offsets[row]), LCD_CMD);
}

// Write float value to LCD
void lcd_write_float(float value)
{
    char buffer[10];
    snprintf(buffer, sizeof(buffer), "%.2f", value);
    lcd_string(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt handler for flow sensor
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        pulse_count = 0;
        sleep(1);

        float flow_rate = calculate_flow_rate(pulse_count);

        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_string("Flow Rate:");
        lcd_write_float(flow_rate);

        lcd_set_cursor(0, 1);
        char flow_rate_str[17];
        snprintf(flow_rate_str, sizeof(flow_rate_str), "X.XX L/min", (int)flow_rate, (int)((flow_rate * 10) % 10));
        lcd_string(flow_rate_str);

        if (flow_rate == 0.0) {
            fprintf(stderr, "Warning: No water flow detected for 1 second.\n");
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_string("No Flow Detected!");
            sleep(5);
            lcd_clear();
        }
    }

    return 0;
}

