        gpioWrite(row_pins[row], 1);

        // Loop through the columns
        for (int col = 0; col < NUM_COLS; col++) {
            // Calculate the column index relative to the starting column
            int current_col = (col + frame_number) % NUM_COLS;

            // Set the column LOW if the current column is the starting column or the starting column + frame_number (mod NUM_COLS)
            if ((col == start_col) || (col == (start_col + frame_number) % NUM_COLS)) {
                gpioWrite(col_pins[col], 0);
            } else {
                gpioWrite(col_pins[col], 1);
            }

            // Delay for the scan time
            gpioDelay(SCAN_DELAY);
        }

        // Set the row LOW
        gpioWrite(row_pins[row], 0);
    }
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Display the wave-like animation (left-to-right)
        for (int frame_number = 0; frame_number < NUM_COLS; frame_number++) {
            display_frame(frame_number, 1); // 1 for left-to-right
        }

        // Display the wave-like animation (right-to-left)
        for (int frame_number = 0; frame_number < NUM_COLS; frame_number++) {
            display_frame(frame_number, 0); // 0 for right-to-left
        }

        // Small delay between frames
        gpioDelay(50000); // 50ms
    }

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

