// Define GPIO pins for rows and columns
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};
const int num_rows = 8;
const int num_cols = 8;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *row_lines[num_rows];
struct gpiod_line *col_lines[num_cols];

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_rows; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < num_cols; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a row of LEDs
void set_row(int row, int value) {
    if (row_lines[row]) {
        int ret = gpiod_line_set_value(row_lines[row], value);
        if (ret < 0) {
            perror("Error setting row value");
        }
    }
}

// Function to set the state of a column of LEDs
void set_column(int col, int value) {
    if (col_lines[col]) {
        int ret = gpiod_line_set_value(col_lines[col], value);
        if (ret < 0) {
            perror("Error setting column value");
        }
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request row lines as outputs
    for (int i = 0; i < num_rows; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            perror("Error getting row line");
            goto cleanup;
        }
        int ret = gpiod_line_request_output(row_lines[i], "led_matrix", 0);
        if (ret < 0) {
            perror("Error requesting row line as output");
            goto cleanup;
        }
    }

    // Request column lines as outputs
    for (int i = 0; i < num_cols; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            perror("Error getting column line");
            goto cleanup;
        }
        int ret = gpiod_line_request_output(col_lines[i], "led_matrix", 1);
        if (ret < 0) {
            perror("Error requesting column line as output");
            goto cleanup;
        }
    }

    // Main loop for animation
    while (1) {
        for (int col = 0; col < num_cols; col++) {
            // Clear the matrix (set all column cathodes HIGH and all row anodes LOW)
            for (int row = 0; row < num_rows; row++) {
                set_row(row, 0);
                set_column(col, 1);
            }

            // Light the current column (set the corresponding column cathode LOW and all row anodes HIGH)
            set_column(col, 0);
            for (int row = 0; row < num_rows; row++) {
                set_row(row, 1);
            }

            // Delay for 150ms
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = 150 * 1000 * 1000; // 150ms
            nanosleep(&delay, NULL);
        }
    }

cleanup:
    // Release GPIO lines and close chip if the loop exits due to an error
    for (int i = 0; i < num_rows; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < num_cols; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 1;
}

