// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// I2C bus
#define I2C_BUS 1

// Number of targets
#define NUM_TARGETS 4

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read a single byte from the sensor
int read_byte(int reg)
{
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to the sensor
int write_byte(int reg, int value)
{
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to read a block of data from the sensor
int read_block(int reg, char *buf, int count)
{
    int result = i2cReadI2CBlockData(i2c_handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a block of data to the sensor
int write_block(int reg, char *buf, int count)
{
    int result = i2cWriteI2CBlockData(i2c_handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error writing block to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

