#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char buf[2];
    int result;

    // Write the register address to be read
    result = i2cWriteByteData(i2c_handle, DISTANCE_REG, DISTANCE_REG);
    if (result < 0) {
        fprintf(stderr, "Error writing register address: %d\n", result);
        return -1;
    }

    // Read two bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (buf[0] << 8) | buf[1];

    return 0;
}

// Log data to a CSV file
int log_data(sensor_data_t data) {
    struct tm *tm_info;
    char timestamp_str[20];

    tm_info = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d\n", timestamp_str, data.distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int distance;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        retries = 0;
        distance = -1; // Initialize to an invalid value

        while (retries < RETRY_COUNT && distance == -1) {
            if (read_distance(&distance) == 0) {
                // Data read successfully, break the retry loop
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying... (%d/%d)\n", retries + 1, RETRY_COUNT);
                // Attempt to re-open I2C
                i2cClose(i2c_handle);
                if (init_i2c() != 0) {
                    fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                    terminate = 1; // Exit the loop if re-initialization fails
                    break;
                }
                retries++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (distance != -1) {
            // Get current timestamp
            sensor_data.timestamp = time(NULL);
            sensor_data.distance = distance;

            // Log the data
            log_data(sensor_data);
        } else {
            // Log error data
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char timestamp_str[20];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

            fprintf(log_file, "%s,-1\n", timestamp_str);
            fflush(log_file);
            fprintf(stderr, "Failed to read distance after multiple retries.\n");
        }

        gpioDelay(100); // Sample every 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

