#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"

static volatile int running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize GPIO pins
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log the event
int log_event() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s Object detected\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() != 0) {
        return 1;
    }

    int last_state = 1; // Assume initially no object detected (HIGH)

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0 && last_state == 1) { // Object detected (LOW) and previously not detected
            printf("Object detected!\n");
            control_led(1); // Turn LED on
            gpioDelay(50);   // Keep LED on for 50ms
            control_led(0); // Turn LED off
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        last_state = sensor_value;
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup GPIO resources
    gpioWrite(LED_PIN, 0); // Ensure LED is off before exiting
    gpioTerminate();

    return 0;
}

