#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define REMINDER_THRESHOLD 15.0

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_timed_out = 0;
static FILE *log_file = NULL;
static int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
void log_data(double distance);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick)
{
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 2;
    } else if (level == PI_TIMEOUT) {
        echo_timed_out = 1;
    }
}

// Function to generate a trigger pulse
void trigger_pulse()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance from pulse width
double calculate_distance(int pulse_width_us)
{
    return (pulse_width_us * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log data to file
void log_data(double distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
            fflush(log_file); // Ensure data is written to disk immediately
        } else {
            fprintf(log_file, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
            fflush(log_file);
        }
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_start_tick = 0;
        echo_end_tick = 0;
        echo_received = 0;
        echo_timed_out = 0;

        trigger_pulse();
        gpioDelay(50000); // Wait 50 ms before next measurement

        if (echo_received == 1) {
            if (echo_end_tick > echo_start_tick) {
                int pulse_width_us = echo_end_tick - echo_start_tick;
                double distance = calculate_distance(pulse_width_us);
                log_data(distance);

                if (distance < REMINDER_THRESHOLD) {
                    time_t rawtime;
                    struct tm *timeinfo;
                    char timestamp[20];

                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
                    fflush(log_file);
                }
            } else {
                log_data(-1.0); // Log an error for stuck echo
            }
        } else if (echo_timed_out) {
            log_data(-2.0); // Log a timeout error
        } else {
            log_data(-3.0); // Log sensor absent error
        }
    }

    // Cleanup
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

