#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    // Enable power, ALS, and proximity sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set ALS integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set wait time
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    // Set pulse length
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set control register (ALS gain)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Set proximity configuration register
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    return 0;
}

// Function to read RGB and proximity values from the sensor
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    uint8_t data[8];

    // Read all 8 bytes in one go
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, (char *)data, 8) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Combine high and low bytes for RGB values
    *red = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    *green = (uint16_t)data[2] | ((uint16_t)data[3] << 8);
    *blue = (uint16_t)data[4] | ((uint16_t)data[5] << 8);

    // Extract proximity value
    *proximity = data[6];

    return 0;
}

// Function to log data to a CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
