#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    // Enable power, ALS, and proximity sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set ALS integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set wait time
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    // Set pulse length
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set control register (ALS gain)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Set proximity configuration register
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    return 0;
}

