    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1182
int init_si1182(int handle)
{
    uint8_t part_id;

    // Read PART_ID register
    if (read_register(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading PART_ID register\n");
        return -1;
    }

    // Verify PART_ID
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    // Configure MEAS_RATE0 register (e.g., 100ms)
    if (write_register(handle, REG_MEAS_RATE0, 0x0A) != 0) {
        fprintf(stderr, "Error configuring MEAS_RATE0 register\n");
        return -1;
    }

    // Reset/start the sensor (COMMAND register)
    if (write_register(handle, REG_COMMAND, 0x01) != 0) {
        fprintf(stderr, "Error resetting/starting sensor\n");
        return -1;
    }

    return 0;
}

