        return -1;
    }
    if (read_register(handle, REG_PS_DATA1, &data1) != 0) {
        fprintf(stderr, "Error reading PS_DATA1 register\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    *proximity = ((uint16_t)data1 << 8) | data0;

    return 0;
}

