#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define CH101_ADDR 0x45

// Define the register addresses for the CH101 sensor
#define CH101_REG_STATUS 0x00
#define CH101_REG_DISTANCE_HIGH 0x01
#define CH101_REG_DISTANCE_LOW 0x02
#define CH101_REG_CONFIG 0x03

// Define the trigger command
#define CH101_TRIGGER_COMMAND 0x01

// Define the measurement mode (continuous mode)
#define CH101_MODE_CONTINUOUS 0x01

// Define the data rate (10 Hz)
#define CH101_DATA_RATE 0x0A

// Define the buffer size for the timestamp string
#define TIMESTAMP_BUFFER_SIZE 20

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int trigger_measurement();
int read_distance(int16_t *distance);
void get_timestamp(char *timestamp_str, size_t size);
int log_data(const char *timestamp, int16_t distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the CH101 sensor
int init_sensor() {
    // Configure the sensor for continuous mode and 10 Hz data rate
    char config_data[2];
    config_data[0] = CH101_REG_CONFIG;
    config_data[1] = (CH101_MODE_CONTINUOUS << 4) | CH101_DATA_RATE; // Combine mode and data rate

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char trigger_data[1];
    trigger_data[0] = CH101_TRIGGER_COMMAND;

    int result = i2cWriteDevice(i2c_handle, trigger_data, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the distance from the sensor
int read_distance(int16_t *distance) {
    char distance_data[2];
    int result = i2cReadDevice(i2c_handle, distance_data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    *distance = (distance_data[0] << 8) | distance_data[1];
    return 0;
}

// Get the current timestamp
void get_timestamp(char *timestamp_str, size_t size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, size, "%Y-%m-%d %H:%M:%S", tm_info);
}

// Log the data to a file
int log_data(const char *timestamp, int16_t distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
