    char trigger_data[1];
    trigger_data[0] = CH101_TRIGGER_COMMAND;

    int result = i2cWriteDevice(i2c_handle, trigger_data, 1);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

