volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio) {
    int reading = gpioRead(gpio);
    if (reading >= 0) {
        return reading;
    } else {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
}

int main() {
    FILE *log_file = NULL;
    int sensor1_reading, sensor2_reading;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting obstacle detection. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        sensor1_reading = read_sensor(SENSOR_1_GPIO);
        sensor2_reading = read_sensor(SENSOR_2_GPIO);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log data to file
        if (sensor1_reading != -1 && sensor2_reading != -1) {
            fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_reading, sensor2_reading);
            fflush(log_file); // Ensure data is written to disk immediately
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log entry.\n");
        }

        gpioDelay(100); // Wait 100 milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

