#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_proximity();
int read_ambient_light();
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = read_proximity();
        int ambient_light = read_ambient_light();

        if (proximity != -1 && ambient_light != -1) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500); // 500 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read proximity data
int read_proximity() {
    int data = -1;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        data = i2cReadWordData(i2c_handle, PROXIMITY_REG);
        if (data >= 0) {
            return data;
        } else {
            fprintf(stderr, "Failed to read proximity data (attempt %d): %d\n", i + 1, data);
            gpioDelay(10); // Small delay before retry
        }
    }
    fprintf(stderr, "Failed to read proximity data after %d retries\n", RETRY_COUNT);
    return -1;
}

// Read ambient light data
int read_ambient_light() {
    int data = -1;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        data = i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REG);
        if (data >= 0) {
            return data;
        } else {
            fprintf(stderr, "Failed to read ambient light data (attempt %d): %d\n", i + 1, data);
            gpioDelay(10); // Small delay before retry
        }
    }
    fprintf(stderr, "Failed to read ambient light data after %d retries\n", RETRY_COUNT);
    return -1;
}

// Log data to file
int log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
