#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define MEASURE_CMD_1 0x50
#define MEASURE_CMD_2 0x0A
#define MEASURE_CMD_3 0x00
#define MEASURE_CMD_4 0x01

#define DISTANCE_THRESHOLD 1000 // mm
#define SAMPLE_INTERVAL_MS 100

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, const unsigned char *buf, int len) {
    int retries = 3;
    while (retries > 0) {
        if (write(fd, buf, len) == len) {
            return 0; // Success
        }
        perror("I2C write failed");
        retries--;
        usleep(10000); // Wait 10ms before retry
    }
    return -1; // Failure after retries
}

int i2c_read(int fd, unsigned char *buf, int len) {
    int retries = 3;
    while (retries > 0) {
        if (read(fd, buf, len) == len) {
            return 0; // Success
        }
        perror("I2C read failed");
        retries--;
        usleep(10000); // Wait 10ms before retry
    }
    return -1; // Failure after retries
}

int read_sensor_data(int fd, unsigned char *data, int len) {
    if (i2c_write(fd, (unsigned char[]){MEASURE_CMD_1, MEASURE_CMD_2, MEASURE_CMD_3, MEASURE_CMD_4}, 4) < 0) {
        fprintf(stderr, "Error writing to sensor.\n");
        return -1;
    }
    usleep(10000); // Wait 10ms
    if (i2c_read(fd, data, len) < 0) {
        fprintf(stderr, "Error reading from sensor.\n");
        return -1;
    }
    return 0;
}

int validate_data(const unsigned char *data) {
    if (data[0] != MEASURE_CMD_1) {
        fprintf(stderr, "Invalid data header.\n");
        return -1;
    }
    return 0;
}

int calculate_distance(const unsigned char *data) {
    if (validate_data(data) < 0) {
        return -1;
    }
    return (data[11] << 8) | data[12];
}

int log_intrusion(int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("intrusion_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s - Average distance: %d mm - Intrusion detected!\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_fd = i2c_open(I2C_BUS, SENSOR_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    unsigned char data[15];
    int distance_sum = 0;
    int sample_count = 0;

    while (keep_running) {
        if (read_sensor_data(i2c_fd, data, 15) == 0) {
            int distance = calculate_distance(data);
            if (distance >= 0) {
                distance_sum += distance;
                sample_count++;
                if (sample_count >= 10) {
                    int average_distance = distance_sum / sample_count;
                    if (average_distance < DISTANCE_THRESHOLD) {
                        log_intrusion(average_distance);
                    }
                    distance_sum = 0;
                    sample_count = 0;
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

