#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadI2CBlockData(handle, reg, (char*)value, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteI2CBlockData(handle, reg, (char*)&value, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the model ID from the sensor
int read_model_id(int handle, uint8_t *model_id) {
    if (read_register(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, model_id) != 0) {
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int handle, uint16_t *distance) {
    uint8_t range_status[2];

    // Start a new measurement
    if (write_register(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    // Wait for the measurement to complete (with timeout)
    int timeout_count = 0;
    while (1) {
        if (read_register(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &range_status[0]) != 0) {
            return -1;
        }
        if (range_status[0] & 0x01) {
            break;
        }
        gpioDelay(1000); // 1 ms delay
        timeout_count++;
        if (timeout_count > 100) { // Timeout after 100 ms
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read the range status
    if (read_register(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &range_status[1]) != 0) {
        return -1;
    }

    // Combine the two bytes to form the distance
    *distance = (range_status[0] << 8) | range_status[1];

    // Clear the interrupt
    if (write_register(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    return 0;
}

