    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t model_id;
    if (read_model_id(i2c_handle, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        if (read_distance(i2c_handle, &distance) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

