#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1182 I2C address
#define SI1182_ADDR 0x39

// Si1182 register addresses
#define SI1182_REG_CONFIG 0x18
#define SI1182_REG_IRQ_STATUS 0x25
#define SI1182_REG_PROX_LSB 0x2A
#define SI1182_REG_PROX_MSB 0x2B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the Si1182 sensor
int init_si1182()
{
    // Write to the CONFIG register to enable proximity mode
    if (i2cWriteByteData(i2c_handle, SI1182_REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to read the proximity value from the Si1182 sensor
int read_proximity()
{
    unsigned char lsb, msb;
    int proximity_value;

    // Read the LSB and MSB of the proximity value
    lsb = i2cReadByteData(i2c_handle, SI1182_REG_PROX_LSB);
    msb = i2cReadByteData(i2c_handle, SI1182_REG_PROX_MSB);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    // Combine the LSB and MSB to get the 16-bit proximity value
    proximity_value = (msb << 8) | lsb;

    return proximity_value;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1182 sensor
    if (init_si1182() < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        int data_ready;
        int proximity_value;

        // Check if data is ready by reading the IRQ status register
        data_ready = i2cReadByteData(i2c_handle, SI1182_REG_IRQ_STATUS) & 0x01;

        if (data_ready) {
            // Read the proximity value
            proximity_value = read_proximity();

            if (proximity_value >= 0) {
                // Print the proximity value
                printf("Proximity value: %d\n", proximity_value);
            } else {
                fprintf(stderr, "Failed to read proximity value\n");
            }
        } else {
            // Data not ready yet
            //printf("Data not ready yet\n");
        }

        // Wait for 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

