#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define DISTANCE_SCALE 0.125

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 500000000}; // 500 ms
    unsigned char data[2];
    int distance_raw;
    float distance_mm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device presence
    if (ioctl(i2c_fd, I2C_SMBUS, I2C_SMBUS_READ_BYTE_DATA) < 0) {
        perror("Error verifying device presence");
        close(i2c_fd);
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");

    while (1) {
        // Read distance data
        if (read(i2c_fd, data, 2) != 2) {
            perror("Error reading distance data");
            fprintf(stderr, "Retrying in 500ms...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Combine bytes and convert to millimetres
        distance_raw = (data[1] << 8) | data[0];
        distance_mm = distance_raw * DISTANCE_SCALE;

        // Print distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
        }
    }

    // Close I2C bus (should not reach here due to signal handler)
    close(i2c_fd);
    return 0;
}

