#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define OPT3101 I2C address
#define OPT3101_ADDR 0x44

// Define OPT3101 register addresses (replace with actual values from datasheet)
#define OPT3101_REG_DISTANCE_CH0 0x00 // Example: Register for channel 0 distance
#define OPT3101_REG_AMBIENT_LIGHT 0x02 // Example: Register for ambient light
#define OPT3101_REG_ERROR_FLAGS 0x04 // Example: Register for error flags

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

int i2c_handle;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an OPT3101 register
int read_opt3101_register(int handle, int reg) {
    int data = i2cReadByteData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, data);
        return -1; // Indicate error
    }
    return data;
}

// Function to write a single byte to an OPT3101 register
int write_opt3101_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1; // Indicate error
    }
    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance from channel 0
        int distance = read_opt3101_register(i2c_handle, OPT3101_REG_DISTANCE_CH0);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
        } else {
            printf("Distance: %d\n", distance);
        }

        // Read ambient light data
        int ambient_light = read_opt3101_register(i2c_handle, OPT3101_REG_AMBIENT_LIGHT);
        if (ambient_light < 0) {
            fprintf(stderr, "Error reading ambient light\n");
        } else {
            printf("Ambient Light: %d\n", ambient_light);
        }

        // Read error flags
        int error_flags = read_opt3101_register(i2c_handle, OPT3101_REG_ERROR_FLAGS);
        if (error_flags < 0) {
            fprintf(stderr, "Error reading error flags\n");
        } else {
            printf("Error Flags: 0x%02X\n", error_flags);
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // The following lines will never be reached in normal execution
    // because the while(1) loop runs indefinitely.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

