// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 200         // Timeout in microseconds
#define MAX_DISTANCE_US 38000  // Maximum distance in microseconds (38cm)

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_us);
void log_distance(double distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, unsigned int tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            start_tick = tick;
            echo_received = 1; // Indicate rising edge received
        } else if (level == 0 && echo_received == 1) {
            end_tick = tick;
            echo_received = 0; // Reset flag
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_us) {
    if (pulse_us <= 0 || pulse_us > MAX_DISTANCE_US) {
        fprintf(stderr, "Error: Invalid pulse duration: %u us\n", pulse_us);
        return -1.0; // Indicate an error
    }
    return (double)pulse_us * SPEED_OF_SOUND / 2.0;
}

// Function to log the distance with a timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
