    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set up callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for a second
        gpioDelay(1000000); // 1 second = 1000000 microseconds

        // Calculate pulse duration
        unsigned int pulse_us = end_tick - start_tick;

        // Calculate distance
        double distance = calculate_distance(pulse_us);

        // Log the distance
        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Could not measure distance\n");
        }
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

