#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define INTRUSION_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

volatile sig_atomic_t terminate = 0;
int uart_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int init_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, no hardware flow control
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, unsigned char *buffer, int count) {
    ssize_t bytes_read = read(fd, buffer, count);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return 0;
    }
    return bytes_read;
}

int validate_magic_word(const unsigned char *buffer, int count) {
    if (count != 8) {
        fprintf(stderr, "Invalid magic word length: %d\n", count);
        return -1;
    }

    unsigned char magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    for (int i = 0; i < 8; i++) {
        if (buffer[i] != magic_word[i]) {
            fprintf(stderr, "Invalid magic word: expected 0x%02x, got 0x%02x\n", magic_word[i], buffer[i]);
            return -1;
        }
    }
    return 0;
}

int parse_range_profile(const unsigned char *data, int count, short *range_profile, int num_bins) {
    if (count != num_bins * 2) { // Each bin is 2 bytes (16 bits)
        fprintf(stderr, "Invalid range profile data length: %d\n", count);
        return -1;
    }

    for (int i = 0; i < num_bins; i++) {
        range_profile[i] = (short)data[i * 2] | ((short)data[i * 2 + 1] << 8); // Little-endian
    }
    return 0;
}

int detect_intrusion(const short *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        float distance = i * 0.0486; // Range in meters
        if (range_profile[i] > 0 && distance <= threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        close(uart_fd);
        return EXIT_FAILURE;
    }

    unsigned char buffer[256]; // Buffer for UART data
    short range_profile[64];    // Range profile data

    while (!terminate) {
        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            if (validate_magic_word(buffer, bytes_read) == 0) {
                if (parse_range_profile(buffer + 8, bytes_read - 8, range_profile, 64) == 0) {
                    if (detect_intrusion(range_profile, 64, INTRUSION_THRESHOLD)) {
                        time_t rawtime;
                        struct tm *timeinfo;
                        char timestamp[20];

                        time(&rawtime);
                        timeinfo = localtime(&rawtime);
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                        fprintf(stdout, "Intrusion detected at %s\n", timestamp);
                        fprintf(log_file, "%s,%.3f\n", timestamp, INTRUSION_THRESHOLD);
                        fflush(log_file);

                        gpioWrite(GPIO_LED, 1); // Turn on LED
                        gpioDelay(2000);         // Wait for 2 seconds
                        gpioWrite(GPIO_LED, 0); // Turn off LED
                    }
                }
            }
        }
        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    gpioWrite(GPIO_LED, 0); // Ensure LED is off
    gpioTerminate();
    close(uart_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated successfully.\n");
    return EXIT_SUCCESS;
}

