#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define BUZZER_PIN 18

// Define log file name
#define LOG_FILE "obstacle_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor();
void control_buzzer(int state);
void log_event(int sensor_state, int buzzer_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully.\n");
    } else if (signal == SIGTERM) {
        printf("Termination signal received. Exiting gracefully.\n");
    }
    running = 0;
}

// Function to read the sensor state
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Function to log events to a file
void log_event(int sensor_state, int buzzer_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Sensor: %d, Buzzer: %d\n", timestamp, sensor_state, buzzer_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    int sensor_state, buzzer_state;
    int prev_sensor_state = -1; // Initialize to an invalid state

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sensor_state = read_sensor();

        if (sensor_state != prev_sensor_state) {
            buzzer_state = (sensor_state == 0) ? 1 : 0; // Active-low sensor
            control_buzzer(buzzer_state);
            log_event(sensor_state, buzzer_state);
            prev_sensor_state = sensor_state;
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_buzzer(0); // Turn off buzzer
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

