#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM__MODE_START 0x007
#define VL53L1X_REG_SYSRANGE__START 0x000
#define VL53L1X_REG_RESULT__INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT__RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM__INTERRUPT_CLEAR 0x014

// Thresholds for parking guidance
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_data(time_t timestamp, int distance);
void print_parking_guidance(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    char data[1];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Software reset
    char reset_data[2];
    reset_data[0] = 0x00;
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM__MODE_START, reset_data, 1) != 0) {
        fprintf(stderr, "Error writing reset command\n");
        return -1;
    }
    gpioDelay(2000); // 2 ms delay

    // Start continuous ranging
    char start_data[2];
    start_data[0] = 0x01;
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM__MODE_START, start_data, 1) != 0) {
        fprintf(stderr, "Error writing start command\n");
        return -1;
    }

    // Wait for ranging to start
    int ready = 0;
    int timeout = 0;
    while (!ready && timeout < 100) {
        char status_data[1];
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_SYSRANGE__START, status_data, 1) != 1) {
            fprintf(stderr, "Error reading ranging status\n");
            return -1;
        }
        if (status_data[0] & 0x01) {
            ready = 1;
        }
        gpioDelay(1000); // 1 ms delay
        timeout++;
    }

    if (!ready) {
        fprintf(stderr, "Timeout waiting for ranging to start\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    int distance = -1;

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT__RANGE_STATUS, data, 2) != 2) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }
    int range_status = (data[0] << 8) | data[1];

    // Check for valid range
    if ((range_status & 0x1F) == 0) {
        // Read distance (big-endian)
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT__RANGE_STATUS + 10, data, 2) != 2) {
            fprintf(stderr, "Error reading distance\n");
            return -1;
        }
        distance = (data[0] << 8) | data[1];
    } else {
        fprintf(stderr, "Invalid range status: 0x%04X\n", range_status);
        return -1;
    }

    return distance;
}

// Log data to CSV file
void log_data(time_t timestamp, int distance) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp_str, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Print parking guidance message
void print_parking_guidance(int distance) {
    if (distance < STOP_THRESHOLD) {
        printf("STOP\n");
    } else if (distance >= STOP_THRESHOLD && distance < APPROACH_THRESHOLD) {
        printf("APPROACH\n");
    } else if (distance >= APPROACH_THRESHOLD && distance < SLOW_THRESHOLD) {
        printf("SLOW\n");
    } else if (distance >= SLOW_THRESHOLD && distance <= 1200) {
        printf("CLEAR\n");
    } else {
        printf("ERROR: Distance out of range\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            time_t now = time(NULL);
            log_data(now, distance);
            print_parking_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

