#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register address for distance
#define DISTANCE_THRESHOLD 500 // Maximum measurable distance in mm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance();
float map_distance_to_frequency(int distance);
void blink_led(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the CH201 sensor
int read_distance() {
    int distance = -1; // Default to error value
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (result >= 0) {
            distance = (int16_t)result; // Assuming 16-bit distance data
            return distance;
        } else {
            fprintf(stderr, "I2C read error: %d, retrying...\n", result);
            gpioDelay(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Return error value after retries
}

// Map distance to frequency
float map_distance_to_frequency(int distance) {
    if (distance < 0) return 0.0; // Handle invalid distance
    if (distance > DISTANCE_THRESHOLD) {
        return 1.0; // Cap at max distance
    }

    // Linear mapping
    return 10.0 - ((float)distance / DISTANCE_THRESHOLD) * 9.0;
}

// Blink LED based on frequency
void blink_led(float frequency) {
    if (frequency <= 0.0) return; // Don't blink if frequency is 0 or less

    // Calculate on/off times in microseconds
    int on_time = (int)(500000.0 / frequency); // 0.5 seconds / frequency
    int off_time = (int)(500000.0 / frequency); // 0.5 seconds / frequency

    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(on_time);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(off_time);
}

// Log data to stdout
void log_data(float distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %.2f mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            float frequency = map_distance_to_frequency(distance);
            blink_led(frequency);
            log_data((float)distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping blink and logging.\n");
            log_data(-1.0, 0.0); // Log an error value
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

