#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address for the MLX75030
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C

// Define the command to trigger a measurement (replace with actual command from datasheet)
#define MEASURE_COMMAND 0x01

// Define the delay after triggering a measurement (in milliseconds)
#define MEASUREMENT_DELAY 10

// Define the sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int measurement_command;
    int measurement_delay_ms;
    int sampling_interval_ms;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the I2C bus
int initialize_i2c(int bus, int addr) {
    i2c_handle = i2cOpen(bus, addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int handle) {
    int result = i2cWriteByteData(handle, 0, MEASURE_COMMAND);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the distance data
int read_distance(int handle, uint16_t *distance) {
    char buffer[2];
    int result = i2cReadI2CBlockData(handle, 0, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to log the data to a file
int log_data(FILE *file, uint16_t distance) {
    time_t now = time(NULL);
    if (fprintf(file, "%ld,%d\n", now, distance) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c(I2C_BUS, MLX75030_ADDR) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_cm\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for the measurement to complete
        gpioDelay(MEASUREMENT_DELAY);

        // Read the distance
        uint16_t distance;
        if (read_distance(i2c_handle, &distance) != 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Log the data
        if (log_data(log_file, distance) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL);
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

