#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int sensor1_state = 1; // Assume initial state is clear
    int sensor2_state = 1;
    int prev_sensor1_state = 1;
    int prev_sensor2_state = 1;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char event_type[10];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor logging started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        sensor1_state = gpioRead(SENSOR_1_GPIO);
        sensor2_state = gpioRead(SENSOR_2_GPIO);

        // Debounce sensor 1
        if (sensor1_state != prev_sensor1_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
            sensor1_state = gpioRead(SENSOR_1_GPIO);
            if (sensor1_state != prev_sensor1_state) {
                prev_sensor1_state = sensor1_state;
            }
        }

        // Debounce sensor 2
        if (sensor2_state != prev_sensor2_state) {
            gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
            sensor2_state = gpioRead(SENSOR_2_GPIO);
            if (sensor2_state != prev_sensor2_state) {
                prev_sensor2_state = sensor2_state;
            }
        }

        // Log events
        if (sensor1_state != prev_sensor1_state) {
            if (sensor1_state == 0) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                strcpy(event_type, "DETECTED");
                fprintf(log_file, "%s, Sensor 1, %s\n", timestamp, event_type);
                fflush(log_file); // Ensure immediate write
                printf("Sensor 1: %s, Event: %s\n", timestamp, event_type);
            } else {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                strcpy(event_type, "CLEARED");
                fprintf(log_file, "%s, Sensor 1, %s\n", timestamp, event_type);
                fflush(log_file); // Ensure immediate write
                printf("Sensor 1: %s, Event: %s\n", timestamp, event_type);
            }
            prev_sensor1_state = sensor1_state;
        }

        if (sensor2_state != prev_sensor2_state) {
            if (sensor2_state == 0) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                strcpy(event_type, "DETECTED");
                fprintf(log_file, "%s, Sensor 2, %s\n", timestamp, event_type);
                fflush(log_file); // Ensure immediate write
                printf("Sensor 2: %s, Event: %s\n", timestamp, event_type);
            } else {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                strcpy(event_type, "CLEARED");
                fprintf(log_file, "%s, Sensor 2, %s\n", timestamp, event_type);
                fflush(log_file); // Ensure immediate write
                printf("Sensor 2: %s, Event: %s\n", timestamp, event_type);
            }
            prev_sensor2_state = sensor2_state;
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Clean up
    printf("Closing log file...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

