#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define CH101_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

#define TIMEOUT_MS 50

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance_mm;
    time_t timestamp;
} sensor_data_t;

// Function to handle signals
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to get current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    static char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
    return buf;
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from two consecutive I2C registers
int i2c_read_16(int fd, uint8_t high_reg, uint8_t low_reg, uint16_t *value) {
    uint8_t high_val, low_val;

    if (write(fd, &high_reg, 1) != 1) {
        fprintf(stderr, "Error writing high register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &high_val, 1) != 1) {
        fprintf(stderr, "Error reading high byte from I2C: %s\n", strerror(errno));
        return -1;
    }

    if (write(fd, &low_reg, 1) != 1) {
        fprintf(stderr, "Error writing low register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, &low_val, 1) != 1) {
        fprintf(stderr, "Error reading low byte from I2C: %s\n", strerror(errno));
        return -1;
    }

    *value = (high_val << 8) | low_val;
    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int fd) {
    if (i2c_write_reg(fd, MEAS_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Function to check if data is ready with timeout
int is_data_ready(int fd) {
    uint8_t status;
    struct timeval tv;
    fd_set rfds;

    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);

    tv.tv_sec = TIMEOUT_MS / 1000;
    tv.tv_usec = (TIMEOUT_MS % 1000) * 1000;

    int retval = select(fd + 1, &rfds, NULL, NULL, &tv);

    if (retval == -1) {
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        return -1;
    } else if (retval) {
        if (i2c_read_reg(fd, MEAS_STATUS, &status) != 0) {
            fprintf(stderr, "Error reading status register\n");
            return -1;
        }
        if ((status & 0x01) != 0) {
            return 1; // Data ready
        }
    }
    return 0; // Timeout
}

// Function to read the distance in millimeters
int read_distance(int fd, int *distance) {
    uint16_t raw_distance;
    if (i2c_read_16(fd, DIST_HIGH, DIST_LOW, &raw_distance) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    *distance = (int)raw_distance;
    return 0;
}

// Function to log data to a CSV file
int log_data(const char *timestamp, int distance_mm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
    fprintf(log_file, "%s,%d\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1";
    char *timestamp;
    int distance_mm;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement, skipping sample\n");
        } else {
            // Check if data is ready
            if (is_data_ready(i2c_fd) != 0) {
                fprintf(stderr, "Timeout waiting for data, skipping sample\n");
            } else {
                // Read distance
                if (read_distance(i2c_fd, &distance_mm) != 0) {
                    fprintf(stderr, "Error reading distance, skipping sample\n");
                } else {
                    // Get timestamp
                    timestamp = get_timestamp();

                    // Log data
                    if (log_data(timestamp, distance_mm) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }

                    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance_mm);
                }
            }
        }

        // Wait 500 ms
        usleep(500000); // 500 ms = 500000 microseconds
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

