// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// Register addresses (Example - adjust based on datasheet)
#define REG_IDENTIFICATION_MODEL_ID 0x000
#define REG_SYSTEM_START 0x001
#define REG_RESULT_RANGE_STATUS 0x010
#define REG_RESULT_SPAD_NB 0x011
#define REG_RESULT_SIGNAL_RATE 0x014
#define REG_RESULT_AMBIENT_RATE 0x016
#define REG_RESULT_DISTANCE 0x01E

// Zone grid configuration (8x8 = 64 zones)
#define NUM_ZONES 64

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, unsigned char reg_addr, unsigned char *data) {
    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, &reg_addr, 1) != 1) {
        perror("Failed to write to the i2c bus.");
        return -1;
    }

    if (read(fd, data, 1) != 1) {
        perror("Failed to read from the i2c bus.");
        return -1;
    }

    return 0;
}

// Function to write a single byte to an I2C register
int write_register(int fd, unsigned char reg_addr, unsigned char data) {
    unsigned char buf[2];
    buf[0] = reg_addr;
    buf[1] = data;

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.");
        return -1;
    }

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to the i2c bus.");
        return -1;
    }

    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_sensor(int fd) {
    // Example initialization sequence (adjust based on datasheet)
    unsigned char model_id;

    // Check sensor ID (Example)
    if (read_register(fd, REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (model_id != 0xE1) { //Expected model ID
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", model_id);
        return -1;
    }

    // Start the sensor (Example)
    if (write_register(fd, REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error starting sensor\n");
        return -1;
    }

    printf("VL53L5CX sensor initialized successfully.\n");
    return 0;
}

// Function to read distance data for a single zone
int read_zone_distance(int fd, int zone_index, int *distance) {
    // Example: Adjust register addresses based on your zone mapping
    unsigned char reg_addr;
    unsigned char data;

    // Calculate the register address for the zone data (Example)
    reg_addr = 0x024 + (zone_index * 2); // Assuming 2 bytes per zone

    if (read_register(fd, reg_addr, &data) < 0) {
        fprintf(stderr, "Error reading zone %d data\n", zone_index);
        return -1;
    }

    *distance = (int)data; // Assuming direct conversion to distance

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_ZONES; i++) {
            int distance;
            if (read_zone_distance(i2c_fd, i, &distance) == 0) {
                printf("Zone %d: %d mm\n", i, distance);
            } else {
                fprintf(stderr, "Failed to read distance for zone %d\n", i);
            }
        }

        usleep(500000); // 500 ms
    }

    // Cleanup (never reached in this example due to the infinite loop)
    close(i2c_fd);
    return 0;
}

