#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L4CX_REG_RESULT_SPAD_NB_DETECTED 0x0083
#define VL53L4CX_REG_RESULT_PEAK_SIGNAL_RATE 0x0084
#define VL53L4CX_REG_RESULT_AMBIENT_RATE 0x0085
#define VL53L4CX_REG_RESULT_DISTANCE 0x0096
#define VL53L4CX_REG_RESULT_INTERRUPT_STATUS 0x0046

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to write a byte to a VL53L4CX register
int vl53l4cx_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L4CX register
int vl53l4cx_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(handle, reg_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    result = i2cReadDevice(handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L4CX sensor
int vl53l4cx_init(int handle) {
    // Check sensor ID (example)
    uint8_t sensor_id;
    if (vl53l4cx_read_byte(handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (sensor_id != 0xE1) { // Expected sensor ID
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Configure for short-range mode (example)
    if (vl53l4cx_write_byte(handle, VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (vl53l4cx_write_byte(handle, VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (vl53l4cx_write_byte(handle, VL53L4CX_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1;

    // Start ranging
    if (vl53l4cx_write_byte(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return -1;

    return 0;
}

// Function to read the distance from the VL53L4CX sensor
int vl53l4cx_read_distance(int handle, uint16_t *distance) {
    uint8_t high_byte, low_byte;

    if (vl53l4cx_read_byte(handle, VL53L4CX_REG_RESULT_INTERRUPT_STATUS, &high_byte) != 0) return -1;
    if (high_byte & 0x01) {
        if (vl53l4cx_read_byte(handle, VL53L4CX_REG_RESULT_DISTANCE, &low_byte) != 0) return -1;
        if (vl53l4cx_read_byte(handle, VL53L4CX_REG_RESULT_DISTANCE + 1, &high_byte) != 0) return -1;

        *distance = (high_byte << 8) | low_byte;
        return 0;
    } else {
        return -1; // No new data available
    }
}

// Function to get the current timestamp with microsecond precision
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 30, "%Y-%m-%d %H:%M:%S", &tm_info);
    sprintf(timestamp + strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L4CX sensor
    if (vl53l4cx_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L4CX initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        char timestamp[30];

        if (vl53l4cx_read_distance(i2c_handle, &distance) == 0) {
            get_timestamp(timestamp);
            printf("%s, Distance: %d mm\n", timestamp, distance);
        } else {
            get_timestamp(timestamp);
            fprintf(stderr, "%s, Error reading distance\n", timestamp);
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

