#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm

// VL53L1X register addresses (from datasheet)
#define SOFT_RESET 0x0001
#define I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define SYSTEM__MODE_START 0x0007
#define RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X sensor.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Set the I2C address (if needed - depends on the sensor's configuration)
    // This might not be necessary if the sensor is already configured with the correct address.
    // if (i2cWriteByteData(i2c_handle, I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
    //     fprintf(stderr, "Error: Failed to set VL53L1X I2C address.\n");
    //     return -1;
    // }

    // Start continuous ranging mode
    if (i2cWriteByteData(i2c_handle, SYSTEM__MODE_START, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging mode.\n");
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");
    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    int distance = -1; // Default to error value
    unsigned char buffer[2];

    // Read the distance data (2 bytes) from register 0x0096
    if (i2cReadI2CBlockData(i2c_handle, RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, (char *)buffer, 2) == 2) {
        distance = (buffer[0] << 8) | buffer[1];
    } else {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    return distance;
}

// Control the buzzer based on the measured distance
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.  Check if I2C is enabled.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus.\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_vl53l1x() != 0) {
                    fprintf(stderr, "Error: VL53L1X re-initialization failed.\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(500000); // Wait 500 ms
    }

    // Clean up and exit
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

