    // Set the I2C address (if needed - depends on the sensor's configuration)
    // This might not be necessary if the sensor is already configured with the correct address.
    // if (i2cWriteByteData(i2c_handle, I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR) < 0) {
    //     fprintf(stderr, "Error: Failed to set VL53L1X I2C address.\n");
    //     return -1;
    // }

    // Start continuous ranging mode
    if (i2cWriteByteData(i2c_handle, SYSTEM__MODE_START, 0x04) < 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging mode.\n");
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");
    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance() {
    int distance = -1; // Default to error value
    unsigned char buffer[2];

    // Read the distance data (2 bytes) from register 0x0096
    if (i2cReadI2CBlockData(i2c_handle, RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, (char *)buffer, 2) == 2) {
        distance = (buffer[0] << 8) | buffer[1];
    } else {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    return distance;
}

// Control the buzzer based on the measured distance
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    } else {
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
    }
}

int main() {
