    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.  Check if I2C is enabled.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus.\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_vl53l1x() != 0) {
                    fprintf(stderr, "Error: VL53L1X re-initialization failed.\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(500000); // Wait 500 ms
    }

    // Clean up and exit
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

