#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance to measure (cm)
#define MAX_DISTANCE 400.0    // Maximum distance to measure (cm)
#define MIN_PULSE_WIDTH 1000  // Minimum pulse width for servo (us)
#define MAX_PULSE_WIDTH 2000  // Maximum pulse width for servo (us)
#define TIMEOUT_THRESHOLD 50000 // Timeout threshold for echo (us)

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_THRESHOLD) {
            fprintf(stderr, "Error: Echo pulse stuck low\n");
            return -1.0; // Indicate timeout error
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_THRESHOLD) {
            fprintf(stderr, "Error: Echo pulse stuck high\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate the distance
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2

    return distance;
}

// Function to set the servo angle
void set_servo_angle(float angle) {
    // Ensure angle is within the valid range
    if (angle < -90.0) angle = -90.0;
    if (angle > 90.0) angle = 90.0;

    // Calculate the pulse width
    int pulse_width = MIN_PULSE_WIDTH + (int)((angle + 90.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180.0);

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to a file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        float distance = measure_distance();
        float angle = 0.0;

        if (distance > 0) {
            // Map distance to servo angle
            angle = (distance - MIN_DISTANCE) * (90.0 / (MAX_DISTANCE - MIN_DISTANCE));

            // Set the servo angle
            set_servo_angle(angle);

            // Log the data
            log_data(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        gpioDelay(200); // Delay for 200 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

