#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <sys/msg.h>
#include <sys/ipc.h>
#include <time.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MSG_QUEUE_KEY 1234
#define MESSAGE_SIZE 256

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Message queue data structure
typedef struct {
    long mtype;
    char mtext[MESSAGE_SIZE];
} message_t;

// Global variables
int i2c_handle;
int msg_queue_id;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle);
void buzzer_on(int gpio_pin);
void buzzer_off(int gpio_pin);
void signal_handler(int signal);
void cleanup(int i2c_handle, int msg_queue_id, int gpio_pin);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// VL53L1X initialization function
int vl53l1x_init(int i2c_handle) {
    int status;
    uint8_t model_id;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    model_id = (uint8_t)status;

    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    uint8_t reset_data[2] = {0x00, 0x01};
    for (int i = 0; i < 2; ++i) {
        status = i2cWriteByteData(i2c_handle, 0x0000, reset_data[i]);
        if (status < 0) {
            fprintf(stderr, "Error writing reset data: %s\n", strerror(errno));
            return -1;
        }
        gpioDelay(1000); // Wait 1ms after each write
    }
    gpioDelay(10000); // Wait 10ms after reset

    // Configure timing budget (example: 50ms)
    uint8_t timing_budget_data[3] = {0x04, 0x00, 0x00}; // 50ms (4*10ms)
    status = i2cWriteI2CBlockData(i2c_handle, 0x001E, (char *)timing_budget_data + 1, 2); // Write 2 bytes starting from register 0x001E
    if (status < 0) {
        fprintf(stderr, "Error writing timing budget: %s\n", strerror(errno));
        return -1;
    }

    // Start ranging
    uint8_t start_data = 0x01;
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, start_data);
    if (status < 0) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }

    printf("VL53L1X sensor initialized successfully.\n");
    return 0;
}

// VL53L1X distance reading function
int vl53l1x_read_distance(int i2c_handle) {
    int status;
    uint8_t range_status;
    uint16_t distance;

    // Check data ready
    status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
    }
    range_status = (uint8_t)status;

    if (!(range_status & 0x01)) {
        //printf("Data not ready yet\n");
        return -1; // Data not ready
    }

    // Read distance
    uint8_t distance_data[2];
    status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)distance_data, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }
    distance = (uint16_t)((distance_data[0] << 8) | distance_data[1]);

    return distance;
}

// Buzzer control functions
void buzzer_on(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // HIGH
}

void buzzer_off(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // LOW
}

// Cleanup function
void cleanup(int i2c_handle, int msg_queue_id, int gpio_pin) {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (msg_queue_id >= 0) {
        msgctl(msg_queue_id, IPC_RMID, NULL); // Remove message queue
    }
    gpioWrite(gpio_pin, 0); // Ensure buzzer is off
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    int distance;
    int status;
    message_t msg;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    buzzer_off(BUZZER_GPIO);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create message queue
    msg_queue_id = msgget(MSG_QUEUE_KEY, IPC_CREAT | 0666);
    if (msg_queue_id == -1) {
        fprintf(stderr, "Error creating message queue: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance(i2c_handle);
        if (distance >= 0) {
            // Get current timestamp
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

            // Format message
            snprintf(msg.mtext, MESSAGE_SIZE, "%s Distance: %d mm", buf, distance);
            msg.mtype = 1; // Message type (arbitrary)

            // Send message to queue
            if (msgsnd(msg_queue_id, &msg, MESSAGE_SIZE, 0) == -1) {
                fprintf(stderr, "Error sending message: %s\n", strerror(errno));
            }

            // Control buzzer
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_on(BUZZER_GPIO);
            } else {
                buzzer_off(BUZZER_GPIO);
            }

            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup and exit
    cleanup(i2c_handle, msg_queue_id, BUZZER_GPIO);
    return 0;
}

