#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)
#define BUZZER_THRESHOLD 30.0   // Distance threshold for buzzer in cm

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int valid_reading = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void display_distance();
void buzzer_control(float distance);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
        gpioTerminate();           // Terminate pigpio
        exit(0);
    }
}

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        valid_reading = 0; // Reset valid_reading flag
    } else if (level == 0) {
        echo_end_tick = tick;
        // Calculate pulse width in microseconds
        int pulse_width = echo_end_tick - echo_start_tick;

        // Handle tick wraparound
        if (echo_end_tick < echo_start_tick) {
            pulse_width = (0xFFFFFFFF - echo_start_tick) + echo_end_tick;
        }

        // Calculate distance in centimeters
        float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance, convert us to s

        // Validate distance
        if (distance >= 2.0 && distance <= 400.0) {
            valid_reading = 1; // Set valid_reading flag
        } else {
            printf("Invalid distance reading: %.2f cm\n", distance);
        }
    }
}

// Function to display the distance
void display_distance() {
    if (valid_reading) {
        printf("Distance: %.2f cm\n", valid_reading);
    } else {
        printf("Sensor absent or invalid reading.\n");
    }
}

// Function to control the buzzer
void buzzer_control(float distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN to output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(100); // Delay for 100ms
        display_distance();
        buzzer_control(valid_reading ? (float)valid_reading : 0.0); // Pass distance to buzzer control
    }

    return 0;
}

