#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        log_event("Error opening I2C device");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        log_event("VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize servo motor
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz
    gpioSetPWMrange(SERVO_GPIO, 2000); // PWM range for SG90

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        log_event("MQTT initialization failed (out of memory)");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        log_event("MQTT connection failed");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int gate_state = 0; // 0: closed, 1: open
    while (1) {
        int distance = vl53l1x_read_distance(i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            log_event("Error reading distance");
        } else {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Distance: %d mm", distance);
            log_event(log_message);

            if (distance < DISTANCE_THRESHOLD && gate_state == 0) {
                set_servo_angle(OPEN_ANGLE);
                gate_state = 1;
                log_event("Opening gate");

                // Publish MQTT message
                mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen("open"), "open", 0, false);
            } else if (distance >= DISTANCE_THRESHOLD && gate_state == 1) {
                set_servo_angle(CLOSE_ANGLE);
                gate_state = 0;
                log_event("Closing gate");

                // Publish MQTT message
                mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen("close"), "close", 0, false);
            }
        }

        gpioDelay(100); // Check every 100 ms
    }

    return 0;
}

int vl53l1x_init(int i2c_handle) {
    // Implement VL53L1X initialization sequence here
    // This is a simplified example - refer to the VL53L1X datasheet for the complete sequence

    // Example: Check sensor ID (replace with actual register and expected value)
    char reg = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    char data;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device during init\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, &data, 1) != 0) {
        fprintf(stderr, "Error reading from I2C device during init\n");
        return -1;
    }

    if (data != 0xEA) { // Example sensor ID - replace with actual value
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", data);
        return -1;
    }

    // Configure for short-range mode (example)
    char config_data[2];

    // Example: Configure pre-range config
    config_data[0] = VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR;
    config_data[1] = 0x10; // Example value
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing pre-range config\n");
        return -1;
    }

    // Example: Configure final range config
    config_data[0] = VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN;
    config_data[1] = 0x04; // Example value
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing final range config\n");
        return -1;
    }

    // Example: Start ranging
    config_data[0] = VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG;
    config_data[1] = 0x01; // Example value
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

int vl53l1x_read_distance(int i2c_handle) {
    // Implement VL53L1X distance reading here
    // This is a simplified example - refer to the VL53L1X datasheet for the complete sequence

    char reg = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    char data[2];
    char write_data[1];

    // Write the register address to be read
    write_data[0] = reg;
    if (i2cWriteDevice(i2c_handle, write_data, 1) != 0) {
        fprintf(stderr, "Error writing register address for distance reading\n");
        return -1;
    }

    // Read the distance data (2 bytes)
    if (i2cReadDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    // Combine the two bytes to form the distance value
    int distance = (data[0] << 8) | data[1];

    return distance;
}

void set_servo_angle(int angle) {
    // Map angle (0-180) to PWM duty cycle (500-2500)
    int duty_cycle = (int)(((float)angle / 180.0) * 2000.0) + 500;
    gpioPWM(SERVO_GPIO, duty_cycle);
}

void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        printf("MQTT connected to %s:%d\n", MQTT_HOST, MQTT_PORT);
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
    }
}

void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    printf("MQTT disconnected with code %d\n", rc);
}

void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        printf("Received message on topic %s: %s\n", message->topic, payload);

        if (strcmp(payload, "force_open") == 0) {
            set_servo_angle(OPEN_ANGLE);
            log_event("Received force_open command");
            mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen("ack_force_open"), "ack_force_open", 0, false);
        } else if (strcmp(payload, "force_close") == 0) {
            set_servo_angle(CLOSE_ANGLE);
            log_event("Received force_close command");
            mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen("ack_force_close"), "ack_force_close", 0, false);
        } else if (strcmp(payload, "status_request") == 0) {
            // Implement status reporting (e.g., distance, gate state)
            int distance = vl53l1x_read_distance(i2c_handle);
            char status_message[100];
            snprintf(status_message, sizeof(status_message), "Distance: %d mm, Gate State: %s", distance, gate_state ? "open" : "closed");

            mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(status_message), status_message, 0, false);
            log_event("Received status_request command");
        }
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    log_event("Caught signal, cleaning up...");

    // Close I2C device
    i2cClose(i2c_handle);

    // Stop servo motor
    gpioServo(SERVO_GPIO, 0);

    // Disconnect from MQTT broker
    mosquitto_disconnect(mosq);
    mosquitto_loop_stop(mosq, false);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

