#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TRIG_PIN 23
#define ECHO_PIN 24

#define SPEED_OF_SOUND 0.0343 // cm/us

#define TIMEOUT_US 60000       // 60 ms timeout
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000

volatile unsigned int rising_tick = 0;
volatile unsigned int falling_tick = 0;

volatile int echo_received = 0;

FILE *log_file = NULL;

void signal_handler(int signal);

int init_gpio();
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_pulse_width(unsigned int rising, unsigned int falling);
double calculate_distance(double pulse_width);
void log_distance(double distance);
void timeout_handler();

int main() {
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        trigger_pulse();
        echo_received = 0; // Reset echo flag

        // Wait for echo or timeout
        int timeout_count = 0;
        while (echo_received == 0 && timeout_count < 10) {
            gpioDelay(1000); // Check every 1 ms
            timeout_count++;
        }

        if (echo_received == 0) {
            timeout_handler();
            continue; // Skip distance calculation and retry
        }

        // Calculate pulse width and distance
        double pulse_width = calculate_pulse_width(rising_tick, falling_tick);
        double distance = calculate_distance(pulse_width);

        // Validate and log distance
        if (distance > 0 && distance < 400) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        gpioDelay(200000); // 200 ms delay (5 Hz)
    }

    return 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Enable pull-down resistor

    // Set alert function for ECHO pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO pin\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        rising_tick = tick;
        echo_received = 1; // Set echo received flag
    } else if (level == 0) {
        falling_tick = tick;
    }
}

double calculate_pulse_width(unsigned int rising, unsigned int falling) {
    unsigned int diff = falling - rising;

    // Handle tick rollover
    if (diff > 0xFFFFFFFF) {
        diff -= 0xFFFFFFFF;
    }

    return (double)diff;
}

double calculate_distance(double pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stdout, "%s Distance: %.2f cm\n", timestamp, distance);
    fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Flush the buffer to ensure immediate write
}

void timeout_handler() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stderr, "%s Timeout: No echo received within 60 ms\n", timestamp);
    fprintf(log_file, "%s Timeout: No echo received within 60 ms\n", timestamp);
    fflush(log_file);
}

void signal_handler(int signal) {
    printf("Caught signal %d. Exiting cleanly.\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

