#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INTERRUPT_PIN 24
#define SERVO_PIN 18

// Define I2C address
#define VL53L1X_I2C_ADDR 0x29

// Define distance thresholds (in mm)
#define OPEN_THRESHOLD 500
#define CLOSE_THRESHOLD 600

// Define servo pulse width limits (in us)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Global variables
int i2c_handle;
FILE *log_file;
volatile int gate_open = 0; // 0 = closed, 1 = open

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_servo(int open);
void log_event(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(VL53L1X_INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("parking_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance\n");
            // Attempt to re-initialize the sensor
            if (init_vl53l1x() != 0) {
                fprintf(stderr, "VL53L1X re-initialisation failed\n");
            }
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        control_servo(gate_open);
        log_event(distance);

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    i2c_handle = i2cOpen(1, VL53L1X_I2C_ADDR, 0); // I2C bus 1, address 0x29, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor model ID (example)
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID\n");
        i2cClose(i2c_handle);
        return -1;
    }

    if (model_id != 0xEA) { // Expected model ID for VL53L1X
        fprintf(stderr, "Incorrect model ID: 0x%02x\n", model_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Shutdown the sensor
    gpioWrite(VL53L1X_SHUTDOWN_PIN, 0);
    gpioDelay(100); // Delay for 100ms

    // Configure VL53L1X for short-range mode (example)
    char config_data[2];
    config_data[0] = 0x00; // Example register address
    config_data[1] = 0x01; // Example configuration value

    if (i2cWriteI2CBlockData(i2c_handle, 0x02d8, config_data, 2) != 2) {
        fprintf(stderr, "Error writing to VL53L1X\n");
        i2cClose(i2c_handle);
        return -1;
    }

    gpioWrite(VL53L1X_SHUTDOWN_PIN, 1);
    gpioDelay(100); // Delay for 100ms

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    char cmd;
    char data[2];
    int distance;

    // Start a single measurement
    cmd = 0x01; // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, cmd) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete

    // Read range status
    if (i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS) < 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Control servo motor
void control_servo(int open) {
    int pulse_width;

    if (open) {
        pulse_width = SERVO_MAX_PULSE_WIDTH; // Open gate
    } else {
        pulse_width = SERVO_MIN_PULSE_WIDTH; // Close gate
    }

    gpioPWM(SERVO_PIN, pulse_width);
}

// Log gate event
void log_event(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Distance: %d mm, Gate: %s\n", timestamp, distance, gate_open ? "Open" : "Closed");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Stop servo motor
    gpioPWM(SERVO_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

