#include <pigpio.h>
#include <stdint.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define DISTANCE_THRESHOLD_FORWARD 100 // mm
#define DISTANCE_THRESHOLD_BACKWARD 300 // mm
#define DATA_READY_REG 0x0089
#define DISTANCE_MSB_REG 0x0096
#define DISTANCE_LSB_REG 0x0097

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int read_distance(int *distance);
void control_motor(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// VL53L1X initialization function
int vl53l1x_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset command.\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Start measurement
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write start measurement command.\n");
        return -1;
    }

    return 0;
}

// Function to read distance from VL53L1X
int read_distance(int *distance) {
    int data_ready;
    int msb, lsb;

    // Poll for data ready
    int timeout = 0;
    do {
        data_ready = i2cReadByteData(i2c_handle, DATA_READY_REG);
        if (data_ready < 0) {
            fprintf(stderr, "Error: Failed to read data ready status.\n");
            return -1;
        }
        if (!(data_ready & 0x01)) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout++;
            if (timeout > 100) { // Timeout after 100ms
                fprintf(stderr, "Error: Data not ready after timeout.\n");
                return -1;
            }
        }
    } while (!(data_ready & 0x01));

    // Read distance data
    msb = i2cReadByteData(i2c_handle, DISTANCE_MSB_REG);
    if (msb < 0) {
        fprintf(stderr, "Error: Failed to read distance MSB.\n");
        return -1;
    }

    lsb = i2cReadByteData(i2c_handle, DISTANCE_LSB_REG);
    if (lsb < 0) {
        fprintf(stderr, "Error: Failed to read distance LSB.\n");
        return -1;
    }

    *distance = (msb << 8) | lsb;

    return 0;
}

