    if (distance < DISTANCE_THRESHOLD_FORWARD) {
        gpioWrite(MOTOR_FORWARD, 1);
        gpioWrite(MOTOR_BACKWARD, 0);
        printf("Motor: Forward\n");
    } else if (distance > DISTANCE_THRESHOLD_BACKWARD) {
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 1);
        printf("Motor: Backward\n");
    } else {
        gpioWrite(MOTOR_FORWARD, 0);
        gpioWrite(MOTOR_BACKWARD, 0);
        printf("Motor: Stopped\n");
    }
}

