#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for LEDs
#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

// Define I2C address for MPR121
#define MPR121_ADDR 0x5A

// Define MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0 0x5E
#define MPR121_ELECONFIG1 0x5D
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E

// Define LED patterns
const uint8_t led_patterns[12] = {
    0b0000, // ELE0: No touch
    0b0001, // ELE1: LED1 on
    0b0010, // ELE2: LED2 on
    0b0100, // ELE3: LED3 on
    0b1000, // ELE4: LED4 on
    0b0001, // ELE5: LED1 & LED2 on
    0b0100, // ELE6: LED3 on
    0b1000, // ELE7: LED4 on
    0b0001, // ELE8: LED1 & LED2 on
    0b0100, // ELE9: LED3 on
    0b1000, // ELE10: LED4 on
    0b1100  // ELE11: All LEDs on
};

int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Verify sensor presence by reading a known register
    int sensor_id = i2cReadByteData(i2c_handle, 0x00);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: Could not read sensor ID.\n");
        return -1;
    }
    if (sensor_id != 0x5A) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%X\n", sensor_id);
        return -1;
    }

    // Configure MPR121 for proximity sensing
    if (i2cWriteByteData(i2c_handle, MPR121_ELECONFIG0, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to write to ELECONFIG0.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_ELECONFIG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to ELECONFIG1.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to MHDR.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write to NHDR.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to write to NCLR.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write to FDLR.\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    int touch_status_high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Function to set the LED patterns based on the touch status
void set_led_patterns(int touch_status) {
    for (int i = 0; i < 12; i++) {
        if (touch_status & (1 << i)) {
            gpioWrite(LED1_PIN, (led_patterns[i] >> 0) & 1);
            gpioWrite(LED2_PIN, (led_patterns[i] >> 1) & 1);
            gpioWrite(LED3_PIN, (led_patterns[i] >> 2) & 1);
            gpioWrite(LED4_PIN, (led_patterns[i] >> 3) & 1);
        } else {
            gpioWrite(LED1_PIN, 0);
            gpioWrite(LED2_PIN, 0);
            gpioWrite(LED3_PIN, 0);
            gpioWrite(LED4_PIN, 0);
        }
    }
}

// Function to log the touch event
void log_touch_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Electrode %d touched\n", timestamp, electrode);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);
    gpioSetMode(LED3_PIN, PI_OUTPUT);
    gpioSetMode(LED4_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        set_led_patterns(touch_status);

        for (int i = 0; i < 12; i++) {
            if (touch_status & (1 << i)) {
                log_touch_event(i);
            }
        }

        if (touch_status == 0) {
            printf("No electrode touched\n");
        }

        gpioDelay(50000); // Poll every 50ms
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

