// Initialize the MPR121 sensor
int mpr121_init() {
    // Set ECR register to enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, MPR121_ECR_VALUE) < 0) {
        fprintf(stderr, "Error writing to ECR register\n");
        return -1;
    }

    // Configure touch and release thresholds for electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0, 0x0A) < 0) {
