        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    led_off(); // Ensure LED is off initially

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity detector running. Press Ctrl+C to exit.\n");

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check if electrode 0 is touched
            if (mpr121_is_electrode_touched(touch_status, 0)) {
                printf("Proximity detected!\n");
                log_proximity_event();
                led_on();
                gpioDelay(1000); // 1 second delay
                led_off();
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    led_off(); // Ensure LED is off before exiting
    gpioTerminate();

    return 0;
}

