#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000        // 30 ms
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

// Global variables
static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
int wait_echo_rising(void);
int measure_pulse_width(void);
float calculate_distance(int pulse_width);
int log_distance(float distance);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT)
    {
        keep_running = 0;
    }
}

// Initialize GPIO lines
int init_gpio(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line)
    {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line)
    {
        perror("Error getting echo line");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "distance_sensor", 0) < 0)
    {
        perror("Error requesting trigger line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "distance_sensor") < 0)
    {
        perror("Error requesting echo line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return -1;
    }

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse(void)
{
    gpiod_line_set_value(trigger_line, 0);
    usleep(5); // 5 us
    gpiod_line_set_value(trigger_line, 1);
    usleep(10); // 10 us
    gpiod_line_set_value(trigger_line, 0);
}

// Wait for the echo rising edge with timeout
int wait_echo_rising(void)
{
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1)
    {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0)
        {
            perror("Error reading echo line");
            return -1;
        }

        if (value == 1)
        {
            return 0; // Echo rising edge detected
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000L + (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000)
        {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1; // Timeout
        }
    }
}

// Measure the echo pulse width with timeout
int measure_pulse_width(void)
{
    struct timespec start, end;
    int pulse_width_us = 0;
    int timeout = 0;

    if (wait_echo_rising() < 0)
    {
        return -1; // Error or timeout waiting for rising edge
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1)
    {
        int value = gpiod_line_get_value(echo_line);
        if (value < 0)
        {
            perror("Error reading echo line");
            return -1;
        }

        if (value == 0)
        {
            clock_gettime(CLOCK_MONOTONIC, &end);
            pulse_width_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            return pulse_width_us;
        }

        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ns = (now.tv_sec - start.tv_sec) * 1000000000L + (now.tv_nsec - start.tv_nsec);
        if (elapsed_ns > TIMEOUT_US * 1000)
        {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1; // Timeout
        }
    }
}

// Calculate distance in centimeters
float calculate_distance(int pulse_width)
{
    if (pulse_width < 0)
    {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Log distance to file with timestamp
int log_distance(float distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    }
    else
    {
        perror("Error: Log file is NULL");
        return -1;
    }
}

// Cleanup GPIO resources
void cleanup(void)
{
    if (trigger_line)
    {
        gpiod_line_release(trigger_line);
    }
    if (echo_line)
    {
        gpiod_line_release(echo_line);
    }
    if (chip)
    {
        gpiod_chip_close(chip);
    }
    if (log_file)
    {
        fclose(log_file);
    }
}

int main(void)
{
    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0)
    {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL)
    {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Distance sensor started. Press Ctrl+C to exit.\n");

    while (keep_running)
    {
        trigger_pulse();
        int pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance > MIN_DISTANCE && distance < MAX_DISTANCE)
        {
            if (log_distance(distance) == 0)
            {
                printf("Distance: %.2f cm\n", distance);
            }
            else
            {
                fprintf(stderr, "Error logging distance.\n");
            }
        }
        else
        {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            if (log_file != NULL)
            {
                fprintf(log_file, "Error: Invalid distance reading: %.2f cm\n", distance);
                fflush(log_file);
            }
        }

        usleep(1000000); // 1 second delay
    }

    printf("Exiting...\n");
    cleanup();
    return 0;
}

