#define TRIG_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"

volatile unsigned int pulse_start = 0;
volatile unsigned int pulse_end = 0;
volatile int echo_received = 0;

FILE *log_file = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate that an echo is being received
    } else if (level == 0 && echo_received == 1) {
        pulse_end = tick;
        echo_received = 0; // Reset the flag
    }
}

float calculate_distance(unsigned int pulse_width) {
    return (float)pulse_width * 343.0 / 2000000.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN to input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        gpioWrite(TRIG_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIG_PIN, 0);

        gpioDelay(1000); // Wait 1 ms before next trigger

        if (pulse_end > pulse_start && pulse_end - pulse_start > 58 && pulse_end - pulse_start < 25000) {
            unsigned int pulse_width = pulse_end - pulse_start;
            float distance = calculate_distance(pulse_width);
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, Distance: %.2f meters\n", timestamp, distance);
            fflush(log_file); // Ensure data is written to file immediately
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s, Invalid Echo Pulse Width\n", timestamp);
            fflush(log_file);
        }
    }

    return 0;
}

