#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define CMD_CONTINUOUS_MODE 0x0018
#define CMD_NO_TIMEOUT 0x0019
#define CMD_START_RANGING 0x0020
#define RESULT_DISTANCE_MM 0x0014
#define RESULT_STATUS 0x0016

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance, uint8_t *status);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Write configuration commands
    if (i2cWriteByteData(i2c_handle, CMD_CONTINUOUS_MODE, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write continuous mode command.");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CMD_NO_TIMEOUT, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write no timeout command.");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CMD_START_RANGING, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write start ranging command.");
        return -1;
    }

    return 0;
}

// Read distance and status from the sensor
int read_distance(uint16_t *distance, uint8_t *status) {
    char buffer[3];

    // Read distance (2 bytes) and status (1 byte) from registers 0x0014 and 0x0016
    if (i2cReadI2CBlockData(i2c_handle, RESULT_DISTANCE_MM, buffer, 3) != 3) {
        syslog(LOG_ERR, "Failed to read distance and status.");
        return -1;
    }

    // Combine the bytes to form the distance and status values
    *distance = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    *status = (uint8_t)buffer[2];

    return 0;
}

// Log the data to syslog
void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "Timestamp: %s, Distance: %d mm, Status: 0x%02X", timestamp, distance, status);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open syslog
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure XSHUT GPIO as output
    gpioSetMode(XSHUT_GPIO, PI_OUTPUT);
    gpioWrite(XSHUT_GPIO, 1); // Enable sensor

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device.");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        syslog(LOG_ERR, "Sensor initialization failed.");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    uint16_t distance;
    uint8_t status;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance, &status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance, retrying...");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

