#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20.0 // cm
#define LOG_FILE "gate_log.txt"

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD 0x001E
#define VL53L1X_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE 0x001F
#define VL53L1X_REG_FINAL_CROSSTALK_COMPENSATION_PEAK_RATE_MCPS 0x0033
#define VL53L1X_REG_FINAL_CROSSTALK_COMPENSATION_VALLEY_RATE_MCPS 0x0034
#define VL53L1X_REG_SIGNAL_RATE_LIMIT 0x0035
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_STOP_MEASURE 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0083
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1 0x0097

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
float convert_mm_to_cm(int mm);
void control_gate(float distance);
void log_data(float distance, int gate_state, const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int model_id;

    // Check sensor ID
    model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        log_data(0, -1, "Error reading model ID");
        return -1;
    }
    if (model_id != 0xEA) {
        log_data(0, -1, "Incorrect model ID");
        return -1;
    }

    // Configure sensor (example settings - adjust as needed)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD, 0xBB) < 0) {
        log_data(0, -1, "Error writing ROI_CONFIG_USER_ROI_CENTRE_SPAD");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE, 0x10) < 0) {
        log_data(0, -1, "Error writing ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_CROSSTALK_COMPENSATION_PEAK_RATE_MCPS, 0x00) < 0) {
        log_data(0, -1, "Error writing FINAL_CROSSTALK_COMPENSATION_PEAK_RATE_MCPS");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_CROSSTALK_COMPENSATION_VALLEY_RATE_MCPS, 0x00) < 0) {
        log_data(0, -1, "Error writing FINAL_CROSSTALK_COMPENSATION_VALLEY_RATE_MCPS");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SIGNAL_RATE_LIMIT, 0x00) < 0) {
        log_data(0, -1, "Error writing SIGNAL_RATE_LIMIT");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, 0x00) < 0) {
        log_data(0, -1, "Error writing I2C_SLAVE_DEVICE_ADDRESS");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        log_data(0, -1, "Error writing RANGING_MODE");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_STOP_MEASURE, 0x01) < 0) {
        log_data(0, -1, "Error writing START_STOP_MEASURE");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    unsigned char data[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
    if (result < 0) {
        log_data(0, -1, "Error reading distance data");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Convert mm to cm
float convert_mm_to_cm(int mm) {
    return (float)mm / 10.0;
}

// Control the gate actuator
void control_gate(float distance) {
    static int gate_state = 0; // 0 = closed, 1 = open

    if (distance < DISTANCE_THRESHOLD && gate_state == 0) {
        gpioWrite(GPIO_GATE, 1); // Open gate
        gate_state = 1;
        log_data(distance, gate_state, "Gate opened");
    } else if (distance >= DISTANCE_THRESHOLD && gate_state == 1) {
        gpioWrite(GPIO_GATE, 0); // Close gate
        gate_state = 0;
        log_data(distance, gate_state, "Gate closed");
    }
}

// Log data to file
void log_data(float distance, int gate_state, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] Distance: %.2f cm, Gate: %s, Message: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, gate_state ? "OPEN" : "CLOSED", message);
    fflush(log_file);
}

int main() {
    int distance_mm;
    float distance_cm;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for gate actuator
    gpioSetMode(GPIO_GATE, PI_OUTPUT);
    gpioWrite(GPIO_GATE, 0); // Initialize gate to closed state

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_data(0, -1, "Error opening I2C bus");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_data(0, -1, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance_mm) == 0) {
            distance_cm = convert_mm_to_cm(distance_mm);

            // Control gate
            control_gate(distance_cm);

            // Log data
            log_data(distance_cm, gpioRead(GPIO_GATE), "OK");
        } else {
            log_data(0, -1, "Error reading distance");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_GATE, 0); // Ensure gate is closed on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

