#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define SERVO_CENTER 1500
#define TIMEOUT_US 30000 // 30 ms

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int valid_pulse = 0;
volatile int distance_index = 0;
double distance_history[5] = {0.0};
double moving_average = 0.0;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width_us);
double apply_moving_average(double new_value);
int map_distance_to_angle(double distance);
int map_angle_to_pulse_width(int angle);
void log_data(double distance, int angle);
void signal_handler(int signal);

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Alert callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        valid_pulse = 0; // Reset valid_pulse flag
    } else if (level == 0) {
        pulse_end = tick;
        valid_pulse = 1; // Set valid_pulse flag
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width_us) {
    if (pulse_width_us < 0) return -1.0; // Indicate invalid reading
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0;
}

// Function to apply a 5-sample moving average filter
double apply_moving_average(double new_value) {
    distance_history[distance_index] = new_value;
    distance_index = (distance_index + 1) % 5;

    double sum = 0.0;
    for (int i = 0; i < 5; i++) {
        sum += distance_history[i];
    }
    return sum / 5.0;
}

// Function to map distance to servo angle using a logarithmic function
int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1; // Indicate invalid reading

    // Logarithmic mapping (adjust these values to fine-tune the mapping)
    double log_distance = log10(distance / MIN_DISTANCE);
    double angle = 180.0 * log_distance / log10(MAX_DISTANCE / MIN_DISTANCE);

    return (int)angle;
}

// Function to map angle to pulse width (in microseconds)
int map_angle_to_pulse_width(int angle) {
    return (int)(((double)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
}

// Function to log data to a CSV file
void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range for servo (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 20000); // Set range to 20000 for better resolution

    // Register alert callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Trigger the ultrasonic sensor
        trigger_pulse();

        // Wait for a short period to allow the echo pulse to be received
        gpioDelay(100); // Wait 100 ms

        // Calculate pulse width
        int pulse_width_us = pulse_end - pulse_start;

        // Handle wrap-around
        if (pulse_end < pulse_start) {
            pulse_width_us = (0xFFFFFFFF - pulse_start) + pulse_end;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width_us);

        // Apply moving average filter
        if (distance > 0) {
            moving_average = apply_moving_average(distance);
        } else {
            moving_average = -1.0; // Indicate invalid reading
        }

        // Map distance to servo angle
        int angle = map_distance_to_angle(moving_average);

        // Map angle to pulse width
        int pulse_width = map_angle_to_pulse_width(angle);

        // Command the servo
        int result = gpioServo(SERVO_PIN, pulse_width);
        if (result != 0) {
            fprintf(stderr, "Error setting servo pulse width: %d\n", result);
            angle = 90; // Default to center position
            pulse_width = map_angle_to_pulse_width(angle);
            gpioServo(SERVO_PIN, pulse_width); // Re-set to default
        }

        // Log the data
        log_data(moving_average, angle);

        // Wait before the next iteration
        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioServo(SERVO_PIN, SERVO_CENTER); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

