#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for the warning LED
#define WARNING_LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 10

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void add_to_buffer(int distance);
int get_latest_reading();
void check_distance_and_set_led(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(WARNING_LED_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance >= 0) {
            add_to_buffer(distance);
            check_distance_and_set_led(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(50); // 50 ms delay
    }

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    int status;

    // Check sensor ID (example)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, 0x00); // Dummy write to read
    if (status < 0) {
        fprintf(stderr, "Error writing to VL53L1X (ID): %d\n", status);
        return -1;
    }
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Example initialization sequence (refer to VL53L1X datasheet)
    status = i2cWriteByteData(i2c_handle, 0x02d8, 0x01); // Set bit 0 of 0x02d8
    if (status < 0) {
        fprintf(stderr, "Error writing to VL53L1X (init1): %d\n", status);
        return -1;
