// Read distance from VL53L1X sensor
int read_distance() {
    int distance = -1;
    int status;

    // Read distance from register 0x0050 (example)
    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, 0x00); // Dummy write to read
    if (status < 0) {
        fprintf(stderr, "Error writing to VL53L1X (read1): %d\n", status);
        return -1;
    }

    int range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %d\n", range_status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, 0x00); // Dummy write to read
    if (status < 0) {
        fprintf(stderr, "Error writing to VL53L1X (read2): %d\n", status);
        return -1;
    }

    distance = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }

    return distance;
}

// Add distance to circular buffer
void add_to_buffer(int distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Get latest reading from buffer
int get_latest_reading() {
    return distance_buffer[(buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE];
}

// Check distance and set LED
void check_distance_and_set_led(int distance) {
    if (distance < 200) {
        gpioWrite(WARNING_LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(WARNING_LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    // Turn off LED
    gpioWrite(WARNING_LED_PIN, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

