#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Si1102 Registers
#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_ALS_VIS_DATA0 0x08
#define SI1102_REG_ALS_VIS_DATA1 0x09
#define SI1102_REG_COMMAND 0x18
#define SI1102_REG_HW_KEY 0x07
#define SI1102_REG_MEAS_RATE0 0x08

// Commands
#define SI1102_CMD_RESET 0x01
#define SI1102_CMD_ALS_FORCE 0x06

// Global Variables
static int i2c_handle;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function Prototypes
int init_i2c(int bus, int address);
int init_gpio(int pin);
int init_sensor(int i2c_handle);
int read_proximity(int i2c_handle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void log_data(int proximity, const char *status);
void signal_handler(int signal);
void cleanup();

// Helper function to write a byte to an I2C register
int write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Helper function to read a byte from an I2C register
int read_register(int i2c_handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(i2c_handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            int addr = strtol(argv[i + 1], NULL, 16);
            if (addr >= 0x08 && addr <= 0x77) {
                i2c_address = addr;
            } else {
                fprintf(stderr, "Invalid I2C address: 0x%02X. Using default 0x%02X\n", addr, DEFAULT_I2C_ADDRESS);
            }
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atoi(argv[i + 1]);
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
            return 1;
        }
        i++; // Skip the value after -a or -t
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(I2C_BUS, i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(GPIO_PIN) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

int init_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

int init_sensor(int i2c_handle) {
    // Reset the sensor
    if (write_register(i2c_handle, SI1102_REG_COMMAND, SI1102_CMD_RESET) < 0) {
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (write_register(i2c_handle, SI1102_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_register(i2c_handle, SI1102_REG_MEAS_RATE0, 0x08) < 0) return -1; // Set measurement rate

    // Force a measurement
    if (write_register(i2c_handle, SI1102_REG_COMMAND, SI1102_CMD_ALS_FORCE) < 0) {
        return -1;
    }
    gpioDelay(10); // Wait for measurement to complete

    return 0;
}

int read_proximity(int i2c_handle) {
    uint8_t high_byte, low_byte;

    if (read_register(i2c_handle, SI1102_REG_ALS_VIS_DATA0, &high_byte) < 0) {
        return -1;
    }
    if (read_register(i2c_handle, SI1102_REG_ALS_VIS_DATA1, &low_byte) < 0) {
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    int proximity = read_proximity(i2c_handle);
    if (proximity >= 0) {
        log_data(proximity, (proximity > threshold) ? "ALERT" : "SAFE");
    } else {
        fprintf(stderr, "Error reading proximity value in interrupt handler\n");
    }
}

void log_data(int proximity, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, Proximity: %d, Status: %s\n", timestamp, proximity, status);
}

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

