#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 200.0    // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT 200000        // Timeout in microseconds (200 ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
float measure_distance();
float map_distance_to_frequency(float distance);
void generate_tone(float frequency);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM output
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT) {
        fprintf(stderr, "Error: Echo signal did not go low (timeout)\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (diff * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map distance to frequency using a logarithmic scale
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate error
    }

    float frequency = MIN_FREQUENCY * exp((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    return frequency;
}

// Function to generate a tone with a given frequency
void generate_tone(float frequency) {
    if (frequency < 0) {
        fprintf(stderr, "Error: Invalid frequency\n");
        return;
    }

    int range = 1000; // PWM range (adjust as needed)
    int duty_cycle = range / 2; // 50% duty cycle

    gpioSetPWMrange(SPEAKER_PIN, range);
    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial value)
    gpioSetPWMrange(SPEAKER_PIN, 1000);
    gpioSetPWMfrequency(SPEAKER_PIN, 1000); // Initial frequency

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance, frequency;

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (program_running) {
        distance = measure_distance();

        if (distance > 0) {
            frequency = map_distance_to_frequency(distance);

            if (frequency > 0) {
                generate_tone(frequency);
            } else {
                fprintf(stderr, "Error: Invalid frequency, using previous value\n");
            }
        } else {
            fprintf(stderr, "Error: Distance measurement failed, using previous frequency\n");
        }

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM output
    gpioTerminate();          // Terminate pigpio

    return 0;
}

