// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 5.0  // cm
#define MAX_DISTANCE 50.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz
#define TIMEOUT_US 100000 // 100 ms timeout
#define PULSE_WIDTH_US 10 // Trigger pulse width in microseconds

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
float readDistance();
float mapDistanceToFrequency(float distance);
void generateTone(float frequency);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioPWM(BUZZER_PIN, 0); // Stop PWM output
        gpioTerminate();       // Terminate pigpio
        terminate = 1;          // Set terminate flag
        exit(0);               // Exit program
    }
}

// Function to read distance from HC-SR04 sensor
float readDistance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor with a 10 us pulse
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(PULSE_WIDTH_US);
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width with microsecond precision
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo start.\n");
            return -1.0; // Indicate error
        }
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        diff_tick = end_tick - start_tick;
        if (diff_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Timeout waiting for echo end.\n");
            return -1.0; // Indicate error
        }
    }

    end_tick = gpioTick();
    diff_tick = end_tick - start_tick;

    // Calculate the pulse width in microseconds
    float pulse_width_us = (float)diff_tick / 1000.0;

    // Calculate the distance in centimeters (speed of sound: 343 m/s)
    float distance = pulse_width_us / 29.0 / 2.0; // cm

    return distance;
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linear mapping from distance to frequency
    float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp frequency to the defined range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to generate a tone on the buzzer
void generateTone(float frequency) {
    // Set the PWM frequency
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);

    // Set the PWM duty cycle (50% for square wave)
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle (0-255)
}

