    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (!terminate) {
        // Read distance from the sensor
        float distance = readDistance();

        // Check for errors
        if (distance < 0) {
            fprintf(stderr, "Error: Failed to read distance. Using last valid distance.\n");
            // In a real application, you might want to store the last valid distance
            // and use it here to avoid sudden silences.
