#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int pulse_width = gpioRead(ECHO_PIN), start_time, end_time;
        start_time = gpioTick();
        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - start_time > 50000) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                pulse_width = -1; // Indicate timeout
                break;
            }
        }
        if (pulse_width == -1) continue; // Skip if timeout

        start_time = gpioTick();
        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - start_time > 50000) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                pulse_width = -1; // Indicate timeout
                break;
            }
        }
        if (pulse_width == -1) continue; // Skip if timeout

        double distance = (pulse_width / 2.0) / 29.1;

        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf(" Too close!\n");
            } else {
                printf("\n");
            }
        }

        gpioDelay(500000); // 500 ms
    }

    gpioTerminate();
    return 0;
}

