#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8
#define DISTANCE_REG_L 0x0C
#define DISTANCE_REG_H 0x0D
#define MEASURE_REG 0x00
#define MEASURE_VALUE 0x01

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    uint8_t continuous_mode;
    uint8_t range;
} sensor_config_t;

// Function prototypes
int initialize_sensor(sensor_config_t config);
int read_distance(uint16_t *distance);
void log_data(uint16_t distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the sensor
int initialize_sensor(sensor_config_t config) {
    char tx_buf[2];
    char rx_buf[2];

    // Configure continuous measurement mode
    tx_buf[0] = MEASURE_REG;
    tx_buf[1] = config.continuous_mode;
    if (spiWrite(spi_handle, tx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to SPI during initialization.\n");
        return -1;
    }

    // Configure range
    tx_buf[0] = 0x02; // Register address
    tx_buf[1] = config.range;
    if (spiWrite(spi_handle, tx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to SPI during initialization.\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance(uint16_t *distance) {
    char tx_buf[1];
    char rx_buf[2];

    // Trigger measurement
    tx_buf[0] = MEASURE_REG;
    tx_buf[1] = MEASURE_VALUE;
    if (spiWrite(spi_handle, tx_buf, 2) != 0) {
        fprintf(stderr, "Error triggering measurement.\n");
        return -1;
    }

    // Wait for measurement to complete (adjust as needed)
    gpioDelay(1000); // 1 ms

    // Read distance data
    tx_buf[0] = DISTANCE_REG_L;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading low byte from SPI.\n");
        return -1;
    }

    tx_buf[0] = DISTANCE_REG_H;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading high byte from SPI.\n");
        return -1;
    }

    *distance = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Function to log data to a file
void log_data(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    sensor_config_t sensor_config = {0x01, 0x05}; // Continuous mode, 5m range
    uint16_t distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed!\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            if (distance >= 200 && distance <= 5000) {
                log_data(distance);
            } else {
                fprintf(stderr, "Distance out of range: %u mm\n", distance);
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

