    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return 0;
}

// Function to write a register to the Si1175
int si1175_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing register value");
        return -1;
    }
    return 0;
}

