#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 Register Addresses
#define REG_PART_ID 0x00
#define REG_RESET 0x30
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x18

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int read_als_data(uint16_t *als_data);
int read_proximity_data(uint16_t *proximity_data);
void log_data(uint16_t als_data, uint16_t proximity_data);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Si1120 sensor
int si1120_init() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Reset the sensor
        status = i2cWriteByteData(i2c_handle, REG_RESET, 0x01);
        if (status >= 0) {
            gpioDelay(10); // Wait for reset to complete
            break; // Exit retry loop if successful
        } else {
            fprintf(stderr, "Error resetting Si1120: %d. Retrying...\n", status);
            retries--;
            gpioDelay(10); // Wait before retrying
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
        if (part_id >= 0) {
            if (part_id == 0x41) {
                break; // Exit retry loop if successful
            } else {
                fprintf(stderr, "Error: Incorrect Part ID: 0x%02X. Expected 0x41.\n", part_id);
                retries--;
                gpioDelay(10);
            }
        } else {
            fprintf(stderr, "Error reading Part ID: %d. Retrying...\n", part_id);
            retries--;
            gpioDelay(10);
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read correct Part ID after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Reads ALS data from the Si1120
int read_als_data(uint16_t *als_data) {
    int retries = 3;
    int status;
    uint8_t low, high;

    while (retries > 0) {
        low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        if (low >= 0) {
            high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
            if (high >= 0) {
                *als_data = (uint16_t)((high << 8) | low);
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading ALS high byte: %d. Retrying...\n", high);
                retries--;
                gpioDelay(10);
            }
        } else {
            fprintf(stderr, "Error reading ALS low byte: %d. Retrying...\n", low);
            retries--;
            gpioDelay(10);
        }
    }

    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Reads proximity data from the Si1120
int read_proximity_data(uint16_t *proximity_data) {
    int retries = 3;
    int status;
    uint8_t low, high;

    while (retries > 0) {
        low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
        if (low >= 0) {
            high = i2cReadByteData(i2c_handle, REG_PS1_DATA0 + 1);
            if (high >= 0) {
                *proximity_data = (uint16_t)((high << 8) | low);
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading proximity high byte: %d. Retrying...\n", high);
                retries--;
                gpioDelay(10);
            }
        } else {
            fprintf(stderr, "Error reading proximity low byte: %d. Retrying...\n", low);
            retries--;
            gpioDelay(10);
        }
    }

    fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
    return -1; // Failure
}

// Logs the ALS and proximity data to a file
void log_data(uint16_t als_data, uint16_t proximity_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als_data, proximity_data);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    uint16_t als_data, proximity_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ALS and proximity data
        if (read_als_data(&als_data) == 0 && read_proximity_data(&proximity_data) == 0) {
            // Log the data
            log_data(als_data, proximity_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping log.\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

