#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define ALS_DATA_REG 0x22
#define PS_DATA_REG 0x24

volatile sig_atomic_t keep_running = 1;
FILE *log_file = NULL;
int i2c_fd = -1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int init_sensor(int fd) {
    uint8_t part_id;
    if (i2c_read_reg(fd, PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID. Check I2C connection.\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X. Expected 0x82.\n", part_id);
        return -1;
    }

    if (i2c_write_reg(fd, MEAS_RATE_REG, 0x07) != 0) {
        fprintf(stderr, "Failed to write to Measurement Rate Register.\n");
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t buf[4];
    if (i2c_read_regs(fd, ALS_DATA_REG, buf, 4) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
