#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_ADDR 0x60
#define I2C_BUS 1

int i2c_handle;
FILE *log_file;

// Function to write a byte to a specific register
int write_register(int handle, int reg, int value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error writing to register 0x%02X: %d. Retrying...\n", reg, result);
        time_sleep(0.01); // Wait 10ms before retrying
        retries--;
    }
    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read a byte from a specific register
int read_register(int handle, int reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result; // Success
        }
        fprintf(stderr, "Error reading from register 0x%02X: %d. Retrying...\n", reg, result);
        time_sleep(0.01); // Wait 10ms before retrying
        retries--;
    }
    fprintf(stderr, "Failed to read from register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to initialize the Si1145 sensor
int initialize_sensor(int handle) {
    if (write_register(handle, 0x07, 0x03) != 0) return -1; // HW_KEY
    if (write_register(handle, 0x06, 0x02) != 0) return -1; // MEAS_RATE
    if (write_register(handle, 0x1A, 0x00) != 0) return -1; // ALS_EN
    if (write_register(handle, 0x21, 0x0B) != 0) return -1; // PS_ADC_COUNTER
    if (write_register(handle, 0x22, 0x49) != 0) return -1; // ALS_VIS_ADC_GAIN
    if (write_register(handle, 0x24, 0x00) != 0) return -1; // ALS_VIS_ADC_GAIN
    if (write_register(handle, 0x0C, 0x03) != 0) return -1; // PS_LED21
    if (write_register(handle, 0x0F, 0x03) != 0) return -1; // PS_LED3
    if (write_register(handle, 0x11, 0x03) != 0) return -1; // PS_ADC_MISC
    if (write_register(handle, 0x0D, 0x07) != 0) return -1; // PS_ADC_GAIN
    if (write_register(handle, 0x80, 0x03) != 0) return -1; // COMMAND, PS_FORCE
    return 0;
}

// Function to read the proximity value from the sensor
int read_proximity(int handle) {
    int low = read_register(handle, 0x16);
    int high = read_register(handle, 0x17);

    if (low < 0 || high < 0) {
        return -1; // Indicate error
    }

    return (high << 8) | low;
}

// Function to log the proximity value to a file
void log_proximity(int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d\n", timestamp, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int proximity = read_proximity(i2c_handle);
        if (proximity >= 0) {
            log_proximity(proximity);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }
        time_sleep(0.1); // 100ms delay
    }

    return 0;
}

