#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm

// Global variables
volatile static unsigned int rising_edge_time = 0;
volatile static unsigned int falling_edge_time = 0;
volatile static int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully...\n");
        gpioTerminate();
        exit(0);
    }
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupts
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        rising_edge_time = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        falling_edge_time = tick;
        echo_received = 0; // Reset the flag

        // Calculate pulse width
        unsigned int pulse_width = falling_edge_time - rising_edge_time;

        // Calculate distance in centimeters
        float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;

        // Print distance to stdout
        printf("Distance: %.2f cm\n", distance);

        // Control the buzzer
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1); // Activate buzzer
        } else {
            gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse();
        gpioDelay(1000); // Wait 1 second
    }

    return 0;
}

