#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define PWM_FREQ 50 // Hz
#define PWM_RANGE 1000000 // Range for PWM duty cycle (0-1000000)

// VL53L1X Register Addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_INTERMEASUREMENT_PERIOD 0x001E
#define VL53L1X_REG_TIMING_BUDGET 0x0061

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// VL53L1X Initialization function
int vl53l1x_init() {
    // Check sensor ID
    char data[1];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Set timing budget (example: 33ms)
    char budget_data[2];
    budget_data[0] = VL53L1X_REG_TIMING_BUDGET;
    budget_data[1] = 0x33; // Timing budget register value
    if (i2cWriteI2CBlockData(i2c_handle, budget_data[0], &budget_data[1], 1) != 1) {
        fprintf(stderr, "Error setting timing budget\n");
        return -1;
    }

    // Set inter-measurement period (example: 100ms)
    char intermeas_data[2];
    intermeas_data[0] = VL53L1X_REG_INTERMEASUREMENT_PERIOD;
    intermeas_data[1] = 0x64; // Inter-measurement period register value
    if (i2cWriteI2CBlockData(i2c_handle, intermeas_data[0], &intermeas_data[1], 1) != 1) {
        fprintf(stderr, "Error setting inter-measurement period\n");
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading function
int vl53l1x_read_distance() {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    return (data[0] << 8) | data[1]; // Combine high and low bytes
}

// Servo control function
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < 0) pulse_width = 0;
    if (pulse_width > PWM_RANGE) pulse_width = PWM_RANGE;

    gpioPWM(SERVO_GPIO, pulse_width);
}

// Logging function
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for servo control
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQ);
    gpioSetPWMrange(SERVO_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int distance;
    int target_pulse_width = 1000; // Initial closed position
    int current_pulse_width = target_pulse_width;
    set_servo_pulse_width(current_pulse_width);

    // Main loop
    while (!terminate) {
        distance = vl53l1x_read_distance();
        if (distance > 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < 200) {
                if (current_pulse_width < target_pulse_width) {
                    current_pulse_width += 10; // Smoothly increase pulse width
                    if (current_pulse_width > target_pulse_width) current_pulse_width = target_pulse_width;
                    set_servo_pulse_width(current_pulse_width);
                    log_event("Gate opened");
                }
            } else if (distance > 250) {
                if (current_pulse_width > target_pulse_width) {
                    current_pulse_width -= 10; // Smoothly decrease pulse width
                    if (current_pulse_width < target_pulse_width) current_pulse_width = target_pulse_width;
                    set_servo_pulse_width(current_pulse_width);
                    log_event("Gate closed");
                }
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    set_servo_pulse_width(0); // Stop the servo
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

