#define MAX_ANGLE 180          // Maximum servo angle in degrees
#define SERVO_MIN_PULSE_WIDTH 500 // Minimum servo pulse width in us
#define SERVO_MAX_PULSE_WIDTH 2500 // Maximum servo pulse width in us

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
long get_pulse_duration();
float calculate_distance(long pulse_duration);
int map_distance_to_angle(float distance);
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate();          // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration with timeout
long get_pulse_duration() {
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    trigger_sensor();

    int timeout_counter = 0;
    while (!echo_received && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable alert function

    if (!echo_received) {
        return -1; // Timeout
    }

    return echo_end_tick - echo_start_tick;
}

// Callback function for echo pin alerts
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 1;
    }
}

// Function to calculate distance from pulse duration
float calculate_distance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error (timeout)
    }
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Distance in cm
}

// Function to map distance to servo angle
int map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE));
    }
}

// Function to set servo angle
void set_servo_angle(int angle) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        trigger_sensor();

        // Measure the echo pulse duration
        long pulse_duration = get_pulse_duration();

        // Calculate the distance
        float distance = calculate_distance(pulse_duration);

        if (distance < 0) {
            fprintf(stderr, "Timeout occurred. Distance measurement failed.\n");
        } else {
            // Map the distance to a servo angle
            int angle = map_distance_to_angle(distance);

            // Set the servo angle
            set_servo_angle(angle);

            // Print the distance and angle
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        // Delay for 100 ms
        gpioDelay(100000);
    }

    return 0;
}

