#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the Si7005 sensor
int init_si7005()
{
    // Write to the CONFIG register to configure the sensor
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_si7005(float *temperature, float *humidity)
{
    unsigned short raw_temperature, raw_humidity;

    // Read temperature
    raw_temperature = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Read humidity
    raw_humidity = i2cReadWordData(i2c_handle, HUMID_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Convert raw data to temperature and humidity
    *temperature = (175.72 * raw_temperature) / 65536.0 - 46.85;
    *humidity = (125.0 * raw_humidity) / 65536.0 - 6.0;

    return 0;
}

int main()
{
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si7005() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        if (read_si7005(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(2);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

