    while (1) {
        // Read ambient temperature
        int raw_ambient_temp = read_temperature(i2c_handle, TA_REG);
        if (raw_ambient_temp < 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
        } else {
            float ambient_temp = convert_to_celsius(raw_ambient_temp);

            // Read object temperature
            int raw_object_temp = read_temperature(i2c_handle, TO_REG);
            if (raw_object_temp < 0) {
                fprintf(stderr, "Failed to read object temperature\n");
            } else {
                float object_temp = convert_to_celsius(raw_object_temp);

                // Log the temperature data
                if (log_temperature(ambient_temp, object_temp) != 0) {
                    fprintf(stderr, "Failed to log temperature data\n");
                }

                printf("Ambient Temperature: %.2f C, Object Temperature: %.2f C\n", ambient_temp, object_temp);
            }
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

