#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x3608
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR_PRESSURE 60.0
#define SCALE_FACTOR_TEMPERATURE 200.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t checksum);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t cmd[2];
    cmd[0] = (command >> 8) & 0xFF;
    cmd[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Error sending command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == checksum);
}

// Read sensor data and perform CRC validation
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[DATA_LENGTH];

    if (send_command(handle, MEASURE_CMD) != 0) {
        return -1;
    }
    gpioDelay(1000); // Wait at least 1 ms

    if (read_data(handle, raw_data, DATA_LENGTH) != 0) {
        return -1;
    }

    // CRC validation
    if (!validate_crc(raw_data, 2, raw_data[2])) {
        fprintf(stderr, "Pressure CRC check failed!\n");
        return -1;
    }
    if (!validate_crc(raw_data + 3, 2, raw_data[5])) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }
    if (!validate_crc(raw_data + 6, 2, raw_data[8])) {
        fprintf(stderr, "Scale factors CRC check failed!\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    data->pressure = (float)raw_pressure / SCALE_FACTOR_PRESSURE;
    data->temperature = (float)raw_temperature / SCALE_FACTOR_TEMPERATURE;

    return 0;
}

