#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x28
#define TRIGGER_MEASUREMENT_CMD 0x2196
#define DATA_LENGTH 6
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int write_i2c_command(int handle, uint16_t command);
int read_i2c_data(int handle, char *data, int count);
int convert_raw_data(char *data, sensor_data_t *sensor_data);
int log_data(FILE *file, sensor_data_t sensor_data);
void signal_handler(int signal);

// Function to write an I2C command with retry logic
int write_i2c_command(int handle, uint16_t command) {
    int retries = 3;
    int delay_ms = 10;
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    while (retries > 0) {
        if (i2cWriteDevice(handle, buf, 2) == 2) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write failed. Retrying in %d ms...\n", delay_ms);
        gpioDelay(delay_ms * 1000); // pigpio delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// Function to read I2C data with retry logic
int read_i2c_data(int handle, char *data, int count) {
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (i2cReadDevice(handle, data, count) == count) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read failed. Retrying in %d ms...\n", delay_ms);
        gpioDelay(delay_ms * 1000); // pigpio delay in microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// Function to convert raw data to pressure and temperature
int convert_raw_data(char *data, sensor_data_t *sensor_data) {
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    sensor_data->pressure_pa = (float)raw_pressure / 60.0;
    sensor_data->temperature_c = (float)raw_temperature / 200.0;

    return 0;
}

// Function to log data to a file
int log_data(FILE *file, sensor_data_t sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.2f,%.2f\n", timestamp, sensor_data.pressure_pa, sensor_data.temperature_c) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(file); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    char data[DATA_LENGTH];
    sensor_data_t sensor_data;

    while (!terminate) {
        // Trigger measurement
        if (write_i2c_command(i2c_handle, TRIGGER_MEASUREMENT_CMD) != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue; // Skip to the next iteration
        }

        gpioDelay(1000); // Wait at least 1 ms

        // Read data
        if (read_i2c_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Failed to read data.\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        if (convert_raw_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Failed to convert raw data.\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(log_file, sensor_data) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(100000); // Sample every 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

