volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

int init_sensor() {
    if (i2cWriteByte(i2c_handle, TEMP_CMD) != 0) {
        fprintf(stderr, "Error writing temperature command: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    gpioDelay(10); // Wait for sensor to be ready
    if (i2cWriteByte(i2c_handle, HUM_CMD) != 0) {
        fprintf(stderr, "Error writing humidity command: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    gpioDelay(10); // Wait for sensor to be ready
    return 0;
}

