    char buf[2];
    int bytes_read;

    // Read temperature
    bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

