    bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading humidity data: %s\n", pigpio_error(i2c_handle));
        return -1;
    }
    *humidity = (buf[0] << 8) | buf[1];

    return 0;
}

