#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_write(int fd, uint16_t data);
int i2c_read(int fd, uint8_t count, uint8_t *buf);
int sdp800_trigger_measurement(int fd);
int sdp800_read_data(int fd, sensor_data_t *data);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
float convert_temperature(int16_t raw_temperature);
uint8_t crc8(const uint8_t *data, int len);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t data) {
    uint8_t buf[2];
    buf[0] = (data >> 8) & 0xFF;
    buf[1] = data & 0xFF;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t count, uint8_t *buf) {
    if (read(fd, buf, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// SDP800 trigger measurement function
int sdp800_trigger_measurement(int fd) {
    if (i2c_write(fd, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    usleep(45000); // Wait 45 ms
    return 0;
}

// SDP800 read data function
int sdp800_read_data(int fd, sensor_data_t *data) {
    uint8_t buf[9];
    if (i2c_read(fd, 9, buf) < 0) {
        fprintf(stderr, "Error reading data from sensor\n");
        return -1;
    }

    // Extract data and perform CRC check
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    data->scale_factor = (int16_t)((buf[6] << 8) | buf[7]);
    if (crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "Scale factor CRC check failed\n");
        return -1;
    }

    return 0;
}

// Convert raw pressure to Pa
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Convert raw temperature to °C
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to file
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    fflush(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (keep_running) {
        // Trigger measurement
        if (sdp800_trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read data
        if (sdp800_read_data(i2c_fd, &sensor_data) < 0) {
            fprintf(stderr, "Failed to read data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert data
        float pressure = convert_pressure(sensor_data.pressure, sensor_data.scale_factor);
        float temperature = convert_temperature(sensor_data.temperature);

        // Log data
        if (log_data(log_file, pressure, temperature) < 0) {
            fprintf(stderr, "Failed to log data. Exiting.\n");
            break;
        }

        usleep(100000); // Wait 100 ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

