        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    fflush(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (keep_running) {
        // Trigger measurement
        if (sdp800_trigger_measurement(i2c_fd) < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Read data
        if (sdp800_read_data(i2c_fd, &sensor_data) < 0) {
            fprintf(stderr, "Failed to read data. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert data
        float pressure = convert_pressure(sensor_data.pressure, sensor_data.scale_factor);
        float temperature = convert_temperature(sensor_data.temperature);

        // Log data
        if (log_data(log_file, pressure, temperature) < 0) {
            fprintf(stderr, "Failed to log data. Exiting.\n");
            break;
        }

        usleep(100000); // Wait 100 ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

