#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// High repeatability measurement command
#define MEASURE_HIGH_REPEATABILITY 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int sht40_read_data(int i2c_handle, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity data from SHT40
int sht40_read_data(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_HIGH_REPEATABILITY);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 8.5 ms
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for temperature data
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    // Validate CRC for humidity data
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = 100.0 * raw_humidity / 65535.0;

    return 0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read temperature and humidity
        result = sht40_read_data(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Log data
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

