#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60

// Structure for sensor readings
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(float *temperature, float *humidity);
void control_fan(float temperature);
void log_reading(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor(float *temperature, float *humidity) {
    char buf[2];
    int result;

    // Measure temperature
    result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for measurement (datasheet specifies 12.1ms)
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    uint16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;

    // Measure humidity
    result = i2cWriteByte(i2c_handle, HUMID_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(20); // Wait for measurement
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0; // Track fan state

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to log the sensor reading to the circular buffer
void log_reading(float temperature, float humidity) {
    buffer[buffer_index].timestamp = time(NULL);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("[%s] Temp: %.2f C, Humidity: %.2f %%\n", time_str, buffer[index].temperature, buffer[index].humidity);
    }
    printf("--------------------\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
    gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    while (!terminate) {
        if (read_sensor(&temperature, &humidity) == 0) {
            log_reading(temperature, humidity);
            control_fan(temperature);
            print_buffer();
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        sleep(2);
    }

    return 0;
}

