#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SCD40_ADDR 0x62
#define I2C_BUS 1

int i2c_handle;
FILE *log_file;

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SCD40
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    int result;

    // Check data ready
    char cmd[2] = {0xE4, 0xB8};
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing data ready command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait for data ready

    // Read data
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Verify CRC
    for (int i = 0; i < 4; i++) {
        if (crc8(data + i * 2, 2) != data[i + 4]) {
            fprintf(stderr, "CRC check failed for data %d\n", i);
            return -1;
        }
    }

    // Convert data
    *co2 = (data[0] << 8) | data[1];
    *temperature = -45 + 175 * (*co2) / (65535 - 1);
    *humidity = 100 * (*co2) / (65535 - 1);

    return 0;
}

// Function to log data to file
void log_data(uint16_t co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

// Function to stop periodic measurement
void stop_periodic_measurement() {
    char cmd[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error stopping periodic measurement: %d\n", result);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping measurements and exiting.\n");
    stop_periodic_measurement();
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    uint16_t co2;
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handle
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C handle: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Start periodic measurement
    char cmd[2] = {0x21, 0xB1};
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SCD40 data\n");
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

