// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// CRC-8 checksum function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the circular buffer
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Function to add data to the circular buffer
void buffer_add(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void buffer_print(circular_buffer_t *buffer) {
    printf("Circular Buffer Contents:\n");
    int start = buffer->head;
    if (buffer->count == BUFFER_SIZE) {
        start = buffer->head;
    } else {
        start = 0;
    }

