#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to measure pulse widths with microsecond precision
int measure_pulse_widths(int gpio, int *th, int *tl) {
    int start_tick, end_tick, high_count, total_count;
    int i;

    // Wait for the signal to go high
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > 50000) { // 50ms timeout
            fprintf(stderr, "Error: Timeout waiting for signal to go high.\n");
            return -1; // Indicate timeout error
        }
    }
    start_tick = gpioTick();

    high_count = 0;
    total_count = 0;

    while (gpioRead(gpio) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > 50000) { // 50ms timeout
            fprintf(stderr, "Error: Timeout waiting for signal to go low.\n");
            return -1; // Indicate timeout error
        }
        total_count++;
    }
    end_tick = gpioTick();

    *th = end_tick - start_tick;
    *tl = end_tick - start_tick + total_count;

    return 0; // Indicate success
}

// Function to convert pulse widths to temperature in Celsius
double convert_to_celsius(int th, int tl) {
    if (tl == 0) {
        fprintf(stderr, "Error: Division by zero in temperature conversion.\n");
        return -999.0; // Indicate error
    }
    return 4215.0 - (2143.0 * (double)th / (double)tl);
}

// Function to log temperature data to a file
int log_temperature(double temperature) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return -1; // Indicate error
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0; // Indicate success
}

int main() {
    int th, tl;
    double temperature;
    int consecutive_failures = 0;
    const int max_consecutive_failures = 3;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Measure pulse widths
        if (measure_pulse_widths(GPIO_PIN, &th, &tl) == 0) {
            // Convert pulse widths to temperature
            temperature = convert_to_celsius(th, tl);

            if (temperature > -40.0 && temperature < 150.0) {
                // Log temperature data
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error: Failed to log temperature data.\n");
                }
                consecutive_failures = 0; // Reset failure counter
            } else {
                fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", temperature);
                consecutive_failures++;
            }
        } else {
            fprintf(stderr, "Error: Failed to measure pulse widths.\n");
            consecutive_failures++;
        }

        if (consecutive_failures >= max_consecutive_failures) {
            fprintf(stderr, "SENSOR MALFUNCTION\n");
            log_temperature(-999.0); // Log the error
            consecutive_failures = 0; // Reset the counter after logging the error
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Clean up and exit
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

