        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Measure pulse widths
        if (measure_pulse_widths(GPIO_PIN, &th, &tl) == 0) {
            // Convert pulse widths to temperature
            temperature = convert_to_celsius(th, tl);

            if (temperature > -40.0 && temperature < 150.0) {
                // Log temperature data
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error: Failed to log temperature data.\n");
                }
                consecutive_failures = 0; // Reset failure counter
            } else {
                fprintf(stderr, "Error: Temperature reading out of range: %.2f\n", temperature);
                consecutive_failures++;
            }
        } else {
            fprintf(stderr, "Error: Failed to measure pulse widths.\n");
            consecutive_failures++;
        }

        if (consecutive_failures >= max_consecutive_failures) {
            fprintf(stderr, "SENSOR MALFUNCTION\n");
            log_temperature(-999.0); // Log the error
            consecutive_failures = 0; // Reset the counter after logging the error
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Clean up and exit
    gpioTerminate();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

