float apply_sinusoidal_offset(float base_value, float amplitude, float period) {
    float time_in_seconds = time(NULL);
    float time_fraction = time_in_seconds % period / period;
    return base_value + amplitude * (0.5 * (1.0 + sin(2.0 * M_PI * time_fraction)));
}

