        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 2, sensor_data[2]) && validate_crc(sensor_data + 3, 2, sensor_data[5])) {
                // Convert raw data
                uint16_t raw_temp = (sensor_data[0] << 8) | sensor_data[1];
                uint16_t raw_humidity = (sensor_data[3] << 8) | sensor_data[4];

                processed_data.temperature = convert_temperature(raw_temp);
                processed_data.humidity = convert_humidity(raw_humidity);

                // Apply sinusoidal offset
                processed_data.temperature = apply_sinusoidal_offset(processed_data.temperature, SINUSOIDAL_AMP_TEMP, SINUSOIDAL_PERIOD);
                processed_data.humidity = apply_sinusoidal_offset(processed_data.humidity, SINUSOIDAL_AMP_HUM, SINUSOIDAL_PERIOD);

