#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the continuous measurement command
#define MEASURE_CMD 0x362F

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables for graceful shutdown
int i2c_handle = -1;
FILE *fp = NULL;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function to calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send the continuous measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for the conversion time (45 ms)
    gpioDelay(50000); // 50 ms

    // Read 9 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate the CRC checksums
    if (crc8(buffer, 2) != buffer[2] ||
        crc8(buffer + 3, 2) != buffer[5] ||
        crc8(buffer + 6, 2) != buffer[8]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    // Extract the raw data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

// Function to convert raw data to pressure and temperature
void convert_data(const sensor_data_t *raw_data, float *pressure, float *temperature) {
    // Conversion formulas from the SDP810 datasheet
    *pressure = (float)raw_data->pressure / (float)raw_data->scale_factor;
    *temperature = (float)raw_data->temperature / (float)raw_data->scale_factor;
}

// Function to log data to a CSV file
void log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp); // Ensure data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for logging
    fp = fopen("airflow.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(fp);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t raw_data;
    float pressure, temperature;

    // Main loop
    while (1) {
        // Read data from the sensor
        if (read_sdp810(i2c_handle, &raw_data) == 0) {
            // Convert the raw data
            convert_data(&raw_data, &pressure, &temperature);

            // Log the data
            log_data(pressure, temperature);

            printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

