    }

    // Validate CRC checksums
    if (!validate_crc(raw_data[0], raw_data[1], raw_data[2]) ||
        !validate_crc(raw_data[3], raw_data[4], raw_data[5])) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int temperature_raw = (raw_data[0] << 8) | raw_data[1];
    int humidity_raw = (raw_data[3] << 8) | raw_data[4];

    data->temperature = -45.0 + 175.0 * temperature_raw / 65535.0;
    data->humidity = 100.0 * humidity_raw / 65535.0;

    return 0;
}

