    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

