    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("environment.csv", "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty or contains only the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    } else if (file_size == 1) {
        char header[32];
        fread(header, 1, 31, fp);
        if (strncmp(header, "timestamp", 10) == 0) {
            fprintf(fp, ",temperature_c,humidity_pct\n");
        } else {
            fprintf(stderr, "Invalid CSV file format\n");
            fclose(fp);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            log_data(fp, sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    // Clean up and exit
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

