#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define RESET_CMD 0xFE
#define MEASURE_TEMP_HOLD 0xF3
#define MEASURE_HUMID_HOLD 0xF5
#define PAIR_TEMP_HUMID 0xE0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0x00

int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function to handle signals
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Function to reset the Si7021 sensor
int reset_sensor(int fd) {
    uint8_t buf[2];
    buf[0] = RESET_CMD;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing reset command");
        return -1;
    }
    usleep(10000); // Wait for reset to complete
    return 0;
}

// Function to read data from the Si7021 sensor
int read_sensor_data(int fd, uint8_t command, uint8_t *data, int len) {
    uint8_t buf[1];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing measurement command");
        return -1;
    }
    usleep(10000); // Wait for measurement to complete

    int retries = 0;
    while (retries < 5) {
        if (read(fd, data, len) == len) {
            return 0; // Success
        } else {
            perror("Error reading sensor data");
            retries++;
            usleep(10000); // Wait before retrying
        }
    }
    return -1; // Failure after retries
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw) {
    return 175.72 * raw / 65536.0 - 46.85;
}

// Function to convert raw humidity to percentage
float convert_humidity(uint16_t raw) {
    return 125.0 * raw / 65536.0 - 6.0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, SI7021_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Reset the sensor
    if (reset_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Failed to reset sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        uint16_t raw_humidity, raw_temperature;
        float temperature, humidity;

        // Measure humidity
        if (read_sensor_data(i2c_fd, MEASURE_HUMID_HOLD, data, 3) == 0) {
            raw_humidity = (data[0] << 8) | data[1];
            uint8_t crc = crc8(data, 2);
            if (crc == data[2]) {
                humidity = convert_humidity(raw_humidity);
            } else {
                fprintf(stderr, "Humidity CRC error!\n");
                humidity = -999.0; // Indicate error
            }
        } else {
            humidity = -999.0; // Indicate error
        }

        // Measure temperature (paired reading)
        if (read_sensor_data(i2c_fd, PAIR_TEMP_HUMID, data, 3) == 0) {
            raw_temperature = (data[0] << 8) | data[1];
            uint8_t crc = crc8(data, 2);
            if (crc == data[2]) {
                temperature = convert_temperature(raw_temperature);
            } else {
                fprintf(stderr, "Temperature CRC error!\n");
                temperature = -999.0; // Indicate error
            }
        } else {
            temperature = -999.0; // Indicate error
        }

        // Log the data
        if (log_data(log_file, temperature, humidity) < 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

