    pressure_crc = buffer[2];
    raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    temperature_crc = buffer[5];

    // CRC validation
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t temp_data[2] = {buffer[3], buffer[4]};

    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC error!\n");
        return -1;
    }

    if (crc8(temp_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC error!\n");
        return -1;
    }

    // Convert data to physical units
    data->pressure = (float)raw_pressure / 240.0 - 1000.0; // Pa
    data->temperature = (float)raw_temperature / 200.0 - 45.0; // °C

    return 0;
}

