            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 1 second
    }

    // Cleanup
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

