#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the continuous measurement command
#define MEASUREMENT_COMMAND 0x3603

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the scale factor for pressure conversion
#define PRESSURE_SCALE_FACTOR 60.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int count);
int validate_crc(uint8_t data[], int len);
float convert_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Function to log the pressure data to a file
int log_data(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file);
    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send the continuous measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(50); // Wait for conversion (45 ms)

        // Read the sensor data
        if (read_sensor_data(i2c_handle, data, 9) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate the CRC checksums
        if (!validate_crc(data, 2) || !validate_crc(data + 3, 2) || !validate_crc(data + 6, 2)) {
            fprintf(stderr, "CRC validation failed!\n");
            continue;
        }

        // Extract the raw pressure value
        sensor_data.pressure = (int16_t)((data[0] << 8) | data[1]);

        // Convert the raw pressure to Pascals
        float pressure = convert_pressure(sensor_data.pressure);

        // Log the data
        if (log_data(pressure) != 0) {
            fprintf(stderr, "Error logging data!\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

