#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // Hz
#define PWM_RANGE 1000000   // Range for PWM duty cycle (0-1000000)
#define SLPM_MIN 0.0
#define SLPM_MAX 10.0
#define COUNTS_MIN 1638
#define COUNTS_MAX 14745

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *raw_data);
float convert_to_flow_rate(uint14_t raw_flow);
void set_fan_speed(float flow_rate);
void log_data(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Reads sensor data from the Honeywell Zephyr HAF Series sensor
int read_sensor_data(int i2c_handle, uint16_t *raw_data) {
    char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate error
    }

    *raw_data = (buffer[0] << 8) | buffer[1];
    // Mask off status bits (bits 15 and 14)
    *raw_data = (*raw_data >> 2) & 0x3FFF;

    return 0; // Indicate success
}

// Converts the raw sensor reading to flow rate using the linear transfer function
float convert_to_flow_rate(uint14_t raw_flow) {
    float flow_rate = (float)(raw_flow - COUNTS_MIN) * (SLPM_MAX - SLPM_MIN) / (COUNTS_MAX - COUNTS_MIN) + SLPM_MIN;
    return flow_rate;
}

// Sets the fan speed based on the flow rate using PWM
void set_fan_speed(float flow_rate) {
    int duty_cycle;

    if (flow_rate <= SLPM_MIN) {
        duty_cycle = 0;
    } else if (flow_rate >= SLPM_MAX) {
        duty_cycle = PWM_RANGE;
    } else {
        duty_cycle = (int)(((flow_rate - SLPM_MIN) / (SLPM_MAX - SLPM_MIN)) * PWM_RANGE);
    }

    gpioPWM(FAN_GPIO, duty_cycle);
}

