}

// Reads sensor data from the Honeywell Zephyr HAF Series sensor
int read_sensor_data(int i2c_handle, uint16_t *raw_data) {
    char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1; // Indicate error
    }

    *raw_data = (buffer[0] << 8) | buffer[1];
    // Mask off status bits (bits 15 and 14)
    *raw_data = (*raw_data >> 2) & 0x3FFF;

    return 0; // Indicate success
