#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize LPS33HW sensor
int init_lps33hw() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0xB1\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0); // Block data update, 10 Hz, active mode
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    return 0;
}

// Read pressure data from LPS33HW
int read_pressure(int32_t *pressure) {
    char buffer[3];
    int status = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (status < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", status);
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[2]) << 16) | (((uint32_t)buffer[1]) << 8) | ((uint32_t)buffer[0]));
    *pressure = *pressure >> 8; // Sign extend 24-bit value

    return 0;
}

// Read temperature data from LPS33HW
int read_temperature(int16_t *temperature) {
    char buffer[2];
    int status = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", status);
        return -1;
    }

    *temperature = (int16_t)(((uint16_t)buffer[1] << 8) | ((uint16_t)buffer[0]));

    return 0;
}

// Convert raw pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(fp);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_pressure;
    int16_t raw_temperature;
    float pressure_hpa, temperature_celsius;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&raw_pressure) == 0 && read_temperature(&raw_temperature) == 0) {
            // Convert data
            pressure_hpa = convert_pressure(raw_pressure);
            temperature_celsius = convert_temperature(raw_temperature);

            // Log data
            log_data(pressure_hpa, temperature_celsius);

            printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", pressure_hpa, temperature_celsius);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 ms = 1 second
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

