#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from STLM75
float read_temperature() {
    int raw_data;
    float temperature;

    raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_data);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Swap bytes and right-shift
    int16_t swapped_data = ((raw_data & 0xFF) << 8) | ((raw_data & 0xFF00) >> 8);
    swapped_data = swapped_data >> 7;

    temperature = (float)swapped_data / 2.0;

    return temperature;
}

// Function to calculate the running average of the temperature readings
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            float average_temperature = calculate_average();
            control_led(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Skipping temperature reading due to error.\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

