}

// Initialize SCD30 sensor
int initialize_scd30() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    // Add CRC check to the command
    uint8_t crc = crc8((uint8_t *)buf, 2);
    buf[2] = crc;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", result);
        return 1;
    }

    gpioDelay(10); // Wait for the command to be processed
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    // Add CRC check to the command
    uint8_t crc = crc8((uint8_t *)buf, 2);
    buf[2] = crc;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write start periodic measurement command: %d\n", result);
        return 1;
    }

    gpioDelay(10); // Wait for the command to be processed
    return 0;
}

// Check if data is ready
int is_data_ready() {
    char buf[2];
    buf[0] = (CMD_GET_DATA_READY >> 8) & 0xFF;
    buf[1] = CMD_GET_DATA_READY & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write get data ready command: %d\n", result);
        return 0; // Return 0 to avoid blocking the main loop
    }

    gpioDelay(1); // Small delay before reading the response

    char read_buf[3];
    result = i2cReadDevice(i2c_handle, read_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read data ready response: %d\n", result);
        return 0; // Return 0 to avoid blocking the main loop
    }

    uint16_t data_ready = (read_buf[0] << 8) | read_buf[1];
    return (data_ready & 0x0001); // Check if data is ready
