int read_scd30_data(sensor_data_t *data) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

    // Add CRC check to the command
    uint8_t crc = crc8((uint8_t *)buf, 2);
    buf[2] = crc;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return 1;
    }

    gpioDelay(1); // Small delay before reading the data

    char read_buf[18];
    result = i2cReadDevice(i2c_handle, read_buf, 18);
    if (result != 18) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return 1;
    }

    // CRC Check for each value
    for (int i = 0; i < 6; i++) {
        if (crc8((uint8_t *)read_buf + i * 4, 4) != read_buf[i * 4 + 4]) {
            fprintf(stderr, "CRC check failed for value %d\n", i);
            return 1;
        }
    }

