    uint32_t co2_raw = (read_buf[0] << 24) | (read_buf[1] << 16) | (read_buf[2] << 8) | read_buf[3];
    uint32_t temperature_raw = (read_buf[6] << 24) | (read_buf[7] << 16) | (read_buf[8] << 8) | read_buf[9];
    uint32_t humidity_raw = (read_buf[12] << 24) | (read_buf[13] << 16) | (read_buf[14] << 8) | read_buf[15];

    data->co2 = *(float*)&co2_raw;
    data->temperature = *(float*)&temperature_raw;
    data->humidity = *(float*)&humidity_raw;

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to file
void log_data(const sensor_data_t *data, int ventilation_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, data->co2, data->temperature, data->humidity, ventilation_level);
    fflush(log_file);
}

// Ventilation control based on CO2 level
int ventilation_control(float co2) {
    if (co2 < 800.0) {
        return VENTILATION_OFF;
    } else if (co2 < 1199.0) {
        return VENTILATION_LOW;
    } else {
        return VENTILATION_HIGH;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

