    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / (float)scale_factor;
}

// Log data with timestamp
void log_data(float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
}

int main(int argc, char *argv[]) {
    int interval = 1000; // Default interval

    // Parse command-line arguments
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval. Using default (1000 ms).\n");
            interval = 1000;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, CMD_MEASURE) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    char buffer[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_data(i2c_handle, buffer, 9) == 0) {
            // Extract raw data
            sensor_data.pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
            sensor_data.temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
            sensor_data.scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

            // Verify CRC checksums
            if (verify_crc((uint8_t *)buffer, 9)) {
                // Convert raw data to physical units
                float pressure = convert_pressure(sensor_data.pressure, sensor_data.scale_factor);

                // Log the data
                log_data(pressure);
            } else {
                fprintf(stderr, "CRC checksum error\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the specified interval
        gpioDelay(interval * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

