sensor_data_t convert_data(const char *data) {
    sensor_data_t sensor_data;
    // Extract raw values and scale factors
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t scale_factor_pressure = (data[6] << 8) | data[7];

    // Convert raw values to physical units
    sensor_data.pressure = (float)raw_pressure / (float)scale_factor_pressure;
    sensor_data.temperature = (float)raw_temperature / 200.0;

    return sensor_data;
}

