#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

int hdc1000_init(int fd) {
    unsigned char config_data[2];
    config_data[0] = CONFIG_REG;
    config_data[1] = 0x00; // Enable temperature and humidity measurement, 14-bit resolution

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, config_data, 2) != 2) {
        perror("Failed to write to configuration register");
        return -1;
    }

    return 0;
}

int hdc1000_read_data(int fd, float *temperature, float *humidity) {
    unsigned char data[4];
    unsigned short raw_temperature, raw_humidity;

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, (unsigned char[]){TEMP_REG}, 1) != 1) {
        perror("Failed to write to temperature register");
        return -1;
    }

    if (read(fd, data, 4) != 4) {
        perror("Failed to read temperature and humidity data");
        return -1;
    }

    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (hdc1000_init(fd) < 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        close(fd);
        return 1;
    }

    float temperature, humidity;
    while (keep_running) {
        if (hdc1000_read_data(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity.\n");
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

