// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xE3
#define TEMP_RESOLUTION 0.05
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read temperature from Si7051
float read_temperature() {
    char buf[2];
    int result;

    // Send temperature measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Wait for measurement to complete (datasheet says 20ms max)
    gpioDelay(25000); // 25 ms

    // Read two bytes of temperature data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    unsigned int raw_temp = (buf[0] << 8) | buf[1];
    float temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return temperature;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) {
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying...\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

