#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x63

// Define the command to trigger a high-precision measurement
#define MEASURE_CMD 0x40

// Define the command to read calibration coefficients
#define CALIB_CMD 0x50

// Define the number of calibration coefficients
#define NUM_CALIB_COEFF 4

// Define the number of bytes to read for temperature and pressure
#define NUM_READ_BYTES 6

// Structure to hold calibration coefficients
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
} calib_coeff_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read calibration coefficients from the sensor
int read_calibration_coefficients(calib_coeff_t *coeff) {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_CMD, buf, 8);

    if (result < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %d\n", result);
        return -1;
    }

    coeff->c0 = (int32_t)((uint32_t)buf[0] << 24 | (uint32_t)buf[1] << 16 | (uint32_t)buf[2] << 8 | (uint32_t)buf[3]);
    coeff->c1 = (int32_t)((uint32_t)buf[4] << 24 | (uint32_t)buf[5] << 16 | (uint32_t)buf[6] << 8 | (uint32_t)buf[7]);

    return 0;
}

// Function to calculate the scale factors
void calculate_scale_factors(calib_coeff_t coeff, float *scale_factor_lut, float *scale_factor_h, float *scale_factor_p) {
    *scale_factor_lut = (float)coeff.c0 / 1048576.0f;
    *scale_factor_h = (float)coeff.c1 / 1048576.0f;
    *scale_factor_p = (float)(coeff.c00 - coeff.c10) / 1048576.0f;
}

// Function to trigger a high-precision measurement
int trigger_measurement() {
    int result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read temperature and pressure data
int read_temperature_pressure(float *temperature, float *pressure) {
    char buf[NUM_READ_BYTES];
    int result = i2cReadI2CBlockData(i2c_handle, 0, buf, NUM_READ_BYTES);

    if (result < 0) {
        fprintf(stderr, "Error reading temperature and pressure data: %d\n", result);
        return -1;
    }

    // Combine the bytes to form the raw temperature and pressure values
    int32_t raw_temperature = (int32_t)((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]);
    int32_t raw_pressure = (int32_t)((uint32_t)buf[3] << 24 | (uint32_t)buf[4] << 16 | (uint32_t)buf[5] << 8);

    // Apply the compensation formulas from the datasheet
    *temperature = (float)raw_temperature / 1048576.0f;
    *pressure = (float)raw_pressure / 1048576.0f;

    return 0;
}

// Function to log the temperature and pressure data with an ISO-8601 timestamp
void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    calib_coeff_t calib_coeff;
    float scale_factor_lut, scale_factor_h, scale_factor_p;
    float temperature, pressure;

    // Read calibration coefficients
    if (read_calibration_coefficients(&calib_coeff) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calculate the scale factors
    calculate_scale_factors(calib_coeff, &scale_factor_lut, &scale_factor_h, &scale_factor_p);

    // Main loop
    while (!terminate) {
        // Trigger a measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Continuing.\n");
            continue;
        }

        // Wait for 7 ms
        gpioDelay(7000);

        // Read temperature and pressure data
        if (read_temperature_pressure(&temperature, &pressure) != 0) {
            fprintf(stderr, "Failed to read temperature and pressure data. Continuing.\n");
            continue;
        }

        // Log the data
        log_data(temperature, pressure);

        // Wait for 5 seconds
        gpioDelay(5000000);
    }

    // Close the I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

