#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLYNOMIAL 0x31
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0

int i2c_fd;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint16_t data) {
    uint8_t buf[2];
    buf[0] = (data >> 8) & 0xFF;
    buf[1] = data & 0xFF;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

uint8_t crc8(const uint8_t *data, int len, uint8_t initial_value) {
    for (int i = 0; i < len; i++) {
        initial_value ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (initial_value & 0x80) {
                initial_value = (initial_value << 1) ^ CRC_POLYNOMIAL;
            } else {
                initial_value <<= 1;
            }
        }
    }
    return initial_value;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = i2c_open(I2C_BUS, SDP800_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    if (i2c_write(i2c_fd, CMD_CONTINUOUS_MEASUREMENT) < 0) {
        close(i2c_fd);
        return 1;
    }
    usleep(45000); // 45 ms

    uint8_t data[9];
