#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SCALE_FACTOR 0.01
#define MIN_PRESSURE 200.0
#define MAX_PRESSURE 250.0
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    double scale_factor;
    double min_pressure;
    double max_pressure;
    char *log_file_name;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_pressure(int handle, uint16_t *pressure);
double convert_to_kPa(uint16_t raw_pressure, double scale_factor);
void check_pressure_range(double pressure_kPa, double min_pressure, double max_pressure);
int log_data(FILE *file, double pressure_kPa);
void signal_handler(int signal);
int write_header(FILE *file);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02x: %s\n", bus, addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Read pressure data from the sensor
int read_pressure(int handle, uint16_t *pressure) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }

    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw pressure data to kPa
double convert_to_kPa(uint16_t raw_pressure, double scale_factor) {
    return (double)raw_pressure * scale_factor;
}

// Check if pressure is within safe range
void check_pressure_range(double pressure_kPa, double min_pressure, double max_pressure) {
    if (pressure_kPa < min_pressure || pressure_kPa > max_pressure) {
        fprintf(stderr, "Warning: Pressure %.2f kPa is outside the safe range (%f - %f) kPa!\n", pressure_kPa, min_pressure, max_pressure);
    }
}

// Log data to CSV file
int log_data(FILE *file, double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

// Write header to CSV file if it's a new file
int write_header(FILE *file) {
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    if (file_size == 0) {
        if (fprintf(file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX90821_ADDR,
        .scale_factor = SCALE_FACTOR,
        .min_pressure = MIN_PRESSURE,
        .max_pressure = MAX_PRESSURE,
        .log_file_name = LOG_FILE
    };

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    if (write_header(log_file) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_pressure;
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            double pressure_kPa = convert_to_kPa(raw_pressure, config.scale_factor);
            check_pressure_range(pressure_kPa, config.min_pressure, config.max_pressure);
            if (log_data(log_file, pressure_kPa) != 0) {
                break; // Exit loop on log file error
            }
        } else {
            fprintf(stderr, "Retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            continue; // Retry the read
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fprintf(stderr, "Closing I2C handle...\n");
    i2cClose(i2c_handle);
    fprintf(stderr, "Closing log file...\n");
    fclose(log_file);
    fprintf(stderr, "Terminating pigpio...\n");
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

