}

// Log data to CSV file
int log_data(FILE *file, double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

// Write header to CSV file if it's a new file
int write_header(FILE *file) {
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    if (file_size == 0) {
        if (fprintf(file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error writing header to log file: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX90821_ADDR,
        .scale_factor = SCALE_FACTOR,
        .min_pressure = MIN_PRESSURE,
        .max_pressure = MAX_PRESSURE,
        .log_file_name = LOG_FILE
    };

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    if (write_header(log_file) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_pressure;
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            double pressure_kPa = convert_to_kPa(raw_pressure, config.scale_factor);
            check_pressure_range(pressure_kPa, config.min_pressure, config.max_pressure);
            if (log_data(log_file, pressure_kPa) != 0) {
                break; // Exit loop on log file error
            }
        } else {
            fprintf(stderr, "Retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            continue; // Retry the read
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fprintf(stderr, "Closing I2C handle...\n");
    i2cClose(i2c_handle);
    fprintf(stderr, "Closing log file...\n");
    fclose(log_file);
    fprintf(stderr, "Terminating pigpio...\n");
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

