#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASUREMENT_INTERVAL 5 // seconds
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor(uint16_t *raw_temperature, uint16_t *raw_humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
int validate_data(uint16_t raw_temperature, uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;

        // Read sensor data
        if (read_sensor(&raw_temperature, &raw_humidity) == 0) {
            // Validate data
            if (validate_data(raw_temperature, raw_humidity) == 0) {
                // Convert data
                sensor_data.temperature = convert_temperature(raw_temperature);
                sensor_data.humidity = convert_humidity(raw_humidity);

                // Log data
                if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Invalid sensor data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next measurement interval
        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor(uint16_t *raw_temperature, uint16_t *raw_humidity) {
    char buf[4];
    int result;

    // Trigger measurement (write 0x00)
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return 1;
    }

    // Wait for measurement (at least 37ms)
    gpioDelay(50000); // 50 ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }

    // Extract raw temperature and humidity values
    *raw_humidity = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *raw_temperature = ((uint16_t)buf[2] << 6) | (buf[3] >> 2);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature * 165.0 / 16383.0 - 40.0;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return (float)raw_humidity * 100.0 / 16383.0;
}

// Validate sensor data
int validate_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    // Check status bits (first two bits of raw_humidity)
    int status = raw_humidity >> 6;
    if (status != 0) {
        fprintf(stderr, "Sensor status error: %d\n", status);
        return 1;
    }
    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    char log_entry[200];
    long file_size;

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Get current file size
    file_size = fileSize(LOG_FILE);

    // Truncate log file if it exceeds the size limit
    if (file_size > LOG_FILE_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open log file for truncation\n");
            return 1;
        }
        fclose(fp);
    }

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Format log entry
    snprintf(log_entry, sizeof(log_entry), "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);

    // Write log entry to file
    if (fputs(log_entry, fp) == EOF) {
        fprintf(stderr, "Failed to write to log file\n");
        fclose(fp);
        return 1;
    }

    // Close log file
    fclose(fp);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Ctrl+C pressed, exiting...\n");
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

