#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 4
#define TICK_TIME 3 // us
#define SYNC_PULSE_TICKS (56 * TICK_TIME)
#define MIN_NIBBLE_TICKS (36 * TICK_TIME)
#define MAX_NIBBLE_TICKS (813 * TICK_TIME)
#define CHECKSUM_ERROR -1
#define SENSOR_ABSENT -2

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    uint8_t status;
    uint32_t raw_pressure;
    int checksum_valid;
} sensor_data_t;

// Function prototypes
int init_gpio();
void cleanup_gpio();
int read_sent_data(sensor_data_t *data);
uint8_t calculate_checksum(const uint8_t *data, int len);
float convert_to_pressure(uint32_t raw_pressure);
void log_pressure(float pressure);
void signal_handler(int signal);

int main() {
    sensor_data_t sensor_data;
    float pressure;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        if (read_sent_data(&sensor_data) == 0) {
            pressure = convert_to_pressure(sensor_data.raw_pressure);
            sensor_data.checksum_valid = 1; // Assume valid after successful conversion
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Error reading SENT data.\n");
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor
    return 0;
}

void cleanup_gpio() {
    gpioTerminate();
}

int read_sent_data(sensor_data_t *data) {
    uint32_t pulse_widths[4];
    int i;

    // Synchronization pulse
    gpioDelay(SYNC_PULSE_TICKS);

    // Read status nibble
    pulse_widths[0] = gpioTick();
    gpioDelay(TICK_TIME);
    pulse_widths[1] = gpioTick();

    // Read data nibbles
    for (i = 0; i < 3; i++) {
        pulse_widths[i + 1] = gpioTick();
        gpioDelay(TICK_TIME);
        pulse_widths[i + 2] = gpioTick();
    }

    // Read checksum nibble
    pulse_widths[3] = gpioTick();
    gpioDelay(TICK_TIME);
    pulse_widths[4] = gpioTick();

    // Validate pulse widths
    for (i = 0; i < 4; i++) {
        if (pulse_widths[i + 1] - pulse_widths[i] < MIN_NIBBLE_TICKS || pulse_widths[i + 1] - pulse_widths[i] > MAX_NIBBLE_TICKS) {
            fprintf(stderr, "Error: Invalid pulse width for nibble %d\n", i);
            return -1; // Bus error
        }
    }

    // Decode data
    data->status = (uint8_t)((pulse_widths[1] - pulse_widths[0]) / TICK_TIME);
    data->raw_pressure = 0;
    for (i = 0; i < 3; i++) {
        data->raw_pressure = (data->raw_pressure << 1) | ((pulse_widths[i + 2] - pulse_widths[i + 1]) / TICK_TIME & 1);
    }

    // Calculate checksum
    uint8_t checksum_calculated = calculate_checksum((uint8_t*)data, 4);

    // Validate checksum
    if (checksum_calculated != (data->status & 0x0F)) {
        fprintf(stderr, "Error: Checksum mismatch. Calculated: 0x%02X, Received: 0x%02X\n", checksum_calculated, data->status & 0x0F);
        return CHECKSUM_ERROR; // Checksum error
    }

    return 0; // Success
}

uint8_t calculate_checksum(const uint8_t *data, int len) {
    uint8_t sum = 0;
    for (int i = 0; i < len; i++) {
        sum += data[i];
    }
    return sum & 0x0F; // Mask to 4 bits
}

float convert_to_pressure(uint32_t raw_pressure) {
    // Linear transfer function (example values, adjust as needed)
    float scale = 0.1; // Pa/unit
    float offset = 1000.0; // Pa

    return (float)raw_pressure * scale + offset;
}

void log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, Pressure: %.2f Pa\n", timestamp, pressure);
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

