    // Calculate checksum
    uint8_t checksum_calculated = calculate_checksum((uint8_t*)data, 4);

    // Validate checksum
    if (checksum_calculated != (data->status & 0x0F)) {
        fprintf(stderr, "Error: Checksum mismatch. Calculated: 0x%02X, Received: 0x%02X\n", checksum_calculated, data->status & 0x0F);
        return CHECKSUM_ERROR; // Checksum error
    }

    return 0; // Success
}

uint8_t calculate_checksum(const uint8_t *data, int len) {
    uint8_t sum = 0;
    for (int i = 0; i < len; i++) {
        sum += data[i];
    }
    return sum & 0x0F; // Mask to 4 bits
}

float convert_to_pressure(uint32_t raw_pressure) {
    // Linear transfer function (example values, adjust as needed)
    float scale = 0.1; // Pa/unit
    float offset = 1000.0; // Pa

    return (float)raw_pressure * scale + offset;
}

