        return -1;
    }

    // Convert raw temperature to Celsius
    *temperature = (float)raw_temperature * TEMP_SCALE;
    return 0;
}

// Write temperature to file
int write_temperature_to_file(float temperature) {
    unsigned char buffer[4];
    // Convert float to little-endian byte array
    buffer[0] = (unsigned char)(temperature & 0xFF);
    buffer[1] = (unsigned char)((temperature >> 8) & 0xFF);
    buffer[2] = (unsigned char)((temperature >> 16) & 0xFF);
    buffer[3] = (unsigned char)((temperature >> 24) & 0xFF);

    size_t bytes_written = fwrite(buffer, 1, 4, fp);
    if (bytes_written != 4) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

