    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read device ID
    int device_id = read_device_id();
    if (device_id != 0x0117) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    float temperature;
    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file.\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature.\n");
        }
        sleep(SLEEP_SECONDS);
    }

    // Clean up
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

