#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// High precision measurement command
#define SHT40_MEASURE_HIGH 0xFD

// Global variables for cleanup
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int sht40_read_data(int i2c_handle, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 validation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int sht40_read_data(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd = SHT40_MEASURE_HIGH;
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, cmd, 0); // Use i2cWriteByteData to send the command
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for at least 8.5 ms
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6); // Use i2cReadI2CBlockData to read the data
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return 0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor data
        result = sht40_read_data(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Log the data
            log_data(temperature, humidity);
            printf("Temperature: %.2f °C, Humidity: %.2f %%RH\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

