#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define SAMPLE_INTERVAL 5 // seconds
#define BUFFER_SIZE 100

int i2c_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Flush the buffer to file
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature from TMP117
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate an error
    }

    // Convert big-endian data to temperature (LSB = 0.0078125 °C)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * 0.0078125;
    return temperature;
}

// Function to add temperature to the circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to save the buffer to a file
int save_buffer_to_file() {
    FILE *fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return -1;
    }

    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to file!\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature logging started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read temperature
        float temperature = read_temperature();

        // Add to buffer
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(temperature);

            // Save buffer to file
            if (save_buffer_to_file() != 0) {
                fprintf(stderr, "Error saving buffer to file!\n");
            }
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    return 0; // This line will never be reached due to the infinite loop, but it's good practice to include it.
}

