// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 normal power measurement command
#define SHTC3_MEASURE_CMD 0x7866

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int shtc3_read_data(int i2c_handle, float *temperature, float *humidity);
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
int convert_data(uint16_t raw_temperature, uint16_t raw_humidity, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 validation function
int validate_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc = (crc << 1);
        }
    }
    return (crc == checksum) ? 0 : -1; // 0 for success, -1 for failure
}

// Function to read data from SHTC3 sensor
int shtc3_read_data(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    uint16_t raw_temperature, raw_humidity;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, (SHTC3_MEASURE_CMD >> 8) & 0xFF, SHTC3_MEASURE_CMD & 0xFF) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command to SHTC3.\n");
        return -1;
    }

    // Wait for conversion (at least 12.4 ms)
    gpioDelay(15000); // 15 ms

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read data from SHTC3.\n");
        return -1;
    }

    // Validate CRC for temperature data
    if (validate_crc(data, 2, data[2]) != 0) {
        fprintf(stderr, "Error: Temperature CRC validation failed.\n");
        return -1;
    }

    // Validate CRC for humidity data
    if (validate_crc(data + 3, 2, data[5]) != 0) {
        fprintf(stderr, "Error: Humidity CRC validation failed.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    if (convert_data(raw_temperature = (data[0] << 8) | data[1], raw_humidity = (data[3] << 8) | data[4], temperature, humidity) != 0) {
        fprintf(stderr, "Error: Failed to convert raw data to temperature and humidity.\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
int convert_data(uint16_t raw_temperature, uint16_t raw_humidity, float *temperature, float *humidity) {
    // Conversion formulas from SHTC3 datasheet
    *temperature = 175.0 * raw_temperature / 65535.0 - 45.0;
    *humidity = 100.0 * raw_humidity / 65535.0;

    // Validate temperature range
    if (*temperature < -40.0 || *temperature > 125.0) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", *temperature);
        return -1;
    }

    // Validate humidity range
    if (*humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", *humidity);
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write to log file
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

