#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_REG 0x01 // Example register address for magnetic field
#define TEMP_REG 0x02 // Example register address for temperature
#define MAG_SCALE 0.1
#define TEMP_OFFSET -25.0
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int16_t *magnetic_field, int16_t *temperature);
float convert_magnetic_field(int16_t raw_value);
float convert_temperature(int16_t raw_value);
int log_data(float magnetic_field, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from Si7202
int read_sensor_data(int16_t *magnetic_field, int16_t *temperature) {
    char buf[4];
    int bytes_read;

    // Read magnetic field
    bytes_read = i2cReadI2CBlockData(i2c_handle, MAG_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading magnetic field data: %d\n", bytes_read);
        return -1;
    }
    *magnetic_field = (buf[0] << 8) | buf[1];

    // Read temperature
    bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw magnetic field data to Gauss
float convert_magnetic_field(int16_t raw_value) {
    return raw_value * MAG_SCALE;
}

// Convert raw temperature data to Celsius
float convert_temperature(int16_t raw_value) {
    return raw_value * TEMP_OFFSET;
}

// Log data to CSV file
int log_data(float magnetic_field, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, magnetic_field, temperature);
    fclose(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data logging... Press Ctrl+C to exit.\n");

    while (!terminate) {
        int16_t raw_magnetic_field, raw_temperature;

        // Read sensor data
        if (read_sensor_data(&raw_magnetic_field, &raw_temperature) == 0) {
            // Convert data
            float magnetic_field = convert_magnetic_field(raw_magnetic_field);
            float temperature = convert_temperature(raw_temperature);

            // Log data
            if (log_data(magnetic_field, temperature) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Logging NaN values.\n");
            log_data(NaN, NaN);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

