    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to read temperature from TMP117
float read_temperature() {
    int raw_temp;
    int retries = 3;

    while (retries > 0) {
        raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_temp >= 0) {
            // Convert raw temperature to Celsius
            float temp = (float)raw_temp * TEMP_SCALE;
            return temp;
        } else {
            fprintf(stderr, "Error reading temperature: %d. Retrying...\n", raw_temp);
            retries--;
            time_sleep(0.1); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -273.15; // Return absolute zero as error indicator
}

