                fprintf(log_file, "%s", "Error re-opening I2C device\n");
                fflush(log_file);
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

