#include <time.h>
#include <signal.h>
#include <string.h>

#define DHT11_PIN 4 // BCM GPIO 4
#define TIMEOUT_US 100000 // 100 ms timeout

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

// Function to log errors to a file
void log_error(const char *message) {
    FILE *fp = fopen("dht11_errors.log", "a");
    if (fp == NULL) {
        perror("Error opening error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to log data to a file
void log_data(float temperature, float humidity) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        perror("Error opening data log file");
        log_error("Failed to open data log file.");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Temperature: %.1f\u00b0C, Humidity: %.1f%%\n", timestamp, temperature, humidity);
    fclose(fp);
}

// Function to read data from the DHT11 sensor
int read_dht11(int pin, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    long start_time, end_time;

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(18000); // 18 ms
    gpioWrite(pin, 1);
    gpioDelay(20);

    gpioSetMode(pin, PI_INPUT);

    start_time = gpioTick();
    while (gpioRead(pin) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for start signal (HIGH).");
            return -1; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(pin) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for start signal (LOW).");
            return -1; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(pin) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for start signal (HIGH after LOW).");
            return -1; // Timeout
        }
    }

    for (int i = 0; i < 40; i++) {
        start_time = gpioTick();
        while (gpioRead(pin) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data bit start (LOW).");
                return -1; // Timeout
            }
        }

        start_time = gpioTick();
        while (gpioRead(pin) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for data bit end (HIGH).");
                return -1; // Timeout
            }
        }

        end_time = gpioTick();
        if (end_time - start_time > 40) {
            data[bit_count / 8] <<= 1;
            if (end_time - start_time > 60) {
                data[bit_count / 8] |= 1;
            }
        } else {
            log_error("Timeout reading data bit duration.");
            return -1; // Timeout
        }
        bit_count++;
    }

    // Validate checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        log_error("Checksum failure.");
        return -2; // Checksum error
    }

    *humidity = (float)data[0];
    *temperature = (float)data[2];

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int result;

    while (!terminate) {
        result = read_dht11(DHT11_PIN, &temperature, &humidity);

        if (result == 0) {
            log_data(temperature, humidity);
        } else if (result == -1) {
            log_error("Timeout or error reading sensor data.");
        } else if (result == -2) {
            log_error("Checksum failure.");
        } else {
            log_error("Unknown error reading sensor data.");
        }

        gpioDelay(2000000); // 2 seconds
    }

    gpioTerminate();
    return 0;
}

