#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define I2C addresses for the ADPD105 sensors
#define ADPD105_ADDR1 0x64
#define ADPD105_ADDR2 0x65

// Define the I2C bus
#define I2C_BUS 1

// Define the CSV log file name
#define LOG_FILE "cct_log.csv"

// Define the register addresses for the ADPD105
#define ADPD105_REG_ID 0x00
#define ADPD105_REG_RED 0x64
#define ADPD105_REG_GREEN 0x66
#define ADPD105_REG_BLUE 0x68

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_register(int handle, uint8_t reg);
int i2c_write_register(int handle, uint8_t reg, uint8_t value);
int i2c_read_block(int handle, uint8_t reg, char *buf, int count);
int i2c_write_block(int handle, uint8_t reg, char *buf, int count);
int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
float calculate_average_cct(float cct1, float cct2);
int log_data(float average_cct);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C connections if they are open
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close the log file if it is open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read a single register from the ADPD105
int i2c_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single register to the ADPD105
int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a block of data from the ADPD105
int i2c_read_block(int handle, uint8_t reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a block of data to the ADPD105
int i2c_write_block(int handle, uint8_t reg, char *buf, int count) {
    int result = i2cWriteI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error writing block to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to read sensor data from the ADPD105
int read_sensor_data(int handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    if (i2c_read_block(handle, ADPD105_REG_RED, buf, 6) < 0) {
        return -1;
    }

    *red = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];
    *green = (uint16_t)buf[3] << 8 | (uint16_t)buf[2];
    *blue = (uint16_t)buf[5] << 8 | (uint16_t)buf[4];

    return 0;
}

// Function to calculate Correlated Color Temperature (CCT) using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    float X = (float)red / 65535.0;
    float Y = (float)green / 65535.0;
    float Z = (float)blue / 65535.0;

    float x = X - 0.3333;
    float y = Y - 0.3333;

    float n = x * x * 0.333333 + y * y * 0.333333;
    float k = 2.0 * x * y * 0.414666;

    float cct = 449.0 * (n + k) / (1.0 + n + k);

    return cct;
}

// Function to calculate the average CCT from two sensors
float calculate_average_cct(float cct1, float cct2) {
    return (cct1 + cct2) / 2.0;
}

// Function to log data to a CSV file
int log_data(float average_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the log file exists
    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (file_exists) {
        fclose(fp);
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write the header if the file is newly created
    if (!file_exists) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    // Write the data to the log file
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    // Close the log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connections to the ADPD105 sensors
    i2c_handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C connection to sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C connection to sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify the device ID register for both sensors
    int device_id1 = i2c_read_register(i2c_handle1, ADPD105_REG_ID);
    int device_id2 = i2c_read_register(i2c_handle2, ADPD105_REG_ID);

    if (device_id1 != 0x2A || device_id2 != 0x2A) {
        fprintf(stderr, "Error: Incorrect device ID. Sensor 1 ID: 0x%02X, Sensor 2 ID: 0x%02X\n", device_id1, device_id2);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1, cct2, average_cct;

        // Read sensor data from sensor 1
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) < 0) {
            fprintf(stderr, "Error reading sensor 1 data, skipping.\n");
            cct1 = -1.0; // Indicate error
        } else {
            cct1 = calculate_cct(red1, green1, blue1);
        }

        // Read sensor data from sensor 2
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) < 0) {
            fprintf(stderr, "Error reading sensor 2 data, skipping.\n");
            cct2 = -1.0; // Indicate error
        } else {
            cct2 = calculate_cct(red2, green2, blue2);
        }

        // Calculate the average CCT
        if (cct1 != -1.0 && cct2 != -1.0) {
            average_cct = calculate_average_cct(cct1, cct2);
        } else {
            average_cct = -1.0; // Indicate error
        }

        // Log the data
        if (log_data(average_cct) < 0) {
            fprintf(stderr, "Error logging data, skipping.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

