    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (file_exists) {
        fclose(fp);
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    // Write the header if the file is newly created
    if (!file_exists) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    // Write the data to the log file
    fprintf(log_file, "%s,%.2f\n", timestamp, average_cct);

    // Close the log file
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connections to the ADPD105 sensors
    i2c_handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C connection to sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C connection to sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Verify the device ID register for both sensors
    int device_id1 = i2c_read_register(i2c_handle1, ADPD105_REG_ID);
    int device_id2 = i2c_read_register(i2c_handle2, ADPD105_REG_ID);

    if (device_id1 != 0x2A || device_id2 != 0x2A) {
        fprintf(stderr, "Error: Incorrect device ID. Sensor 1 ID: 0x%02X, Sensor 2 ID: 0x%02X\n", device_id1, device_id2);
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint16_t red1, green1, blue1;
        uint16_t red2, green2, blue2;
        float cct1, cct2, average_cct;

        // Read sensor data from sensor 1
        if (read_sensor_data(i2c_handle1, &red1, &green1, &blue1) < 0) {
            fprintf(stderr, "Error reading sensor 1 data, skipping.\n");
            cct1 = -1.0; // Indicate error
        } else {
            cct1 = calculate_cct(red1, green1, blue1);
        }

        // Read sensor data from sensor 2
        if (read_sensor_data(i2c_handle2, &red2, &green2, &blue2) < 0) {
            fprintf(stderr, "Error reading sensor 2 data, skipping.\n");
            cct2 = -1.0; // Indicate error
        } else {
            cct2 = calculate_cct(red2, green2, blue2);
        }

        // Calculate the average CCT
        if (cct1 != -1.0 && cct2 != -1.0) {
            average_cct = calculate_average_cct(cct1, cct2);
        } else {
            average_cct = -1.0; // Indicate error
        }

        // Log the data
        if (log_data(average_cct) < 0) {
            fprintf(stderr, "Error logging data, skipping.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // 1000 milliseconds = 1 second
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

