#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 800.0
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 125.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_kPa;
    float temperature_C;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_raw_pressure(uint16_t *pressure);
int read_raw_temperature(uint16_t *temperature);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
int log_data(float pressure_kPa, float temperature_C);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw pressure data from the sensor
int read_raw_pressure(uint16_t *pressure) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }
    *pressure = (buf[0] << 8) | buf[1];
    return 0;
}

// Read raw temperature data from the sensor
int read_raw_temperature(uint16_t *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw pressure to kPa
float convert_pressure(uint16_t raw_pressure) {
    return (raw_pressure - 0) * (PRESSURE_MAX - PRESSURE_MIN) / (32767 - 0);
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return raw_temperature * 0.01 - 40.0;
}

// Log data to file
int log_data(float pressure_kPa, float temperature_C) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_kPa, temperature_C);
    fflush(log_file);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Tire Pressure Monitoring System started. Logging to pressure_log.txt\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_pressure, raw_temperature;

        // Read sensor data
        if (read_raw_pressure(&raw_pressure) == 0 && read_raw_temperature(&raw_temperature) == 0) {
            // Convert data
            float pressure_kPa = convert_pressure(raw_pressure);
            float temperature_C = convert_temperature(raw_temperature);

            // Log data
            log_data(pressure_kPa, temperature_C);

            printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure_kPa, temperature_C);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        // Wait 2 seconds
        sleep(2);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

