#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define TEMP_HIGH 28.0
#define TEMP_LOW 26.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);

// Function to read temperature from LM75B
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -100.0; // Indicate error
    }

    // Convert raw data to temperature (signed 9-bit format)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 7; // Shift right by 7 bits to get the 9-bit value
    float temperature = raw_temp * 0.5;

    return temperature;
}

// Function to calculate the running average of the temperature buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan based on the average temperature
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (average_temperature > TEMP_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Avg Temp: %.2f °C)\n", average_temperature);
    } else if (average_temperature < TEMP_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Avg Temp: %.2f °C)\n", average_temperature);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize temperature buffer with 0s
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0) { // Check for valid temperature reading
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            float average_temperature = calculate_average();
            printf("Current Temperature: %.2f °C, Average Temperature: %.2f °C\n", temperature, average_temperature);
            control_fan(average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan control.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

