#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

// Function to read temperature from STTS2004 sensor
float read_temperature(int fd) {
    unsigned char buf[2];
    int ret;

    ret = read(fd, buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error
    }

    int raw_temp = (buf[0] << 4) | (buf[1] >> 4); // Combine MSB and LSB, right-shift
    return raw_temp * 0.0625; // Convert to Celsius
}

// Function to set GPIO output
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO output: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

int main() {
    float temperature;
    int gpio_value;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "temperature_monitor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read temperature
        temperature = read_temperature(i2c_fd);
        if (temperature < -999.0) { // Error occurred
            fprintf(stderr, "Error reading temperature, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Determine GPIO value based on temperature
        if (temperature > 28.0) {
            gpio_value = 1; // LED on
        } else if (temperature < 27.0) {
            gpio_value = 0; // LED off
        } else {
            gpio_value = 0; // LED off
        }

        // Set GPIO output
        if (set_gpio_output(gpio_line, gpio_value) < 0) {
            fprintf(stderr, "Error setting GPIO output, exiting...\n");
            break; // Exit loop on error
        }

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        sleep(1); // Wait 1 second
    }

    // Cleanup (in case of error)
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return 0;
}

