#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the continuous measurement command
#define MEASUREMENT_COMMAND 0x362F

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the scale factor data offset
#define SCALE_FACTOR_OFFSET 8

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, int command);
int read_data(int handle, char *buffer, int count);
uint8_t crc8(const uint8_t *data, int len);
int read_sensor_data(int handle, sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, int command) {
    int result = i2cWriteByteData(handle, 0, command);
    if (result < 0) {
        fprintf(stderr, "Failed to send command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadI2CBlockData(handle, 0, buffer, count);
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return result;
}

// Function to calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data and validate CRC
int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[9];
    int result = read_data(handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read 9 bytes of data\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t raw_scale_factor = (buffer[6] << 8) | buffer[7];

    // Extract scale factor
    int scale_factor = raw_scale_factor & 0xFFFF;

    // Validate CRC for pressure
    uint8_t crc_pressure = crc8(buffer, 2);
    if (crc_pressure != buffer[2]) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t crc_temperature = crc8(buffer + 3, 2);
    if (crc_temperature != buffer[5]) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Convert raw values to physical units
    data->differential_pressure = (float)raw_pressure / scale_factor;
    data->temperature = (float)raw_temperature / 200.0f;

    return 0;
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    FILE *fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f, %.2f\n", timestamp, data.differential_pressure, data.temperature);
    fclose(fp);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for at least 45 ms
        gpioDelay(50000); // 50 ms

        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Log sensor data
        log_data(sensor_data);

        // Print sensor data to console
        printf("Differential Pressure: %.2f Pa, Temperature: %.2f °C\n", sensor_data.differential_pressure, sensor_data.temperature);

        // Delay before next measurement
        gpioDelay(100000); // 100 ms
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

