#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xF3
#define HUMID_MEASURE_CMD 0xF5
#define TEMP_ADJUST_CMD 0xE0
#define MEASUREMENT_DELAY_MS 20
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw temperature and humidity data from the sensor
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity) {
    char buf[2];
    int retries = 0;
    int result;

    // Measure temperature
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command (retry %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading temperature data (retry %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        *raw_temperature = (buf[0] << 8) | buf[1];
        break; // Success, exit retry loop
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Measure humidity
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, HUMID_MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing humidity command (retry %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading humidity data (retry %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        *raw_humidity = (buf[0] << 8) | buf[1];
        break; // Success, exit retry loop
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read humidity after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return 175.72 * raw_temperature / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return 125.0 * raw_humidity / 65536.0 - 6.0;
}

// Log data to file and stdout
int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
