    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Convert data
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);

            // Clamp humidity to 0-100%
            if (humidity < 0.0) humidity = 0.0;
            if (humidity > 100.0) humidity = 100.0;

            // Log data
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait 60 seconds
        gpioDelay(60 * 1000 * 1000); // Delay in microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

