#include <time.h>
#include <signal.h>
#include <string.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define HDC1080_TEMP_REG 0x00
#define HDC1080_CONFIG_REG 0x02

// Global variables for I2C handle and program termination
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the HDC1080 sensor
int init_hdc1080(int i2c_handle) {
    // Configure the HDC1080 for 14-bit temperature and humidity resolution
    if (i2cWriteByteData(i2c_handle, HDC1080_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to configuration register!\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1080
int read_hdc1080(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buffer[4];
    int raw_temp, raw_humidity;

    // Trigger a temperature and humidity measurement by writing to the temperature register
    if (i2cWriteByte(i2c_handle, HDC1080_TEMP_REG) < 0) {
        fprintf(stderr, "Error writing to temperature register!\n");
        return -1;
    }

    // Wait for at least 20 ms for the measurement to complete
    gpioDelay(20000); // 20 ms

    // Read 4 bytes from the sensor
    if (i2cReadDevice(i2c_handle, (char *)buffer, 4) != 4) {
        fprintf(stderr, "Error reading from sensor!\n");
        return -1;
    }

    // Combine the bytes to form the raw temperature and humidity values
    raw_temp = (buffer[0] << 8) | buffer[1];
    raw_humidity = (buffer[2] << 8) | buffer[3];

    // Convert the raw values to temperature and humidity
    *temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = (raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log the temperature and humidity data to a file
int log_data(float temperature, float humidity) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Write the data to the log file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    // Close the log file
    fclose(fp);

    return 0;
}

int main() {
    float temperature, humidity;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed!\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC1080 sensor
    if (init_hdc1080(i2c_handle) < 0) {
        fprintf(stderr, "HDC1080 initialization failed!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature and humidity from the sensor
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            // Log the data to the file
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data!\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close the I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

