#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY_CMD 0x2C0E
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"
#define SLEEP_SECONDS 5

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t *data, size_t len) {
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, size_t len) {
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

float convert_to_celsius(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = i2c_open(I2C_BUS, STS40_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    uint8_t write_data[2] = {(MEASURE_HIGH_REPEATABILITY_CMD >> 8) & 0xFF, MEASURE_HIGH_REPEATABILITY_CMD & 0xFF};
    uint8_t read_data[3];
    uint16_t raw_temperature;
    float temperature;

    while (keep_running) {
        if (i2c_write(i2c_fd, write_data, 2) == 0) {
            usleep(10000); // 10 ms
            if (i2c_read(i2c_fd, read_data, 3) == 0) {
                raw_temperature = (read_data[0] << 8) | read_data[1];
                uint8_t crc = read_data[2];

                if (crc8(read_data, 2) == crc) {
                    temperature = convert_to_celsius(raw_temperature);
                    printf("Temperature: %.2f °C\n", temperature);
                    if (log_temperature(temperature) != 0) {
                        fprintf(stderr, "Error logging temperature.\n");
                    }
                } else {
                    fprintf(stderr, "CRC check failed!\n");
                }
            } else {
                fprintf(stderr, "Error reading temperature data.\n");
            }
        } else {
            fprintf(stderr, "Error sending measurement command.\n");
        }
        sleep(SLEEP_SECONDS);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

