#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x3615
#define PRESSURE_SCALE_FACTOR 240.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "hvac_pressure_log.txt"
#define SAMPLE_INTERVAL_MS 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len, uint8_t crc);
int read_sensor_data(int handle, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send a command to the sensor
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Function to read sensor data and validate CRC
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[9];
    int result = read_data(handle, raw_data, 9);
    if (result != 0) {
        return -1;
    }

    // Validate CRC for pressure
    if (!validate_crc(raw_data, 2, raw_data[2])) {
        fprintf(stderr, "CRC error for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature
    if (!validate_crc(raw_data + 3, 2, raw_data[5])) {
        fprintf(stderr, "CRC error for temperature data\n");
        return -1;
    }

    // Extract raw values
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];

    // Convert to physical units
    data->pressure_pa = (float)raw_pressure / PRESSURE_SCALE_FACTOR;
    data->temperature_c = (float)raw_temperature / TEMPERATURE_SCALE_FACTOR;

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    int result = fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c);
    if (result < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CMD_CONTINUOUS_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for at least 50 ms
    gpioDelay(50000); // 50 ms

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Log data
            if (log_data(log_file, sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            // Log error
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s,ERROR,I2C or CRC error\n", timestamp);
            fflush(log_file);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

