#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define PRESSURE_SCALE_FACTOR 500.0
#define TEMPERATURE_OFFSET -45.0
#define TEMPERATURE_SCALE 175.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t raw_temperature;
    uint16_t raw_scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t checksum);
float convert_pressure(int16_t raw_pressure, float scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure_pa, float temperature_c);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 validation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, int len, uint8_t checksum) {
    uint8_t calculated_crc = crc8(data, len);
    if (calculated_crc != checksum) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, float scale_factor) {
    return (float)raw_pressure / scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return TEMPERATURE_OFFSET + (float)raw_temperature / 65535.0 * TEMPERATURE_SCALE;
}

// Log data to file
int log_data(float pressure_pa, float temperature_c) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.3f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CMD_CONTINUOUS_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command.\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Wait for at least 45 ms
    gpioDelay(50000); // 50 ms

    // Main loop
    while (!terminate) {
        char buffer[9];
        sensor_data_t sensor_data;

        // Read 9 bytes of data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue; // Continue to the next iteration
        }

        // Extract raw values
        sensor_data.raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
        sensor_data.raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
        sensor_data.raw_scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

        // Validate CRC checksums
        if (validate_crc((uint8_t*)&buffer[0], 2, buffer[2]) != 0 ||
            validate_crc((uint8_t*)&buffer[3], 2, buffer[5]) != 0 ||
            validate_crc((uint8_t*)&buffer[6], 2, buffer[8]) != 0) {
            fprintf(stderr, "CRC validation failed. Skipping data point.\n");
            continue; // Skip to the next iteration
        }

        // Convert raw values to physical units
        float pressure_pa = convert_pressure(sensor_data.raw_pressure, PRESSURE_SCALE_FACTOR);
        float temperature_c = convert_temperature(sensor_data.raw_temperature);

        // Log data
        if (log_data(pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

