        printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);

        // Wait 5 seconds
        gpioDelay(5000000); // 5000000 microseconds = 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Verify the sensor identity
int verify_sensor_identity() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return 1;
    }
    if (who_am_i != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return 1;
    }
    printf("Sensor identity verified.\n");
    return 0;
}

// Read the calibration coefficients
int read_calibration_coefficients(calibration_coeffs_t *coeffs) {
    char buffer[18];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_0, buffer, 18);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration coefficients: %d\n", result);
        return 1;
    }

    coeffs->c0 = (int32_t)((uint32_t)buffer[0] << 24 | (uint32_t)buffer[1] << 16 | (uint32_t)buffer[2] << 8 | (uint32_t)buffer[3]);
    coeffs->c1 = (int32_t)((uint32_t)buffer[4] << 24 | (uint32_t)buffer[5] << 16 | (uint32_t)buffer[6] << 8 | (uint32_t)buffer[7]);
    coeffs->c00 = (int32_t)((uint32_t)buffer[8] << 24 | (uint32_t)buffer[9] << 16 | (uint32_t)buffer[10] << 8 | (uint32_t)buffer[11]);
    coeffs->c10 = (int32_t)((uint32_t)buffer[12] << 24 | (uint32_t)buffer[13] << 16 | (uint32_t)buffer[14] << 8 | (uint32_t)buffer[15]);
    coeffs->c01 = (int32_t)((uint32_t)buffer[16] << 24 | (uint32_t)buffer[17] << 16);

    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return 1;
    }
    return 0;
}

// Read the pressure and temperature data
int read_pressure_temperature(int32_t *pressure, int32_t *temperature) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read pressure and temperature data: %d\n", result);
        return 1;
    }

    *pressure = (int32_t)((uint32_t)buffer[0] << 16 | (uint32_t)buffer[1] << 8 | (uint32_t)buffer[2]);
    *temperature = (int32_t)((uint32_t)buffer[3] << 16 | (uint32_t)buffer[4] << 8 | (uint32_t)buffer[5]);

    return 0;
}

// Convert the raw pressure data to hPa
double convert_pressure(int32_t raw_pressure, const calibration_coeffs_t *coeffs) {
    double p_sca = (double)raw_pressure / (double)(1 << 20);
    double p_off = (double)coeffs->c00 / (double)(1 << 20);
    double p_sens = (double)coeffs->c10 / (double)(1 << 20);
    double p_comp = p_sca * p_sens - p_off;
    return p_comp;
}

// Convert the raw temperature data to Celsius
double convert_temperature(int32_t raw_temperature, const calibration_coeffs_t *coeffs) {
    double t_sca = (double)raw_temperature / (double)(1 << 20);
    double t_off = (double)coeffs->c0 / (double)(1 << 20);
    double t_sens = (double)coeffs->c1 / (double)(1 << 20);
    double t_comp = t_sca * t_sens - t_off;
    return t_comp;
}

// Log the data to a file
int log_data(double pressure, double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);

    return 0;
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    terminate = 1;
    printf("Received SIGINT. Exiting...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

