#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi 4
#define ICP10125_ADDR 0x63  // ICP-10125 default I2C address
#define LED_GPIO_CHIP "gpiochip0" // GPIO chip name
#define LED_GPIO_PIN 17         // GPIO pin for the LED (BCM numbering)

// Calibration coefficients
int16_t c0, c1, c2, c3;

// Global variables for cleanup
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int read_calibration_coefficients(int fd);
int trigger_measurement(int fd);
int read_pressure_temperature(int fd, int32_t *pressure, int32_t *temperature);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
double calculate_temperature(int32_t raw_temperature);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_request_line(struct gpiod_chip *chip, int pin, struct gpiod_line **line, const char *consumer);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_set_direction(struct gpiod_line *line, const char *direction);
void signal_handler(int sig);

// I2C read function with error handling and retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, reg) < 0) {
            perror("Failed to set I2C slave address");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, len %d, result %d). Retrying...\n", reg, len, result);
            retries--;
            usleep(10000); // Wait 10ms before retry
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X, len %d).\n", reg, len);
    return -1; // Failure
}

// I2C write function with error handling and retry
int i2c_write_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, reg) < 0) {
            perror("Failed to set I2C slave address");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        result = write(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (reg 0x%02X, len %d, result %d). Retrying...\n", reg, len, result);
            retries--;
            usleep(10000); // Wait 10ms before retry
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, len %d).\n", reg, len);
    return -1; // Failure
}

// Read calibration coefficients from OTP memory
int read_calibration_coefficients(int fd) {
    uint8_t data[8];
    uint8_t reg = 0x66; // OTP register address

    if (i2c_read_bytes(fd, reg, data, 8) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients.\n");
        return -1;
    }

    c0 = (data[0] << 8) | data[1];
    c1 = (data[2] << 8) | data[3];
    c2 = (data[4] << 8) | data[5];
    c3 = (data[6] << 8) | data[7];

