int trigger_measurement(int fd) {
    uint8_t data[2];
    data[0] = (0x40 << 8) | 0x11; // High accuracy mode command

    if (i2c_write_bytes(fd, 0x00, data, 2) != 0) {
        fprintf(stderr, "Failed to trigger measurement.\n");
        return -1;
    }

    usleep(20000); // Wait 20ms for measurement
    return 0;
}

