int read_pressure_temperature(int fd, int32_t *pressure, int32_t *temperature) {
    uint8_t data[6];
    uint8_t reg = 0x00; // Data register address

    if (i2c_read_bytes(fd, reg, data, 6) != 0) {
        fprintf(stderr, "Failed to read pressure and temperature data.\n");
        return -1;
    }

    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    *temperature = (data[3] << 16) | (data[4] << 8) | data[5];

