    double p = raw_pressure;
    double T = raw_temperature;

    p = (p - (c0 * 0.5 + c1 * 0.25)) / c2;
    p = p + ((c0 * c0) / 4.0 + c1 * c1) / c2;
    p = p * 700.0;

    return p;
