#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    unsigned char buf[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(10); // Wait before retrying
            retries++;
            continue;
        }

        gpioDelay(10); // Wait for measurement

        result = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            gpioDelay(10); // Wait before retrying
            retries++;
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int raw_T = (buf[0] << 8) | buf[1];
        unsigned int raw_RH = (buf[3] << 8) | buf[4];

        *temperature = -45 + 175 * (raw_T / 65535);
        *humidity = -6 + 125 * (raw_RH / 65535);

        // Clamp humidity to 0-100%
        if (*humidity < 0) *humidity = 0;
        if (*humidity > 100) *humidity = 100;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    float temperature, humidity;
    char buffer[1024] = {0};
    char response[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (!terminate) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            continue; // Continue listening even if accept fails
        }

        // Read SHT40 data
        if (read_sht40(i2c_handle, &temperature, &humidity) != 0) {
            fprintf(stderr, "Failed to read SHT40 data\n");
            const char *error_page = "<!DOCTYPE html><html><body><h1>Error: Could not read sensor data.</h1></body></html>";
            send(new_socket, error_page, strlen(error_page), 0);
            close(new_socket);
            continue;
        }

        // Create HTML response
        snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<!DOCTYPE html><html><body><h1>Temperature: %.2f &deg;C</h1><h1>Humidity: %.2f %%</h1></body></html>", temperature, humidity);

        // Send HTTP response
        send(new_socket, response, strlen(response), 0);

        close(new_socket);
    }

    // Clean up
    close(server_fd);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Server shut down\n");
    return 0;
}

