#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0625

int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    return (float)raw_temp * TEMP_SCALE;
}

int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("temperature_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Skipping logging due to temperature read error.\n");
        }
        sleep(5);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

