#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG_REG 0x0E
#define CONFIG_REG 0x0F
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to read temperature and humidity from HDC2010
int read_hdc2010(int i2c_handle, float *temperature, float *humidity)
{
    unsigned char buf[4];
    int retries = 3;
    int result;

    // Trigger measurement
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG_REG, 0x01);
        if (result == 0) break; // Success
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to trigger measurement after multiple retries.\n");
        return -1;
    }

    gpioDelay(10000); // Wait 10ms for measurement to complete

    retries = 3;
    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, MEASUREMENT_CONFIG_REG, (char *)buf, 4);
        if (result == 4) break; // Success
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Failed to read data after multiple retries.\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    unsigned int raw_temperature = (buf[0] << 8) | buf[1];
    unsigned int raw_humidity = (buf[2] << 8) | buf[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main()
{
    float temperature, humidity;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
