// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Continuous measurement command (0x362F)
#define MEASURE_CMD 0x362F

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0, MEASURE_CMD) < 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read 6 bytes of data
        char buffer[6];
        int bytes_read = i2cReadI2CBlockData(i2c_handle, 0, buffer, 6);

        if (bytes_read != 6) {
            fprintf(stderr, "Failed to read 6 bytes of data: %d\n", bytes_read);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Extract raw pressure and temperature values
        int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

        // Calculate CRC checksums
        uint8_t pressure_crc = crc8(buffer, 2);
        uint8_t temperature_crc = crc8(buffer + 2, 2);

        // Verify checksums
        if (pressure_crc != buffer[2] || temperature_crc != buffer[5]) {
            fprintf(stderr, "CRC checksum error\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Log raw values to console
        printf("Pressure: %d, Temperature: %d\n", raw_pressure, raw_temperature);

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Cleanup (never reached in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

