#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>
#include <math.h>

// Constants
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TARGET_PROFILE_FILE "profile.txt"
#define REFLOW_LOG_FILE "reflow_log.csv"
#define NUM_PROFILE_POINTS 10
#define SAMPLE_RATE_HZ 1

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Structure to hold profile data
typedef struct {
    double time;
    double target_temp;
} profile_point_t;

profile_point_t profile[NUM_PROFILE_POINTS];
int profile_size = 0;

// Function Prototypes
int spi_init(int bus, int chip_select);
int spi_read_max6675(int fd, double *temperature);
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error);
void set_relay_duty_cycle(double duty_cycle);
int read_profile(const char *filename, profile_point_t *profile, int *size);
int log_data(double time, double temperature, double duty_cycle);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(int bus, int chip_select) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "spi%d.%d", bus, chip_select);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode (CPHA = 0, CPOL = 0)
    unsigned char mode = 0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

// SPI Read from MAX6675
int spi_read_max6675(int fd, double *temperature) {
    unsigned char tx_buf[2] = {0x00, 0x00}; // Dummy data to clock out the data
    unsigned char rx_buf[2];

    if (write(fd, tx_buf, 2) != 2) {
        perror("Error writing to SPI device");
        return -1;
    }

    if (read(fd, rx_buf, 2) != 2) {
        perror("Error reading from SPI device");
        return -1;
    }

    // Extract temperature data (bits 3-14)
    int raw_temp = ((rx_buf[0] << 8) | rx_buf[1]) >> 2;

    // Check for open circuit fault (bit 2)
    if (rx_buf[0] & 0x04) {
        fprintf(stderr, "MAX6675: Open circuit fault detected!\n");
        return -1;
    }

    // Convert raw temperature to Celsius (12-bit resolution)
    *temperature = (double)raw_temp * 0.25;

    return 0;
}

// PID Control
double pid_control(double setpoint, double actual_value, double *integral, double *previous_error) {
    double error = setpoint - actual_value;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Set Relay Duty Cycle
void set_relay_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int on_time_ms = (int)(duty_cycle * 1000); // Convert duty cycle to milliseconds
    int off_time_ms = 1000 - on_time_ms;

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "relay_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Error setting GPIO value (HIGH)");
        cleanup();
        exit(EXIT_FAILURE);
    }
    usleep(on_time_ms * 1000); // Convert milliseconds to microseconds

    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Error setting GPIO value (LOW)");
        cleanup();
        exit(EXIT_FAILURE);
    }
    usleep(off_time_ms * 1000); // Convert milliseconds to microseconds
}

// Read Target Temperature Profile
int read_profile(const char *filename, profile_point_t *profile, int *size) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening profile file");
        return -1;
    }

    char line[256];
    *size = 0;
    while (fgets(line, sizeof(line), fp) != NULL && *size < NUM_PROFILE_POINTS) {
        double time, temp;
        if (sscanf(line, "%lf,%lf", &time, &temp) == 2) {
            profile[*size].time = time;
            profile[*size].target_temp = temp;
            (*size)++;
        } else {
            fprintf(stderr, "Error parsing line: %s", line);
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);
    return 0;
}

// Log Data to File
int log_data(double time, double temperature, double duty_cycle) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }

    fprintf(log_file, "%lf,%lf,%lf\n", time, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Cleanup Resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "relay_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_CHIP_SELECT);
    if (spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Read target profile
    if (read_profile(TARGET_PROFILE_FILE, profile, &profile_size) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(REFLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "time,temperature,duty_cycle\n");

    // Initialize PID variables
    double integral = 0.0;
    double previous_error = 0.0;
    double time_elapsed = 0.0;
    double last_profile_time = 0.0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        double current_time = (double)now;
        double temperature;

        // Read temperature from MAX6675
        if (spi_read_max6675(spi_fd, &temperature) == 0) {
            // Calculate time elapsed since last profile point
            if (last_profile_time > 0.0) {
                time_elapsed = current_time - last_profile_time;
            } else {
                time_elapsed = 0.0;
            }

            // Find the closest profile point
            int i;
            for (i = 0; i < profile_size - 1; i++) {
                if (current_time >= profile[i].time && current_time < profile[i + 1].time) {
                    break;
                }
            }

            // Linear interpolation if between profile points
            double target_temp = profile[i].target_temp;
            if (i < profile_size - 1) {
                double time_diff = profile[i + 1].time - profile[i].time;
                target_temp += (current_time - profile[i].time) / time_diff * (profile[i + 1].target_temp - target_temp);
            }

            // PID control
            double duty_cycle = pid_control(target_temp, temperature, &integral, &previous_error);

            // Set relay duty cycle
            set_relay_duty_cycle(duty_cycle);

            // Log data
            log_data(current_time, temperature, duty_cycle);

            printf("%s - Temperature: %.2f C, Duty Cycle: %.2f\n", buf, temperature, duty_cycle);

            last_profile_time = current_time;
        } else {
            fprintf(stderr, "Error reading temperature, skipping control loop.\n");
        }

        sleep(1); // Sample at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

