    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "relay_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_BUS, SPI_CHIP_SELECT);
    if (spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Read target profile
    if (read_profile(TARGET_PROFILE_FILE, profile, &profile_size) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(REFLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "time,temperature,duty_cycle\n");

    // Initialize PID variables
    double integral = 0.0;
    double previous_error = 0.0;
    double time_elapsed = 0.0;
    double last_profile_time = 0.0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        double current_time = (double)now;
        double temperature;

        // Read temperature from MAX6675
        if (spi_read_max6675(spi_fd, &temperature) == 0) {
            // Calculate time elapsed since last profile point
            if (last_profile_time > 0.0) {
                time_elapsed = current_time - last_profile_time;
            } else {
                time_elapsed = 0.0;
            }

            // Find the closest profile point
            int i;
            for (i = 0; i < profile_size - 1; i++) {
                if (current_time >= profile[i].time && current_time < profile[i + 1].time) {
                    break;
                }
            }

            // Linear interpolation if between profile points
            double target_temp = profile[i].target_temp;
            if (i < profile_size - 1) {
                double time_diff = profile[i + 1].time - profile[i].time;
                target_temp += (current_time - profile[i].time) / time_diff * (profile[i + 1].target_temp - target_temp);
            }

            // PID control
            double duty_cycle = pid_control(target_temp, temperature, &integral, &previous_error);

            // Set relay duty cycle
            set_relay_duty_cycle(duty_cycle);

            // Log data
            log_data(current_time, temperature, duty_cycle);

            printf("%s - Temperature: %.2f C, Duty Cycle: %.2f\n", buf, temperature, duty_cycle);

            last_profile_time = current_time;
        } else {
            fprintf(stderr, "Error reading temperature, skipping control loop.\n");
        }

        sleep(1); // Sample at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

