#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_RELAY_PIN 17
#define PWM_PIN 18

// Define PWM frequency and range
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000

// Define sysfs paths for w1-gpio
#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_FILE "w1_slave"

// Define log file path
#define LOG_FILE "greenhouse.log"

// Global variables
double setpoint_temperature = 25.0; // Default setpoint
double Kp = 1.0; // Default Kp
double Ki = 0.1; // Default Ki
double Kd = 0.01; // Default Kd
int pwm_duty_cycle = 0;
FILE *log_file = NULL;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double Kp, double Ki, double Kd, double *integral, double *previous_error);
void set_heater_state(int state);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double average_temperature, double setpoint, double pid_output, int pwm_duty_cycle);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from DS18B20 sensor
double read_temperature() {
    char devices_path[256];
    char slave_path[256];
    char w1_slave_path[512];
    FILE *fp;
    char line[256];
    unsigned char data[9];
    int i;
    double temperature = -1000.0; // Initialize to an invalid value

    // Construct the paths
    snprintf(devices_path, sizeof(devices_path), "%s", W1_DEVICES_DIR);

    // Find the sensor directory
    snprintf(slave_path, sizeof(slave_path), "%s/28-xxxxxxxxxxxx", W1_DEVICES_DIR);
    for (i = 0; i < 10; i++) {
        snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s", devices_path, slave_path);
        if (access(w1_slave_path, F_OK) == 0) {
            break;
        }
        sprintf(slave_path, "%s/28-xxxxxxxxxx%02x", W1_DEVICES_DIR, i % 10 + '0');
    }

    if (i == 10) {
        fprintf(stderr, "Error: DS18B20 sensor not found.\n");
        return -1000.0; // Indicate sensor-absent
    }

    // Read the w1_slave file
    snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s", devices_path, slave_path);
    fp = fopen(w1_slave_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s for reading.\n", w1_slave_path);
        return -1000.0; // Indicate bus-error
    }

    // Read the file line by line
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (strstr(line, "YES") != NULL) {
            // Read the temperature data
            if (fgets(line, sizeof(line), fp) != NULL) {
                if (sscanf(line, "t=%f", &temperature) != 1) {
                    fprintf(stderr, "Error: Could not read temperature from %s.\n", w1_slave_path);
                    temperature = -1000.0;
                }
                break;
            }
        }
    }

    fclose(fp);

    // CRC validation
    unsigned char temp_data[8];
    memcpy(temp_data, data, 8);
    if (crc8(temp_data, 8) != data[8]) {
        fprintf(stderr, "Error: CRC check failed for temperature reading from %s.\n", w1_slave_path);
        temperature = -1000.0;
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double Kp, double Ki, double Kd, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set the heater state (on/off)
void set_heater_state(int state) {
    gpioWrite(HEATER_RELAY_PIN, state);
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_PIN, duty_cycle);
}

// Function to log data to file
void log_data(double average_temperature, double setpoint, double pid_output, int pwm_duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %d\n", timestamp, average_temperature, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Turn off the heater
    set_heater_state(0);

    // Set PWM to 0
    set_pwm_duty_cycle(0);

    // Close the GPIO lines
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    double average_temperature = 0.0;
    double temperatures[5] = {0.0}; // Array to store temperatures for 5-second interval
    int i;
    double pid_output;
    double integral = 0.0;
    double previous_error = 0.0;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:p:i:d:")) != -1) {
        switch (opt) {
            case 's':
                setpoint_temperature = atof(optarg);
                break;
            case 'p':
                Kp = atof(optarg);
                break;
            case 'i':
                Ki = atof(optarg);
                break;
            case 'd':
                Kd = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s setpoint] [-p Kp] [-i Ki] [-d Kd]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_RELAY_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open %s for writing.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Greenhouse heater control started. Setpoint: %.2f, Kp: %.2f, Ki: %.2f, Kd: %.2f\n", setpoint_temperature, Kp, Ki, Kd);

    // Main loop
    while (1) {
        // Read temperatures from all sensors
        for (i = 0; i < 5; i++) {
            temperatures[i] = read_temperature();
            if (temperatures[i] < -900) {
                fprintf(stderr, "Error: Sensor %d failed, skipping.\n", i + 1);
                temperatures[i] = 0.0; // Assign a default value to avoid affecting average
            }
        }

        // Calculate average temperature
        average_temperature = 0.0;
        for (i = 0; i < 5; i++) {
            average_temperature += temperatures[i];
        }
        average_temperature /= 5.0;

        // Calculate PID output
        pid_output = calculate_pid(setpoint_temperature, average_temperature, Kp, Ki, Kd, &integral, &previous_error);

        // Set PWM duty cycle
        set_pwm_duty_cycle((int)pid_output);
        pwm_duty_cycle = (int)pid_output;

        // Log data
        log_data(average_temperature, setpoint_temperature, pid_output, pwm_duty_cycle);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

