#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define POLL_INTERVAL_S 5
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_aht20();
int read_aht20(float *humidity, float *temperature);
void control_dehumidifier(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, cleaning up...\n", signal);
}

// AHT20 Initialization function
int initialize_aht20() {
    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    int result;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        result = i2cWriteDevice(i2c_handle, (char *)init_cmd, sizeof(init_cmd));
        if (result == 0) {
            return 0; // Success
        }
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: AHT20 initialization failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// AHT20 Read function
int read_aht20(float *humidity, float *temperature) {
    uint8_t trigger_cmd[] = {0xAC, 0x33, 0x00};
    uint8_t data[6];
    int result;

    for (int i = 0; i < MAX_RETRIES; ++i) {
        // Trigger measurement
