#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define SLEEP_SECONDS 60

volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;
int sockfd = -1;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    terminate = 1;
}

// Function to read data from I2C device
int i2c_read_data(int fd, uint8_t *data, int len) {
    if (write(fd, NULL, 0) != 0) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write data to I2C device
int i2c_write_data(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read humidity from HTU21D sensor
int read_humidity(int fd, float *humidity) {
    uint8_t data[3];
    int retries = 3;

    while (retries > 0) {
        if (i2c_write_data(fd, (uint8_t[]){TRIGGER_HUMID_MEASURE}, 1) == 0) {
            usleep(100000); // Wait for measurement (at least 50ms)
            if (i2c_read_data(fd, data, 3) == 0) {
                uint16_t raw_humidity = (data[0] << 8) | data[1];
                *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);
                return 0; // Success
            }
        } else {
            syslog(LOG_ERR, "Failed to trigger humidity measurement.");
        }
        retries--;
        usleep(100000); // Wait before retry
    }

    syslog(LOG_ERR, "Failed to read humidity after multiple retries.");
    return -1; // Failure
}

// Function to format humidity data as JSON
int format_json(float humidity, char *json_string, size_t buffer_size) {
    int ret = snprintf(json_string, buffer_size, "{\"humidity\": %.2f}", humidity);
    if (ret < 0 || ret >= buffer_size) {
        syslog(LOG_ERR, "Failed to format JSON string.");
        return -1;
    }
    return 0;
}

// Function to send HTTP POST request
int send_http_post(const char *json_string) {
    struct sockaddr_in serv_addr;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // Assuming port 80

    if (inet_pton(AF_INET, API_ENDPOINT, &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             API_ENDPOINT, strlen(json_string), json_string);

    if (send(sockfd, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    char response[1024] = {0};
    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    syslog(LOG_INFO, "HTTP Response: %s", response);

    close(sockfd);
    sockfd = -1;
    return 0;
}

int main() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity sensor program...");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return EXIT_FAILURE;
    }

    float humidity;
    char json_string[128];
    int retries;

    while (!terminate) {
        retries = 3;
        while (retries > 0) {
            if (read_humidity(i2c_fd, &humidity) == 0) {
                if (format_json(humidity, json_string, sizeof(json_string)) == 0) {
                    if (send_http_post(json_string) == 0) {
                        syslog(LOG_INFO, "Humidity: %.2f%%, JSON: %s", humidity, json_string);
                        break; // Exit retry loop on success
                    } else {
                        syslog(LOG_ERR, "HTTP POST failed.");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to format JSON.");
                }
            } else {
                syslog(LOG_ERR, "Failed to read humidity.");
            }
            retries--;
            sleep(5); // Wait before retry
        }

        if (retries == 0) {
            syslog(LOG_ERR, "Failed to send humidity data after multiple retries.");
        }

        sleep(SLEEP_SECONDS);
    }

    syslog(LOG_INFO, "Closing I2C device...");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    syslog(LOG_INFO, "Closing sockets...");
    if (sockfd != -1) {
        close(sockfd);
    }

    syslog(LOG_INFO, "Exiting humidity sensor program.");
    closelog();
    return EXIT_SUCCESS;
}

