int read_aht20(int handle, float *temperature, float *humidity);
int read_pir(int gpio);
int log_data(FILE *fp, float temperature, float humidity, int motion);
int create_log_file(const char *filename);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read temperature from TMP117 sensor
int read_tmp117(int handle, float *temperature) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) {
            // Combine the two bytes into a 16-bit value
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            // Convert to Celsius
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117 (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
        }
    }
    return -1; // Failure after retries
}

// Read temperature and humidity from AHT20 sensor
int read_aht20(int handle, float *temperature, float *humidity) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    char measure_cmd[3] = {0xAC, 0x33, 0x00};
    char buf[7];
    int retries = 0;
    int result;

    // Send initialization command
    result = i2cWriteDevice(handle, init_cmd, 3);
    if (result != 3) {
        fprintf(stderr, "Error sending AHT20 initialization command (attempt %d): %d\n", retries + 1, result);
        return -1;
    }
    gpioDelay(100); // Wait for initialization

    // Send measurement command
    result = i2cWriteDevice(handle, measure_cmd, 3);
    if (result != 3) {
        fprintf(stderr, "Error sending AHT20 measurement command (attempt %d): %d\n", retries + 1, result);
        return -1;
    }
    gpioDelay(80); // Wait for measurement

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 7);
        if (result == 7) {
            // Check busy bit
            if ((buf[0] & 0x80) == 0) {
                // Combine the 5 bytes into a 20-bit humidity and 20-bit temperature values
                int humidity_raw = ((buf[1] & 0x3F) << 8) | buf[2];
                int temperature_raw = (buf[3] << 8) | buf[4];

                // Convert to physical values (datasheet formulas)
                *humidity = (float)humidity_raw / 1048576.0 * 100.0;
                *temperature = (float)temperature_raw / 1048576.0 * 200.0 - 50.0;
                return 0; // Success
            } else {
                fprintf(stderr, "AHT20 busy (attempt %d)\n", retries + 1);
            }
        } else {
            fprintf(stderr, "Error reading AHT20 (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(BACKOFF_DELAY_MS * (1 << retries)); // Exponential backoff
    }
    return -1; // Failure after retries
}

