#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_DIRECTION_PIN_1 23
#define MOTOR_DIRECTION_PIN_2 24

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *rain_line;
struct gpiod_line *enable_line;
struct gpiod_line *direction_line_1;
struct gpiod_line *direction_line_2;

// Function prototypes
int read_rain_sensor(struct gpiod_line *line);
void control_motor(struct gpiod_line *enable_line, struct gpiod_line *direction_line_1, struct gpiod_line *direction_line_2);
void stop_motor(struct gpiod_line *enable_line);
void cleanup(int signal);
void log_event(const char *message);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    log_event("Received signal, cleaning up...");

    // Stop the motor
    stop_motor(enable_line);

    // Release GPIO lines
    if (rain_line) {
        gpiod_line_release(rain_line);
    }
    if (enable_line) {
        gpiod_line_release(enable_line);
    }
    if (direction_line_1) {
        gpiod_line_release(direction_line_1);
    }
    if (direction_line_2) {
        gpiod_line_release(direction_line_2);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_event("Cleanup complete, exiting.");
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading rain sensor value");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the motor
void control_motor(struct gpiod_line *enable_line, struct gpiod_line *direction_line_1, struct gpiod_line *direction_line_2) {
    log_event("Starting motor control...");

    // Set direction to forward
    if (gpiod_line_set_value(direction_line_1, 1) < 0) {
        perror("Error setting direction line 1");
        return;
    }
    if (gpiod_line_set_value(direction_line_2, 0) < 0) {
        perror("Error setting direction line 2");
        return;
    }

    // Enable the motor
    if (gpiod_line_set_value(enable_line, 1) < 0) {
        perror("Error enabling motor");
        return;
    }

    // Run the motor for 5 seconds
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;
    nanosleep(&sleep_time, NULL);

    // Stop the motor
    stop_motor(enable_line);

    log_event("Motor control complete.");
}

// Function to stop the motor
void stop_motor(struct gpiod_line *enable_line) {
    log_event("Stopping motor...");

    // Disable the motor
    if (gpiod_line_set_value(enable_line, 0) < 0) {
        perror("Error disabling motor");
        return;
    }

    log_event("Motor stopped.");
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout); // Ensure the output is flushed immediately
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }
    log_event("GPIO chip opened successfully.");

    // Get GPIO lines
    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    enable_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    direction_line_1 = gpiod_chip_get_line(chip, MOTOR_DIRECTION_PIN_1);
    direction_line_2 = gpiod_chip_get_line(chip, MOTOR_DIRECTION_PIN_2);

    if (!rain_line || !enable_line || !direction_line_1 || !direction_line_2) {
        perror("Error getting GPIO line");
        cleanup(0); // Clean up and exit
        return 1;
    }
    log_event("GPIO lines obtained successfully.");

    // Request GPIO lines for input and output
    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("Error requesting rain sensor line as input");
        cleanup(0);
        return 1;
    }
    log_event("Rain sensor line requested as input.");

    if (gpiod_line_request_output(enable_line, "motor_enable", 0) < 0) {
        perror("Error requesting motor enable line as output");
        cleanup(0);
        return 1;
    }
    log_event("Motor enable line requested as output.");

    if (gpiod_line_request_output(direction_line_1, "motor_direction_1", 0) < 0) {
        perror("Error requesting motor direction line 1 as output");
        cleanup(0);
        return 1;
    }
    log_event("Motor direction line 1 requested as output.");

    if (gpiod_line_request_output(direction_line_2, "motor_direction_2", 0) < 0) {
        perror("Error requesting motor direction line 2 as output");
        cleanup(0);
        return 1;
    }
    log_event("Motor direction line 2 requested as output.");

    log_event("GPIO lines configured successfully.");

    // Main loop
    while (1) {
        int rain_detected = read_rain_sensor(rain_line);
        if (rain_detected < 0) {
            log_event("Error reading rain sensor, exiting.");
            cleanup(0);
            return 1;
        }

        if (rain_detected == 0) {
            log_event("Rain detected!");
            control_motor(enable_line, direction_line_1, direction_line_2);
        }

        // Sleep for 2 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 2;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

