    // Main loop
    while (1) {
        int rain_detected = read_rain_sensor(rain_line);
        if (rain_detected < 0) {
            log_event("Error reading rain sensor, exiting.");
            cleanup(0);
            return 1;
        }

        if (rain_detected == 0) {
            log_event("Rain detected!");
            control_motor(enable_line, direction_line_1, direction_line_2);
        }

        // Sleep for 2 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 2;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

