// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU usage from /proc/stat
void read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL)
    {
        perror("Error opening /proc/stat");
        *user = *nice = *system = *idle = 0; // Set to 0 to avoid using uninitialized values
        return;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL)
    {
        perror("Error reading /proc/stat");
        fclose(fp);
        *user = *nice = *system = *idle = 0; // Set to 0 to avoid using uninitialized values
        return;
    }

    if (strncmp(line, "cpu ", 4) != 0)
    {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        fclose(fp);
        *user = *nice = *system = *idle = 0; // Set to 0 to avoid using uninitialized values
        return;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu", user, nice, system, idle) != 4)
    {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        *user = *nice = *system = *idle = 0; // Set to 0 to avoid using uninitialized values
        return;
    }

    fclose(fp);
}

// Function to calculate CPU load percentage
double calculate_cpu_load()
{
    unsigned long long user1, nice1, system1, idle1;
    unsigned long long user2, nice2, system2, idle2;
    unsigned long long PrevIdle, Idle;

    read_cpu_stats(&user1, &nice1, &system1, &idle1);
    gpioDelay(500); // Wait 500ms
    read_cpu_stats(&user2, &nice2, &system2, &idle2);

    PrevIdle = idle1;
    Idle = idle2;

    unsigned long long PrevNonIdle = user1 + nice1 + system1;
    unsigned long long NonIdle = user2 + nice2 + system2;

    unsigned long long PrevTotal = PrevIdle + PrevNonIdle;
    unsigned long long Total = Idle + NonIdle;

    double load = (1.0 - (double)(Total - PrevTotal) / (double)PrevTotal) * 100.0;

    return load;
}

// Function to set RGB LED color using hardware PWM
void set_rgb_color(int red, int green, int blue)
{
    // Clamp PWM values to 0-255 range
    red   = (red   < 0) ? 0 : (red   > 255) ? 255 : red;
    green = (green < 0) ? 0 : (green > 255) ? 255 : green;
    blue  = (blue  < 0) ? 0 : (blue  > 255) ? 255 : blue;

    // Common anode, so invert PWM values
    gpioPWM(RED_PIN,   255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN,  255 - blue);
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("CPU Load Controlled RGB LED running... Press Ctrl+C to exit.\n");

    while (!terminate)
    {
        // Calculate CPU load
        double cpu_load = calculate_cpu_load();

        // Map CPU load to RGB color gradient
        int red, green, blue;
        if (cpu_load <= 50.0)
        {
            red   = 0;
            green = 255;
            blue  = 0;
        }
        else if (cpu_load <= 100.0)
        {
            // Yellow to Red transition
            red   = 255;
            green = 255 - (int)((cpu_load - 50.0) * 255.0 / 50.0);
            blue  = 0;
        }
        else
        {
            red   = 255;
            green = 0;
            blue  = 0;
        }

        // Set RGB LED color
        set_rgb_color(red, green, blue);

        // Wait for 500ms
        gpioDelay(500);
    }

    // Turn off LED before exiting
    set_rgb_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

