    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int read_raw_data(int handle, int32_t *raw_temperature, int32_t *raw_pressure) {
    // Set forced mode
    if (write_register(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        return -1;
    }

    // Wait for measurement to complete (datasheet recommends at least 2ms)
    gpioDelay(5000); // 5ms

    uint8_t data[6];
    int result = i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature and pressure using the BMP280 datasheet formulas
int compensate_data(int32_t raw_temperature, int32_t raw_pressure, double *temperature, double *pressure) {
    double var1, var2, var3, var4, var5, var6, var7, var8;

    // Temperature compensation
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    *temperature = (t_fine / 5120.0);

    // Pressure compensation
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }

    double p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    *pressure = (p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0);

    return 0;
}

// Function to format temperature and pressure data into a JSON string
char *format_json(double temperature, double pressure) {
    char *json_string = (char *)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\":%.2f,\"pressure\":%.2f}", temperature, pressure);
    return json_string;
}

// Function to send the JSON string over UDP
int send_udp_packet(const char *json_string, const char *ip_address, int port) {
    struct sockaddr_in server_addr;

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        return -1;
    }

    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP packet: %d\n", errno);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read chip ID
    int chip_id = read_register(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%02X\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket: %d\n", errno);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;
        char *json_string;

        // Read raw data
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Error reading raw data, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Compensate data
        if (compensate_data(raw_temperature, raw_pressure, &temperature, &pressure) < 0) {
            fprintf(stderr, "Error compensating data, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Format data into JSON string
        json_string = format_json(temperature, pressure);
        if (json_string == NULL) {
            fprintf(stderr, "Error formatting JSON, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Send UDP packet
        if (send_udp_packet(json_string, "192.168.1.100", 5000) < 0) {
            fprintf(stderr, "Error sending UDP packet, retrying in 5 seconds...\n");
        }

        free(json_string);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here due to signal handler)
    i2cClose(i2c_handle);
    close(udp_socket);
    gpioTerminate();

    return 0;
}

