#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000
#define BUFFER_SIZE 20

// Data Structures
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

typedef struct {
    LogEntry buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
static int spi_handle;
static CircularBuffer log_buffer;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_gpio();
int init_spi();
int read_max31855(uint16_t *raw_data);
float extract_temperature(uint16_t raw_data);
int check_fault(uint16_t raw_data);
int set_fan_speed(float temperature);
void add_to_buffer(CircularBuffer *buffer, float temperature, int duty_cycle);
void print_buffer(CircularBuffer *buffer);
void signal_handler(int signal);
void cleanup();

// Function Implementations
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255);

    return 0;
}

int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int read_max31855(uint16_t *raw_data) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *raw_data = ((uint16_t)rx_buf[0] << 8) | (uint16_t)rx_buf[1];
    return 0;
}

float extract_temperature(uint16_t raw_data) {
    int16_t thermocouple_data = (raw_data >> 2) & 0x3FFF; // Extract 14 bits
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend if negative
    }
    return thermocouple_data * 0.25;
}

int check_fault(uint16_t raw_data) {
    int fault = raw_data >> 16;
    if (fault & 0x0001) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1;
    }
    if (fault & 0x0002) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (fault & 0x0004) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }
    return 0;
}

int set_fan_speed(float temperature) {
    int duty_cycle = 0;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature <= 40.0) {
        duty_cycle = (int)((temperature - 25.0) * 50.0 / 15.0);
    } else if (temperature > 40.0 && temperature <= 60.0) {
        duty_cycle = 50 + (int)((temperature - 40.0) * 150.0 / 20.0);
    } else {
        duty_cycle = 255;
    }

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(FAN_GPIO, duty_cycle);
    return duty_cycle;
}

void add_to_buffer(CircularBuffer *buffer, float temperature, int duty_cycle) {
    buffer->buffer[buffer->head].timestamp = time(NULL);
    buffer->buffer[buffer->head].temperature = temperature;
    buffer->buffer[buffer->head].duty_cycle = duty_cycle;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

void print_buffer(CircularBuffer *buffer) {
    printf("\n--- Log Buffer Contents ---\n");
    int start = (buffer->count == BUFFER_SIZE) ? buffer->head : 0;
    for (int i = 0; i < buffer->count; i++) {
        int index = (start + i) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer->buffer[index].timestamp));
        printf("[%s] Temp: %.2f°C, Duty: %d\n", time_str, buffer->buffer[index].temperature, buffer->buffer[index].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n\n");
}

void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

void cleanup() {
    gpioPWM(FAN_GPIO, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize
    if (init_gpio() != 0) return 1;
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    log_buffer.head = 0;
    log_buffer.count = 0;

    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        if (read_max31855(&raw_data) == 0) {
            float temperature = extract_temperature(raw_data);
            if (check_fault(raw_data) == 0) {
                int duty_cycle = set_fan_speed(temperature);
                add_to_buffer(&log_buffer, temperature, duty_cycle);
                printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
            } else {
                fprintf(stderr, "Faulty temperature reading skipped.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan update.\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    print_buffer(&log_buffer);
    cleanup();
    return 0;
}

