#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define LOG_FILE "rtd_log.csv"
#define MAX_RETRIES 3

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;

// Function prototypes
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int max31865_init(int fd);
int max31865_read_rtd(int fd, uint16_t *rtd_msb, uint16_t *rtd_lsb);
int max31865_read_fault(int fd, uint8_t *fault_status);
float rtd_to_temperature(uint16_t rtd_value);
int log_data(FILE *fp, float temperature);
void signal_handler(int sig);
int gpio_init(int pin);
void gpio_release(int pin);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

// SPI initialization
int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MAX31865 initialization
int max31865_init(int fd) {
    uint8_t config_reg = 0xC2; // 3-wire RTD, 50 Hz, Bias enabled
    uint8_t fault_status;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, &config_reg, 1) != 1) {
            perror("Error writing to config register");
            retries++;
            sleep(1); // Wait before retrying
            continue;
        }

        if (max31865_read_fault(fd, &fault_status) != 0) {
            fprintf(stderr, "Error reading fault status after config write.\n");
            retries++;
            sleep(1);
            continue;
        }

        if (fault_status != 0) {
            fprintf(stderr, "Fault detected: 0x%02X\n", fault_status);
            return -1; // Initialization failed due to fault
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "MAX31865 initialization failed after %d retries.\n", MAX_RETRIES);
    return -1; // Initialization failed after multiple retries
}

// MAX31865 read RTD value
int max31865_read_rtd(int fd, uint16_t *rtd_msb, uint16_t *rtd_lsb) {
    uint8_t tx_buf[1] = {0x01}; // Read RTD MSB command
    uint8_t rx_buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, tx_buf, 1) != 1) {
            perror("Error writing read RTD command");
            retries++;
            sleep(1);
            continue;
        }

        if (spi_transfer(fd, NULL, rx_buf, 2) != 0) {
            fprintf(stderr, "Error during RTD read transfer.\n");
            retries++;
            sleep(1);
            continue;
        }

        *rtd_msb = rx_buf[0];
        *rtd_lsb = rx_buf[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read RTD value after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// MAX31865 read fault status
int max31865_read_fault(int fd, uint8_t *fault_status) {
    uint8_t tx_buf[1] = {0x07}; // Read fault status command
    uint8_t rx_buf[1];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (write(fd, tx_buf, 1) != 1) {
            perror("Error writing read fault command");
            retries++;
            sleep(1);
            continue;
        }

        if (spi_transfer(fd, NULL, rx_buf, 1) != 0) {
            fprintf(stderr, "Error during fault status read transfer.\n");
            retries++;
            sleep(1);
            continue;
        }

        *fault_status = rx_buf[0];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read fault status after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// RTD to temperature conversion (Callendar-Van Dusen equation)
float rtd_to_temperature(uint16_t rtd_value) {
    // Constants
    const float R0 = 100.0; // Reference resistor value
    const float A = 3.9083e-3;
    const float B = -5.775e-7;
    const float C = -4.183e-3;

    // Resistor value calculation (example for PT100)
    float rtd_resistance = (rtd_value * 430.0) / 32768.0; // Assuming 430 Ohm reference resistor

    // Temperature calculation
    float temperature = A + (B * (rtd_resistance / R0 - 1)) + (C * (rtd_resistance / R0 - 1) * (rtd_resistance / R0 - 1));

    return temperature;
}

// Log data to file
int log_data(FILE *fp, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// GPIO initialization
int gpio_init(int pin) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, pin);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "rtd_logger", 1) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting GPIO line high");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// GPIO release
void gpio_release(int pin) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    uint16_t rtd_msb, rtd_lsb;
    uint8_t fault_status;
    float temperature;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(CS_PIN) != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        gpio_release(CS_PIN);
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init(spi_fd) != 0) {
        fprintf(stderr, "MAX31865 initialization failed.\n");
        close(spi_fd);
        gpio_release(CS_PIN);
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Error opening log file");
        close(spi_fd);
        gpio_release(CS_PIN);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read RTD value
        if (max31865_read_rtd(spi_fd, &rtd_msb, &rtd_lsb) == 0) {
            // Combine MSB and LSB
            uint16_t rtd_value = ((rtd_msb & 0x0F) << 8) | rtd_lsb;

            // Read fault status
            if (max31865_read_fault(spi_fd, &fault_status) != 0) {
                fprintf(stderr, "Error reading fault status during temperature reading.\n");
            } else {
                // Convert RTD value to temperature
                temperature = rtd_to_temperature(rtd_value);

                // Log data
                if (log_data(log_fp, temperature) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            fprintf(stderr, "Error reading RTD value.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Cleanup
    close(spi_fd);
    fclose(log_fp);
    gpio_release(CS_PIN);

    return 0;
}

