void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the BME280 sensor
int bme280_init(int i2c_fd) {
    // Check the chip ID
    unsigned char chip_id;
    if (read(i2c_fd, &chip_id, 1) != 1) {
        perror("Failed to read chip ID");
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Incorrect chip ID 0x%02x\n", chip_id);
        return -1;
    }

    // Set the sensor to forced mode
    unsigned char mode_control_reg = 0b00100011; // Forced mode, oversampling x1
    if (write(i2c_fd, &mode_control_reg, 1) != 1) {
        perror("Failed to write mode control register");
        return -1;
    }

    // Set the control humidity register
    unsigned char control_humidity_reg = 0b00000011; // Oversampling x1
    if (write(i2c_fd, &control_humidity_reg, 1) != 1) {
        perror("Failed to write control humidity register");
        return -1;
    }

    // Set the config register
    unsigned char config_reg = 0b00000000; // Normal mode, t_sb = 0.5ms, filter off
    if (write(i2c_fd, &config_reg, 1) != 1) {
        perror("Failed to write config register");
        return -1;
    }

    return 0;
}

// Function to read data from the BME280 sensor
int bme280_read_data(int i2c_fd, float *temperature, float *humidity, float *pressure) {
    unsigned char data[8];
    if (read(i2c_fd, data, 8) != 8) {
        perror("Failed to read data");
        return -1;
    }

    // Extract raw data
    int raw_pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int raw_temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int raw_humidity = (data[6] << 8) | data[7];

    // Dummy conversion (replace with actual BME280 conversion formulas)
    *temperature = (float)raw_temperature / 100.0;
    *humidity = (float)raw_humidity / 1000.0;
    *pressure = (float)raw_pressure / 100.0;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *log_file, float temperature, float humidity, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BME280 sensor
    if (bme280_init(i2c_fd) != 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }
    rewind(log_file);

    // Main loop
    float temperature, humidity, pressure;
    while (1) {
        // Read data from the sensor
        if (bme280_read_data(i2c_fd, &temperature, &humidity, &pressure) == 0) {
            // Log the data
            log_data(log_file, temperature, humidity, pressure);
            printf("Temperature: %.2f C, Humidity: %.2f %%, Pressure: %.2f hPa\n", temperature, humidity, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource release.
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

