// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0-3, higher values increase accuracy but consume more power)
#define BMP180_OSS 0

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds * 10 Hz)
#define BUFFER_SIZE 600

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure data and timestamp
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_data_t;

// Circular buffer structure
typedef struct {
    pressure_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
circular_buffer_t pressure_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *cal);
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_pressure(int32_t raw_temp, int32_t raw_pressure, const bmp180_calibration_data_t *cal);
void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, float pressure);
float calculate_average_pressure(const circular_buffer_t *buffer);
void trigger_alert(float pressure, float average_pressure);
