void signal_handler(int signal);
void log_message(const char *message);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    log_message("I2C initialized successfully.");
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *cal) {
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal->ac1 = (buf[0] << 8) | buf[1];
    cal->ac2 = (buf[2] << 8) | buf[3];
    cal->ac3 = (buf[4] << 8) | buf[5];
    cal->ac4 = (buf[6] << 8) | buf[7];
    cal->ac5 = (buf[8] << 8) | buf[9];
    cal->ac6 = (buf[10] << 8) | buf[11];
    cal->b1 = (buf[12] << 8) | buf[13];
    cal->b2 = (buf[14] << 8) | buf[15];
    cal->mb = (buf[16] << 8) | buf[17];
    cal->mc = (buf[18] << 8) | buf[19];
    cal->md = (buf[20] << 8) | buf[21];

    log_message("Calibration data read successfully.");
    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &write_buf[1], 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5 ms

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, &write_buf[0], 0) != 0) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[3];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &write_buf[1], 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 26 ms for OSS = 0

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, &write_buf[0], 0) != 0) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int32_t raw_temp, int32_t raw_pressure, const bmp180_calibration_data_t *cal) {
    int32_t X1, X2, X3, B3, B5, B6, p;
    uint32_t B4, B7;

    // Temperature calculations
    X1 = ((int32_t)raw_temp - (int32_t)cal->ac6) * ((int32_t)cal->ac5) / pow(2, 15);
    X2 = ((int32_t)cal->mc * pow(2, 11)) / (X1 + cal->md);
    B5 = X1 + X2;

    // Pressure calculations
    B6 = B5 - 4000;
    X1 = (cal->b2 * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    X2 = cal->ac2 * B6 / pow(2, 11);
    X3 = X1 + X2;
    B3 = (((cal->ac1 * 4 + X3) << BMP180_OSS) + 2) / 4;

    X1 = cal->ac3 * B6 / pow(2, 13);
    X2 = (cal->b1 * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    X3 = ((X1 + X2) + 2) / pow(2, 2);
    B4 = cal->ac4 * (uint32_t)(X3 + 32768) / pow(2, 15);
    B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000)
        p = (B7 * 2) / B4;
    else
        p = (B7 / B4) * 2;

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (X1 + X2 + 3791) / pow(2, 4);

    return pressure / 100.0; // Convert to hPa
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, float pressure) {
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].pressure = pressure;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the rolling average pressure
float calculate_average_pressure(const circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i].pressure;
    }
    return sum / buffer->count;
}

// Function to trigger an alert if the pressure deviates significantly
void trigger_alert(float pressure, float average_pressure) {
    float deviation = pressure - average_pressure;
    if (deviation > 5.0 || deviation < -5.0) {
        time_t now = time(NULL);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "%s - ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa, Deviation: %.2f hPa\n", timestamp, pressure, average_pressure, deviation);
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        gpioDelay(1000000);       // Wait 1 second
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temp, raw_pressure;
    float pressure, average_pressure;

    if (read_raw_temperature(&raw_temp) != 0) {
        log_message("Error reading raw temperature.");
        return;
    }

    if (read_raw_pressure(&raw_pressure) != 0) {
        log_message("Error reading raw pressure.");
        return;
    }

    pressure = calculate_pressure(raw_temp, raw_pressure, &calibration_data);

    time_t now = time(NULL);
    add_to_buffer(&pressure_buffer, now, pressure);

    average_pressure = calculate_average_pressure(&pressure_buffer);
    trigger_alert(pressure, average_pressure);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s - Pressure: %.2f hPa, Average Pressure: %.2f hPa\n", timestamp, pressure, average_pressure);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "Ctrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s - %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    pressure_buffer.head = 0;
    pressure_buffer.count = 0;

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Set up hardware timer
    gpioSetTimerFuncEx(0, 50, timer_callback, NULL); // Timer 0, 50 ms interval

    log_message("Program started.");

    // Main loop
    while (!terminate) {
        gpioDelay(100000); // Sleep for 0.1 seconds to reduce CPU usage
    }

    // Clean up
    gpioSetTimerFuncEx(0, 50, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW
    gpioTerminate();

    log_message("Program terminated.");
    return 0;
