#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQUENCY 25000

volatile sig_atomic_t terminate = 0;
FILE *log_fp = NULL;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to read temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

int calculate_duty_cycle(int temp) {
    if (temp < 40000) {
        return 0;
    }
    if (temp > 70000) {
        return 255;
    }
    return (temp - 40000) * 255 / (70000 - 40000);
}

void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

void log_data(int temp, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, Temperature: %d m°C, Duty Cycle: %d\n", timestamp, temp, duty_cycle);
        fflush(log_fp); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Log file not open, skipping log entry.\n");
    }
}

int main() {
    int temp, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, 255);

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read temperature, using previous value.\n");
            // Consider a default or previous valid temperature here
        } else {
            duty_cycle = calculate_duty_cycle(temp);
            set_fan_speed(duty_cycle);
            log_data(temp, duty_cycle);
        }

        sleep(5);
    }

    // Cleanup
    set_fan_speed(0); // Stop the fan
    fclose(log_fp);
    gpioTerminate();

    printf("Fan control stopped.\n");
    return 0;
}

