#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
float convert_to_celsius(int16_t raw_temp);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_temp);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from LM75 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (buf[0] << 5) | (buf[1] >> 3); // Combine bytes and shift
    *temperature = convert_to_celsius(raw_temp);
    return 0;
}

// Convert raw temperature data to Celsius
float convert_to_celsius(int16_t raw_temp) {
    return (float)raw_temp / 256.0;
}

// Add temperature reading to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate running average of temperature readings
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control LED based on average temperature
void control_led(float average_temp) {
    if (average_temp > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C communication
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&temp_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;
    float average_temp;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&temp_buffer, temperature);
            average_temp = calculate_average(&temp_buffer);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temp);
            control_led(average_temp);
        } else {
            fprintf(stderr, "Failed to read temperature. Attempting re-initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

