#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <jansson.h>

// Constants
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_FAULT_REG 0x07
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define PT100_RREF 430.0
#define TARGET_TEMP_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01

// Global variables
double target_temperature = TARGET_TEMP_DEFAULT;
double Kp = KP_DEFAULT;
double Ki = KI_DEFAULT;
double Kd = KD_DEFAULT;
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_spi();
int init_max31865();
int read_max31865_faults(uint8_t *fault_status);
int read_max31865_rtd_code(uint16_t *rtd_code);
double rtd_to_resistance(uint16_t rtd_code);
double resistance_to_temperature(double resistance);
int pid_control(double current_temperature, double target_temperature, double *integral, double *previous_error);
void set_pwm_duty_cycle(int duty_cycle);
void load_config(const char *filename);
void signal_handler(int signal);
void log_error(const char *message);

int main() {
    // Load configuration from file
    load_config("config.json");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO and SPI
    if (init_gpio() != 0 || init_spi() != 0 || init_max31865() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double integral = 0.0;
    double previous_error = 0.0;

    // Main loop
    while (!terminate) {
        uint16_t rtd_code;
        uint8_t fault_status;
        double current_temperature;
        int duty_cycle;

        // Read RTD code and fault status
        if (read_max31865_rtd_code(&rtd_code) != 0 || read_max31865_faults(&fault_status) != 0) {
            log_error("Failed to read MAX31865 data");
            set_pwm_duty_cycle(0); // Shut off heater
            break; // Exit loop
        }

        // Check for faults
        if (fault_status != 0) {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "MAX31865 fault: 0x%02X", fault_status);
            log_error(error_message);
            set_pwm_duty_cycle(0); // Shut off heater
            break; // Exit loop
        }

        // Convert RTD code to resistance
        double resistance = rtd_to_resistance(rtd_code);

        // Convert resistance to temperature
        current_temperature = resistance_to_temperature(resistance);

        // PID control
        duty_cycle = pid_control(current_temperature, target_temperature, &integral, &previous_error);

        // Set PWM duty cycle
        set_pwm_duty_cycle(duty_cycle);

        // Print temperature and duty cycle (for debugging)
        printf("Temperature: %.2f°C, Duty Cycle: %d\n", current_temperature, duty_cycle);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Ensure heater is off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// Initialize GPIO
int init_gpio() {
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize MAX31865
int init_max31865() {
    char config_data[2];
    config_data[0] = MAX31865_CONFIG_REG | 0x80; // Write enable
    config_data[1] = 0xC1; // Configuration: VBIAS, auto-conversion, clear faults

    if (spiWrite(spi_handle, config_data, 2) != 0) {
        fprintf(stderr, "Failed to write to MAX31865 config register\n");
        return 1;
    }
    gpioDelay(1000); // Wait for configuration to take effect
    return 0;
}

// Read MAX31865 fault status
int read_max31865_faults(uint8_t *fault_status) {
    char tx_buf[1], rx_buf[1];
    tx_buf[0] = MAX31865_FAULT_REG | 0x00; // Read command

    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Failed to read MAX31865 fault register\n");
        return 1;
    }

    *fault_status = rx_buf[0];
    return 0;
}

// Read MAX31865 RTD code
int read_max31865_rtd_code(uint16_t *rtd_code) {
    char tx_buf[2], rx_buf[2];
    tx_buf[0] = MAX31865_RTD_MSB_REG | 0x00; // Read command

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Failed to read MAX31865 RTD registers\n");
        return 1;
    }

    *rtd_code = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Convert RTD code to resistance
double rtd_to_resistance(uint16_t rtd_code) {
    return (double)rtd_code / 32768.0 * PT100_RREF;
}

// Convert resistance to temperature (Callendar-Van Dusen equation)
double resistance_to_temperature(double resistance) {
    // PT100 nominal resistance at 0°C is 100 ohms
    double R0 = 100.0;
    double A = 3.9083e-3;
    double B = -5.775e-7;

    double t = (R0 - resistance) / (A * R0);
    if (t < 0) return 0.0; // Ensure temperature is not negative

    double temp = t + (B * t * t);
    return temp;
}

// PID control algorithm
int pid_control(double current_temperature, double target_temperature, double *integral, double *previous_error) {
    double error = target_temperature - current_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Limit output to PWM range
    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return (int)output;
}

// Set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Load configuration from JSON file
void load_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        // Use default values
        return;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    json_t *Kp_json = json_object_get(root, "Kp");
    json_t *Ki_json = json_object_get(root, "Ki");
    json_t *Kd_json = json_object_get(root, "Kd");

    if (json_is_real(target_temp)) {
        target_temperature = json_real_value(target_temp);
    } else {
        fprintf(stderr, "Warning: target_temperature not found or invalid in config file, using default value\n");
    }

    if (json_is_real(Kp_json)) {
        Kp = json_real_value(Kp_json);
    } else {
        fprintf(stderr, "Warning: Kp not found or invalid in config file, using default value\n");
    }

    if (json_is_real(Ki_json)) {
        Ki = json_real_value(Ki_json);
    } else {
        fprintf(stderr, "Warning: Ki not found or invalid in config file, using default value\n");
    }

    if (json_is_real(Kd_json)) {
        Kd = json_real_value(Kd_json);
    } else {
        fprintf(stderr, "Warning: Kd not found or invalid in config file, using default value\n");
    }

    json_decref(root);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Log error
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

