#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for data logging toggle
#define LOGGING_GPIO 27

// I2C handle
int i2c_handle;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Logging enabled flag
volatile int logging_enabled = 0;

// Last GPIO state for debouncing
volatile int last_gpio_state = 0;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, double temperature);
int log_data(double pressure);
void toggle_logging();
void signal_handler(int signal);

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(LOGGING_GPIO, PI_INPUT);
    gpioSetPullUpDown(LOGGING_GPIO, PI_PUD_UP);

    // Initialize I2C
    if (init_i2c() != 0)
    {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0)
    {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Data logging is initially disabled. Press GPIO%d to toggle.\n", LOGGING_GPIO);

    // Main loop
    while (1)
    {
        // Check for falling edge on GPIO27
        int current_gpio_state = gpioRead(LOGGING_GPIO);
        if (current_gpio_state == 0 && last_gpio_state == 1)
        {
            toggle_logging();
            printf("Data logging %s\n", logging_enabled ? "enabled" : "disabled");
        }
        last_gpio_state = current_gpio_state;

        // If logging is enabled, read and log data every 2 seconds
        if (logging_enabled)
        {
            int32_t raw_temp, raw_pressure;
            double temperature, pressure;

            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) != 0 || read_raw_pressure(&raw_pressure) != 0)
            {
                fprintf(stderr, "Failed to read sensor data\n");
                continue; // Skip to the next iteration
            }

            // Calculate temperature and pressure
            temperature = calculate_temperature(raw_temp);
            pressure = calculate_pressure(raw_pressure, temperature);

            // Log the data
            if (log_data(pressure) != 0)
            {
                fprintf(stderr, "Failed to log data\n");
            }

            sleep(2); // Wait 2 seconds
        }
        else
        {
            sleep(1); // Sleep for 1 second even when logging is disabled
        }
    }

    return 0;
}

// Initialize I2C
int init_i2c()
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read calibration data from the BMP180
int read_calibration_data()
{
    char buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, buf, 22) != 22)
    {
        fprintf(stderr, "Failed to read calibration data block\n");
        return 1;
    }

    ac1 = (buf[0] << 8) | buf[1];
    ac2 = (buf[2] << 8) | buf[3];
    ac3 = (buf[4] << 8) | buf[5];
    ac4 = (buf[6] << 8) | buf[7];
    ac5 = (buf[8] << 8) | buf[9];
    ac6 = (buf[10] << 8) | buf[11];
    b1 = (buf[12] << 8) | buf[13];
    b2 = (buf[14] << 8) | buf[15];
    mb = (buf[16] << 8) | buf[17];
    mc = (buf[18] << 8) | buf[19];
    md = (buf[20] << 8) | buf[21];

    return 0;
}

// Read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp)
{
    char buf[2];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &write_buf[1], 1) != 1)
    {
        fprintf(stderr, "Failed to write temperature measurement command\n");
        return 1;
    }

    gpioDelay(5); // Wait 4.5ms (minimum)

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, &write_buf[0], 0) != 0) {
        fprintf(stderr, "Failed to set register for temperature read\n");
        return 1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2)
    {
        fprintf(stderr, "Failed to read raw temperature data\n");
        return 1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

// Read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure)
{
    char buf[3];
    char write_buf[2];

    write_buf[0] = BMP180_REG_CONTROL;
    write_buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &write_buf[1], 1) != 1)
    {
        fprintf(stderr, "Failed to write pressure measurement command\n");
        return 1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    write_buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, &write_buf[0], 0) != 0) {
        fprintf(stderr, "Failed to set register for pressure read\n");
        return 1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3)
    {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return 1;
    }

    *raw_pressure = ((uint32_t)buf[0] << 16 | (uint32_t)buf[1] << 8 | (uint32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp)
{
    int32_t X1 = (((int32_t)raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, double temperature)
{
    int32_t B6 = ((int32_t)temperature * 10) - 4000;
    int32_t X1 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X2 = ((int32_t)ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    uint32_t X1_u = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_u = ((uint32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t X3_u = ((X1_u + X2_u) + 2) >> 2;
    uint32_t B4 = ((uint32_t)ac4 * (X3_u + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Log data to file
int log_data(double pressure)
{
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL)
    {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f Pa\n", s, pressure);
    fclose(fp);
    return 0;
}

// Toggle logging enabled flag
void toggle_logging()
{
    logging_enabled = !logging_enabled;
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

