#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz

// Define target temperature
#define TARGET_TEMPERATURE 25.0

// Define safe maximum duty cycle
#define SAFE_MAX_DUTY_CYCLE 80

// Define log file name
#define LOG_FILE "heater_log.csv"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
float read_temperature();
int control_heater(float current_temperature, float target_temperature);
void log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// PI controller parameters
float Kp = 1.0;
float Ki = 0.1;
float integral = 0.0;

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        log_data(-999.0, -1); // Log error
        return -999.0; // Indicate error
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        log_data(-998.0, -1); // Log error
        return -998.0; // Indicate error
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        log_data(-997.0, -1); // Log error
        return -997.0; // Indicate error
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        log_data(-996.0, -1); // Log error
        return -996.0; // Indicate error
    }

    // Extract temperature data (ignoring fault bit)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = (float)raw_temp * 0.25;

    return temperature;
}

// Function to control the heater using PWM
int control_heater(float current_temperature, float target_temperature) {
    float error = target_temperature - current_temperature;

    // PI controller
    integral += error;
    float output = Kp * error + Ki * integral;

    // Anti-windup
    if (output > SAFE_MAX_DUTY_CYCLE) {
        output = SAFE_MAX_DUTY_CYCLE;
        integral = 0.0; // Reset integral term
    } else if (output < 0) {
        output = 0;
        integral = 0.0; // Reset integral term
    }

    // Set PWM duty cycle
    int duty_cycle = (int)(output * 100.0); // pigpio duty cycle is 0-100
    gpioPWM(HEATER_PIN, duty_cycle);

    return duty_cycle;
}

// Function to log data to a CSV file
void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioPWM(HEATER_PIN, 0); // Turn off heater
    spiClose(spi_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CE0, PI_OUTPUT); //CS
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_SCLK, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 2MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }
    rewind(log_file);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float current_temperature;
    int duty_cycle;

    while (running) {
        current_temperature = read_temperature();

        if (current_temperature != -999.0) {
            duty_cycle = control_heater(current_temperature, TARGET_TEMPERATURE);
            log_data(current_temperature, duty_cycle);
            printf("Temperature: %.2f C, Duty Cycle: %d%%\n", current_temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature. Turning heater off.\n");
            gpioPWM(HEATER_PIN, 0);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(HEATER_PIN, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

