#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (BCM numbering)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds (m°C)
#define TEMP_BLUE  40000
#define TEMP_GREEN 59999
#define TEMP_RED   60000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to read CPU temperature from file
int read_cpu_temp(void)
{
    FILE *fp;
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL)
    {
        fprintf(stderr, "Error: Failed to open temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1)
    {
        fprintf(stderr, "Error: Failed to read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp))
    {
        fprintf(stderr, "Error: fscanf encountered an error.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to set RGB LED color using hardware PWM
void set_rgb_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common anode
}

int main(void)
{
    int temp;
    int red, green, blue;

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate)
    {
        // Read CPU temperature
        temp = read_cpu_temp();
        if (temp == -1)
        {
            // Error reading temperature, skip this cycle
            gpioDelay(500000); // 0.5 seconds
            continue;
        }

        // Convert temperature to Celsius
        temp = temp / 1000;

        // Determine RGB color based on temperature
        if (temp < TEMP_BLUE)
        {
            red = 0;
            green = 0;
            blue = 255;
        }
        else if (temp < TEMP_GREEN)
