#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 2
#define SERVER_URL "http://yourserver.com/api/humidity"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int i, j;
    unsigned int raw_data[5] = {0};
    unsigned int checksum;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // Changed from 40 to 30 to avoid timeout

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low (response signal)
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
        gpioDelay(1); // Check every 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "Error: DHT22 response timeout (low)\n");
        return data; // Return invalid data
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "Error: DHT22 response timeout (high)\n");
        return data; // Return invalid data
    }

    // Read the 40-bit data stream
    for (i = 0; i < 5; i++) {
        raw_data[i] = 0;
        for (j = 0; j < 8; j++) {
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
                gpioDelay(1);
                timeout++;
            }

            if (timeout >= 100) {
                fprintf(stderr, "Error: DHT22 data timeout (low)\n");
                return data; // Return invalid data
            }

            long start = gpioTick();
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
                gpioDelay(1);
                timeout++;
            }

            if (timeout >= 100) {
                fprintf(stderr, "Error: DHT22 data timeout (high)\n");
                return data; // Return invalid data
            }

            long end = gpioTick();
            if ((end - start) > 40) { // > 40 us indicates a '1'
                raw_data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    checksum = (raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3]) & 0xFF;
    if (checksum != raw_data[4]) {
        fprintf(stderr, "Error: DHT22 checksum mismatch (calculated: %d, received: %d)\n", checksum, raw_data[4]);
        return data; // Return invalid data
    }

    // Convert data to temperature and humidity
    data.humidity = ((raw_data[0] * 256) + raw_data[1]) / 10.0;
    data.temperature = (((raw_data[2] & 0x7F) * 256) + raw_data[3]) / 10.0;
    if (raw_data[2] & 0x80) {
        data.temperature *= -1;
    }
    data.valid = 1;

    return data;
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    char* json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to send HTTP POST request
CURLcode send_http_post(const char* json_payload) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Error: Failed to initialize curl\n");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    return res;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            char* json_payload = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_payload != NULL) {
                CURLcode res = send_http_post(json_payload);
                if (res != CURLE_OK) {
                    fprintf(stderr, "Error: HTTP POST failed (attempt %d)\n", 1);
                }
                free(json_payload);
            } else {
                fprintf(stderr, "Error: Failed to format JSON\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read DHT22 data\n");
        }

        sleep(5);
    }

    gpioTerminate();
    return 0;
}

