#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting
#define BMP180_OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
static int i2c_handle;
static FILE *log_file = NULL;
static volatile int logging_enabled = 0;
static volatile uint32_t last_interrupt_time = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_bmp180();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t ut);
double calculate_pressure(int32_t up, int32_t ut);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to initialize the BMP180 sensor
int init_bmp180() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Open I2C bus 1, BMP180 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t buffer[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buffer, 22);

    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (buffer[0] << 8) | buffer[1];
    ac2 = (buffer[2] << 8) | buffer[3];
    ac3 = (buffer[4] << 8) | buffer[5];
    ac4 = (buffer[6] << 8) | buffer[7];
    ac5 = (buffer[8] << 8) | buffer[9];
    ac6 = (buffer[10] << 8) | buffer[11];
    b1 = (buffer[12] << 8) | buffer[13];
    b2 = (buffer[14] << 8) | buffer[15];
    mb = (buffer[16] << 8) | buffer[17];
    mc = (buffer[18] << 8) | buffer[19];
    md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    gpioDelay(26000); // Wait 26ms for OSS = 3

    uint8_t data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int32_t up, int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");

        if (logging_enabled) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            int32_t raw_temp, raw_pressure;
            if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                double temperature = calculate_temperature(raw_temp);
                double pressure = calculate_pressure(raw_pressure, raw_temp);

                fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, pressure, temperature);
                fflush(log_file); // Ensure data is written to file immediately
            } else {
                fprintf(stderr, "Error reading sensor data in interrupt handler\n");
            }
        }
    }
}

// Signal handler function for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
