#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4 // BCM GPIO 4, physical pin 7
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds
#define DEFAULT_URL "http://your-server.com/api/humidity"

static char *server_url = DEFAULT_URL;
static volatile int running = 1;

// Structure to hold DHT22 data
typedef struct {
    int humidity;
    int checksum;
} DHT22Data;

// Function prototypes
int read_dht22(int gpio, DHT22Data *data);
int validate_checksum(int humidity, int checksum);
int post_humidity(const char *url, int humidity);
void signal_handler(int signal);

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Function to read DHT22 sensor data
int read_dht22(int gpio, DHT22Data *data) {
    int i, j;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // > 1 ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 20-40 us

    gpioSetMode(gpio, PI_INPUT);

    // Read 40 bits of data
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            // Wait for the pin to go high
            int count = 0;
            while (gpioRead(gpio) == 0) {
                count++;
                gpioDelay(1); // Check every microsecond
                if (count > 100) return -1; // Timeout
            }

            // Wait for the pin to go low
            count = 0;
            while (gpioRead(gpio) == 1) {
                count++;
                gpioDelay(1);
                if (count > 100) return -1; // Timeout
            }

            // Determine if it's a 0 or a 1 based on the length of the high pulse
            if (count > 40) {
                raw_data[i] |= (1 << (7 - j));
            }
        }
    }

    // Validate checksum
    if (!validate_checksum(raw_data[0], raw_data[1] + raw_data[2] + raw_data[3])) {
        syslog(LOG_ERR, "Checksum validation failed");
        return -2;
    }

    data->humidity = raw_data[0];
    data->checksum = raw_data[1];

    return 0;
}

// Function to validate the checksum
int validate_checksum(int humidity, int checksum) {
    return (humidity == (checksum & 0xFF));
}

// Function to POST humidity data to the server
int post_humidity(const char *url, int humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[50];
    int retries = 0;
    int backoff_delay = 1;

    snprintf(json_data, sizeof(json_data), "{\"humidity\": %d}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        while (retries < MAX_RETRIES) {
            res = curl_easy_perform(curl);
            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "Humidity posted successfully. Response code: %ld", response_code);
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 0;
                } else {
                    syslog(LOG_ERR, "HTTP request failed. Response code: %ld", response_code);
                }
            } else {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            }

            retries++;
            if (retries < MAX_RETRIES) {
                syslog(LOG_WARNING, "Retrying in %d seconds...", backoff_delay);
                sleep(backoff_delay);
                backoff_delay *= 2; // Exponential backoff
            }
        }

        syslog(LOG_ERR, "Failed to post humidity after %d retries.", MAX_RETRIES);
        curl_easy_cleanup(curl);
        curl_global_cleanup();
        return -1;
    } else {
        syslog(LOG_ERR, "Failed to initialize libcurl.");
        curl_global_cleanup();
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return 1;
        }
    }

    // Initialize syslog
    openlog("dht22_humidity_poster", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        DHT22Data data;
        int result;

        result = read_dht22(DHT22_GPIO, &data);

        if (result == 0) {
            syslog(LOG_INFO, "Humidity: %d%%", data.humidity);
            if (post_humidity(server_url, data.humidity) != 0) {
                syslog(LOG_ERR, "Failed to post humidity.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 sensor. Error code: %d", result);
        }

        sleep(10);
    }

    // Cleanup
    gpioTerminate();
    closelog();
    curl_global_cleanup();

    return 0;
}

