    char buffer[10];

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read temperature");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &temp) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        return -1;
    }

    return temp;
}

int read_fan_max_state() {
    FILE *fp;
    int max_state = -1;
    char buffer[10];

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open fan max_state file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        perror("Failed to read fan max_state");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &max_state) != 1) {
        fprintf(stderr, "Failed to parse fan max_state\n");
        return -1;
    }

    return max_state;
}

