    FILE *fp;
    int max_state = read_fan_max_state();

    if (max_state == -1) {
        fprintf(stderr, "Failed to read fan max_state, cannot set speed\n");
        return -1;
    }

    if (speed < 0 || speed > max_state) {
        fprintf(stderr, "Invalid fan speed: %d, max_state: %d\n", speed, max_state);
        return -1;
    }

    fp = fopen(FAN_FILE, "w");
    if (fp == NULL) {
        perror("Failed to open fan file for writing");
        return -1;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        perror("Failed to write fan speed");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

