    signal(SIGTERM, signal_handler);

    while (program_running) {
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature, using previous fan speed\n");
        } else {
            if (temp < 45000) {
                fan_speed = 0;
            } else if (temp < 55000) {
                fan_speed = 1;
            } else if (temp < 65000) {
                fan_speed = 2;
            } else {
                fan_speed = 3;
            }

            if (set_fan_speed(fan_speed) != 0) {
                fprintf(stderr, "Failed to set fan speed, using previous fan speed\n");
            }
        }

        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (fan_speed != 0 && fan_speed != fan_speed) {
            log_fp = fopen(LOG_FILE, "a");
            if (log_fp != NULL) {
                fprintf(log_fp, "%s: Fan speed changed to %d\n", timestamp, fan_speed);
                fclose(log_fp);
            } else {
                perror("Failed to open log file");
            }
        }

        sleep(5);
    }

    if (set_fan_speed(0) != 0) {
