#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK_PIN 11
#define SPI_CS_PIN 8
#define SPI_DO_PIN 9

// Define PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define target temperature
#define TARGET_TEMPERATURE 50.0

// Define failsafe temperature limits
#define FAILSAFE_MIN_TEMP 0.0
#define FAILSAFE_MAX_TEMP 100.0

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 500000 // 500 kHz

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
double read_temperature();
void set_heater_pwm(double duty_cycle);
double calculate_pid(double current_temperature, double target_temperature, double *integral, double *previous_error);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char buffer[4];
    int result;

    result = spiRead(spi_handle, buffer, 4);
    if (result != 4) {
        fprintf(log_file, "%ld SPI read error: %d\n", time(NULL), result);
        fflush(log_file);
        return -273.15; // Return absolute zero on error
    }

    // Check for fault bits
    if (buffer[3] & 0x01) {
        fprintf(log_file, "%ld MAX31855 Fault: Open circuit\n", time(NULL));
        fflush(log_file);
        return -273.15; // Indicate error
    }
    if (buffer[3] & 0x02) {
        fprintf(log_file, "%ld MAX31855 Fault: Short to GND\n", time(NULL));
        fflush(log_file);
        return -273.15; // Indicate error
    }
    if (buffer[3] & 0x04) {
        fprintf(log_file, "%ld MAX31855 Fault: Short to VCC\n", time(NULL));
        fflush(log_file);
        return -273.15; // Indicate error
    }

    // Extract temperature data (ignoring fault bits for now)
    int16_t raw_temp = ((buffer[0] << 8) | buffer[1]) >> 2;
    double temperature = (double)raw_temp * 0.25;

    return temperature;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int pulse_width = (int)(duty_cycle * 10000); // pigpio uses microseconds
    gpioPWM(HEATER_PIN, pulse_width / 100);
}

// Function to calculate PID output
double calculate_pid(double current_temperature, double target_temperature, double *integral, double *previous_error) {
    double error = target_temperature - current_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.6f\n", now, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set heater pin as output
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Set PWM frequency for heater pin
    gpioSetPWMfrequency(HEATER_PIN, 1000); // 1 kHz
    gpioSetPWMrange(HEATER_PIN, 10000); // Range 0-10000 for percentage

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double integral = 0.0;
    double previous_error = 0.0;

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature > FAILSAFE_MAX_TEMP || temperature < FAILSAFE_MIN_TEMP) {
            fprintf(log_file, "%ld Failsafe triggered: Temperature out of range\n", time(NULL));
            fflush(log_file);
            set_heater_pwm(0.0); // Disable heater
            running = 0; // Stop the loop
            continue; // Skip to the next iteration
        }

        if (temperature < -273.0) {
            fprintf(log_file, "%ld Invalid temperature reading\n", time(NULL));
            fflush(log_file);
            set_heater_pwm(0.0); // Disable heater
            running = 0; // Stop the loop
            continue; // Skip to the next iteration
        }

        // Calculate PID output
        double pid_output = calculate_pid(temperature, TARGET_TEMPERATURE, &integral, &previous_error);

        // Set heater PWM
        set_heater_pwm(pid_output);

        // Log data
        log_data(temperature, gpioGetPWMdutycycle(HEATER_PIN) / 10.0, pid_output);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Clean up
    set_heater_pwm(0.0); // Disable heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

