#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

int read_cpu_temp() {
    FILE *fp;
    int temp = 0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

int calculate_duty_cycle(int temp) {
    int duty_cycle = 0;

    if (temp <= 40000) {
        duty_cycle = 0;
    } else if (temp >= 70000) {
        duty_cycle = 1000000;
    } else {
        duty_cycle = (int)(((float)(temp - 40000) / (70000 - 40000)) * 1000000);
    }

    return duty_cycle;
}

int set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

int log_data(int temp, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, (float)temp / 1000.0, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    int temp, duty_cycle;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Write CSV header if the file is new
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        fp = fopen(LOG_FILE, "w");
        if (fp != NULL) {
            fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
            fclose(fp);
        } else {
            perror("Error creating log file");
            gpioTerminate();
            return 1;
        }
    } else {
        fclose(fp);
    }

    while (!terminate) {
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting\n");
            // Consider a default temperature or exiting the loop/program
        } else {
            duty_cycle = calculate_duty_cycle(temp);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed, continuing...\n");
            }
            if (log_data(temp, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data, continuing...\n");
            }
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down fan and terminating pigpio...\n");
    set_fan_speed(0); // Turn off the fan
    gpioTerminate();   // Terminate pigpio

    return 0;
}

