    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, (float)temp / 1000.0, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
