#include <time.h>
#include <signal.h>
#include <string.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define measurement command
#define MEASURE_CMD 0x3608

// Define CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int i2c_handle, int sensor_addr, float *flow_rate);
int validate_crc(uint8_t data[], int len);
void log_data(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, int sensor_addr, float *flow_rate) {
    char buf[3];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 3);
        if (result == 3) {
            // Success
            break;
        } else {
            fprintf(stderr, "I2C read error (sensor 0x%02X), retrying...\n", sensor_addr);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (result != 3) {
        fprintf(stderr, "Failed to read from sensor 0x%02X after multiple retries.\n", sensor_addr);
        return -1; // Indicate failure
    }

    // Convert raw data to flow rate
    int16_t raw_value = (buf[0] << 8) | buf[1];
    *flow_rate = (float)raw_value * 0.01;

    // Validate CRC
    uint8_t data[2] = {buf[0], buf[1]};
    if (!validate_crc(data, 2)) {
        fprintf(stderr, "CRC validation failed for sensor 0x%02X.\n", sensor_addr);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to validate CRC-8 checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len]);
}

// Function to log data to a file
void log_data(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (program_running) {
        // Read data from sensor 1
        if (read_sensor(i2c_handle1, SENSOR1_ADDR, &flow1) == 0) {
            // Read data from sensor 2
            if (read_sensor(i2c_handle2, SENSOR2_ADDR, &flow2) == 0) {
                // Log the data
                log_data(flow1, flow2);
            } else {
                fprintf(stderr, "Error reading sensor 2.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor 1.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

