#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18

// Define the number of pulses per revolution (360 degrees)
#define PULSES_PER_REVOLUTION 360

// Define the quadrature state machine states
typedef enum {
    STATE_A,
    STATE_B,
    STATE_C,
    STATE_D
} QuadratureState;

// Global variable to store the current quadrature state
QuadratureState currentState = STATE_A;

// Global variable to store the current angular position
float currentAngle = 0.00;

// File pointer for the log file
FILE *logFile = NULL;

// Function prototypes
int initializeGPIO();
void handleGPIOError(int errorCode, const char *message);
void encoderISR(int gpio, int level, uint32_t tick, void *user);
void updateAngle(int a, int b);
void logState(float angle);
void signalHandler(int signal);

// Signal handler function to handle SIGINT and SIGTERM
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the log file if it's open
    if (logFile != NULL) {
        fclose(logFile);
        printf("Log file closed.\n");
    }

    // Terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

// Function to initialize the pigpio library and configure GPIO pins
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP);
    gpioSetMode(ENCODER_B_PIN, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP);

    // Set up interrupt service routines (ISRs) for both channels
    if (gpioSetISRFuncEx(ENCODER_A_PIN, RISING_EDGE, 0, encoderISR, NULL) != 0) {
        handleGPIOError(1, "Failed to set ISR for ENCODER_A_PIN");
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_PIN, RISING_EDGE, 0, encoderISR, NULL) != 0) {
        handleGPIOError(1, "Failed to set ISR for ENCODER_B_PIN");
        return 1;
    }

    return 0; // Indicate success
}

// Function to handle GPIO errors
void handleGPIOError(int errorCode, const char *message) {
    fprintf(stderr, "GPIO Error: %s (Error Code: %d)\n", message, errorCode);
    gpioTerminate();
    exit(1);
}

// Interrupt service routine (ISR) for the rotary encoder
void encoderISR(int gpio, int level, uint32_t tick, void *user) {
    static int lastA = 0;
    static int lastB = 0;
    int a = gpioRead(ENCODER_A_PIN);
    int b = gpioRead(ENCODER_B_PIN);

    if (a != lastA) {
        if (a != b) {
            if (a == 1) {
                currentState = (currentState == STATE_A) ? STATE_C : (currentState == STATE_C) ? STATE_A : STATE_B;
            } else {
                currentState = (currentState == STATE_A) ? STATE_B : (currentState == STATE_B) ? STATE_A : STATE_D;
            }
        }
    }

    if (b != lastB) {
        if (b != a) {
            if (b == 1) {
                currentState = (currentState == STATE_B) ? STATE_A : (currentState == STATE_A) ? STATE_C : STATE_D;
            } else {
                currentState = (currentState == STATE_B) ? STATE_D : (currentState == STATE_D) ? STATE_A : STATE_C;
            }
        }
    }

    lastA = a;
    lastB = b;

    updateAngle(a, b);
}

// Function to update the current angle based on the quadrature state machine
void updateAngle(int a, int b) {
    switch (currentState) {
        case STATE_A:
            currentAngle = 0.00;
            break;
        case STATE_B:
            currentAngle = 90.00;
            break;
        case STATE_C:
            currentAngle = 180.00;
            break;
        case STATE_D:
            currentAngle = 270.00;
            break;
    }

    // Normalize the angle to be between 0.00 and 360.00
    if (currentAngle > 360.00) {
        currentAngle -= 360.00;
    } else if (currentAngle < 0.00) {
        currentAngle += 360.00;
    }
}

// Function to log the current state to a file
void logState(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (logFile != NULL) {
        fprintf(logFile, "%s, Angle: %.2f\n", timestamp, angle);
        fflush(logFile); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize the pigpio library
    if (initializeGPIO() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file in append mode
    logFile = fopen("encoder_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Rotary encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to continuously monitor the encoder
    while (1) {
        // Log the current state every 100 milliseconds
        gpioDelay(100000); // 100 milliseconds
        logState(currentAngle);
    }

    return 0; // This line will never be reached due to the infinite loop
}

