#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define PULSES_PER_REVOLUTION 1

static volatile int pulse_count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal)
{
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Interrupt service routine (ISR)
void pulse_counter(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&mutex);
    pulse_count++;
    pthread_mutex_unlock(&mutex);
}

// Function to calculate RPM
double calculate_rpm()
{
    pthread_mutex_lock(&mutex);
    int local_pulse_count = pulse_count;
    pulse_count = 0; // Reset pulse count for next interval
    pthread_mutex_unlock(&mutex);

    return (double)local_pulse_count / PULSES_PER_REVOLUTION * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL)
    {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, rpm);
    fflush(fp);
    fclose(fp);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register ISR for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_counter, NULL) != 0)
    {
        fprintf(stderr, "Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    while (running)
    {
        // Calculate RPM
        double rpm = calculate_rpm();

        // Log RPM
        log_rpm(rpm);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Clean up and exit
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    printf("RPM monitoring stopped.\n");
    return 0;
}

