#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADPD144RI I2C address
#define ADPD144RI_ADDR 0x39

// ADPD144RI Register Addresses
#define ADPD144RI_PART_ID 0x00
#define ADPD144RI_RED_DATA_HIGH 0x02
#define ADPD144RI_RED_DATA_LOW 0x03
#define ADPD144RI_IR_DATA_HIGH 0x04
#define ADPD144RI_IR_DATA_LOW 0x05
#define ADPD144RI_FIFO_DATA 0x06
#define ADPD144RI_FIFO_CONTROL 0x08
#define ADPD144RI_INTERRUPT_ENABLE 0x09
#define ADPD144RI_INTERRUPT_STATUS 0x0A
#define ADPD144RI_FIFO_THRESHOLD 0x0B
#define ADPD144RI_LED_DRIVE 0x0C
#define ADPD144RI_LED_CURRENT 0x0D
#define ADPD144RI_CHIP_ID 0x11
#define ADPD144RI_RESET 0x12

// GPIO pin for LED
#define LED_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_register(uint8_t reg, uint8_t *value);
int write_register(uint8_t reg, uint8_t value);
int read_sensor_data(sensor_data_t *data);
void control_led(uint16_t ir_value);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read a single byte from a register
int read_register(uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Write a single byte to a register
int write_register(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read sensor data from FIFO
int read_sensor_data(sensor_data_t *data) {
    uint8_t high_byte, low_byte;

    if (read_register(ADPD144RI_RED_DATA_HIGH, &high_byte) < 0) return -1;
    if (read_register(ADPD144RI_RED_DATA_LOW, &low_byte) < 0) return -1;
    data->red = (high_byte << 8) | low_byte;

    if (read_register(ADPD144RI_IR_DATA_HIGH, &high_byte) < 0) return -1;
    if (read_register(ADPD144RI_IR_DATA_LOW, &low_byte) < 0) return -1;
    data->ir = (high_byte << 8) | low_byte;

    return 0;
}

// Control the LED based on IR value
void control_led(uint16_t ir_value) {
    if (ir_value > 2000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data.red, data.ir);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Control LED
            control_led(sensor_data.ir);

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

