#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_CONTROL_PIN 18
#define SAMPLE_INTERVAL_MS 10

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_CONTROL_PIN, PI_OUTPUT);
    gpioWrite(GAIN_CONTROL_PIN, 0); // Set GAIN to 60dB

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening audio_log.txt");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Poll for rising edge
        if (gpioRead(AUDIO_INPUT_PIN) == 1) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            fprintf(log_file, "%s 1\n", timestamp);
            fflush(log_file); // Ensure data is written to file immediately

            // Debounce: Wait for a short period to avoid multiple triggers for the same event
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
        }

        gpioDelay(1000); // Check every 1 ms
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    printf("Audio peak detection stopped.\n");
    return 0;
}

