#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Sensor I2C address
#define SLF3S_ADDR 0x36

// I2C bus
#define I2C_BUS 1

// Measurement command
#define MEASURE_CMD 0x3608

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_flow_data(int16_t *raw_flow, uint8_t *crc);
float convert_to_flow_rate(int16_t raw_flow);
int validate_crc(uint8_t crc, uint8_t data[], int len);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the SLF3S-4000B sensor
int initialize_sensor() {
    char buf[2];
    buf[0] = (MEASURE_CMD >> 8) & 0xFF;
    buf[1] = MEASURE_CMD & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    return 0;
}

// Reads flow data from the sensor
int read_flow_data(int16_t *raw_flow, uint8_t *crc) {
    char buf[3];

    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    *raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *crc = buf[2];

    return 0;
}

// Converts raw flow data to flow rate in uL/min
float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / 1000.0;
}

// Validates the CRC-8 checksum
int validate_crc(uint8_t crc, uint8_t data[], int len) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc) ? 0 : -1;
}

// Logs the flow rate to a CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.3f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t raw_flow;
    uint8_t crc;
    float flow_rate;

    // Main loop
    while (!terminate) {
        if (read_flow_data(&raw_flow, &crc) == 0) {
            if (validate_crc(crc, (uint8_t *)&raw_flow, 2) == 0) {
                flow_rate = convert_to_flow_rate(raw_flow);
                log_flow_rate(flow_rate);
                printf("Flow Rate: %.3f uL/min\n", flow_rate);
            } else {
                fprintf(stderr, "CRC validation failed.\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow data.\n");
        }

        gpioDelay(1000); // Wait 1000 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

