    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,IAQ,TVOC,eCO2\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate IAQ index
            float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);

            // Log data
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            printf("IAQ: %.2f, TVOC: %u ppb, eCO2: %u ppm\n", iaq, sensor_data.tvoc, sensor_data.eco2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

