#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_LINE 17
#define CONSUMER_LABEL "ttp223_tamper"
#define INTRUSION_TIMEOUT 5 // seconds

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;
static time_t last_touch_time = 0;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to check if the sensor has been continuously touched for the intrusion timeout
int is_intrusion_detected(time_t last_touch_time)
{
    time_t current_time = time(NULL);
    if (current_time - last_touch_time >= INTRUSION_TIMEOUT) {
        return 1;
    }
    return 0;
}

// Function to print an intrusion alert
void print_intrusion_alert()
{
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    printf("INTRUSION DETECTED: %s\n", buf);
}

int main()
{
    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as input
    if (gpiod_line_request_input(line, CONSUMER_LABEL) < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (keep_running) {
        int sensor_value = read_sensor(line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value == 1) {
            time_t now = time(NULL);
            if (last_touch_time == 0) {
                last_touch_time = now;
            }

            if (is_intrusion_detected(last_touch_time)) {
                print_intrusion_alert();
                last_touch_time = 0; // Reset the timer after printing the alert
            }
        } else {
            last_touch_time = 0; // Reset the timer if the sensor is released
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

