#include <stdio.h>
#include <stdlib.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>

// Define GPIO pin for L/R select
#define GPIO_PIN 17

// Define audio parameters
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S16_LE
#define PERIOD_SIZE 1024

// Global variables for signal handling
snd_pcm_t *pcm_handle = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO
int gpio_init(int pin)
{
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "audio_capture", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to set GPIO value
void gpio_set_value(int pin, int value)
{
    if (gpiod_line_set_value(gpio_line, value) < 0) {
        perror("Error setting GPIO value");
    }
}

// Function to initialize ALSA
int alsa_init(int sample_rate, int num_channels, snd_pcm_format_t format, int period_size)
{
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "cannot open audio device default (%s)\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "cannot initialize hardware parameter structure (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "cannot set access type (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, format)) < 0) {
        fprintf(stderr, "cannot set sample format (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, num_channels)) < 0) {
        fprintf(stderr, "cannot set channel count (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "cannot set sample rate (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size_near(pcm_handle, hw_params, &period_size, 0)) < 0) {
        fprintf(stderr, "cannot set period size (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "cannot set parameters (%s)\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

// Function to read audio data from ALSA
int alsa_read_data(short *buffer, int num_frames)
{
    int err = snd_pcm_readi(pcm_handle, buffer, num_frames);
    if (err < 0) {
        fprintf(stderr, "error from read: %s\n", snd_strerror(err));
        return -1;
    }
    return err;
}

// Function to write audio data to file
int write_to_file(const char *filename, const short *buffer, int num_frames)
{
    FILE *fp = fopen(filename, "ab");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(buffer, sizeof(short), num_frames, fp);
    if (bytes_written != num_frames) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (gpio_init(GPIO_PIN) < 0) {
        return 1;
    }

    // Set GPIO to low initially (select left channel)
    gpio_set_value(GPIO_PIN, 0);

    // Initialize ALSA
    if (alsa_init(SAMPLE_RATE, NUM_CHANNELS, FORMAT, PERIOD_SIZE) < 0) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Allocate buffer for audio data
    short *buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (!buffer) {
        fprintf(stderr, "Error allocating memory for buffer\n");
        snd_pcm_close(pcm_handle);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read audio data
        int frames_read = alsa_read_data(buffer, PERIOD_SIZE);
        if (frames_read > 0) {
            // Write audio data to file
            if (write_to_file("audio_capture.pcm", buffer, frames_read) < 0) {
                fprintf(stderr, "Error writing audio data to file\n");
                break;
            }
        } else if (frames_read < 0) {
            fprintf(stderr, "Error reading audio data\n");
            break;
        }
    }

    // Clean up resources
    free(buffer);
    snd_pcm_close(pcm_handle);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

