#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Shutdown signal received.");
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency for the fan pin
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);

    return 0;
}

// Read flame sensor value with debouncing
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    gpioDelay(50000); // 50 ms debounce
    return value;
}

// Control the cooling fan
void control_fan(int flame_detected) {
    static int flame_start_time = 0;
    static int flame_duration = 0;
    int duty_cycle = 0;

    if (flame_detected) {
        // Calculate flame duration using an exponential curve
        flame_duration = (flame_duration * 0.9) + 10; // Decay with a small increment
        if (flame_duration > 500) flame_duration = 500; // Cap at 500ms

        // Scale duty cycle based on flame duration (0-80%)
        duty_cycle = (int)(((float)flame_duration / 500.0) * 80.0);

        gpioPWM(FAN_PIN, duty_cycle); // Set PWM duty cycle
        log_event("Flame detected, fan started.");
    } else {
        gpioPWM(FAN_PIN, 0); // Stop the fan
        log_event("Flame ended, fan stopped.");
    }
}

// Log events to file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

