#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define data buffer size
#define DATA_BUFFER_SIZE 32768

// Define magic number
#define MAGIC_NUMBER 0x52444144

// Define data structure for configuration
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
    uint16_t frame_period_ms;
} config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi();
int configure_gpio();
int write_header(FILE *file, config_t config);
int read_data(uint8_t *data_buffer);
int log_frame(FILE *file, uint32_t frame_number, uint8_t *data_buffer);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure GPIO pins
int configure_gpio() {
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_UP); // Enable pull-up resistor
    return 0;
}

// Write header to log file
int write_header(FILE *file, config_t config) {
    uint8_t header[8];
    uint8_t *ptr = header;
    uint32_t magic_number_bytes[4];
    magic_number_bytes[0] = (MAGIC_NUMBER >> 0) & 0xFF;
    magic_number_bytes[1] = (MAGIC_NUMBER >> 8) & 0xFF;
    magic_number_bytes[2] = (MAGIC_NUMBER >> 16) & 0xFF;
    magic_number_bytes[3] = (MAGIC_NUMBER >> 24) & 0xFF;

    memcpy(ptr, magic_number_bytes, 4);
    ptr += 4;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;
    uint8_t timestamp_bytes[8];
    memcpy(timestamp_bytes, &timestamp, 8);
    memcpy(ptr, timestamp_bytes, 8);
    ptr += 8;

    memcpy(ptr, &config, sizeof(config_t));
    ptr += sizeof(config_t);

    fwrite(header, 1, ptr - header, file);
    return 0;
}

// Read data from SPI
int read_data(uint8_t *data_buffer) {
    int bytes_read = spiRead(spi_handle, data_buffer, DATA_BUFFER_SIZE);
    if (bytes_read != DATA_BUFFER_SIZE) {
        fprintf(stderr, "SPI read failed: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Log frame data to file
int log_frame(FILE *file, uint32_t frame_number, uint8_t *data_buffer) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    uint8_t *ptr = data_buffer;
    fwrite(ptr, 1, DATA_BUFFER_SIZE, file);

    fprintf(file, "Frame: %u, Timestamp: %llu\n", frame_number, timestamp);
    fflush(file);
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (gpio == DATA_READY_PIN && level == 0) { // Falling edge indicates data ready
        uint8_t *data_buffer = (uint8_t *)malloc(DATA_BUFFER_SIZE);
        if (data_buffer == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        if (read_data(data_buffer) == 0) {
            uint32_t frame_number = 0; // Placeholder frame number
            log_frame(log_file, frame_number, data_buffer);
        }
        free(data_buffer);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins
    if (configure_gpio() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("radar_data.log", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    config_t config = {77000000, 79000000, 64, 256, 100};
    if (write_header(log_file, config) != 0) {
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler
    gpioSetAlertFunc(DATA_READY_PIN, interrupt_handler);

    printf("Data acquisition started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

