        int current_value = read_flame_sensor(line);
        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        if (current_value != prev_value) {
            if (log_state_transition(log_fp, current_value) < 0) {
                fprintf(stderr, "Error logging state transition, exiting.\n");
                break;
            }
            prev_value = current_value;
        }

        usleep(100000); // 100 milliseconds
    }

    // Cleanup
    printf("Cleaning up resources.\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

