#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_data);
float calculate_lux(uint16_t raw_data);
int log_data(float lux);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t raw_data;
    float lux;
} sensor_data_t;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        sensor_data_t sensor_data;

        // Read sensor data
        if (read_sensor_data(&sensor_data.raw_data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Continue to the next iteration
        }

        // Calculate lux
        sensor_data.lux = calculate_lux(sensor_data.raw_data);

        // Log the data
        if (log_data(sensor_data.lux) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure the sensor
int configure_sensor() {
    // Continuous conversion mode, 100ms conversion time, auto range
    uint16_t config_value = 0x1080; // 0b0001000010000000
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 3);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (config): %d, retries left: %d\n", result, retries);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to configure sensor after multiple retries\n");
    return 1;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_data) {
    char buf[1];
    buf[0] = RESULT_REG;

    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result == 0) {
            char read_buf[2];
            result = i2cReadDevice(i2c_handle, read_buf, 2);
            if (result == 2) {
                *raw_data = (read_buf[0] << 8) | read_buf[1];
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (result): %d, retries left: %d\n", result, retries);
            }
        } else {
            fprintf(stderr, "I2C write failed (result): %d, retries left: %d\n", result, retries);
        }
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries\n");
    return 1;
}

// Calculate lux
float calculate_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int mantissa = raw_data & 0x0FFF;
    return 0.01 * (float)(1 << exponent) * mantissa;
}

// Log data to file
int log_data(float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

