#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 channels
#define TTP226_PIN_1 2
#define TTP226_PIN_2 3
#define TTP226_PIN_3 4
#define TTP226_PIN_4 5
#define TTP226_PIN_5 6
#define TTP226_PIN_6 7
#define TTP226_PIN_7 8
#define TTP226_PIN_8 9

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

int main()
{
    int i, pin;
    int state;

    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (pin = TTP226_PIN_1; pin <= TTP226_PIN_8; pin++)
    {
        gpioSetMode(pin, PI_INPUT);
    }

    // Main loop to read and log the sensor data
    while (!terminate)
    {
        for (pin = TTP226_PIN_1; pin <= TTP226_PIN_8; pin++)
        {
            state = gpioRead(pin);
            if (state == PI_BAD_GPIO)
            {
                fprintf(stderr, "Error reading GPIO %d\n", pin);
            } else {
                printf("Channel %d: %d\n", pin, state);
            }
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

