// Define the GPIO pins connected to the TTP226 sensor outputs
#define TTP226_PIN_1 2
#define TTP226_PIN_2 3
#define TTP226_PIN_3 4
#define TTP226_PIN_4 5
#define TTP226_PIN_5 6
#define TTP226_PIN_6 7
#define TTP226_PIN_7 8
#define TTP226_PIN_8 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGTERM, exiting gracefully...\n");
}

int main() {
    int i;
    int gpio_status;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Configure each GPIO pin as an input with a pull-down resistor
    for (i = 0; i < 8; i++) {
        gpio_status = gpioSetMode(TTP226_PIN_1 + i, PI_INPUT);
        if (gpio_status != 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d: %d\n", TTP226_PIN_1 + i, gpio_status);
            gpioTerminate();
            return 1;
        }

        gpio_status = gpioSetPullUpDown(TTP226_PIN_1 + i, PI_PUD_DOWN);
        if (gpio_status != 0) {
            fprintf(stderr, "Failed to set pull-down for GPIO %d: %d\n", TTP226_PIN_1 + i, gpio_status);
            gpioTerminate();
            return 1;
        }

        // Validate the configuration by reading the pin and checking if it returns 0
        int read_value = gpioRead(TTP226_PIN_1 + i);
        if (read_value != 0) {
            fprintf(stderr, "GPIO %d configuration invalid: expected 0, got %d\n", TTP226_PIN_1 + i, read_value);
            gpioTerminate();
            return 1;
        }
    }

    // Main sampling loop
    while (program_running) {
        // Get the current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "[+%1234 ms]", time_info);

        // Read the state of each channel
        for (i = 0; i < 8; i++) {
            int read_value = gpioRead(TTP226_PIN_1 + i);
            printf("%s CH%d=%d", timestamp, i + 1, read_value);
        }
        printf("\n");

        // Delay for 100 milliseconds
        gpioDelay(100000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

