#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

// Define the GPIO lines connected to the TTP226 channels
const int gpio_lines[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_lines = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[8]; // Assuming a maximum of 8 lines

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            struct gpiod_line_request_config config;
            memset(&config, 0, sizeof(config));
            config.consumer = "touch_sensor";
            config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

            if (gpiod_line_release(lines[i]) < 0) {
                perror("Error releasing GPIO line");
            }

            lines[i] = NULL;
        }
    }

    // Close the GPIO chip
    if (chip) {
        if (gpiod_chip_close(chip) < 0) {
            perror("Error closing GPIO chip");
        }
        chip = NULL;
    }

    exit(0);
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request the GPIO lines
    for (int i = 0; i < num_lines; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                if (lines[j]) {
                    struct gpiod_line_request_config config;
                    memset(&config, 0, sizeof(config));
                    config.consumer = "touch_sensor";
                    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            chip = NULL;
            return 1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line");
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                if (lines[j]) {
                    struct gpiod_line_request_config config;
                    memset(&config, 0, sizeof(config));
                    config.consumer = "touch_sensor";
                    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            chip = NULL;
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Get the current time
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        // Read the state of each channel
        int channel_states[8] = {0};
        for (int i = 0; i < num_lines; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Error reading GPIO line");
                // Release previously acquired lines
                for (int j = 0; j < num_lines; j++) {
                    if (lines[j]) {
                        struct gpiod_line_request_config config;
                        memset(&config, 0, sizeof(config));
                        config.consumer = "touch_sensor";
                        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
                        gpiod_line_release(lines[j]);
                    }
                }
                gpiod_chip_close(chip);
                chip = NULL;
                return 1;
            }
            channel_states[i] = value;
        }

        // Log the data to the console
        printf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n", timestamp,
               channel_states[0], channel_states[1], channel_states[2],
               channel_states[3], channel_states[4], channel_states[5],
               channel_states[6], channel_states[7]);

        // Wait for 50 milliseconds
        struct timespec req = {0, 50000000}; // 50 milliseconds
        nanosleep(&req, NULL);
    }

    return 0;
}

