#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x18
#define SI1145_CHLIST 0x01
#define SI1145_ALS_FORCE 0x06
#define SI1145_UV_INDEX 0x2C
#define SI1145_ALS_VIS 0x22

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_uv_index();
int read_als_visible();
void log_data(int uv_index, int als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the Si1145 sensor
int si1145_init() {
    int part_id;

    // Check PART ID
    part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    // Configure CHLIST
    if (i2cWriteByteData(i2c_handle, SI1145_CHLIST, 0x01) < 0) {
        fprintf(stderr, "Error writing CHLIST\n");
        return -1;
    }

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, SI1145_ALS_FORCE, 0x07) < 0) {
        fprintf(stderr, "Error writing ALS_FORCE\n");
        return -1;
    }

