#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define ALARM_HIGH 1
#define ALARM_LOW 0
#define FLOW_LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Sensor-specific constants
#define START_MEASUREMENT_CMD_HIGH 0x36
#define START_MEASUREMENT_CMD_LOW 0x08
#define FLOW_DATA_REG 0x00
#define FLOW_DATA_LENGTH 3

// Global variables
static int i2c_fd1 = -1;
static int i2c_fd2 = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int i2c_close(int fd);
int gpio_init(const char *chipname, int pin);
int gpio_set_value(int line, int value);
int gpio_uninit(int line);
int log_message(const char *message);
float convert_flow_rate(unsigned char *data);
unsigned char calculate_crc(unsigned char *data, int len);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// GPIO initialization function
int gpio_init(const char *chipname, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chipname);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }
    if (gpiod_line_request_output(gpio_line, "flow_control", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        return -1;
    }
    return 0;
}

// GPIO set value function
int gpio_set_value(int line, int value) {
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// GPIO uninitialize function
int gpio_uninit(int line) {
    if (gpiod_line_release(gpio_line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    if (gpiod_chip_close(gpio_chip) < 0) {
        perror("Error closing GPIO chip");
        return -1;
    }
    return 0;
}

// Log message function
int log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return -1;
    }
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
    return 0;
}

// Convert flow rate function
float convert_flow_rate(unsigned char *data) {
    int16_t flow_raw = (data[0] << 8) | data[1];
    return (float)flow_raw * 0.036;
}

// Calculate CRC function
unsigned char calculate_crc(unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Initialize I2C for both sensors
    i2c_fd1 = i2c_open(1, SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        log_message("Failed to open I2C device for sensor 1");
        goto cleanup;
    }

    i2c_fd2 = i2c_open(1, SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        log_message("Failed to open I2C device for sensor 2");
        goto cleanup;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        log_message("Failed to initialize GPIO");
        goto cleanup;
    }

    // Send start measurement command to both sensors
    unsigned char start_cmd[2] = {START_MEASUREMENT_CMD_HIGH, START_MEASUREMENT_CMD_LOW};
    if (i2c_write(i2c_fd1, start_cmd, 2) < 0) {
        log_message("Failed to send start measurement command to sensor 1");
        goto cleanup;
    }
    usleep(100000); // 100ms delay

    if (i2c_write(i2c_fd2, start_cmd, 2) < 0) {
        log_message("Failed to send start measurement command to sensor 2");
        goto cleanup;
    }
    usleep(100000); // 100ms delay

    // Main loop
    while (!terminate) {
        unsigned char flow_data1[FLOW_DATA_LENGTH];
        unsigned char flow_data2[FLOW_DATA_LENGTH];
        float flow_rate1, flow_rate2, avg_flow_rate;
        int flow_crc_valid1, flow_crc_valid2;

        // Read flow data from sensor 1
        if (i2c_read(i2c_fd1, flow_data1, FLOW_DATA_LENGTH) < 0) {
            log_message("Failed to read flow data from sensor 1");
            flow_rate1 = -1.0; // Indicate error
            flow_crc_valid1 = 0;
        } else {
            unsigned char crc = calculate_crc(flow_data1, FLOW_DATA_LENGTH - 1);
            if (crc == flow_data1[FLOW_DATA_LENGTH - 1]) {
                flow_crc_valid1 = 1;
            } else {
                log_message("CRC check failed for sensor 1");
                flow_crc_valid1 = 0;
            }
            flow_rate1 = convert_flow_rate(flow_data1);
        }

        // Read flow data from sensor 2
        if (i2c_read(i2c_fd2, flow_data2, FLOW_DATA_LENGTH) < 0) {
            log_message("Failed to read flow data from sensor 2");
            flow_rate2 = -1.0; // Indicate error
            flow_crc_valid2 = 0;
        } else {
            unsigned char crc = calculate_crc(flow_data2, FLOW_DATA_LENGTH - 1);
            if (crc == flow_data2[FLOW_DATA_LENGTH - 1]) {
                flow_crc_valid2 = 1;
            } else {
                log_message("CRC check failed for sensor 2");
                flow_crc_valid2 = 0;
            }
            flow_rate2 = convert_flow_rate(flow_data2);
        }

        // Calculate average flow rate
        if (flow_rate1 >= 0 && flow_crc_valid1 && flow_rate2 >= 0 && flow_crc_valid2) {
            avg_flow_rate = (flow_rate1 + flow_rate2) / 2.0;
        } else if (flow_rate1 >= 0 && flow_crc_valid1) {
            avg_flow_rate = flow_rate1;
        } else if (flow_rate2 >= 0 && flow_crc_valid2) {
            avg_flow_rate = flow_rate2;
        } else {
            avg_flow_rate = -1.0; // Indicate error
        }

        // Control alarm based on average flow rate
        if (avg_flow_rate >= 0) {
            if (avg_flow_rate < 0.5) {
                gpio_set_value(gpio_line, ALARM_HIGH);
            } else {
                gpio_set_value(gpio_line, ALARM_LOW);
            }
        } else {
            gpio_set_value(gpio_line, ALARM_LOW); // Disable alarm on error
        }

        // Log average flow rate
        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Average flow rate: %.2f ml/min", avg_flow_rate);
        log_message(log_buffer);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    // Cleanup resources
    if (i2c_fd1 >= 0) i2c_close(i2c_fd1);
    if (i2c_fd2 >= 0) i2c_close(i2c_fd2);
    if (gpio_line) gpio_uninit(gpio_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (log_file) fclose(log_file);

    return EXIT_SUCCESS;
}

