    usleep(100000); // 100ms delay

    if (i2c_write(i2c_fd2, start_cmd, 2) < 0) {
        log_message("Failed to send start measurement command to sensor 2");
        goto cleanup;
    }
    usleep(100000); // 100ms delay

    // Main loop
    while (!terminate) {
        unsigned char flow_data1[FLOW_DATA_LENGTH];
        unsigned char flow_data2[FLOW_DATA_LENGTH];
        float flow_rate1, flow_rate2, avg_flow_rate;
        int flow_crc_valid1, flow_crc_valid2;

        // Read flow data from sensor 1
        if (i2c_read(i2c_fd1, flow_data1, FLOW_DATA_LENGTH) < 0) {
            log_message("Failed to read flow data from sensor 1");
            flow_rate1 = -1.0; // Indicate error
            flow_crc_valid1 = 0;
        } else {
            unsigned char crc = calculate_crc(flow_data1, FLOW_DATA_LENGTH - 1);
            if (crc == flow_data1[FLOW_DATA_LENGTH - 1]) {
                flow_crc_valid1 = 1;
            } else {
                log_message("CRC check failed for sensor 1");
                flow_crc_valid1 = 0;
            }
            flow_rate1 = convert_flow_rate(flow_data1);
        }

        // Read flow data from sensor 2
        if (i2c_read(i2c_fd2, flow_data2, FLOW_DATA_LENGTH) < 0) {
            log_message("Failed to read flow data from sensor 2");
            flow_rate2 = -1.0; // Indicate error
            flow_crc_valid2 = 0;
        } else {
            unsigned char crc = calculate_crc(flow_data2, FLOW_DATA_LENGTH - 1);
            if (crc == flow_data2[FLOW_DATA_LENGTH - 1]) {
                flow_crc_valid2 = 1;
            } else {
                log_message("CRC check failed for sensor 2");
                flow_crc_valid2 = 0;
            }
            flow_rate2 = convert_flow_rate(flow_data2);
        }

        // Calculate average flow rate
        if (flow_rate1 >= 0 && flow_crc_valid1 && flow_rate2 >= 0 && flow_crc_valid2) {
            avg_flow_rate = (flow_rate1 + flow_rate2) / 2.0;
        } else if (flow_rate1 >= 0 && flow_crc_valid1) {
            avg_flow_rate = flow_rate1;
        } else if (flow_rate2 >= 0 && flow_crc_valid2) {
            avg_flow_rate = flow_rate2;
        } else {
            avg_flow_rate = -1.0; // Indicate error
        }

        // Control alarm based on average flow rate
        if (avg_flow_rate >= 0) {
            if (avg_flow_rate < 0.5) {
                gpio_set_value(gpio_line, ALARM_HIGH);
            } else {
                gpio_set_value(gpio_line, ALARM_LOW);
            }
        } else {
            gpio_set_value(gpio_line, ALARM_LOW); // Disable alarm on error
        }

        // Log average flow rate
        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Average flow rate: %.2f ml/min", avg_flow_rate);
        log_message(log_buffer);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

cleanup:
    // Cleanup resources
    if (i2c_fd1 >= 0) i2c_close(i2c_fd1);
    if (i2c_fd2 >= 0) i2c_close(i2c_fd2);
    if (gpio_line) gpio_uninit(gpio_line);
    if (gpio_chip) gpiod_chip_close(gpio_chip);
    if (log_file) fclose(log_file);

    return EXIT_SUCCESS;
}

