#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4  // BCM GPIO 4, physical pin 7
#define BUFFER_SIZE 100

// Structure to hold timestamp and reading
typedef struct {
    time_t timestamp;
    int reading;
} Entry;

// Circular buffer
Entry buffer[BUFFER_SIZE];
int head = 0;
int tail = 0;
int count = 0;

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Function to configure GPIO pin as input with pull-up resistor
int configure_gpio() {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add an entry to the circular buffer
void add_to_buffer(time_t timestamp, int reading) {
    buffer[head].timestamp = timestamp;
    buffer[head].reading = reading;
    head = (head + 1) % BUFFER_SIZE;
    if (count < BUFFER_SIZE) {
        count++;
    } else {
        tail = (tail + 1) % BUFFER_SIZE;
    }
}

// Function to print the buffer contents
void print_buffer() {
    int i = tail;
    for (int j = 0; j < count; j++) {
        printf("%ld,%d\n", buffer[i].timestamp, buffer[i].reading);
        i = (i + 1) % BUFFER_SIZE;
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Configure GPIO pin
    if (configure_gpio()) {
        gpioTerminate();
        return 1;
    }

    printf("Obstacle avoidance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            time_t current_time = time(NULL);
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected at %ld\n", current_time);
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Print buffer contents before exiting
    print_buffer();

    // Release pigpio resources
    gpioTerminate();

    return 0;
}

