#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_X_MSB_REG 0x2B
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Y_MSB_REG 0x2D
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_Z_MSB_REG 0x2F
#define ACCEL_SCALE_FACTOR 0.0009765625f // g/LSB
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_init(const char *bus, int addr);
int sensor_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = ioctl(fd, I2C_SLAVE, reg);
        if (result < 0) {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s (errno: %d)\n", reg, strerror(errno), errno);
            retries++;
            usleep(10000); // 10ms delay
        } else {
            return result;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Indicate failure
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = ioctl(fd, I2C_SLAVE, (reg << 8) | value);
        if (result < 0) {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s (errno: %d)\n", reg, value, strerror(errno), errno);
            retries++;
            usleep(10000); // 10ms delay
        } else {
            return 0; // Indicate success
        }
    }
    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, value 0x%02X)\n", MAX_RETRIES, reg, value);
    return -1; // Indicate failure
}

// I2C block read function with retry
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int result;
    while (retries < MAX_RETRIES) {
        result = ioctl(fd, I2C_SLAVE, reg);
        if (result < 0) {
            fprintf(stderr, "I2C block read error (reg 0x%02X): %s (errno: %d)\n", reg, strerror(errno), errno);
            retries++;
            usleep(10000); // 10ms delay
        } else {
            result = read(fd, buf, len);
            if (result != len) {
                fprintf(stderr, "I2C block read short read (reg 0x%02X, expected %d, got %d)\n", reg, len, result);
                result = -1; // Indicate failure
            }
            return result;
        }
    }
    fprintf(stderr, "I2C block read failed after %d retries (reg 0x%02X, len %d)\n", MAX_RETRIES, reg, len);
    return -1; // Indicate failure
}

// I2C initialization function
int i2c_init(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s (errno: %d)\n", bus, strerror(errno), errno);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s (errno: %d)\n", addr, strerror(errno), errno);
        close(fd);
        return -1;
    }

    return fd;
}

// Sensor initialization function
int sensor_init(int fd) {
    if (i2c_write_reg(fd, MODE_CONTROL_REG, 0x10) < 0) {
        fprintf(stderr, "Failed to switch sensor to active mode\n");
        return -1;
    }

    // Wait for operating status to become active (bit 0 of register 0x1B)
    int status = 0;
    int timeout = 1000; // 1 second timeout
    while (status == 0 && timeout > 0) {
        status = i2c_read_reg(fd, OPERATING_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Failed to read operating status\n");
            return -1;
        }
        usleep(10000); // 10ms delay
        timeout--;
    }

    if (status == 0) {
        fprintf(stderr, "Sensor failed to become active within 1 second\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[4];
    int result;

    result = i2c_read_block(fd, ACCEL_X_LSB_REG, buf, 4);
    if (result < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    // Combine LSB and MSB, convert to signed 16-bit integer, and scale to g
    *x = (float)((int16_t)((buf[1] << 8) | buf[0])) * ACCEL_SCALE_FACTOR;
    *y = (float)((int16_t)((buf[3] << 8) | buf[2])) * ACCEL_SCALE_FACTOR;
    *z = (float)((int16_t)((buf[1] << 8) | buf[0])) * ACCEL_SCALE_FACTOR;

    return 0;
}

// Function to log data to CSV file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to CSV file: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }

    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, D7S_ADDR);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize sensor
    if (sensor_init(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file for appending
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if the file is newly created and write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    float x, y, z;
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    return EXIT_SUCCESS;
}

