        fprintf(stderr, "Failed to open CSV file: %s (errno: %d)\n", strerror(errno), errno);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Check if the file is newly created and write the header
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    float x, y, z;
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 500ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);

    return EXIT_SUCCESS;
}

