#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCtrl+C detected. Exiting gracefully...\n");
}

int main() {
    int sensor1_value, sensor2_value;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", SENSOR_2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        sensor1_value = gpioRead(SENSOR_1_PIN);
        sensor2_value = gpioRead(SENSOR_2_PIN);

        // Error check for gpioRead
        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Error reading sensor values\n");
            break; // Exit loop on error
        }

        // Control LED based on sensor values
        if (sensor1_value == 0 || sensor2_value == 0) {
            gpioWrite(LED_PIN, 1); // Turn LED ON
        } else {
            gpioWrite(LED_PIN, 0); // Turn LED OFF
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up and terminate pigpio
    gpioWrite(LED_PIN, 0); // Ensure LED is OFF before exiting
    gpioTerminate();

    return 0;
}

