#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_MS 2000 // 2 seconds
#define LOG_FILE "stall_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading from GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

int is_stalled(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

int log_stall(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    printf("Conveyor belt stall detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, continue to the next iteration
            gpioDelay(100); // Small delay to avoid flooding the console with errors
            continue;
        }

        if (is_stalled(sensor1_value, sensor2_value)) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_stall(timestamp) == 0) {
                printf("Stall detected and logged: %s\n", timestamp);
            } else {
                fprintf(stderr, "Failed to log stall event.\n");
            }

            gpioDelay(STALL_DURATION_MS); // Debounce
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

