#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170 register addresses
#define TMAG5170_REG_X_MSB 0x01
#define TMAG5170_REG_X_LSB 0x02
#define TMAG5170_REG_Y_MSB 0x03
#define TMAG5170_REG_Y_LSB 0x04
#define TMAG5170_REG_Z_MSB 0x05
#define TMAG5170_REG_Z_LSB 0x06
#define TMAG5170_REG_DIAG 0x00

// Sensitivity (LSB/mT) for 50 mT range
#define SENSITIVITY 0.0001

// File to log data to
#define LOG_FILE "magnetic_log.csv"

// I2C handle
int i2c_handle;

// File pointer
FILE *log_file;

// Flag to indicate if the file is newly created
int file_new = 1;

// Function prototypes
int init_i2c();
int verify_device_id();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_mt(int16_t raw_value);
int log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // Bus 1, address 0x0E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, TMAG5170_REG_DIAG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != 0x8D) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x8D)\n", device_id);
        return -1;
    }

    printf("Device ID verified.\n");
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, TMAG5170_REG_X_MSB, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert raw data to mT
float convert_to_mt(int16_t raw_value) {
    return raw_value * SENSITIVITY;
}

// Log data to CSV file
int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (file_new) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file for writing: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        file_new = 0;
    }

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int16_t raw_x, raw_y, raw_z;
    float x_mt, y_mt, z_mt;

    while (1) {
        // Read sensor data
        if (read_sensor_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert to mT
            x_mt = convert_to_mt(raw_x);
            y_mt = convert_to_mt(raw_y);
            z_mt = convert_to_mt(raw_z);

            // Log data
            if (log_data(x_mt, y_mt, z_mt) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup (should not reach here in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

