#include <signal.h>
#include <string.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int pigpio_init_result;
    int read_result;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    char log_entry[100];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
            fprintf(log_file, "%s ERROR: pigpio initialisation failed: %d\n", timestamp, pigpio_init_result);
            fclose(log_file);
        }
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        read_result = gpioRead(GPIO_PIN);
        if (read_result >= 0) {
            if (read_result == 1) {
                // Water detected
                time(&current_time);
                time_info = localtime(&current_time);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
                printf("%s ALERT: Water detected!\n", timestamp);

                log_file = fopen(LOG_FILE, "a");
                if (log_file != NULL) {
                    snprintf(log_entry, sizeof(log_entry), "%s ALERT: Water detected\n", timestamp);
                    fprintf(log_file, "%s", log_entry);
                    fclose(log_file);
                } else {
                    fprintf(stderr, "Error opening log file!\n");
                }
