#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
FILE *log_file = NULL;

// Function to handle the interrupt (rising edge)
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user;  // unused
    pulse_count++;
}

// Function to calculate RPM
double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0;
}

// Function to log RPM to file and print to stdout
void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }

    printf("%s %.2f\n", timestamp, rpm);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    (void)signal; // unused
    printf("\nCaught signal, exiting gracefully...\n");

    // Disable timer and alert callback
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Close the log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback for rising edge
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1)
    {
        // Record the current pulse count
        int current_pulse_count = pulse_count;

        // Reset the pulse count for the next second
        pulse_count = 0;

        // Calculate RPM
        double rpm = calculate_rpm(current_pulse_count);

        // Log the RPM
        log_rpm(rpm);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    return 0;
}

