#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Structure to hold the shared state
typedef struct {
    int sensor_a_state;
    int sensor_b_state;
    pthread_mutex_t mutex;
} shared_state_t;

// Global shared state
shared_state_t shared_state = {0, 0, PTHREAD_MUTEX_INITIALIZER};

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation_event(const char *direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Sensor A ISR function
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&shared_state.mutex);
    shared_state.sensor_a_state = level;
    pthread_mutex_unlock(&shared_state.mutex);
}

// Sensor B ISR function
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&shared_state.mutex);
    shared_state.sensor_b_state = level;
    pthread_mutex_unlock(&shared_state.mutex);
}

// Function to log rotation events
void log_rotation_event(const char *direction) {
    FILE *fp = fopen("rotation_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening rotation_log.txt");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 10, ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s %s\n", timestamp, direction);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Set up interrupt handlers
    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for SENSOR_A_GPIO\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for SENSOR_B_GPIO\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        pthread_mutex_lock(&shared_state.mutex);
        int current_state = (shared_state.sensor_a_state << 1) | shared_state.sensor_b_state;
        pthread_mutex_unlock(&shared_state.mutex);

        // Quadrature state machine
        switch (current_state) {
            case 0:
                if (shared_state.sensor_a_state == 1) {
                    log_rotation_event("CW");
                }
                break;
            case 1:
                if (shared_state.sensor_b_state == 1) {
                    log_rotation_event("CCW");
                }
                break;
            case 2:
                if (shared_state.sensor_a_state == 1) {
                    log_rotation_event("CW");
                }
                break;
            case 3:
                if (shared_state.sensor_b_state == 1) {
                    log_rotation_event("CCW");
                }
                break;
            default:
                break;
        }

        gpioDelay(1); // Sleep for 1ms to reduce CPU usage
    }

    // Clean up
    gpioTerminate();
    pthread_mutex_destroy(&shared_state.mutex);

    return 0;
}

