#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define constants
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_DELAY_MS 5

// Global variables
static volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received shutdown signal. Shutting down...");
        running = 0;
        control_led(0); // Turn off LED
        gpioTerminate(); // Terminate pigpio
        closelog(); // Close syslog
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    log_event("GPIO initialisation complete");
    return 0;
}

// Read touch sensor value with debouncing
int read_touch_sensor() {
    int value = gpioRead(TOUCH_SENSOR_PIN);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    return value;
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, message);
}

int main() {
    // Open syslog
    openlog("touch_sensor_app", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed. Exiting.");
        closelog();
        return 1;
    }

    log_event("Application started");

    // Main loop
    while (running) {
        int touch_value = read_touch_sensor();

        if (touch_value == 1) {
            control_led(1); // Turn on LED
            log_event("Touch detected");
        } else {
            control_led(0); // Turn off LED
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Poll interval
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    gpioTerminate();
    closelog();

    return 0;
}

