    time_t now = time(NULL);
    log_buffer[overflow_counter].sensor_pin = sensor_pin;
    log_buffer[overflow_counter].timestamp = now;
    log_buffer[overflow_counter].state = state;

    overflow_counter = (overflow_counter + 1) % BUFFER_SIZE;
}

