#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Signal handler for graceful shutdown
void signalHandler(int signum) {
    keepRunning = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Function to read the rain sensor state
int readRainSensor() {
    return gpioRead(RAIN_SENSOR_GPIO);
}

// Function to log rain events with timestamp
void logRainEvent(int rainDetected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (logFile != NULL) {
        if (rainDetected == 0) {
            fprintf(logFile, "%s Rain Detected\n", timestamp);
        } else {
            fprintf(logFile, "%s No Rain\n", timestamp);
        }
        fflush(logFile); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Cannot log rain event.\n");
    }
}

int main() {
    int previousState = -1; // Initialize to an invalid state
    int currentState;

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 17 as input with pull-up resistor
    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP);

    // Open the log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        currentState = readRainSensor();

        if (currentState != previousState) {
            logRainEvent(currentState);
            previousState = currentState;
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (logFile != NULL) {
        fclose(logFile);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

