#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_MS 5
#define NUM_MAGNETS 2 // Assuming 2 magnets per revolution

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);
}

// Function to log sensor data to a CSV file
void log_sensor_data(const char *timestamp, int sensor1_state, int sensor2_state) {
    FILE *fp = fopen("shaft_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening shaft_log.txt");
        return;
    }
    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

// Function to calculate RPM
double calculate_rpm(unsigned int pulse_count, double elapsed_time) {
    if (elapsed_time > 0) {
        return (double)pulse_count / elapsed_time * 60.0 / NUM_MAGNETS; // pulses/second to RPM
    } else {
        return 0.0;
    }
}

// Function to print RPM to the console
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Install signal handler
    signal(SIGINT, signal_handler);

    unsigned int pulse_count = 0;
    int sensor1_state = gpioRead(SENSOR_1_GPIO);
    int sensor2_state = gpioRead(SENSOR_2_GPIO);
    char timestamp[30];
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    printf("Monitoring shaft RPM... Press Ctrl+C to exit.\n");

    while (program_running) {
        // Debounce sensor 1
        gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
        int new_sensor1_state = gpioRead(SENSOR_1_GPIO);
        if (new_sensor1_state != sensor1_state) {
            get_iso8601_timestamp(timestamp);
            log_sensor_data(timestamp, sensor1_state, sensor2_state);
            sensor1_state = new_sensor1_state;
            pulse_count++;
        }

        // Debounce sensor 2
        gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
        int new_sensor2_state = gpioRead(SENSOR_2_GPIO);
        if (new_sensor2_state != sensor2_state) {
            get_iso8601_timestamp(timestamp);
            log_sensor_data(timestamp, sensor1_state, sensor2_state);
            sensor2_state = new_sensor2_state;
            pulse_count++;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        if (elapsed_time >= 1.0) {
            double rpm = calculate_rpm(pulse_count, elapsed_time);
            print_rpm(rpm);

            get_iso8601_timestamp(timestamp);
            log_sensor_data(timestamp, sensor1_state, sensor2_state);

            pulse_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        gpioDelay(1000); // Check every 1 ms
    }

    gpioTerminate();
    return 0;
}

