#include <string.h>

// Si1182 I2C address
#define SI1182_ADDR 0x28

// Si1182 Register Addresses
#define SI1182_PART_ID 0x00
#define SI1182_CONFIG 0x30
#define SI1182_HR_DATA 0x02
#define SI1182_SPO2_DATA 0x04

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int heart_rate;
    int spo2;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the Si1182 sensor
int initialize_sensor() {
    // Check if the sensor is present by reading the PART_ID register
    int part_id = i2cReadByteData(i2c_handle, SI1182_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
