#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define ALARM_THRESHOLD 2 // seconds
#define POLL_INTERVAL 100 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void activate_alarm(int gpio_pin);
void deactivate_alarm(int gpio_pin);
void log_event(const char *event_type);
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to activate the alarm (buzzer/LED)
void activate_alarm(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
    }
}

// Function to deactivate the alarm (buzzer/LED)
void deactivate_alarm(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
    }
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors (optional, but recommended for tilt sensors)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int alarm_active = 0;
    time_t tilt_start_time = 0;
    int sensor1_state = read_sensor(SENSOR_1_PIN);
    int sensor2_state = read_sensor(SENSOR_2_PIN);

    if (sensor1_state < 0 || sensor2_state < 0) {
        fprintf(stderr, "Error reading sensor values. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Bridge monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int new_sensor1_state = read_sensor(SENSOR_1_PIN);
        int new_sensor2_state = read_sensor(SENSOR_2_PIN);

        if (new_sensor1_state < 0 || new_sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            break;
        }

        if (new_sensor1_state != sensor1_state) {
            if (new_sensor1_state == 1) {
                log_event("Tilt Start - Sensor 1");
                if (!alarm_active) {
                    activate_alarm(ALARM_PIN);
                    alarm_active = 1;
                    tilt_start_time = time(NULL);
                }
            } else {
                log_event("Tilt End - Sensor 1");
                if (alarm_active) {
                    deactivate_alarm(ALARM_PIN);
                    alarm_active = 0;
                }
            }
            sensor1_state = new_sensor1_state;
        }

        if (new_sensor2_state != sensor2_state) {
            if (new_sensor2_state == 1) {
                log_event("Tilt Start - Sensor 2");
                if (!alarm_active) {
                    activate_alarm(ALARM_PIN);
                    alarm_active = 1;
                    tilt_start_time = time(NULL);
                }
            } else {
                log_event("Tilt End - Sensor 2");
                if (alarm_active) {
                    deactivate_alarm(ALARM_PIN);
                    alarm_active = 0;
                }
            }
            sensor2_state = new_sensor2_state;
        }

        if (alarm_active) {
            if (time(NULL) - tilt_start_time >= ALARM_THRESHOLD) {
                log_event("Alarm Activated");
            }
        }

        gpioDelay(POLL_INTERVAL);
    }

    // Clean up and exit
    deactivate_alarm(ALARM_PIN);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

