#define ACCEL_REG_Y_L 0x2A
#define ACCEL_REG_Y_H 0x2B
#define ACCEL_REG_Z_L 0x2C
#define ACCEL_REG_Z_H 0x2D
#define THRESHOLD 500.0
#define LED_GPIO 17
#define EUCLIDEAN_THRESHOLD 500.0
#define EUCLIDEAN_SCALE_FACTOR 0.001 // Example scale factor, adjust as needed

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_acceleration(float *x, float *y, float *z);
float calculate_euclidean_magnitude(float x, float y, float z);
void control_led(int on);
void log_event(float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the sensor
int init_sensor() {
    // Clear power-down bit in CTRL1 register
    char buf[2];
    buf[0] = CTRL1_REG;
    buf[1] = 0x00; // Clear power-down bit

    int retries = 3;
    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, buf, 2) == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error initializing sensor, retrying...\n");
        gpioDelay(10); // Wait 10 ms before retrying
        retries--;
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buf[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadDevice(i2c_handle, buf, 6) == 6) {
            // Combine high and low bytes for each axis
            int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
            int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
            int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

            // Convert to g-force units (adjust scale factor as needed)
            *x = (float)raw_x * EUCLIDEAN_SCALE_FACTOR;
            *y = (float)raw_y * EUCLIDEAN_SCALE_FACTOR;
            *z = (float)raw_z * EUCLIDEAN_SCALE_FACTOR;

            return 0; // Success
        }
        fprintf(stderr, "Error reading acceleration data, retrying...\n");
        gpioDelay(10); // Wait 10 ms before retrying
        retries--;
    }
    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Calculate Euclidean vibration magnitude
float calculate_euclidean_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log the event to file
void log_event(float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z, magnitude;

    printf("Monitoring seismic activity... Press Ctrl+C to exit.\n");

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_euclidean_magnitude(x, y, z);

            if (magnitude > THRESHOLD) {
                control_led(1); // Turn on LED
                log_event(magnitude);
                gpioDelay(1000); // Wait 1 second
                control_led(0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

