// Define GPIO pins
#define SENSOR_1 4
#define SENSOR_2 17
#define SENSOR_3 27
#define SENSOR_4 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetMode(SENSOR_4, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (!terminate)
    {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR_1);
        int sensor2_value = gpioRead(SENSOR_2);
        int sensor3_value = gpioRead(SENSOR_3);
        int sensor4_value = gpioRead(SENSOR_4);

        // Check if any sensor detects an object
        if (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0)
        {
            // Turn on LED
            gpioWrite(LED_PIN, 1);
        }
        else
        {
            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // Delay in microseconds
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    return 0;
}

