#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor pins
#define SENSOR_PIN_1 3
#define SENSOR_PIN_2 5
#define SENSOR_PIN_3 7
#define SENSOR_PIN_4 11
#define SENSOR_PIN_5 13

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read sensor data
int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading sensor on pin %d: %d", pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log flame detection event
void log_flame_event(int sensor_id, int pin)
{
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    FILE *fp = fopen("/var/log/flame_events.log", "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file: %m");
        return;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Error acquiring lock on log file: %m");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", buf, sensor_id, pin);
    fflush(fp);

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Error releasing lock on log file: %m");
    }

    fclose(fp);
}

int main()
{
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);
    gpioSetMode(SENSOR_PIN_3, PI_INPUT);
    gpioSetMode(SENSOR_PIN_4, PI_INPUT);
    gpioSetMode(SENSOR_PIN_5, PI_INPUT);

    syslog(LOG_INFO, "Flame monitor started");

    // Main loop
    while (!terminate) {
        int sensor1_state = read_sensor(SENSOR_PIN_1);
        int sensor2_state = read_sensor(SENSOR_PIN_2);
        int sensor3_state = read_sensor(SENSOR_PIN_3);
        int sensor4_state = read_sensor(SENSOR_PIN_4);
        int sensor5_state = read_sensor(SENSOR_PIN_5);

        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1 || sensor4_state == -1 || sensor5_state == -1) {
            syslog(LOG_ERR, "Error reading sensor data, continuing...");
        } else {
            // Check for rising edge transitions on sensor 1
            if (sensor1_state == 0 && sensor1_state != gpioRead(SENSOR_PIN_1)) {
                gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                if (read_sensor(SENSOR_PIN_1) == 0) {
                    log_flame_event(1, SENSOR_PIN_1);
                }
            }

            // Check for rising edge transitions on sensor 2
            if (sensor2_state == 0 && sensor2_state != gpioRead(SENSOR_PIN_2)) {
                gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                if (read_sensor(SENSOR_PIN_2) == 0) {
                    log_flame_event(2, SENSOR_PIN_2);
                }
            }

            // Check for rising edge transitions on sensor 3
            if (sensor3_state == 0 && sensor3_state != gpioRead(SENSOR_PIN_3)) {
                gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                if (read_sensor(SENSOR_PIN_3) == 0) {
                    log_flame_event(3, SENSOR_PIN_3);
                }
            }

            // Check for rising edge transitions on sensor 4
            if (sensor4_state == 0 && sensor4_state != gpioRead(SENSOR_PIN_4)) {
                gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                if (read_sensor(SENSOR_PIN_4) == 0) {
                    log_flame_event(4, SENSOR_PIN_4);
                }
            }

            // Check for rising edge transitions on sensor 5
            if (sensor5_state == 0 && sensor5_state != gpioRead(SENSOR_PIN_5)) {
                gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
                if (read_sensor(SENSOR_PIN_5) == 0) {
                    log_flame_event(5, SENSOR_PIN_5);
                }
            }
        }

        gpioDelay(1000); // Poll every 1 second
    }

    // Cleanup
    syslog(LOG_INFO, "Flame monitor stopping");
    gpioTerminate();
    closelog();

    return 0;
}

