#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variables for GPIO chip and line
struct gpiod_chip *chip;
struct gpiod_line *lines[8]; // Array to store lines for each sensor

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_sensors; i++)
    {
        if (lines[i])
        {
            gpiod_line_release(lines[i]);
            printf("Released line %d (GPIO %d)\n", i, sensor_pins[i]);
        }
    }

    // Close the GPIO chip
    if (chip)
    {
        gpiod_chip_close(chip);
        printf("Closed GPIO chip %s\n", GPIOCHIP);
    }

    exit(0);
}

int main()
{
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip)
    {
        perror("Error opening GPIO chip");
        return 1;
    }
    printf("Opened GPIO chip %s\n", GPIOCHIP);

    // Get lines for each sensor
    for (int i = 0; i < num_sensors; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i])
        {
            perror("Error getting line for sensor");
            // Release previously acquired lines
            for (int j = 0; j < i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
        printf("Get line %d (GPIO %d)\n", i, sensor_pins[i]);
    }

    // Request lines for input
    for (int i = 0; i < num_sensors; i++)
    {
        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0)
        {
            perror("Error requesting line as input");
            // Release previously acquired lines
            for (int j = 0; j < num_sensors; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
        printf("Requested line %d (GPIO %d) as input\n", i, sensor_pins[i]);
    }

    // Main loop
    while (1)
    {
        for (int i = 0; i < num_sensors; i++)
        {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0)
            {
                perror("Error reading line value");
                // Release previously acquired lines
                for (int j = 0; j < num_sensors; j++)
                {
                    gpiod_line_release(lines[j]);
                }
                gpiod_chip_close(chip);
                return 1;
            }

            if (value != 0 && value != 1) {
              fprintf(stderr, "Invalid value read from line %d: %d\n", i, value);
              continue;
            }

            if (value == 1)
            {
                // Touch detected
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

                printf("%s Sensor %d (GPIO %d) touched\n", buf, i, sensor_pins[i]);
            }
            else if (value == 0)
            {
                // Touch released
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

                printf("%s Sensor %d (GPIO %d) released\n", buf, i, sensor_pins[i]);
            }
        }

        // Wait 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

