#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define GAIN_1_8 0x00
#define INTEGRATION_TIME_100MS 0x00
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int configure_sensor();
int read_als_data(uint16_t *als_data);
float convert_to_lux(uint16_t als_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the VEML7700 sensor
int configure_sensor() {
    uint16_t config_value = (INTEGRATION_TIME_100MS << 8) | GAIN_1_8;
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ambient light data from the VEML7700 sensor
int read_als_data(uint16_t *als_data) {
    char buf[1];
    buf[0] = ALS_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ALS register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }

    *als_data = (read_buf[1] << 8) | read_buf[0];
    return 0;
}

// Convert raw ALS data to lux
float convert_to_lux(uint16_t als_data) {
    return (float)als_data * 0.0576;
}

// Set LED brightness based on lux value
int set_led_brightness(float lux) {
    int brightness = 0;
    if (lux < 100) {
        brightness = PWM_RANGE;
    } else if (lux < 500) {
        brightness = (int)(PWM_RANGE * 0.75);
    } else if (lux < 1000) {
        brightness = (int)(PWM_RANGE * 0.5);
    } else {
        brightness = (int)(PWM_RANGE * 0.25);
    }

    gpioPWM(LED_GPIO, brightness);
    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    uint16_t als_data;
    float lux;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        // Read ALS data
        if (read_als_data(&als_data) == 0) {
            // Convert to lux
            lux = convert_to_lux(als_data);

            // Set LED brightness
            if (set_led_brightness(lux) != 0) {
                error_code = -1;
            } else {
                error_code = 0;
            }

            // Log data
            log_data(lux, gpioGetPWMdutycycle(LED_GPIO), error_code);
        } else {
            error_code = -1;
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

