#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define TOUCH_PIN_1 2
#define TOUCH_PIN_2 3
#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile int touch_states[8] = {0}; // Array to store the current state of each touch channel
volatile unsigned long last_touch_time[8] = {0}; // Array to store the last touch time for each channel
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_touch_event(int channel);
void update_led();
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor channels
        int channel1_value = gpioRead(TOUCH_PIN_1);
        int channel2_value = gpioRead(TOUCH_PIN_2);
        int channel3_value = gpioRead(TOUCH_PIN_3);
        int channel4_value = gpioRead(TOUCH_PIN_4);
        int channel5_value = gpioRead(TOUCH_PIN_5);
        int channel6_value = gpioRead(TOUCH_PIN_6);
        int channel7_value = gpioRead(TOUCH_PIN_7);
        int channel8_value = gpioRead(TOUCH_PIN_8);

        // Debounce and update touch states
        if (channel1_value == 1 && (gpioTick() - last_touch_time[0] > DEBOUNCE_TIME * 1000)) {
            touch_states[0] = 1;
            last_touch_time[0] = gpioTick();
            log_touch_event(1);
        } else if (channel1_value == 0) {
            touch_states[0] = 0;
        }

        if (channel2_value == 1 && (gpioTick() - last_touch_time[1] > DEBOUNCE_TIME * 1000)) {
            touch_states[1] = 1;
            last_touch_time[1] = gpioTick();
            log_touch_event(2);
        } else if (channel2_value == 0) {
            touch_states[1] = 0;
        }

        if (channel3_value == 1 && (gpioTick() - last_touch_time[2] > DEBOUNCE_TIME * 1000)) {
            touch_states[2] = 1;
            last_touch_time[2] = gpioTick();
            log_touch_event(3);
        } else if (channel3_value == 0) {
            touch_states[2] = 0;
        }

        if (channel4_value == 1 && (gpioTick() - last_touch_time[3] > DEBOUNCE_TIME * 1000)) {
            touch_states[3] = 1;
            last_touch_time[3] = gpioTick();
            log_touch_event(4);
        } else if (channel4_value == 0) {
            touch_states[3] = 0;
        }

        if (channel5_value == 1 && (gpioTick() - last_touch_time[4] > DEBOUNCE_TIME * 1000)) {
            touch_states[4] = 1;
            last_touch_time[4] = gpioTick();
            log_touch_event(5);
        } else if (channel5_value == 0) {
            touch_states[4] = 0;
        }

        if (channel6_value == 1 && (gpioTick() - last_touch_time[5] > DEBOUNCE_TIME * 1000)) {
            touch_states[5] = 1;
            last_touch_time[5] = gpioTick();
            log_touch_event(6);
        } else if (channel6_value == 0) {
            touch_states[5] = 0;
        }

        if (channel7_value == 1 && (gpioTick() - last_touch_time[6] > DEBOUNCE_TIME * 1000)) {
            touch_states[6] = 1;
            last_touch_time[6] = gpioTick();
            log_touch_event(7);
        } else if (channel7_value == 0) {
            touch_states[6] = 0;
        }

        if (channel8_value == 1 && (gpioTick() - last_touch_time[7] > DEBOUNCE_TIME * 1000)) {
            touch_states[7] = 1;
            last_touch_time[7] = gpioTick();
            log_touch_event(8);
        } else if (channel8_value == 0) {
            touch_states[7] = 0;
        }

        // Update the LED based on touch states
        update_led();

        // Wait 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN_1, PI_INPUT);
    gpioSetMode(TOUCH_PIN_2, PI_INPUT);
    gpioSetMode(TOUCH_PIN_3, PI_INPUT);
    gpioSetMode(TOUCH_PIN_4, PI_INPUT);
    gpioSetMode(TOUCH_PIN_5, PI_INPUT);
    gpioSetMode(TOUCH_PIN_6, PI_INPUT);
    gpioSetMode(TOUCH_PIN_7, PI_INPUT);
    gpioSetMode(TOUCH_PIN_8, PI_INPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(TOUCH_PIN_1, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_2, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_3, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_4, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_5, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_6, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_7, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_8, PI_PUD_DOWN);

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to log touch events to a file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to update the LED based on touch states
void update_led() {
    int all_released = 1;
    for (int i = 0; i < 8; i++) {
        if (touch_states[i] == 1) {
            all_released = 0;
            break;
        }
    }

    gpioWrite(LED_PIN, !all_released);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    cleanup_gpio();
    exit(0);
}

