        if (channel3_value == 1 && (gpioTick() - last_touch_time[2] > DEBOUNCE_TIME * 1000)) {
            touch_states[2] = 1;
            last_touch_time[2] = gpioTick();
            log_touch_event(3);
        } else if (channel3_value == 0) {
            touch_states[2] = 0;
        }

        if (channel4_value == 1 && (gpioTick() - last_touch_time[3] > DEBOUNCE_TIME * 1000)) {
            touch_states[3] = 1;
            last_touch_time[3] = gpioTick();
            log_touch_event(4);
        } else if (channel4_value == 0) {
            touch_states[3] = 0;
        }

        if (channel5_value == 1 && (gpioTick() - last_touch_time[4] > DEBOUNCE_TIME * 1000)) {
            touch_states[4] = 1;
            last_touch_time[4] = gpioTick();
            log_touch_event(5);
        } else if (channel5_value == 0) {
            touch_states[4] = 0;
        }

        if (channel6_value == 1 && (gpioTick() - last_touch_time[5] > DEBOUNCE_TIME * 1000)) {
            touch_states[5] = 1;
            last_touch_time[5] = gpioTick();
            log_touch_event(6);
        } else if (channel6_value == 0) {
            touch_states[5] = 0;
        }

        if (channel7_value == 1 && (gpioTick() - last_touch_time[6] > DEBOUNCE_TIME * 1000)) {
            touch_states[6] = 1;
            last_touch_time[6] = gpioTick();
            log_touch_event(7);
        } else if (channel7_value == 0) {
            touch_states[6] = 0;
        }

        if (channel8_value == 1 && (gpioTick() - last_touch_time[7] > DEBOUNCE_TIME * 1000)) {
            touch_states[7] = 1;
            last_touch_time[7] = gpioTick();
            log_touch_event(8);
        } else if (channel8_value == 0) {
            touch_states[7] = 0;
        }

        // Update the LED based on touch states
        update_led();

        // Wait 50 milliseconds
        gpioDelay(50000); // 50 ms
    }

    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN_1, PI_INPUT);
    gpioSetMode(TOUCH_PIN_2, PI_INPUT);
    gpioSetMode(TOUCH_PIN_3, PI_INPUT);
    gpioSetMode(TOUCH_PIN_4, PI_INPUT);
    gpioSetMode(TOUCH_PIN_5, PI_INPUT);
    gpioSetMode(TOUCH_PIN_6, PI_INPUT);
    gpioSetMode(TOUCH_PIN_7, PI_INPUT);
    gpioSetMode(TOUCH_PIN_8, PI_INPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(TOUCH_PIN_1, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_2, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_3, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_4, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_5, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_6, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_7, PI_PUD_DOWN);
    gpioSetPullUpDown(TOUCH_PIN_8, PI_PUD_DOWN);

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to log touch events to a file
void log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to update the LED based on touch states
void update_led() {
    int all_released = 1;
    for (int i = 0; i < 8; i++) {
        if (touch_states[i] == 1) {
            all_released = 0;
            break;
        }
    }

    gpioWrite(LED_PIN, !all_released);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    cleanup_gpio();
    exit(0);
}

