#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3001_ADDR 0x44

// Define the configuration register address and value
#define CONFIG_REG 0x01
#define CONFIG_VALUE 0xC810 // Continuous mode, auto range, 100ms conversion

// Define the result register address
#define RESULT_REG 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int i2c_address;
    int config_register;
    int result_register;
    int config_value;
} sensor_config_t;

// Function prototypes
int init_i2c();
int write_config_word(uint16_t config_word);
int read_result_word(uint16_t *result_word);
float calculate_lux(uint16_t result_word);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write the configuration word to the OPT3001
int write_config_word(uint16_t config_word) {
    uint8_t data[2];
    data[0] = (config_word >> 8) & 0xFF; // MSB
    data[1] = config_word & 0xFF;      // LSB

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, (data[0] << 8) | data[1]);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the result word from the OPT3001
int read_result_word(uint16_t *result_word) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Byte swap the result word
    uint8_t msb = (result >> 8) & 0xFF;
    uint8_t lsb = result & 0xFF;
    *result_word = (msb << 8) | lsb;

    return 0;
}

// Calculate lux value from the result word
float calculate_lux(uint16_t result_word) {
    int exponent = (result_word >> 12) & 0x0F;
    int mantissa = result_word & 0x0FFF;
    return mantissa * 0.01 * (1 << exponent);
}

// Log the data to a file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Write configuration word
    if (write_config_word(CONFIG_VALUE) != 0) {
        cleanup();
        return 1;
    }

    // Wait for at least 100ms for the first conversion
    gpioDelay(100000); // 100ms

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t result_word;
    float lux;

    // Main loop
    while (!terminate) {
        // Read result word
        if (read_result_word(&result_word) == 0) {
            // Calculate lux value
            lux = calculate_lux(result_word);

            // Log the data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data!\n");
            }

            // Print lux value to stdout
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Error reading result word!\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

