#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to write a log message to the file
int log_message(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", get_timestamp(), message);
    fflush(log_file); // Ensure the message is written immediately
    return 0;
}

// Function to handle a touch event
void handle_touch_event(int value) {
    if (value == 1) {
        if (log_message("Touch Detected") != 0) {
            fprintf(stderr, "Error: Failed to log touch detected event.\n");
        }
    } else if (value == 0) {
        if (log_message("Touch Released") != 0) {
            fprintf(stderr, "Error: Failed to log touch released event.\n");
        }
    }
}

// Function to read the touch sensor value with debouncing
int read_touch_sensor() {
    static int last_value = 0;
    static struct timespec last_change_time = {0, 0};
    struct timespec current_time;
    int current_value;

    if (gpiod_line_get_value(line, &current_value) < 0) {
        fprintf(stderr, "Error: Failed to read GPIO value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    long time_diff_ns = (now.tv_sec - last_change_time.tv_sec) * 1000000000L + (now.tv_nsec - last_change_time.tv_nsec);

    if (current_value != last_value) {
        if (time_diff_ns > DEBOUNCE_DELAY_MS * 1000000) { // Convert ms to ns
            last_value = current_value;
            last_change_time = now;
            return current_value;
        }
    }

    return last_value; // Return the last stable value
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for input
    if (gpiod_line_request_input(line, "touch_sensor") < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line for input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int touch_value = read_touch_sensor();
        if (touch_value >= 0) {
            handle_touch_event(touch_value);
        }
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 10000000; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

