#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define START_MEASUREMENT_CMD 0x3608
#define FLOW_CONVERSION_FACTOR 90.0
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
    int error;
} sensor_data_t;

// Function prototypes
int init_i2c();
int start_measurement();
sensor_data_t read_flow_data();
float convert_to_ml_min(int16_t raw_flow);
int validate_flow_rate(float flow_rate);
int log_data(float flow_rate, const char *status);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start continuous measurement mode
int start_measurement() {
    char cmd[2] = {(START_MEASUREMENT_CMD >> 8) & 0xFF, START_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms
    return 0;
}

// Read flow data from the sensor
sensor_data_t read_flow_data() {
    sensor_data_t data = {0};
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);

    if (result != 3) {
        fprintf(stderr, "Error reading flow data: %d\n", result);
        data.error = -1; // Indicate I2C read error
        return data;
    }

    data.raw_flow = (buffer[0] << 8) | buffer[1];
    data.crc = buffer[2];

    uint8_t crc_calculated = crc8((uint8_t *)buffer, 2);

    if (data.crc != crc_calculated) {
        fprintf(stderr, "CRC check failed!\n");
        data.error = -2; // Indicate CRC error
        return data;
    }

    return data;
}

// Convert raw flow data to ml/min
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow / FLOW_CONVERSION_FACTOR;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
        fprintf(stderr, "Invalid flow rate: %.2f ml/min\n", flow_rate);
        return -1; // Indicate invalid flow rate
    }
    return 0;
}

// Log data to file
int log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("cooling_log.csv", "a+");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file!\n");
            return -1;
        }
        // Check if the file is newly created and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        }
        fseek(log_file, 0, SEEK_END);
    }

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file);
    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start measurement
    if (start_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_flow_data();

        if (sensor_data.error == 0) {
            float flow_rate = convert_to_ml_min(sensor_data.raw_flow);
            int status = validate_flow_rate(flow_rate);

            if (status == 0) {
                log_data(flow_rate, "OK");
                printf("Flow Rate: %.2f ml/min, Status: OK\n", flow_rate);
            } else {
                log_data(flow_rate, "INVALID");
                printf("Flow Rate: %.2f ml/min, Status: INVALID\n", flow_rate);
            }
        } else {
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break;
            }
            if (start_measurement() != 0) {
                fprintf(stderr, "Failed to re-start measurement, exiting.\n");
                break;
            }
            fprintf(stderr, "I2C re-initialization failed, logging ERROR.\n");
            log_data(0.0, "ERROR");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

