#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;

// File pointer for the log file
FILE *log_file = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int log_data(FILE *fp, int left, int middle, int right);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");

        // Release GPIO lines
        if (left_line) {
            gpiod_line_release(left_line);
        }
        if (middle_line) {
            gpiod_line_release(middle_line);
        }
        if (right_line) {
            gpiod_line_release(right_line);
        }

        // Close the GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        // Flush the log file
        if (log_file) {
            fflush(log_file);
        }

        // Close the log file
        if (log_file) {
            fclose(log_file);
        }

        exit(0);
    }
}

// Function to read the sensor value from a given GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to a CSV file
int log_data(FILE *fp, int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines for the sensors
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !middle_line || !right_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as input
    if (gpiod_line_request_input(left_line, "path_planning") < 0 ||
        gpiod_line_request_input(middle_line, "path_planning") < 0 ||
        gpiod_line_request_input(right_line, "path_planning") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("path_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to read sensor data and log it
    while (1) {
        int left_value = read_sensor(left_line);
        int middle_value = read_sensor(middle_line);
        int right_value = read_sensor(right_line);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            fprintf(stderr, "Error reading sensor data, skipping log.\n");
        } else {
            if (log_data(log_file, left_value, middle_value, right_value) == -1) {
                fprintf(stderr, "Error logging data, skipping.\n");
            }
        }

        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

