        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", FLAME_SENSOR_GPIO, gpio_request_result);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state == 0 && last_state == 1) { // Flame detected (active low)
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
