#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#include <gpiod.h>

#define GPIOCHIP "gpiochip4"
#define TOUCH_PIN 23
#define LED_PIN 24

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle signals
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the event to a file
int log_event(const char *timestamp, int led_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to toggle the LED state
int toggle_led(int current_state) {
    int new_state = !current_state;
    if (gpiod_line_set_value(led_line, new_state) < 0) {
        perror("Failed to set LED value");
        return -1;
    }
    return new_state;
}

// Callback function for touch events
void touch_callback(struct gpiod_line *line, void *userdata) {
    (void)line; // Suppress unused parameter warning
    (void)userdata;

    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log.\n");
        return;
    }

    int led_state = toggle_led(0); // Toggle LED on rising edge
    if (led_state < 0) {
        fprintf(stderr, "Failed to toggle LED.\n");
        free(timestamp);
        return;
    }

    if (log_event(timestamp, led_state) < 0) {
        fprintf(stderr, "Failed to log event.\n");
    }

    free(timestamp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the line for the touch sensor
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("Failed to get touch sensor line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the line for the LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        perror("Failed to request touch sensor line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the event detection
    struct gpiod_line_event event;
    struct timespec timeout = {0, 1000000000L}; // 1 second timeout

    printf("Monitoring touch sensor on GPIO%d...\n", TOUCH_PIN);

    while (!terminate) {
        int ret = gpiod_line_event_wait(touch_line, &timeout);

        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Failed to wait for event");
            break;
        } else if (ret == 0) {
            // Timeout occurred, no event
            continue;
        } else {
            // Event occurred
            if (gpiod_line_event_read(touch_line, &event) < 0) {
                perror("Failed to read event");
                break;
            }

            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                touch_callback(touch_line, NULL);
            }
        }
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

