#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_flame_sensor(void);
void activate_buzzer(void);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        printf("Signal received, exiting gracefully.\n");
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get flame sensor line
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request flame sensor line as input
    ret = gpiod_line_request_input(flame_line, "flame_alert");
    if (ret < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request buzzer line as output
    ret = gpiod_line_request_output(buzzer_line, "flame_alert", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_line_release(flame_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        perror("Error reading flame sensor value");
        return -1;
    }
    return value;
}

// Activate buzzer for 2 seconds
void activate_buzzer(void) {
    struct timespec sleep_time;
    sleep_time.tv_sec = 2;
    sleep_time.tv_nsec = 0;

    // Turn buzzer on
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Error setting buzzer value");
        return;
    }

    // Wait for 2 seconds
    nanosleep(&sleep_time, NULL);

    // Turn buzzer off
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Error setting buzzer value");
    }
}

// Log event to file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Turn off buzzer
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
    }

    // Release GPIO lines
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    int flame_detected = 0;
    int prev_flame_state = 1; // Initialize to no flame detected (HIGH)
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    // Log system start
    log_event("System started");

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Check alert_log.txt for details.\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int flame_value = read_flame_sensor();
        if (flame_value < 0) {
            fprintf(stderr, "Error reading flame sensor. Continuing...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        if (flame_value == 0 && prev_flame_state == 1) {
            // Flame detected (LOW-to-HIGH transition)
            log_event("Flame detected!");
            activate_buzzer();
            flame_detected = 1; // Set flag to prevent repeated logging
        } else if (flame_value == 1 && prev_flame_state == 0) {
            // Flame gone (HIGH-to-LOW transition)
            // We don't log this event, as it's not relevant for the safety system.
            prev_flame_state = 1; // Reset the state to avoid repeated logging
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

