#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_MS 200
#define LOG_FILE "touch_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 1; // Assume initially not touched (HIGH)
    unsigned long last_touch_time = 0;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 0 && last_touch_state == 1) { // Detect falling edge (HIGH-to-LOW transition)
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_MS * 1000) { // Debounce
                gpioWrite(LED_PIN, !gpioRead(LED_PIN)); // Toggle LED

                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];

                time(&rawtime);
                timeinfo = gmtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                fprintf(log_file, "%s Touch detected\n", timestamp);
                fflush(log_file); // Ensure immediate write to file

                last_touch_time = current_time;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10); // Poll every 10 ms
    }

    gpioWrite(LED_PIN, 0); // Turn off LED

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

