#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors (BCM numbering)
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Log file name
#define LOG_FILE "magnet_log.txt"

// Global variables
static FILE *log_file = NULL;
static volatile int running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} sensor_states_t;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_state(int sensor_id, int state);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR1_GPIO\n");
        return 1;
    }
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_GPIO\n");
        return 1;
    }
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR3_GPIO\n");
        return 1;
    }
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Failed to read sensor on GPIO %d\n", gpio);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log the state of a sensor to a file
int log_state(int sensor_id, int state) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp\n");
        return 1;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            free(timestamp);
            return 1;
        }
    }

    fprintf(log_file, "%s Sensor%d: %d\n", timestamp, sensor_id, state);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Record initial sensor states
    sensor_states_t initial_states;
    initial_states.sensor1_state = read_sensor(SENSOR1_GPIO);
    initial_states.sensor2_state = read_sensor(SENSOR2_GPIO);
    initial_states.sensor3_state = read_sensor(SENSOR3_GPIO);

    if (initial_states.sensor1_state == -1 || initial_states.sensor2_state == -1 || initial_states.sensor3_state == -1) {
        fprintf(stderr, "Failed to read initial sensor states, exiting\n");
        gpioTerminate();
        return 1;
    }

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int new_sensor1_state = read_sensor(SENSOR1_GPIO);
        int new_sensor2_state = read_sensor(SENSOR2_GPIO);
        int new_sensor3_state = read_sensor(SENSOR3_GPIO);

        if (new_sensor1_state == -1 || new_sensor2_state == -1 || new_sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for state changes and log them
        if (new_sensor1_state != initial_states.sensor1_state) {
            if (log_state(1, new_sensor1_state) != 0) {
                fprintf(stderr, "Failed to log sensor 1 state\n");
            }
            initial_states.sensor1_state = new_sensor1_state;
        }

        if (new_sensor2_state != initial_states.sensor2_state) {
            if (log_state(2, new_sensor2_state) != 0) {
                fprintf(stderr, "Failed to log sensor 2 state\n");
            }
            initial_states.sensor2_state = new_sensor2_state;
        }

        if (new_sensor3_state != initial_states.sensor3_state) {
            if (log_state(3, new_sensor3_state) != 0) {
                fprintf(stderr, "Failed to log sensor 3 state\n");
            }
            initial_states.sensor3_state = new_sensor3_state;
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Clean up and exit
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

