int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

