    if (write_register(handle, SI1182_LED_CURRENT, config.led_current) < 0) return -1;
    if (write_register(handle, SI1182_AVG, config.averaging) < 0) return -1;
    if (write_register(handle, SI1182_ENABLE, config.enable) < 0) return -1;
