#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_START_PIN 5
#define SENSOR_END_PIN 12
#define OUTPUT_START_PIN 17
#define OUTPUT_END_PIN 24

// Define I2C parameters
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_lines[8];
static struct gpiod_line *output_lines[8];
static int i2c_fd;
static volatile sig_atomic_t terminate = 0;
static int counter = 0;
static int last_sensor_states[8] = {0};

// Function prototypes
int init_gpio(void);
int init_i2c(void);
void cleanup(void);
void signal_handler(int sig);
void update_output_gpio(int bit);
void log_touch_event(int channel, int counter_value);
void log_light_level(int light_level);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    int i, ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    // Request sensor lines
    for (i = 0; i < 8; i++) {
        int pin = SENSOR_START_PIN + i;
        sensor_lines[i] = gpiod_chip_get_line(chip, pin);
        if (!sensor_lines[i]) {
            perror("gpiod_chip_get_line (sensor)");
            goto cleanup_chip;
        }
        ret = gpiod_line_request_input(sensor_lines[i], "touch_counter");
        if (ret < 0) {
            perror("gpiod_line_request_input (sensor)");
            goto cleanup_lines;
        }
        gpiod_line_request_set_debounce(sensor_lines[i], 10); // 10ms debounce
    }

    // Request output lines
    for (i = 0; i < 8; i++) {
        int pin = OUTPUT_START_PIN + i;
        output_lines[i] = gpiod_chip_get_line(chip, pin);
        if (!output_lines[i]) {
            perror("gpiod_chip_get_line (output)");
            goto cleanup_lines;
        }
        ret = gpiod_line_request_output(output_lines[i], "touch_counter", 0); // Initial value 0
        if (ret < 0) {
            perror("gpiod_line_request_output (output)");
            goto cleanup_lines;
        }
    }

    return 0;

cleanup_lines:
    for (i = 0; i < 8; i++) {
        if (sensor_lines[i]) gpiod_line_release(sensor_lines[i]);
        if (output_lines[i]) gpiod_line_release(output_lines[i]);
    }
cleanup_chip:
    if (chip) gpiod_chip_close(chip);
    return -1;
}

// Initialize I2C
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }

    unsigned char config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("write config command");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(void) {
    int i;

    // Reset all output lines to 0
    for (i = 0; i < 8; i++) {
        if (output_lines[i]) {
            gpiod_line_set_value(output_lines[i], 0);
        }
    }

    // Release GPIO lines
    for (i = 0; i < 8; i++) {
        if (sensor_lines[i]) gpiod_line_release(sensor_lines[i]);
        if (output_lines[i]) gpiod_line_release(output_lines[i]);
    }

    // Close I2C device
    if (i2c_fd > 0) close(i2c_fd);

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);
}

// Update output GPIOs based on the counter bit
void update_output_gpio(int bit) {
    int i;
    for (i = 0; i < 8; i++) {
        if (output_lines[i]) {
            gpiod_line_set_value(output_lines[i], (counter >> i) & 1);
        }
    }
}

// Log touch event
void log_touch_event(int channel, int counter_value) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("touch_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
        fclose(fp);
    } else {
        fprintf(stderr, "Warning: Could not open touch_log.txt for writing.\n");
    }

    printf("Touch on channel %d | Counter: %d\n", channel, counter_value);
}

// Log light level
void log_light_level(int light_level) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fp = fopen("light_log.txt", "a");
    if (fp) {
        fprintf(fp, "%s, Light Level: %d\n", timestamp, light_level);
        fclose(fp);
    } else {
        fprintf(stderr, "Warning: Could not open light_log.txt for writing.\n");
    }

    printf("Light Level: %d\n", light_level);
}

int main(void) {
    int i, sensor_value, prev_sensor_value;
    unsigned char data[2];
    int light_level;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
