#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_lines[8];
static struct gpiod_line *output_lines[8];
static int i2c_fd;
static volatile sig_atomic_t terminate = 0;
static int counter = 0;
static int last_sensor_states[8] = {0};

// Function prototypes
int init_gpio(void);
int init_i2c(void);
void cleanup(void);
void signal_handler(int sig);
void update_output_gpio(int bit);
void log_touch_event(int channel, int counter_value);
void log_light_level(int light_level);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize GPIO lines
int init_gpio(void) {
    int i, ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }

    // Request sensor lines
    for (i = 0; i < 8; i++) {
        int pin = SENSOR_START_PIN + i;
        sensor_lines[i] = gpiod_chip_get_line(chip, pin);
        if (!sensor_lines[i]) {
            perror("gpiod_chip_get_line (sensor)");
            goto cleanup_chip;
        }
        ret = gpiod_line_request_input(sensor_lines[i], "touch_counter");
        if (ret < 0) {
            perror("gpiod_line_request_input (sensor)");
            goto cleanup_lines;
        }
        gpiod_line_request_set_debounce(sensor_lines[i], 10); // 10ms debounce
    }

    // Request output lines
    for (i = 0; i < 8; i++) {
        int pin = OUTPUT_START_PIN + i;
        output_lines[i] = gpiod_chip_get_line(chip, pin);
        if (!output_lines[i]) {
            perror("gpiod_chip_get_line (output)");
            goto cleanup_lines;
        }
        ret = gpiod_line_request_output(output_lines[i], "touch_counter", 0); // Initial value 0
        if (ret < 0) {
            perror("gpiod_line_request_output (output)");
            goto cleanup_lines;
        }
    }

    return 0;

cleanup_lines:
    for (i = 0; i < 8; i++) {
        if (sensor_lines[i]) gpiod_line_release(sensor_lines[i]);
        if (output_lines[i]) gpiod_line_release(output_lines[i]);
    }
cleanup_chip:
    if (chip) gpiod_chip_close(chip);
    return -1;
