// Initialize I2C
int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }

    unsigned char config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("write config command");
        close(i2c_fd);
        return -1;
    }

    return 0;
