#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_17 17
#define GPIO_18 18
#define DEBOUNCE_MS 50
#define POLL_MS 100

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log tilt event
void log_tilt_event(int gpio) {
    char* timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to handle tilt event
void handle_tilt_event(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick_17 = 0;
    static uint32_t last_tick_18 = 0;
    uint32_t current_tick = gpioTick();

    if (gpio == GPIO_17) {
        if (last_tick_17 != 0 && (current_tick - last_tick_17) < DEBOUNCE_MS * 1000) return; // Debounce
        log_tilt_event(gpio);
        last_tick_17 = current_tick;
    } else if (gpio == GPIO_18) {
        if (last_tick_18 != 0 && (current_tick - last_tick_18) < DEBOUNCE_MS * 1000) return; // Debounce
        log_tilt_event(gpio);
        last_tick_18 = current_tick;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Request GPIO lines
    gpioSetMode(GPIO_17, PI_INPUT);
    gpioSetPullUpDown(GPIO_17, PI_PUD_UP);
    gpioSetAlertFuncEx(GPIO_17, handle_tilt_event, NULL);

    gpioSetMode(GPIO_18, PI_INPUT);
    gpioSetPullUpDown(GPIO_18, PI_PUD_UP);
    gpioSetAlertFuncEx(GPIO_18, handle_tilt_event, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(POLL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    printf("Releasing resources...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

