    gpioSetAlertFuncEx(GPIO_18, handle_tilt_event, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(POLL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    printf("Releasing resources...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

