        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    if (gpiod_line_request_input(sensor2_line, "obstacle_detector") < 0) {
        perror("Error requesting sensor2 line as input");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    if (gpiod_line_request_output(led_line, "obstacle_indicator", 0) < 0) {
        perror("Error requesting led line as output");
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        sensor1_value = read_sensor(sensor1_line);
        sensor2_value = read_sensor(sensor2_line);

        if (sensor1_value < 0 || sensor2_value < 0) {
