#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        if (gpioRead(MIC_PIN) == 1) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Peak detected at: %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
            }
            gpioDelay(100); // 100 ms
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to write to GPIO%d\n", LED_PIN);
            }
        }
        gpioDelay(125); // Approximate 8 kHz sampling rate
    }

    gpioWrite(LED_PIN, 0); // Ensure LED is off on exit
    gpioTerminate();
    return 0;
}

