#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *left_line, *center_line, *right_line;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully.\n", sig);

    // Release GPIO lines
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (center_line) {
        gpiod_line_release(center_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int left_value, center_value, right_value;
    struct timespec sleep_time;

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for the sensors
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    if (!left_line || !center_line || !right_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines for input
    if (gpiod_line_request_input(left_line, "sensor_left") < 0) {
        perror("Error requesting left sensor line");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(center_line, "sensor_center") < 0) {
        perror("Error requesting center sensor line");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(right_line, "sensor_right") < 0) {
        perror("Error requesting right sensor line");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure pull-up resistors
    if (gpiod_line_request_rising_edge_events(left_line, "sensor_left_edge") < 0) {
        perror("Error requesting left sensor rising edge events");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_rising_edge_events(center_line, "sensor_center_edge") < 0) {
        perror("Error requesting center sensor rising edge events");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_rising_edge_events(right_line, "sensor_right_edge") < 0) {
        perror("Error requesting right sensor rising edge events");
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up sleep time for 100ms
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds

    // Main loop to read and print sensor values
    while (1) {
        // Read sensor values
        left_value = gpiod_line_event_value(gpiod_line_get_events(left_line));
        center_value = gpiod_line_event_value(gpiod_line_get_events(center_line));
        right_value = gpiod_line_event_value(gpiod_line_get_events(right_line));

        // Print sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 100ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

