#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1175_ADDR 0x49
#define ALS_VISIBLE_LSB_REG 0x24
#define ALS_VISIBLE_MSB_REG 0x25

int i2c_fd = -1; // Global file descriptor for I2C device

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a register from the Si1175 sensor
int read_si1175_register(int fd, unsigned char reg) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buf[0];
}

// Function to read the ALS visible data (LSB and MSB)
int read_als_visible(int fd) {
    int lsb = read_si1175_register(fd, ALS_VISIBLE_LSB_REG);
    if (lsb < 0) return -1;

    int msb = read_si1175_register(fd, ALS_VISIBLE_MSB_REG);
    if (msb < 0) return -1;

    return (msb << 8) | lsb;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        int als_value = read_als_visible(i2c_fd);
        if (als_value >= 0) {
            printf("ALS Visible: %d\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS visible data.\n");
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup (should not reach here in normal execution due to signal handler)
    close(i2c_fd);
    return 0;
}

