#include <errno.h>
#include <string.h>

// Define GPIO pins for the Keywish 3-Way Tracking Sensor
#define LEFT_PIN 2
#define MIDDLE_PIN 3
#define RIGHT_PIN 4

// Global variables for GPIO lines and chip
struct gpiod_line *left_line = NULL;
struct gpiod_line *middle_line = NULL;
struct gpiod_line *right_line = NULL;
struct gpiod_chip *chip = NULL;

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");

        // Release GPIO lines
        if (left_line) {
            gpiod_line_release(left_line);
        }
        if (middle_line) {
            gpiod_line_release(middle_line);
        }
        if (right_line) {
            gpiod_line_release(right_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

int main() {
    int left_value, middle_value, right_value;
    struct timespec sleep_time = {0, 100000000}; // 100 milliseconds

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);

    if (!left_line || !middle_line || !right_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as inputs
    if (gpiod_line_request_input(left_line, "keywish_sensor") < 0) {
        perror("Error requesting left line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(middle_line, "keywish_sensor") < 0) {
        perror("Error requesting middle line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_input(right_line, "keywish_sensor") < 0) {
        perror("Error requesting right line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read GPIO values
        left_value = gpiod_line_get_value(left_line);
        middle_value = gpiod_line_get_value(middle_line);
        right_value = gpiod_line_get_value(right_line);

        // Log sensor values to stdout
        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Sleep for 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

