#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define NUM_LINES 8

// Define the GPIO line numbers for the TTP226 channels
const int line_numbers[NUM_LINES] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variables for GPIO lines and chip
struct gpiod_line *lines[NUM_LINES];
struct gpiod_chip *chip;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_LINES; i++)
    {
        if (lines[i])
        {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close the GPIO chip
    if (chip)
    {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip)
    {
        fprintf(stderr, "Error opening GPIO chip '%s'\n", GPIOCHIP);
        return 1;
    }

    // Request the GPIO lines
    for (int i = 0; i < NUM_LINES; i++)
    {
        lines[i] = gpiod_chip_get_line(chip, line_numbers[i]);
        if (!lines[i])
        {
            fprintf(stderr, "Error getting GPIO line %d\n", line_numbers[i]);
            // Release previously acquired lines
            for (int j = 0; j < i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Request the line as an input
        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0)
        {
            fprintf(stderr, "Error requesting GPIO line %d as input\n", line_numbers[i]);
            // Release previously acquired lines
            for (int j = 0; j <= i; j++)
            {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (1)
    {
        // Get the current time
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%S.%03d", timeinfo);

        // Read the state of each channel
        int channel_states[NUM_LINES];
        for (int i = 0; i < NUM_LINES; i++)
        {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0)
            {
                fprintf(stderr, "Error reading GPIO line %d\n", line_numbers[i]);
                // Handle the error appropriately (e.g., exit, retry)
                channel_states[i] = -1; // Indicate an error
            } else {
                channel_states[i] = value;
            }
        }

        // Log the data to the console
        printf("[%s] ", timestamp);
        for (int i = 0; i < NUM_LINES; i++)
        {
            printf("CH%d=%d ", i + 1, channel_states[i]);
        }
        printf("\n");

        // Wait for 200 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

