#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE      255

// Define fade duration
#define FADE_DURATION 5 //seconds

// Global flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize pigpio and GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins to output mode
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0)
    {
        syslog(LOG_ERR, "Failed to set RED_PIN to output mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0)
    {
        syslog(LOG_ERR, "Failed to set GREEN_PIN to output mode");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0)
    {
        syslog(LOG_ERR, "Failed to set BLUE_PIN to output mode");
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM frequency for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM frequency for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM frequency for BLUE_PIN");
        gpioTerminate();
        return -1;
    }

    // Set PWM range
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM range for RED_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM range for GREEN_PIN");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0)
    {
        syslog(LOG_ERR, "Failed to set PWM range for BLUE_PIN");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a random hue value (0-359)
int generate_hue()
{
    unsigned char hue;
    if (read(STDIN_FILENO, &hue, 1) != 1) {
        hue = rand() % 360; // Use /dev/urandom if STDIN is not available
    }
    return hue;
}

// Function to convert HSV to RGB
void hsv_to_rgb(int hue, int *r, int *g, int *b)
{
    if (hue >= 0 && hue < 60)
    {
        *r = 255;
        *g = (int)((float)hue / 60.0 * 255.0);
        *b = 0;
    }
    else if (hue >= 60 && hue < 120)
    {
        *r = (int)((float)(hue - 60) / 60.0 * 255.0);
        *g = 255;
        *b = 0;
    }
    else if (hue >= 120 && hue < 180)
    {
        *r = 0;
        *g = 255;
        *b = (int)((float)(hue - 120) / 60.0 * 255.0);
    }
    else if (hue >= 180 && hue < 240)
    {
        *r = 0;
        *g = (int)((float)(hue - 180) / 60.0 * 255.0);
        *b = 255;
    }
    else if (hue >= 240 && hue < 300)
    {
        *r = (int)((float)(hue - 240) / 60.0 * 255.0);
        *g = 0;
        *b = 255;
    }
    else
    {
        *r = 255;
        *g = 0;
        *b = (int)((float)(hue - 300) / 60.0 * 255.0);
    }
}

