#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96
#define TCS34725_ID 0x12

// GPIO pin for LED
#define LED_PIN 17

// Calibration values (example)
#define RED_GAIN 1.0
#define RED_OFFSET 0.0
#define GREEN_GAIN 1.0
#define GREEN_OFFSET 0.0
#define BLUE_GAIN 1.0
#define BLUE_OFFSET 0.0
#define CLEAR_GAIN 1.0
#define CLEAR_OFFSET 0.0

// Red value threshold
#define RED_THRESHOLD 200

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int tcs34725_init(int fd);
int tcs34725_read_register(int fd, uint8_t reg);
int tcs34725_write_register(int fd, uint8_t reg, uint8_t value);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue);
int control_led(int gpio_pin, int state);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Enable power and RGBC
        if (tcs34725_write_register(fd, TCS34725_ENABLE, 0x03) == 0) {
            // Set integration time (ATIME = 0x00 for ~154ms)
            if (tcs34725_write_register(fd, TCS34725_ATIME, 0x00) == 0) {
                // Set gain (CONTROL = 0x00 for 1x gain)
                if (tcs34725_write_register(fd, TCS34725_CONTROL, 0x00) == 0) {
                    // Verify sensor ID
                    int sensor_id = tcs34725_read_register(fd, TCS34725_ID);
                    if (sensor_id == 0x44) {
                        printf("TCS34725 sensor initialized successfully.\n");
                        return 0; // Success
                    } else {
                        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", sensor_id);
                        return -1; // Sensor ID error
                    }
                } else {
                    fprintf(stderr, "Error: Failed to set gain.\n");
                    return -1; // Gain setting error
                }
            } else {
                fprintf(stderr, "Error: Failed to set integration time.\n");
                return -1; // Integration time error
            }
        } else {
            fprintf(stderr, "Error: Failed to enable sensor.\n");
            return -1; // Enable error
        }
        retries--;
        usleep(10000); // Wait before retrying
    }
    fprintf(stderr, "Error: TCS34725 initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Read a single byte from a TCS34725 register
int tcs34725_read_register(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }

    return value;
}

// Write a single byte to a TCS34725 register
int tcs34725_write_register(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error: Could not write to register");
        return -1;
    }

    return 0;
}

// Read 16-bit data from the TCS34725
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    // Read all 8 bytes at once
    if (write(fd, NULL, 0) != 0) { // Dummy write to trigger read
        perror("Error: Could not trigger read");
        return -1;
    }

    if (read(fd, buffer, 8) != 8) {
        perror("Error: Could not read data");
        return -1;
    }

    *clear = (uint16_t)buffer[1] << 8 | buffer[0];
    *red   = (uint16_t)buffer[3] << 8 | buffer[2];
    *green = (uint16_t)buffer[5] << 8 | buffer[4];
    *blue  = (uint16_t)buffer[7] << 8 | buffer[6];

    return 0;
}

// Calibrate the raw RGB and clear data
void calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, float *calibrated_clear, float *calibrated_red, float *calibrated_green, float *calibrated_blue) {
    *calibrated_clear = (float)clear * CLEAR_GAIN + CLEAR_OFFSET;
    *calibrated_red   = (float)red   * RED_GAIN   + RED_OFFSET;
    *calibrated_green = (float)green * GREEN_GAIN + GREEN_OFFSET;
    *calibrated_blue  = (float)blue  * BLUE_GAIN  + BLUE_OFFSET;
}

// Control the LED state
int control_led(int gpio_pin, int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        perror("Error: Failed to set LED state");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error: Could not open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line for LED pin
    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        perror("Error: Could not get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "color_sensor", 0) < 0) {
        perror("Error: Could not request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t clear, red, green, blue;
        float calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;

        // Read data from sensor
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate the data
            calibrate_data(clear, red, green, blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

            // Print calibrated RGB and clear values
            printf("Clear: %.2f, Red: %.2f, Green: %.2f, Blue: %.2f\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                if (control_led(LED_PIN, 1) != 0) {
                    fprintf(stderr, "Error: Failed to turn LED on.\n");
                }
            } else {
                if (control_led(LED_PIN, 0) != 0) {
                    fprintf(stderr, "Error: Failed to turn LED off.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Re-initializing...\n");
            // Attempt to re-initialize the sensor
            tcs34725_init(i2c_fd);
        }

        usleep(200000); // 200 ms delay
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    printf("Exiting.\n");
    return 0;
}

