    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error: Could not open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line for LED pin
    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        perror("Error: Could not get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "color_sensor", 0) < 0) {
        perror("Error: Could not request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t clear, red, green, blue;
        float calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;

        // Read data from sensor
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate the data
            calibrate_data(clear, red, green, blue, &calibrated_clear, &calibrated_red, &calibrated_green, &calibrated_blue);

