                }
            } else {
                if (control_led(LED_PIN, 0) != 0) {
                    fprintf(stderr, "Error: Failed to turn LED off.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Re-initializing...\n");
            // Attempt to re-initialize the sensor
            tcs34725_init(i2c_fd);
        }

        usleep(200000); // 200 ms delay
    }

    // Clean up resources
    printf("Cleaning up resources...\n");
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    printf("Exiting.\n");
    return 0;
}

