// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(uint16_t *lux);
int map_lux_to_brightness(uint16_t lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Send measurement command
    uint8_t cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// BH1750 reading function with retry
int read_bh1750(uint16_t *lux) {
    uint8_t buffer[2];
    int retries = 3;

    while (retries > 0) {
        if (read(i2c_fd, buffer, 2) == 2) {
            *lux = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1; // Failure
}

