int map_lux_to_brightness(uint16_t lux) {
    // Define lux range and corresponding brightness range
    int min_lux = 0;
    int max_lux = 1000;
    int min_brightness = 0;
    int max_brightness = 255;

    // Clamp lux value to the defined range
    if (lux < min_lux) {
        lux = min_lux;
    }
    if (lux > max_lux) {
        lux = max_lux;
    }

    // Logarithmic mapping
    float log_lux = log10f((float)lux);
    float log_max_lux = log10f((float)max_lux);
    float brightness_float = (log_lux / log_max_lux) * (max_brightness - min_brightness) + min_brightness;

    // Clamp brightness to the defined range
    int brightness = (int)brightness_float;
    if (brightness < min_brightness) {
        brightness = min_brightness;
    }
    if (brightness > max_brightness) {
        brightness = max_brightness;
    }

    return brightness;
}

