#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x20 // One-Time High-Resolution Mode
#define APA102_START_FRAME 0x00000000
#define APA102_END_FRAME 0xFFFFFFFF
#define APA102_LED_FRAME_START 0xE0000000
#define NUM_LEDS 32
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *device);
int init_spi(const char *device);
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux);
int send_apa102_frame(int spi_fd, int brightness);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", sig);
}

// Initialize I2C
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI
int init_spi(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode and speed
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t cmd = BH1750_CMD;
    uint8_t buf[2];

    if (write(i2c_fd, &cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(120000); // Wait for conversion (at least 120ms)

    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    unsigned int raw = (buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2;
    return 0;
}

// Map lux value to APA102 brightness (5-bit)
int map_lux_to_brightness(float lux) {
    if (lux < 10) {
        return 0;
    } else if (lux > 300) {
        return 31;
    } else {
        return (int)(((lux - 10) / (300 - 10)) * 31);
    }
}

// Send APA102 frame
int send_apa102_frame(int spi_fd, int brightness) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    uint8_t led_frame[4];

    // Create LED frame
    led_frame[0] = 0xE0 | (brightness & 0x1F); // Global brightness
    led_frame[1] = 0x00; // Blue
    led_frame[2] = 0x00; // Green
    led_frame[3] = 0x00; // Red

    // Send start frame
    if (write(spi_fd, start_frame, 4) != 4) {
        perror("Error sending start frame");
        return -1;
    }

    // Send LED frames
    for (int i = 0; i < NUM_LEDS; i++) {
        if (write(spi_fd, led_frame, 4) != 4) {
            perror("Error sending LED frames");
            return -1;
        }
    }

    // Send end frame
    if (write(spi_fd, end_frame, 4) != 4) {
        perror("Error sending end frame");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi("/dev/spidev0.0");
    if (spi_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    float lux;
    int brightness;

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);
            printf("Brightness: %d\n", brightness);

            // Send APA102 frame
            if (send_apa102_frame(spi_fd, brightness) != 0) {
                fprintf(stderr, "Error sending APA102 frame\n");
            }
        } else {
            fprintf(stderr, "Error reading BH1750 sensor\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

