#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define WS2812B_GPIO 18
#define NUM_LEDS 1
#define LUX_MAX 120000.0
#define GAMMA 2.2

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int init_veml7700(int fd);
unsigned int read_veml7700_als(int fd);
float convert_to_lux(unsigned int raw_value);
unsigned char map_lux_to_brightness(float lux);
int init_gpio(int gpio_pin);
void set_gpio_output(struct gpiod_line *line);
void bit_bang_ws2812b(struct gpiod_line *line, unsigned char *data, int num_leds);
void threshold_control(struct gpiod_line *line, unsigned char *data, int num_leds, int threshold);
void cleanup(int signum);

// Signal handler
void cleanup(int signum) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Turn off LED strip
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Release GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close I2C file descriptor
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

// Initialize I2C
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize VEML7700 sensor
int init_veml7700(int fd) {
    unsigned short config_value = 0x0000; // Integration time 100ms, Gain 1/8
    unsigned char buf[3];

    buf[0] = VEML7700_CONFIG_REG;
    buf[1] = config_value & 0xFF;        // LSB
    buf[2] = (config_value >> 8) & 0xFF; // MSB

    if (write(fd, buf, 3) != 3) {
        perror("Error writing to VEML7700 configuration register");
        return -1;
    }

    return 0;
}

// Read ALS data from VEML7700
unsigned int read_veml7700_als(int fd) {
    unsigned char buf[1];
    unsigned int raw_value;

    buf[0] = VEML7700_ALS_REG;

    if (write(fd, buf, 1) != 1) {
        perror("Error writing to VEML7700 ALS register");
        return 0; // Return 0 on error
    }

    if (read(fd, buf, 1) != 1) {
        perror("Error reading from VEML7700 ALS register");
        return 0; // Return 0 on error
    }

    raw_value = buf[0];
    return raw_value;
}

// Convert raw ALS value to lux
float convert_to_lux(unsigned int raw_value) {
    return raw_value * 0.0288;
}

// Map lux value to brightness using gamma correction
unsigned char map_lux_to_brightness(float lux) {
    float brightness = 255.0 * pow(lux / LUX_MAX, 1.0 / GAMMA);
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    return (unsigned char)brightness;
}

// Initialize GPIO
int init_gpio(int gpio_pin) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "veml7700_led", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Set GPIO line output
void set_gpio_output(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Error setting GPIO line output to low");
    }
}

// Bit-bang WS2812B LED strip
void bit_bang_ws2812b(struct gpiod_line *line, unsigned char *data, int num_leds) {
    struct timespec on_time = {0, 800000}; // 800kHz, 0.8us high time
    struct timespec off_time = {0, 400000};  // 800kHz, 0.4us low time

    for (int i = 0; i < num_leds; i++) {
        for (int j = 7; j >= 0; j--) {
            if ((data[i] >> j) & 1) {
                // Bit is 1, set GPIO high
                if (gpiod_line_set_value(line, 1) < 0) {
                    perror("Error setting GPIO line high");
                }
                nanosleep(&on_time, NULL);
                if (gpiod_line_set_value(line, 0) < 0) {
                    perror("Error setting GPIO line low");
                }
                nanosleep(&off_time, NULL);
            } else {
                // Bit is 0, set GPIO low
                if (gpiod_line_set_value(line, 0) < 0) {
                    perror("Error setting GPIO line low");
                }
                nanosleep(&off_time, NULL);
                if (gpiod_line_set_value(line, 1) < 0) {
                    perror("Error setting GPIO line high");
                }
                nanosleep(&on_time, NULL);
            }
        }
    }
}

// Threshold control (fallback)
void threshold_control(struct gpiod_line *line, unsigned char *data, int num_leds, int threshold) {
    for (int i = 0; i < num_leds; i++) {
        if (data[i] > threshold) {
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Error setting GPIO line high");
            }
        } else {
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Error setting GPIO line low");
            }
        }
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize I2C
    int retry_count = 0;
    while ((i2c_fd = init_i2c(I2C_BUS, VEML7700_ADDR)) < 0 && retry_count < 3) {
        fprintf(stderr, "I2C initialization failed. Retrying in 100ms...\n");
        usleep(100000); // 100ms
        retry_count++;
    }
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        return 1;
    }

    // Initialize VEML7700
    retry_count = 0;
    while (init_veml7700(i2c_fd) < 0 && retry_count < 3) {
        fprintf(stderr, "VEML7700 initialization failed. Retrying in 100ms...\n");
        usleep(100000); // 100ms
        retry_count++;
    }
    if (init_veml7700(i2c_fd) < 0) {
        fprintf(stderr, "VEML7700 initialization failed after multiple retries. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(WS2812B_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ALS data
        unsigned int raw_value = read_veml7700_als(i2c_fd);

        // Convert to lux
        float lux = convert_to_lux(raw_value);

        // Map to brightness
        unsigned char brightness = map_lux_to_brightness(lux);

        // Prepare LED data (single LED)
        unsigned char led_data[NUM_LEDS] = {brightness, brightness, brightness}; // RGB

        // Control LED strip
        bit_bang_ws2812b(gpio_line, led_data, NUM_LEDS);

        // Print data
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        usleep(200000); // 200ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

