#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define BUFFER_SIZE 60
#define MAX_LUX 1000

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_gpio();
int read_bh1750(float *lux);
float convert_to_lux(uint16_t raw_value);
void update_circular_buffer(float lux);
float calculate_average_lux();
float map_lux_to_blink_rate(float average_lux);
void blink_led(float blink_rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    uint8_t mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize the GPIO pin
int init_gpio() {
    char buffer[64];
    int ret;

    // Export GPIO
    snprintf(buffer, sizeof(buffer), GPIO_PATH "/export");
    int export_fd = open(buffer, O_WRONLY);
    if (export_fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }
    ret = write(export_fd, GPIO_PIN, strlen(GPIO_PIN));
    if (ret < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(export_fd);
        return -1;
    }
    close(export_fd);

    // Set direction to output
    snprintf(buffer, sizeof(buffer), GPIO_PATH "/gpio%d/direction", GPIO_PIN);
    int direction_fd = open(buffer, O_WRONLY);
    if (direction_fd < 0) {
        perror("Error opening /sys/class/gpio/gpio17/direction");
        return -1;
    }
    ret = write(direction_fd, "out", 3);
    if (ret < 0) {
        perror("Error writing to /sys/class/gpio/gpio17/direction");
        close(direction_fd);
        return -1;
    }
    close(direction_fd);

    return 0;
}

// Function to read the BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t buffer[2];
    int ret;

    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    *lux = convert_to_lux(raw_value);
    return 0;
}

// Function to convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to update the circular buffer
void update_circular_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average lux
float calculate_average_lux() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to map lux to blink rate
float map_lux_to_blink_rate(float average_lux) {
    float rate = 0.5 + (average_lux / MAX_LUX) * 4.5;
    if (rate < 0.5) rate = 0.5;
    if (rate > 5.0) rate = 5.0;
    return rate;
}

// Function to blink the LED
void blink_led(float blink_rate) {
    struct timeval tv;
    long period_us = (long)(500000.0 / blink_rate); // Period in microseconds
    long on_time_us = period_us / 2;
    long off_time_us = period_us - on_time_us;

    tv.tv_sec = 0;
    tv.tv_usec = on_time_us;
    write(gpio_fd, &tv, sizeof(tv));

    tv.tv_usec = off_time_us;
