#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line, *clock_line, *latch_line;

// Function prototypes
int shift_out(unsigned char data);
int display_digit(unsigned char digit);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

// Shift-out function
int shift_out(unsigned char data) {
    int i;
    for (i = 0; i < 8; i++) {
        // Set data pin
        gpiod_line_set_value(data_line, (data >> (7 - i)) & 0x01);

        // Clock high
        gpiod_line_set_value(clock_line, 1);
        usleep(1); // Small delay

        // Clock low
        gpiod_line_set_value(clock_line, 0);
        usleep(1); // Small delay
    }

    // Latch high
    gpiod_line_set_value(latch_line, 1);
    usleep(1); // Small delay

    // Latch low
    gpiod_line_set_value(latch_line, 0);
    usleep(1); // Small delay

    return 0;
}

// Display digit function
int display_digit(unsigned char digit) {
    // Common cathode 7-segment display pattern for '5'
    unsigned char pattern = 0x49; // Q0=1, Q1=1, Q2=0, Q3=1, Q4=1, Q5=0, Q6=1, Q7=0
    if (shift_out(pattern)) {
        fprintf(stderr, "Error: Shift-out failed\n");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = 500 * 1000 * 1000; // 500 ms
    off_time.tv_sec = 0;
    off_time.tv_nsec = 500 * 1000 * 1000; // 500 ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(data_line, "74HC595 data", 0) < 0) {
        perror("Error requesting data line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(clock_line, "74HC595 clock", 0) < 0) {
        perror("Error requesting clock line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(latch_line, "74HC595 latch", 0) < 0) {
        perror("Error requesting latch line as output");
        cleanup(0);
        return 1;
    }

    // Main loop
    while (1) {
        // Display '5'
        if (display_digit(0x49)) {
            fprintf(stderr, "Error displaying digit\n");
        }
        nanosleep(&on_time, NULL);

        // Turn off display
        if (display_digit(0x00)) {
            fprintf(stderr, "Error displaying digit\n");
        }
        nanosleep(&off_time, NULL);
    }

    return 0;
}

