#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit program
    exit(0);
}

int main()
{
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request LED line as output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with pull-up
    if (gpiod_line_request_input(button_line, "button", GPIOD_LINE_REQUEST_PUD_UP) < 0) {
        perror("Error requesting button line as input");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Blink LED
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Error setting LED value (on)");
            break;
        }
        sleep(1);

        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Error setting LED value (off)");
            break;
        }
        sleep(1);

        // Monitor button events
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(button_line, &event, 1000); // 1-second timeout

        if (ret < 0) {
            if (errno == ETIMEDOUT) {
                // Timeout occurred, no event
            } else {
                perror("Error waiting for button event");
                break;
            }
        } else if (ret > 0) {
            // Event occurred
            if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                printf("Button pressed! Exiting.\n");
                break; // Exit loop on button press
            } else {
                fprintf(stderr, "Unknown button event type: %d\n", event.event_type);
            }
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

