#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, exiting gracefully...\n", sig);

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get GPIO lines
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", LED_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(button_line, "button") < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", BUTTON_PIN, strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int button_pressed = 0;
    while (1) {
        int value = gpiod_line_get_value(button_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d value: %s\n", BUTTON_PIN, strerror(errno));
            break; // Exit loop on error
        }

        if (value == 1 && !button_pressed) {
            // Button pressed
            button_pressed = 1;

            // Blink LED
            while (button_pressed) {
                if (gpiod_line_set_value(led_line, 1) < 0) {
                    fprintf(stderr, "Error setting GPIO line %d value to 1: %s\n", LED_PIN, strerror(errno));
                    break; // Exit blink loop on error
                }
                usleep(500000); // 500ms

                if (gpiod_line_set_value(led_line, 0) < 0) {
                    fprintf(stderr, "Error setting GPIO line %d value to 0: %s\n", LED_PIN, strerror(errno));
                    break; // Exit blink loop on error
                }
                usleep(500000); // 500ms

                // Check if button is still pressed
                int current_value = gpiod_line_get_value(button_line);
                if (current_value < 0) {
                    fprintf(stderr, "Error reading GPIO line %d value during blink: %s\n", BUTTON_PIN, strerror(errno));
                    break; // Exit blink loop on error
                }
                if (current_value == 0) {
                    button_pressed = 0; // Button released during blink
                    break; // Exit blink loop
                }
            }
        } else if (value == 0 && button_pressed) {
            // Button released
            button_pressed = 0;

            // Turn off LED
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error setting GPIO line %d value to 0: %s\n", LED_PIN, strerror(errno));
                break; // Exit loop on error
            }
        }

        usleep(50000); // Small delay to avoid busy-waiting
    }

    // Release GPIO lines and close chip (in case the loop exited due to an error)
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

