#include <time.h>
#include <gpiod.h>

// Define GPIO pins for RGB LED (BCM numbering)
#define RED_PIN 18
#define GREEN_PIN 23
#define BLUE_PIN 24

// Define PWM period in nanoseconds (10 ms = 1000000000 ns)
#define PWM_PERIOD 10000000

// Global variables for GPIO lines and chip
struct gpiod_line *red_line = NULL;
struct gpiod_line *green_line = NULL;
struct gpiod_line *blue_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
void set_red(int duty_cycle);
void set_green(int duty_cycle);
void set_blue(int duty_cycle);
void generate_random_color(int *red, int *green, int *blue);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the red PWM duty cycle
void set_red(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value for red: %d\n", duty_cycle);
        return;
    }

    // Calculate the on and off times in nanoseconds
    long on_time = (long)((float)duty_cycle / 100.0 * PWM_PERIOD);
    long off_time = PWM_PERIOD - on_time;

    // Set the GPIO line value
    if (gpiod_line_set_value(red_line, 0) < 0) { // Low
        perror("Error setting red line low");
    }
    usleep(on_time / 1000); // Convert ns to us

    if (gpiod_line_set_value(red_line, 1) < 0) { // High
        perror("Error setting red line high");
    }
    usleep(off_time / 1000); // Convert ns to us
}

// Function to set the green PWM duty cycle
void set_green(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value for green: %d\n", duty_cycle);
        return;
    }

    // Calculate the on and off times in nanoseconds
    long on_time = (long)((float)duty_cycle / 100.0 * PWM_PERIOD);
    long off_time = PWM_PERIOD - on_time;

    // Set the GPIO line value
    if (gpiod_line_set_value(green_line, 0) < 0) { // Low
        perror("Error setting green line low");
    }
    usleep(on_time / 1000); // Convert ns to us

    if (gpiod_line_set_value(green_line, 1) < 0) { // High
        perror("Error setting green line high");
    }
    usleep(off_time / 1000); // Convert ns to us
}

// Function to set the blue PWM duty cycle
void set_blue(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value for blue: %d\n", duty_cycle);
        return;
    }

    // Calculate the on and off times in nanoseconds
    long on_time = (long)((float)duty_cycle / 100.0 * PWM_PERIOD);
    long off_time = PWM_PERIOD - on_time;

    // Set the GPIO line value
    if (gpiod_line_set_value(blue_line, 0) < 0) { // Low
        perror("Error setting blue line low");
    }
    usleep(on_time / 1000); // Convert ns to us

    if (gpiod_line_set_value(blue_line, 1) < 0) { // High
        perror("Error setting blue line high");
    }
    usleep(off_time / 1000); // Convert ns to us
}

// Function to generate random RGB values
void generate_random_color(int *red, int *green, int *blue) {
    *red = rand() % 101;
    *green = rand() % 101;
    *blue = rand() % 101;
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for RGB pins
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    // Request GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        perror("Error requesting red line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        perror("Error requesting green line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        perror("Error requesting blue line as output");
        cleanup(0);
        return 1;
    }

    // Main loop
    while (1) {
        int red, green, blue;

        // Generate random RGB values
        generate_random_color(&red, &green, &blue);

        // Set PWM duty cycles
        set_red(red);
        set_green(green);
        set_blue(blue);

        // Sleep for 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

