// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28

// GPIO pin for impact indication
#define IMPACT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double g_threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int config_accelerometer();
accelerometer_data_t read_accelerometer_data();
double calculate_magnitude(accelerometer_data_t data);
void handle_impact(accelerometer_data_t data);
void log_impact(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
