#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADPD188BI I2C address
#define ADPD188BI_ADDR 0x39

// ADPD188BI register addresses
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_LSB_REG 0x66
#define RED_MSB_REG 0x67
#define GREEN_LSB_REG 0x68
#define GREEN_MSB_REG 0x69
#define BLUE_LSB_REG 0x6A
#define BLUE_MSB_REG 0x6B

// GPIO pin for LED PWM
#define LED_PIN 18

// I2C handle
int i2c_handle;

// File pointer for CSV log
FILE *log_file;

// Function prototypes
int init_adpd188bi();
uint16_t read_als();
void read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void set_led_brightness(uint16_t als_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioPWM(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initialize ADPD188BI sensor
int init_adpd188bi() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, MODE_REG, 0x01) == 0) {
            printf("ADPD188BI initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error initializing ADPD188BI (attempt %d). Retrying in 100ms...\n", 4 - retries);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize ADPD188BI after multiple retries.\n");
    return -1; // Failure
}

// Read ALS data from the sensor
uint16_t read_als() {
    int lsb, msb;
    int retries = 3;

    while (retries > 0) {
        lsb = i2cReadByteData(i2c_handle, ALS_LSB_REG);
        if (lsb >= 0) {
            msb = i2cReadByteData(i2c_handle, ALS_MSB_REG);
            if (msb >= 0) {
                return (uint16_t)((msb << 8) | lsb);
            } else {
                fprintf(stderr, "Error reading ALS MSB (attempt %d). Retrying in 100ms...\n", 4 - retries);
                gpioDelay(100000); // 100ms delay
                retries--;
            }
        } else {
            fprintf(stderr, "Error reading ALS LSB (attempt %d). Retrying in 100ms...\n", 4 - retries);
            gpioDelay(100000); // 100ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return 0; // Return 0 on failure
}

// Read RGB data from the sensor
void read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int red_lsb, red_msb, green_lsb, green_msb, blue_lsb, blue_msb;

    red_lsb = i2cReadByteData(i2c_handle, RED_LSB_REG);
    red_msb = i2cReadByteData(i2c_handle, RED_MSB_REG);
    green_lsb = i2cReadByteData(i2c_handle, GREEN_LSB_REG);
    green_msb = i2cReadByteData(i2c_handle, GREEN_MSB_REG);
    blue_lsb = i2cReadByteData(i2c_handle, BLUE_LSB_REG);
    blue_msb = i2cReadByteData(i2c_handle, BLUE_MSB_REG);

    if (red_lsb < 0 || red_msb < 0 || green_lsb < 0 || green_msb < 0 || blue_lsb < 0 || blue_msb < 0) {
        fprintf(stderr, "Error reading RGB data.\n");
        *red = *green = *blue = 0; // Set to 0 on error
        return;
    }

    *red = (uint16_t)((red_msb << 8) | red_lsb);
    *green = (uint16_t)((green_msb << 8) | green_lsb);
    *blue = (uint16_t)((blue_msb << 8) | blue_lsb);
}

// Log data to CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Set LED brightness based on ALS value
void set_led_brightness(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * 255.0);

    // Ensure duty cycle is within bounds
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADPD188BI_ADDR, 0); // Bus 1, address 0x39, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADPD188BI sensor
    if (init_adpd188bi() != 0) {
        fprintf(stderr, "ADPD188BI initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Configure PWM on LED pin
    gpioSetPWMfrequency(LED_PIN, 1000); // 1 kHz PWM frequency
    gpioSetPWMrange(LED_PIN, 255); // PWM range of 0-255

    // Open CSV file for logging
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t als_value, red_value, green_value, blue_value;

    // Main loop
    while (1) {
        // Read sensor data
        als_value = read_als();
        read_rgb(&red_value, &green_value, &blue_value);

        // Log data
        log_data(als_value, red_value, green_value, blue_value);

        // Set LED brightness
        set_led_brightness(als_value);

        // Wait 500ms
        gpioDelay(500000); // 500ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

