#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold (m/s^2)
#define IMPACT_THRESHOLD 19.62

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_sensor();
accelerometer_data_t read_accelerometer_data();
double calculate_magnitude(accelerometer_data_t data);
void log_impact(accelerometer_data_t data, double magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the FXOS8700CQ sensor
int initialize_sensor() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xC7, got 0x%X\n", who_am_i);
        return -1;
    }
    printf("WHO_AM_I check passed!\n");

    // Configure sensor for ±2g mode and active mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

// Reads accelerometer data from the FXOS8700CQ
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine MSB and LSB, shift right by 2 bits
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    return data;
}

// Calculates the magnitude of the acceleration vector
double calculate_magnitude(accelerometer_data_t data) {
    // Convert raw data to g units (assuming +/- 2g range)
    double x_g = (double)data.x / 4096.0;
    double y_g = (double)data.y / 4096.0;
    double z_g = (double)data.z / 4096.0;

    // Calculate magnitude
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

