#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD_US 50000 // microseconds
#define CALIBRATION_SAMPLES 100
#define DPS_THRESHOLD 50.0

// Global variables
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int gyro_init(int fd);
int gyro_read_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_data);
int calibrate_gyro(int fd, int16_t *x, int16_t *y, int16_t *z);
int log_data(FILE *fp, float x, float y, float z);
void check_thresholds(float x, float y, float z);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    if (i2c_write_byte(fd, CTRL_REG1, 0x0F) != 0) return -1; // Normal mode, all axes enabled, 100 Hz ODR
    if (i2c_write_byte(fd, CTRL_REG4, 0x00) != 0) return -1; // 250 dps full-scale, continuous update
    return 0;
}

// Gyroscope data reading function
int gyro_read_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, OUT_X_L, data, 6) != 0) return -1;

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data * 0.00875;
}

// Gyroscope calibration function
int calibrate_gyro(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    int16_t x_val, y_val, z_val;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (gyro_read_data(fd, &x_val, &y_val, &z_val) != 0) return -1;
        x_sum += x_val;
        y_sum += y_val;
        z_sum += z_val;
        usleep(10000); // 10 ms delay
    }

    x_offset = (float)x_sum / CALIBRATION_SAMPLES;
    y_offset = (float)y_sum / CALIBRATION_SAMPLES;
    z_offset = (float)z_sum / CALIBRATION_SAMPLES;

    printf("Calibration complete.\n");
    printf("X offset: %f, Y offset: %f, Z offset: %f\n", x_offset, y_offset, z_offset);
    return 0;
}

// Log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Check for threshold violations
void check_thresholds(float x, float y, float z) {
    if (fabs(x) > DPS_THRESHOLD || fabs(y) > DPS_THRESHOLD || fabs(z) > DPS_THRESHOLD) {
        fprintf(stderr, "WARNING: Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = gmtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(log_file, "%s,ALERT: Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", timestamp, x, y, z);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    int16_t raw_x, raw_y, raw_z;
    float x_dps, y_dps, z_dps;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize gyroscope
    if (gyro_init(i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Calibrate gyroscope
    if (calibrate_gyro(i2c_fd, &raw_x, &raw_y, &raw_z) != 0) {
        fprintf(stderr, "Gyroscope calibration failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (gyro_read_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x_dps = convert_to_dps(raw_x) - x_offset;
            y_dps = convert_to_dps(raw_y) - y_offset;
            z_dps = convert_to_dps(raw_z) - z_offset;

            // Log data
            if (log_data(log_file, x_dps, y_dps, z_dps) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            // Check for threshold violations
            check_thresholds(x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        usleep(SAMPLE_PERIOD_US); // Delay for desired sample rate
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

