#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_DEVID 0x00

// GPIO pin for LED
#define LED_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the ADXL345 sensor
int adxl345_init() {
    // Verify DEVID
    char buf[2];
    buf[0] = ADXL345_DEVID;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to DEVID register.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error reading DEVID register.\n");
        return -1;
    }
    if (buf[0] != 0xE5) {
        fprintf(stderr, "Incorrect DEVID: 0x%02X\n", buf[0]);
        return -1;
    }

    // Set full resolution, ±2g range, and measure mode
    buf[0] = ADXL345_POWER_CTL;
    buf[1] = 0x08; // Enable measurement
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register.\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char buf[7];
    buf[0] = ADXL345_DATAX0 | 0x80; // Read multiple bytes starting from DATAX0

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 7) != 0) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x_raw = (int16_t)((buf[2] << 8) | buf[1]);
    int16_t y_raw = (int16_t)((buf[4] << 8) | buf[3]);
    int16_t z_raw = (int16_t)((buf[6] << 8) | buf[5]);

    // Convert to g units (assuming full resolution, ±2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control the LED based on acceleration
void control_led(float x, float y, float z) {
    if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            control_led(x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(100000); // 100 ms delay (10 Hz)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

