#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC registers
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03

// Sensitivity values (adjust based on your sensor's configuration)
#define ACCEL_SENSITIVITY 0.001 // g/LSB for +/- 2g range
#define MAG_SENSITIVITY 0.08 // gauss/LSB for +/- 1.3 gauss range

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x, y, z;
} sensor_data_t;

// Function prototypes
int init_lsm303();
sensor_data_t read_accelerometer();
sensor_data_t read_magnetometer();
float calculate_heading(sensor_data_t accel, sensor_data_t mag);
void log_data(float heading, sensor_data_t accel, sensor_data_t mag);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM303DLHC
int init_lsm303() {
    // Initialize accelerometer
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    // Initialize magnetometer
    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
sensor_data_t read_accelerometer() {
    sensor_data_t accel;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        accel.x = accel.y = accel.z = 0.0; // Return zero values on error
        return accel;
    }

    // Combine high and low bytes, convert to g
    accel.x = (int16_t)((buffer[1] << 8) | buffer[0]) * ACCEL_SENSITIVITY;
    accel.y = (int16_t)((buffer[3] << 8) | buffer[2]) * ACCEL_SENSITIVITY;
    accel.z = (int16_t)((buffer[5] << 8) | buffer[4]) * ACCEL_SENSITIVITY;

    return accel;
}

// Read magnetometer data
sensor_data_t read_magnetometer() {
    sensor_data_t mag;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        mag.x = mag.y = mag.z = 0.0; // Return zero values on error
        return mag;
    }

    // Combine high and low bytes, convert to gauss
    mag.x = (int16_t)((buffer[0] << 8) | buffer[1]) * MAG_SENSITIVITY;
    mag.y = (int16_t)((buffer[2] << 8) | buffer[3]) * MAG_SENSITIVITY;
    mag.z = (int16_t)((buffer[4] << 8) | buffer[5]) * MAG_SENSITIVITY;

    return mag;
}

// Calculate tilt-compensated heading
float calculate_heading(sensor_data_t accel, sensor_data_t mag) {
    float roll = atan2(accel.y, accel.z);
    float pitch = atan2(-accel.x, sqrt(accel.y * accel.y + accel.z * accel.z));

    float mag_x_comp = mag.x * cos(pitch) + mag.z * sin(pitch);
    float mag_y_comp = mag.x * sin(roll) * sin(pitch) + mag.y * cos(roll) - mag.z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
void log_data(float heading, sensor_data_t accel, sensor_data_t mag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, heading, accel.x, accel.y, accel.z, mag.x, mag.y);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C bus for accelerometer\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C bus for magnetometer\n");
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303DLHC
    if (init_lsm303() < 0) {
        fprintf(stderr, "LSM303DLHC initialisation failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y\n");
    }
    rewind(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t accel_data = read_accelerometer();
        sensor_data_t mag_data = read_magnetometer();

        // Calculate heading
        float heading = calculate_heading(accel_data, mag_data);

        // Log data
        log_data(heading, accel_data, mag_data);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

