#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// Sensitivity values (from ADIS16488A datasheet)
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function prototypes
int spi_read_register(int reg_addr, int16_t *data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void cleanup();
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int reg_addr, int16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer: MSB=0, register address (7 bits), dummy bit
    tx_buf[0] = 0x00; // MSB = 0 for read
    tx_buf[1] = (reg_addr << 1); // Register address (7 bits)
    tx_buf[2] = 0x00; // Dummy bit

    // Use spiXfer to send the transmit buffer and receive the response
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);

    if (result < 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate an error
    }

    // Extract the 16-bit data from the receive buffer
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0; // Indicate success
}

// Function to read gyroscope and accelerometer data
imu_data_t read_imu_data() {
    imu_data_t data;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (spi_read_register(X_GYRO, &raw_gyro_x) != 0) {
        fprintf(stderr, "Error reading X_GYRO\n");
        data.gyro_x = 0.0; // Set to 0.0 in case of error
    } else {
        data.gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    }

    if (spi_read_register(Y_GYRO, &raw_gyro_y) != 0) {
        fprintf(stderr, "Error reading Y_GYRO\n");
        data.gyro_y = 0.0;
    } else {
        data.gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    }

    if (spi_read_register(Z_GYRO, &raw_gyro_z) != 0) {
        fprintf(stderr, "Error reading Z_GYRO\n");
        data.gyro_z = 0.0;
    } else {
        data.gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    }

    // Read accelerometer data
    if (spi_read_register(X_ACCEL, &raw_accel_x) != 0) {
        fprintf(stderr, "Error reading X_ACCEL\n");
        data.accel_x = 0.0;
    } else {
        data.accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    }

    if (spi_read_register(Y_ACCEL, &raw_accel_y) != 0) {
        fprintf(stderr, "Error reading Y_ACCEL\n");
        data.accel_y = 0.0;
    } else {
        data.accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    }

    if (spi_read_register(Z_ACCEL, &raw_accel_z) != 0) {
        fprintf(stderr, "Error reading Z_ACCEL\n");
        data.accel_z = 0.0;
    } else {
        data.accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;
    }

    return data;
}

// Function to log data to a CSV file
void log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp_ms,
            data.gyro_x,
            data.gyro_y,
            data.gyro_z,
            data.accel_x,
            data.accel_y,
            data.accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup function to close SPI, file, and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register cleanup function with atexit
    if (atexit(cleanup) != 0) {
        fprintf(stderr, "Failed to register cleanup function.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
