// SPI initialization function
int spi_init(int bus, int device, int mode, int bits, int speed) {
    char spi_device_path[20];
    snprintf(spi_device_path, sizeof(spi_device_path), "/dev/spidev%d.%d", bus, device);

    int fd = open(spi_device_path, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_val = SPI_MODE(mode);
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_val = SPI_BITS_PER_WORD(bits);
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_val) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    int speed_val = SPI_MAX_SPEED(speed);
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED(SPI_MAX_SPEED),
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD(SPI_BITS_PER_WORD),
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// ADIS16448 register read function
int adis16448_read_register(int fd, uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Set MSB of register address to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spi_transfer(fd, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error during SPI transfer for register 0x%02X\n", reg_addr);
        return -1;
    }

    // Combine the two bytes to form the 16-bit data
    *data = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

