#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Signal Handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read data from ADIS16448
int16_t read_adis16448(uint8_t register_address) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct the transmit buffer
    tx_buffer[0] = register_address | 0x8000; // Set MSB for read
    tx_buffer[1] = 0x00; // Dummy byte for clocking out data
    tx_buffer[2] = 0x00; // Dummy byte for clocking out data

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return 0; // Return 0 on failure
    }

    // Extract the received data
    uint16_t raw_data = (rx_buffer[1] << 8) | rx_buffer[2];
    return (int16_t)raw_data;
}

// Function to scale raw data to physical units
void scale_data(int16_t raw_data, float *scaled_value, float scale_factor) {
    *scaled_value = (float)raw_data * scale_factor;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t raw_gyro_x = read_adis16448(X_GYRO_OUT);
        int16_t raw_gyro_y = read_adis16448(Y_GYRO_OUT);
        int16_t raw_gyro_z = read_adis16448(Z_GYRO_OUT);

        // Read accelerometer data
        int16_t raw_accel_x = read_adis16448(X_ACCL_OUT);
        int16_t raw_accel_y = read_adis16448(Y_ACCL_OUT);
        int16_t raw_accel_z = read_adis16448(Z_ACCL_OUT);

        // Scale the data
        float gyro_x = 0.0;
        float gyro_y = 0.0;
        float gyro_z = 0.0;
        float accel_x = 0.0;
        float accel_y = 0.0;
        float accel_z = 0.0;

        scale_data(raw_gyro_x, &gyro_x, 0.05);
        scale_data(raw_gyro_y, &gyro_y, 0.05);
        scale_data(raw_gyro_z, &gyro_z, 0.05);
        scale_data(raw_accel_x, &accel_x, 0.00025);
        scale_data(raw_accel_y, &accel_y, 0.00025);
        scale_data(raw_accel_z, &accel_z, 0.00025);

        // Print the data
        printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s, Accel X: %.2f g, Accel Y: %.2f g, Accel Z: %.2f g\n",
               gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 us
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

