#include <stdint.h>
#include <errno.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int fd, uint8_t reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = ioctl(fd, I2C_SLAVE, MPU6886_ADDR);
        if (result < 0) {
            perror("Failed to set I2C slave address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        result = write(fd, &reg, 1);
        if (result != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        uint8_t value;
        result = read(fd, &value, 1);
        if (result != 1) {
            perror("Failed to read register value");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        return value;
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    int retries = 3;
    int result;

    while (retries > 0) {
        result = ioctl(fd, I2C_SLAVE, MPU6886_ADDR);
        if (result < 0) {
            perror("Failed to set I2C slave address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        result = write(fd, buf, 2);
        if (result != 2) {
            perror("Failed to write to register");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        return 0; // Indicate success
    }

    fprintf(stderr, "Failed to write to register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to read 16-bit data from two consecutive I2C registers
int16_t read_word(int fd, uint8_t reg) {
    int retries = 3;
    int result;
    uint8_t buffer[2];

    while (retries > 0) {
        result = ioctl(fd, I2C_SLAVE, MPU6886_ADDR);
        if (result < 0) {
            perror("Failed to set I2C slave address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        result = write(fd, &reg, 1);
        if (result != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        result = read(fd, buffer, 2);
        if (result != 2) {
            perror("Failed to read word");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        return (int16_t)((buffer[0] << 8) | buffer[1]);
    }

    fprintf(stderr, "Failed to read word from register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C bus 1 on Raspberry Pi

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_fd, 0x75);
    if (who_am_i != 0x86) {
        fprintf(stderr, "MPU-6886 not found. WHO_AM_I register returned 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }
    printf("MPU-6886 found!\n");

    // Wake up the sensor
    if (write_register(i2c_fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        close(i2c_fd);
        return 1;
    }
    usleep(10000); // Wait for sensor to wake up

    // Configure accelerometer and gyroscope
    if (write_register(i2c_fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure accelerometer\n");
        close(i2c_fd);
        return 1;
    }
    if (write_register(i2c_fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure gyroscope\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        int16_t accel_x = read_word(i2c_fd, ACCEL_XOUT_H);
        int16_t accel_y = read_word(i2c_fd, ACCEL_XOUT_H + 2);
        int16_t accel_z = read_word(i2c_fd, ACCEL_XOUT_H + 4);

        // Read gyroscope data
        int16_t gyro_x = read_word(i2c_fd, GYRO_XOUT_H);
        int16_t gyro_y = read_word(i2c_fd, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_word(i2c_fd, GYRO_XOUT_H + 4);

        // Print the raw data
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        usleep(50000); // 50ms delay
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
