int read_sensor_data(sensor_data_t *data) {
    char buf[14];

    // Read accelerometer and gyroscope data in one burst
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Error: Could not read sensor data\n");
        return -1;
    }

