#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define OUT_X_MSB 0x01
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMPACT_THRESHOLD 2.0f
#define LED_ON_DURATION_MS 500

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int mma8451q_init(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
  uint8_t buf[1];
  buf[0] = reg;
  if (write(fd, buf, 1) != 1) {
    perror("I2C write (read reg) failed");
    return -1;
  }
  if (read(fd, buf, 1) != 1) {
    perror("I2C read failed");
    return -1;
  }
  return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    perror("I2C write failed");
    return -1;
  }
  return 0;
}

// MMA8451Q initialization function
int mma8451q_init(int fd) {
  // Check WHO_AM_I register
  int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
  if (who_am_i != 0x1A) {
    fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x1A\n", who_am_i);
    return -1;
  }

  // Set to active mode, 800 Hz ODR
  if (i2c_write_reg(fd, CTRL_REG1, 0x01) != 0) {
    fprintf(stderr, "Error: Failed to set active mode\n");
    return -1;
  }

  return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
  uint8_t buf[6];
  buf[0] = OUT_X_MSB;

  if (write(fd, buf, 1) != 1) {
    perror("I2C write (read accel) failed");
    return -1;
  }

  if (read(fd, buf, 6) != 6) {
    perror("I2C read failed");
    return -1;
  }

  *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
  *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
  *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;

  return 0;
}

// Calculate magnitude function
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
  // Convert raw values to g units (assuming +-2g range, 1g = 1024 counts)
  float x_g = (float)x / 1024.0f;
  float y_g = (float)y / 1024.0f;
  float z_g = (float)z / 1024.0f;

  return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact function
void log_impact(int16_t x, int16_t y, int16_t z) {
  time_t now = time(NULL);
  struct tm *t = localtime(&now);
  char timestamp[64];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

  fprintf(log_file, "%s - Impact detected: X=%d, Y=%d, Z=%d\n", timestamp, x, y, z);
  fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
  fprintf(stderr, "Signal received, terminating...\n");
  terminate = 1;
}

int main() {
  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Open I2C bus
  i2c_fd = open("/dev/i2c-1", O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
    return 1;
  }

  // Initialize MMA8451Q
  if (mma8451q_init(i2c_fd) != 0) {
    fprintf(stderr, "MMA8451Q initialization failed\n");
    close(i2c_fd);
    return 1;
  }

  // Open GPIO chip
  gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
  if (!gpio_chip) {
    perror("Failed to open GPIO chip");
    close(i2c_fd);
    return 1;
  }

  // Open GPIO line
  gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
  if (!gpio_line) {
    perror("Failed to open GPIO line");
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    return 1;
  }

  // Request GPIO line for output
  struct gpiod_line_request_config config;
  memset(&config, 0, sizeof(config));
  config.consumer = "impact_detector";
  config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

  if (gpiod_line_request(gpio_line, &config, 0) != 0) {
    perror("Failed to request GPIO line for output");
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    return 1;
  }

  // Open log file
  log_file = fopen("impact_log.txt", "a");
  if (!log_file) {
    perror("Failed to open log file");
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    return 1;
  }

  int16_t x, y, z;
  float magnitude;

  // Main loop
  while (!terminate) {
    if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
      magnitude = calculate_magnitude(x, y, z);

      if (magnitude > IMPACT_THRESHOLD) {
        printf("Impact detected! Magnitude: %.2f g\n", magnitude);
        log_impact(x, y, z);

        // Turn on LED
        struct gpiod_line_request_config output_config;
        memset(&output_config, 0, sizeof(output_config));
        output_config.consumer = "impact_detector";
        output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(gpio_line, &output_config, 0) != 0) {
          perror("Failed to request GPIO line for output");
          terminate = 1; // Exit loop on error
          break;
        }

        gpiod_line_set_value(gpio_line, 1);
        usleep(LED_ON_DURATION_MS * 1000); // Sleep for LED_ON_DURATION_MS milliseconds
        gpiod_line_set_value(gpio_line, 0);

        gpiod_line_release(gpio_line);
        gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN); // Re-request line after release
        if (!gpio_line) {
          perror("Failed to re-open GPIO line");
          terminate = 1; // Exit loop on error
          break;
        }

      }
    } else {
      fprintf(stderr, "Failed to read acceleration data\n");
      terminate = 1; // Exit loop on error
      break;
    }

    usleep(100000); // Sleep for 100 milliseconds
  }

  // Cleanup
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  if (gpio_chip != NULL) {
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
  }
  if (log_file != NULL) {
    fclose(log_file);
  }

  return 0;
}

