#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define TMAG5273_ADDR 0x35
#define X_REG 0x10
#define Y_REG 0x11
#define Z_REG 0x12

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

int16_t read_magnetic_field(int reg) {
    uint8_t buf[2];
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read magnetic field data");
        return -1;
    }
    return (int16_t)((buf[1] << 8) | buf[0]);
}

int main() {
    struct timespec ts;
    int16_t x, y, z;
    char timestamp[30];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("magnetic_field_log.csv", "a+");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fseek(log_file, 0, SEEK_END);

    while (keep_running) {
        x = read_magnetic_field(X_REG);
        y = read_magnetic_field(Y_REG);
        z = read_magnetic_field(Z_REG);

        if (x == -1 || y == -1 || z == -1) {
            fprintf(stderr, "Error reading magnetic field data. Retrying...\n");
            nanosleep(&(struct timespec){0, 100000000}, NULL); // 100ms delay
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
        fprintf(log_file, "%s.%09ld,%d,%d,%d\n", timestamp, ts.tv_nsec, x, y, z);
        fflush(log_file);

        nanosleep(&(struct timespec){1, 0}, NULL); // 1 second delay
    }

    if (i2c_fd != -1) close(i2c_fd);
    if (log_file != NULL) fclose(log_file);

    return 0;
}

