#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20
#define ADXL345_REG_DEVID 0x00

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Freefall threshold (300mg)
#define FREEFALL_THRESHOLD 300

// Freefall time (100ms)
#define FREEFALL_TIME 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int adxl345_init(int fd);
int gpio_request_line(struct gpiod_chip *chip, int gpio, struct gpiod_line **line, const char *consumer);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_get_value(struct gpiod_line *line);
int gpio_set_edge(struct gpiod_line *line, enum gpiod_line_event event);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    uint8_t devid;

    // Verify device ID
    if (i2c_read_reg(fd, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set THRESH_FF (300mg)
    if (i2c_write_reg(fd, ADXL345_REG_THRESH_FF, FREEFALL_THRESHOLD / 2) != 0) {
        fprintf(stderr, "Error setting THRESH_FF\n");
        return -1;
    }

    // Set TIME_FF (100ms)
    if (i2c_write_reg(fd, ADXL345_REG_TIME_FF, FREEFALL_TIME / 10) != 0) {
        fprintf(stderr, "Error setting TIME_FF\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_write_reg(fd, ADXL345_REG_INT_ENABLE, 0x02) != 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2c_write_reg(fd, ADXL345_REG_INT_MAP, 0x00) != 0) {
        fprintf(stderr, "Error mapping freefall interrupt\n");
        return -1;
    }

    // Enter measurement mode
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error entering measurement mode\n");
        return -1;
    }

    return 0;
}

// GPIO request line function
int gpio_request_line(struct gpiod_chip *chip, int gpio, struct gpiod_line **line, const char *consumer) {
    *line = gpiod_chip_get_line(chip, gpio);
    if (!*line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request(*line, *line, GPIOD_LINE_REQUEST_DIRECTION_INPUT, consumer) < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// GPIO get value function
int gpio_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Failed to get GPIO value");
        return -1;
    }
    return value;
}

// GPIO set edge function
int gpio_set_edge(struct gpiod_line *line, enum gpiod_line_event event) {
    if (gpiod_line_request_rising_edge(line, event) < 0) {
        perror("Failed to request rising edge");
        return -1;
    }
    return 0;
}

// Log data function
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line
    if (gpio_request_line(gpio_chip, INTERRUPT_GPIO, &gpio_line, "freefall_logger") != 0) {
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");
    fflush(log_file);

    // Enable interrupt
    if (gpio_set_value(gpio_line, 1) != 0) {
        fprintf(stderr, "Failed to enable interrupt\n");
        fclose(log_file);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Wait for interrupt
        if (gpio_get_value(gpio_line) == 0) {
            // Read interrupt source
            uint8_t int_source;
            if (i2c_read_reg(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) != 0) {
                fprintf(stderr, "Failed to read interrupt source\n");
                break;
            }

            // Check for freefall interrupt
            if (int_source & 0x04) {
                // Read acceleration data
                uint8_t data[6];
                if (read(i2c_fd, data, 6) != 6) {
                    perror("Failed to read acceleration data");
                    break;
                }

                // Combine high and low bytes
                int16_t x = (int16_t)((data[1] << 8) | data[0]);
                int16_t y = (int16_t)((data[3] << 8) | data[2]);
                int16_t z = (int16_t)((data[5] << 8) | data[4]);

                // Log data
                log_data(log_file, x, y, z);
            }

            // Clear interrupt
            if (i2c_write_reg(i2c_fd, ADXL345_REG_INT_SOURCE, 0x04) != 0) {
                fprintf(stderr, "Failed to clear interrupt\n");
                break;
            }
        }

        nanosleep(&sleep_time, NULL);
    }

    // Disable interrupt
    if (gpio_set_value(gpio_line, 0) != 0) {
        fprintf(stderr, "Failed to disable interrupt\n");
    }

    // Close I2C bus
    close(i2c_fd);

    // Release GPIO line
    gpiod_line_release(gpio_line);

    // Close GPIO chip
    gpiod_chip_close(gpio_chip);

    // Close log file
    fclose(log_file);

    return 0;
}

