#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Scaling factors
#define ACCEL_SCALE 0.061  // +/- 2g, 0.061 mg/LSB
#define GYRO_SCALE 8.75   // +/- 250 dps, 8.75 mdps/LSB

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5   // g
#define TIME_WINDOW 1.0       // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data, const char *state);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize LSM6DSR
int init_lsm6dsr() {
    // Configure accelerometer: +/- 2g, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 104 Hz, +/- 2g
        fprintf(stderr, "Failed to write to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +/- 250 dps, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 104 Hz, +/- 250 dps
        fprintf(stderr, "Failed to write to CTRL2_G\n");
        return -1;
    }

    // Verify WHO_AM_I register (should return 0x69)
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F); // WHO_AM_I register
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x69\n", who_am_i);
        return -1;
    }

    return 0;
}

// Read sensor data from LSM6DSR
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];

    // Read accelerometer data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    // Read gyroscope data (6 bytes)
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer + 6, 6) < 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return -1;
    }

    // Convert raw data to physical units
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    data->accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0f; // Convert to g
    data->accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0f;
    data->accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0f;

    data->gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0f;   // Convert to dps
    data->gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0f;
    data->gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log data to file
void log_data(sensor_data_t data, const char *state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%s\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z, state);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(sensor_data_t data) {
    static float acceleration_magnitude = 0.0f;
    static time_t freefall_start_time = 0;
    static int impact_detected = 0;
    static time_t impact_end_time = 0;
    static int freefall = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT

    float magnitude = calculate_acceleration_magnitude(data);

    switch (freefall) {
        case 0: // IDLE
            if (magnitude < FREEFALL_THRESHOLD) {
                freefall = 1;
                freefall_start_time = time(NULL);
                printf("Freefall detected\n");
            }
            break;
        case 1: // FREEFALL
            if (magnitude > FREEFALL_THRESHOLD) {
                freefall = 0;
                printf("Freefall ended\n");
            } else {
                if (difftime(time(NULL), freefall_start_time) >= TIME_WINDOW) {
                    freefall = 2;
                    impact_detected = 0;
                    impact_end_time = time(NULL);
                    printf("Impact detected\n");
                }
            }
            break;
        case 2: // IMPACT
            if (magnitude > IMPACT_THRESHOLD) {
                freefall = 0;
                printf("Impact ended\n");
            }
            break;
    }

    if (freefall == 2 && impact_detected == 0) {
        log_data(data, "IMPACT");
        impact_detected = 1;
    } else if (freefall == 1 && impact_detected == 0) {
        log_data(data, "FREEFALL");
    } else if (freefall == 0 && impact_detected == 0) {
        log_data(data, "IDLE");
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z,State\n");

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Fall detection
            fall_detection(sensor_data);

            // Log data
            log_data(sensor_data, "IDLE"); // Always log as IDLE for now
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
        }

        gpioDelay(10); // 10 ms delay (approximately 100 Hz)
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

