#include <signal.h>
#include <string.h>

// ADIS16266 Register Addresses
#define X_GYRO_OUT 0x14
#define WHO_AM_I  0x02

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3       // CPOL=1, CPHA=1

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
float read_gyro_data(int handle);
void log_data(FILE *fp, float data);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for grouping SPI configuration
typedef struct {
    int channel;
    int speed;
    int mode;
} spi_config_t;


int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        float gyro_data = read_gyro_data(spi_handle);
        if (gyro_data != -1000.0) { // Error code for read_gyro_data
            log_data(log_file, gyro_data);
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }
        gpioDelay(10000); // 10 ms delay
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = spi_read_register(spi_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x3F5A\n", who_am_i);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "Timestamp,Angular Rate (deg/s)\n");
    fflush(log_file);

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int spi_read_register(int handle, uint8_t reg) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for read
    tx_buf[1] = 0x00;       // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    return ((int)rx_buf[0] << 8) | (int)rx_buf[1];
}

int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = value;

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write failed: %d\n", result);
        return -1;
    }

    return 0;
}

float read_gyro_data(int handle) {
    int raw_data = spi_read_register(handle, X_GYRO_OUT);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
        return -1000.0; // Indicate an error
    }
    return (float)((int16_t)raw_data) * 0.0305;
}

void log_data(FILE *fp, float data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f\n", timestamp, data);
    fflush(fp);
}

