#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define GYRO_ADDRESS 0x69

// Define the register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Define the WHO_AM_I register value
#define WHO_AM_I_VALUE 0xD3

// Define the sensitivity factor
#define SENSITIVITY 8.75

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
int read_gyro_data(gyro_data_t *data);
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the gyroscope
int initialize_gyro() {
    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x0F);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0xD3, got 0x%X\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure the gyroscope
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        i2cClose(i2c_handle);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        i2cClose(i2c_handle);
        return -1;
    }

    printf("Gyroscope initialized successfully\n");
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buffer[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", bytes_read);
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to degrees per second
    data->x = (float)x / SENSITIVITY;
    data->y = (float)y / SENSITIVITY;
    data->z = (float)z / SENSITIVITY;

    return 0;
}

// Function to log data to a file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Format the timestamp
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    // Write the data to the file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize the gyroscope
    if (initialize_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Log the data
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Clean up resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

