#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", rc);
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_GPIO);
        if (sensor_value == PI_BAD_GPIO) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
            fprintf(log_file, "%s - ERROR: Invalid GPIO reading\n", buf);
            fflush(log_file);
        } else {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

            if (sensor_value == 0) {
                fprintf(log_file, "%s - Flame detected: YES\n", buf);
                printf("FLAME DETECTED!\n");
            } else {
                fprintf(log_file, "%s - Flame detected: NO\n", buf);
            }
            fflush(log_file);
        }

        gpioDelay(500000); // 500 ms
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

