#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define SAMPLE_INTERVAL_MS 100

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelerationData;

// Global variables for signal handling
volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_read_data(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_data(int fd, uint8_t reg_addr, uint8_t data);
AccelerationData read_acceleration_data(int fd);
char* get_iso8601_timestamp();
int log_data_to_csv(const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read function with error handling and retry
int i2c_read_data(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            return -1;
        }

        if (write(fd, &reg_addr, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", 4 - retries, strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retry
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure after retries
}

// I2C write function with error handling and retry
int i2c_write_data(int fd, uint8_t reg_addr, uint8_t data) {
    int retries = 3;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            return -1;
        }

        if (write(fd, &reg_addr, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        if (write(fd, &data, 1) != 1) {
            perror("Failed to write data");
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure after retries
}

// Function to read acceleration data from the sensor
AccelerationData read_acceleration_data(int fd) {
    uint8_t data[6];
    AccelerationData accel_data;

    if (i2c_read_data(fd, 0x28, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data.\n");
        accel_data.x = 0; // Set to default value in case of error
        accel_data.y = 0;
        accel_data.z = 0;
        return accel_data;
    }

    accel_data.x = (int16_t)((data[1] << 8) | data[0]);
    accel_data.y = (int16_t)((data[3] << 8) | data[2]);
    accel_data.z = (int16_t)((data[5] << 8) | data[4]);

    return accel_data;
}

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log data to a CSV file
int log_data_to_csv(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        keep_running = 0;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (keep_running) {
        AccelerationData accel_data = read_acceleration_data(i2c_fd);
        char *timestamp = get_iso8601_timestamp();

        if (timestamp != NULL) {
            if (log_data_to_csv(timestamp, accel_data.x, accel_data.y, accel_data.z) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
            free(timestamp); // Free the allocated memory
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

