#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

static volatile int running = 1;

// Structure to hold sensor data
typedef struct {
    int sensor1_state;
    int sensor2_state;
    long long timestamp_ms;
} SensorData;

// Function to get current timestamp with millisecond precision
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

// Function to log sensor data to a file
int log_sensor_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%lld,%d,%d\n", data.timestamp_ms, data.sensor1_state, data.sensor2_state);
    fclose(fp);
    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    printf("Conveyor belt safety system started. Press Ctrl+C to exit.\n");

    while (running) {
        SensorData data;
        data.timestamp_ms = get_timestamp_ms();
        data.sensor1_state = gpioRead(SENSOR_1_GPIO);
        data.sensor2_state = gpioRead(SENSOR_2_GPIO);

        if (log_sensor_data(data) != 0) {
            fprintf(stderr, "Error logging sensor data\n");
        }

        // Check if both sensors are triggered (logic 1)
        if (data.sensor1_state == 1 && data.sensor2_state == 1) {
            printf("CONVEYOR HALTED!\n");
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

