#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01

#define PI 3.14159265359

int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }
    return 0;
}

int read_register(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(i2c_fd, value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }
    return 0;
}

int write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }
    return 0;
}

int verify_sensor() {
    uint8_t who_am_i;
    if (read_register(WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x2A\n", who_am_i);
        return -1;
    }
    return 0;
}

int configure_sensor() {
    if (write_register(CTRL_REG1, 0x01) < 0) return -1; // Active mode, 100Hz
    if (write_register(XYZ_DATA_CFG, 0x00) < 0) return -1; // +/- 2g range
    return 0;
}

int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    uint8_t reg = OUT_X_MSB;

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(i2c_fd, data, 6) != 6) {
        perror("Error reading acceleration data");
        return -1;
    }

    *x = ((int16_t)data[0] << 8 | data[1]) >> 4;
    *y = ((int16_t)data[2] << 8 | data[3]) >> 4;
    *z = ((int16_t)data[4] << 8 | data[5]) >> 4;

    return 0;
}

double calculate_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 4096.0; // Assuming +/- 2g range (2^11 = 2048)
    double y_g = (double)y / 4096.0;
    double z_g = (double)z / 4096.0;
    return atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180 / PI;
}

int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_i2c() < 0) {
        return 1;
    }

    if (verify_sensor() < 0) {
        close(i2c_fd);
        return 1;
    }

    if (configure_sensor() < 0) {
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    double angle;

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            angle = calculate_angle(x, y, z);
            if (fabs(angle) > 45.0) {
                log_data(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }
        usleep(10000); // 10 ms
    }

    fclose(log_file);
    close(i2c_fd);
    return 0;
}

