#include <errno.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG3 0x22
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F

// Calibration constants (example values, adjust as needed)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detection threshold (mG)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int lis3mdl_init(int fd);
int read_magnetic_data(int fd, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void metal_detection(float x, float y, float z);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return data;
}

// I2C block read function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// LIS3MDL initialization function
int lis3mdl_init(int fd) {
    int retries = 3;
    int who_am_i;

    while (retries > 0) {
        // Verify sensor presence
        who_am_i = i2c_read_byte(fd, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (who_am_i != 0x3D) {
            fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D. Check I2C connection.\n", who_am_i);
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure sensor for continuous conversion mode at 80 Hz ODR
        if (i2c_write_byte(fd, CTRL_REG1, 0x70) < 0) { // High-performance mode on all axes
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (i2c_write_byte(fd, CTRL_REG3, 0x00) < 0) { // Continuous conversion mode
            fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (i2c_write_byte(fd, CTRL_REG4, 0x0C) < 0) { // 80 Hz ODR
            fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        printf("LIS3MDL initialized successfully.\n");
        return 0; // Initialization successful
    }

    fprintf(stderr, "LIS3MDL initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read magnetic data and apply calibration
int read_magnetic_data(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_block(fd, OUT_X_L, data, 6) < 0) {
        fprintf(stderr, "Error reading magnetic data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((data[1] << 8) | data[0]);
    raw_y = (int16_t)((data[3] << 8) | data[2]);
    raw_z = (int16_t)((data[5] << 8) | data[4]);

    // Apply calibration offsets and scales
    *x = (float)raw_x * 0.146 + X_OFFSET; // Convert to mG
    *y = (float)raw_y * 0.146 + Y_OFFSET;
    *z = (float)raw_z * 0.146 + Z_OFFSET;

    return 0;
}

// Function to log data to file
void log_data(float x, float y, float z) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

// Function to detect metal based on magnetic field magnitude
void metal_detection(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        printf("Metal Detected! Magnitude: %.2f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    float x, y, z;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize LIS3MDL sensor
    if (lis3mdl_init(i2c_fd) < 0) {
        fprintf(stderr, "LIS3MDL initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        if (read_magnetic_data(i2c_fd, &x, &y, &z) == 0) {
            log_data(x, y, z);
            metal_detection(x, y, z);
        } else {
            fprintf(stderr, "Error reading magnetic data.\n");
        }

        usleep(100000); // 10 Hz sampling rate (100ms delay)
    }

    return 0;
}

