#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// ADXL354B Register Addresses
#define ADXL354B_RESET 0x1F
#define ADXL354B_POWER_CTL 0x2D
#define ADXL354B_STATUS 0x04
#define ADXL354B_XDATA 0x08
#define ADXL354B_YDATA 0x0B
#define ADXL354B_ZDATA 0x0E
#define ADXL354B_PARTID 0x01

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Sensitivity (3.9 microg/LSB)
#define SENSITIVITY 0.0000039

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_configure(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx[len + 1];
    char rx[len + 1];
    int i, result;

    tx[0] = reg | 0x80; // Set MSB for read
    for (i = 1; i <= len; i++) {
        tx[i] = 0x00; // Dummy data for reading
    }

    for (i = 0; i < 3; i++) {
        result = spiXfer(handle, tx, rx, len + 1);
        if (result == len + 1) {
            for (j = 0; j < len; j++) {
                data[j] = rx[j + 1];
            }
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1 ms before retry
        }
    }
    return -1; // Failure after retries
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx[2];
    char rx[2];
    int result;

    tx[0] = reg & 0x7F; // Clear MSB for write
    tx[1] = data;

