#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// ADIS16362 Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05 // deg/sec/LSB
#define ACCL_SCALE 0.0025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function prototypes
int read_register(int reg_addr, int *data);
imu_data_t process_data(int raw_gyro_x, int raw_gyro_y, int raw_gyro_z, int raw_accel_x, int raw_accel_y, int raw_accel_z);
void log_data(imu_data_t data);
void signal_handler(int signal);

// Function to read a register from the ADIS16362
int read_register(int reg_addr, int *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0; // Indicate success
}

// Function to process raw data and convert to physical units
imu_data_t process_data(int raw_gyro_x, int raw_gyro_y, int raw_gyro_z, int raw_accel_x, int raw_accel_y, int raw_accel_z) {
    imu_data_t data;

    data.x_gyro = (float)raw_gyro_x * GYRO_SCALE;
    data.y_gyro = (float)raw_gyro_y * GYRO_SCALE;
    data.z_gyro = (float)raw_gyro_z * GYRO_SCALE;
    data.x_accel = (float)raw_accel_x * ACCL_SCALE;
    data.y_accel = (float)raw_accel_y * ACCL_SCALE;
    data.z_accel = (float)raw_accel_z * ACCL_SCALE;

    return data;
}

// Function to log data to a file
void log_data(imu_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    long timestamp_ns = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(log_file, "%ld,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp_ns,
            data.x_gyro,
            data.y_gyro,
            data.z_gyro,
            data.x_accel,
            data.y_accel,
            data.z_accel);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

        // Read gyroscope data
        if (read_register(X_GYRO, &raw_gyro_x) != 0) {
            fprintf(stderr, "Error reading X_GYRO, skipping...\n");
            continue;
        }
        if (read_register(Y_GYRO, &raw_gyro_y) != 0) {
            fprintf(stderr, "Error reading Y_GYRO, skipping...\n");
            continue;
        }
        if (read_register(Z_GYRO, &raw_gyro_z) != 0) {
            fprintf(stderr, "Error reading Z_GYRO, skipping...\n");
            continue;
        }

        // Read accelerometer data
        if (read_register(X_ACCL, &raw_accel_x) != 0) {
            fprintf(stderr, "Error reading X_ACCL, skipping...\n");
            continue;
        }
        if (read_register(Y_ACCL, &raw_accel_y) != 0) {
            fprintf(stderr, "Error reading Y_ACCL, skipping...\n");
            continue;
        }
        if (read_register(Z_ACCL, &raw_accel_z) != 0) {
            fprintf(stderr, "Error reading Z_ACCL, skipping...\n");
            continue;
        }

        // Process data
        imu_data_t imu_data = process_data(raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z);

        // Log data
        log_data(imu_data);

        // Delay for approximately 100 Hz
        gpioDelay(10000); // 10 ms delay (10000 microseconds)
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

