#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void sigint_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log messages with timestamps
void log_message(const char *message)
{
    char *timestamp = get_timestamp();
    printf("[%s] %s\n", timestamp, message);
}

// Function to simulate the self-parking sequence
void self_parking_sequence()
{
    log_message("Self-parking sequence started");
    log_message("Obstacle detected, initiating parking sequence...");
    log_message("Aligning vehicle...");
    log_message("Slowing down...");
    log_message("Stopping...");
    log_message("Engaging reverse gear...");
    log_message("Moving backward...");
    log_message("Stopping...");
    log_message("Engaging park lock...");
    log_message("Self-parking sequence completed");
}

int main()
{
    int ret;

    // Register signal handler for SIGINT
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line for input
    ret = gpiod_line_request_input(line, "self-parking");
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_message("Self-parking system started");

    // Main loop
    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        if (value == 0) { // Obstacle detected (LOW)
            log_message("Obstacle detected!");
            self_parking_sequence();
        }

        sleep(1); // Poll every 1 second
    }

    // Clean up
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    log_message("Self-parking system stopped");

    return EXIT_SUCCESS;
}

