#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int sensor1_value, sensor2_value;
    time_t current_time;
    struct tm *time_info;
    char time_string[50];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Collision avoidance system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor values
        sensor1_value = gpioRead(SENSOR1_GPIO);
        sensor2_value = gpioRead(SENSOR2_GPIO);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Log sensor data with timestamp
        printf("[%s] Sensor 1: %d, Sensor 2: %d\n", time_string, sensor1_value, sensor2_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Clean up GPIO resources
    gpioTerminate();

    printf("Collision avoidance system terminated.\n");
    return 0;
}

