#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// ADIS16266 Register Addresses
#define ADIS16266_XGYRO_OUT 0x04
#define ADIS16266_YGYRO_OUT 0x06
#define ADIS16266_ZGYRO_OUT 0x08
#define ADIS16266_MSC_CTRL  0x24

// SPI Device and CS Pin
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8 // GPIO8 (CE0)

// SPI Mode and Speed
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz

// Scale Factor
#define SCALE_FACTOR 0.02f // deg/sec/LSB

// Global Variables
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_init(void);
int gpio_init(void);
void cs_set_low(void);
void cs_set_high(void);
int spi_transfer(uint8_t address, uint8_t *data, int len);
int16_t read_gyro_data(uint8_t address);
float convert_to_angular_rate(int16_t raw_data);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold gyroscope data
typedef struct {
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;


int main(void) {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("ADIS16266 Gyroscope Reader\n");

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        int16_t raw_x_rate = read_gyro_data(ADIS16266_XGYRO_OUT);
        int16_t raw_y_rate = read_gyro_data(ADIS16266_YGYRO_OUT);
        int16_t raw_z_rate = read_gyro_data(ADIS16266_ZGYRO_OUT);

        // Convert to angular rates
        float x_rate = convert_to_angular_rate(raw_x_rate);
        float y_rate = convert_to_angular_rate(raw_y_rate);
        float z_rate = convert_to_angular_rate(raw_z_rate);

        // Print the data
        printf("X: %.3f deg/s, Y: %.3f deg/s, Z: %.3f deg/s\n", x_rate, y_rate, z_rate);

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

// SPI Initialization Function
int spi_init(void) {
    int ret;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization Function
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get CS line
    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request CS line for output
    ret = gpiod_line_request_output(cs_line, "gyro_reader", 1); // Initial value high
    if (ret < 0) {
        perror("Error requesting CS line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set CS high initially
    gpiod_line_set_value(cs_line, 1);

    return 0;
}

// CS Line Control Functions
void cs_set_low(void) {
    gpiod_line_set_value(cs_line, 0);
}

void cs_set_high(void) {
    gpiod_line_set_value(cs_line, 1);
}

// SPI Transfer Function
int spi_transfer(uint8_t address, uint8_t *data, int len) {
    uint8_t tx_buf[len + 1];
    uint8_t rx_buf[len + 1];
    struct spi_ioc_transfer tr;

    // Prepare transmit buffer
    tx_buf[0] = address | 0x80; // Set MSB for read
    for (int i = 0; i < len; i++) {
        tx_buf[i + 1] = data[i];
    }

    // Prepare SPI transfer structure
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = len + 1;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error performing SPI transfer");
        return -1;
    }

    // Copy received data to output buffer
    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// Read Gyroscope Data Function
int16_t read_gyro_data(uint8_t address) {
    uint8_t data[2];

    // Set CS low
    cs_set_low();

    // Perform SPI transfer
    if (spi_transfer(address, data, 2) < 0) {
        fprintf(stderr, "Error reading gyro data from address 0x%02X\n", address);
        cs_set_high();
        return 0; // Return 0 on error
    }

    // Set CS high
    cs_set_high();

    // Combine the two bytes into a 16-bit value
    int16_t raw_data = (int16_t)((data[0] << 8) | data[1]);

    return raw_data;
}

// Convert to Angular Rate Function
float convert_to_angular_rate(int16_t raw_data) {
    return (float)raw_data * SCALE_FACTOR;
}

// Signal Handler Function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup Function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
    }
}

