// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 registers
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the FXOS8700 sensor
int init_sensor(int handle) {
    // Verify sensor presence
    int who_am_i = read_register(handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0xC7) {
        fprintf(stderr, "Error: FXOS8700 not found or communication error (WHO_AM_I = 0x%02X)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer and magnetometer
    if (write_register(handle, FXOS8700_CTRL_REG1, 0x01) < 0) return -1; // Active mode, 100 Hz
    if (write_register(handle, FXOS8700_CTRL_REG2, 0x02) < 0) return -1; // High resolution
    if (write_register(handle, FXOS8700_M_CTRL_REG1, 0x1F) < 0) return -1; // Hybrid mode, OSR = 1
    if (write_register(handle, FXOS8700_M_CTRL_REG2, 0x20) < 0) return -1; // Hybrid mode, OSR = 1

    return 0;
}

// Function to read accelerometer and magnetometer data
int read_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result = i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Extract accelerometer data (14-bit, left-aligned)
    *accel_x = ((int16_t)buffer[0] << 6) | (buffer[1] >> 2);
    *accel_y = ((int16_t)buffer[2] << 6) | (buffer[3] >> 2);
    *accel_z = ((int16_t)buffer[4] << 6) | (buffer[5] >> 2);

    // Extract magnetometer data (16-bit)
    *mag_x = ((int16_t)buffer[6] << 8) | buffer[7];
    *mag_y = ((int16_t)buffer[8] << 8) | buffer[9];
    *mag_z = ((int16_t)buffer[10] << 8) | buffer[11];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    while (!terminate) {
        // Read sensor data
        if (read_data(i2c_handle, &accel_x, &accel_y, &accel_z, &mag_x, &mag_y, &mag_z) == 0) {
            // Print the raw data
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Mag: X=%6d, Y=%6d, Z=%6d\n", accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

