#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

#define THRESHOLD 30.0
#define I2C_BUS "/dev/i2c-1"

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

int i2c_read_register(int fd, unsigned char reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    unsigned char value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return value;
}

int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

int read_acceleration_data(int fd, short *x, short *y, short *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = i2c_read_register(fd, DATAX0);
    x1 = i2c_read_register(fd, DATAX1);
    y0 = i2c_read_register(fd, DATAY0);
    y1 = i2c_read_register(fd, DATAY1);
    z0 = i2c_read_register(fd, DATAZ0);
    z1 = i2c_read_register(fd, DATAZ1);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        fprintf(stderr, "Error reading acceleration data.\n");
        return -1;
    }

    *x = (short)((x1 << 8) | x0);
    *y = (short)((y1 << 8) | y0);
    *z = (short)((z1 << 8) | z0);

    return 0;
}

void calculate_tilt_angles(short x, short y, short z, float *roll, float *pitch) {
    *roll = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
    *pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;
}

int log_event(float roll, float pitch) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
