                printf("Tilt event: Roll=%.2f, Pitch=%.2f\n", roll, pitch);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        usleep(100000); // 100 ms
    }

    if (i2c_write_register(i2c_fd, POWER_CTL, 0x00) < 0) { // Disable measurement mode
        fprintf(stderr, "Failed to disable measurement mode.\n");
    }

    close(i2c_fd);
    return 0;
}

