#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define WINDOW_SIZE_US 5000000  // 5 seconds
#define DEFAULT_THRESHOLD 10

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

int count_high_readings(int gpio_pin, int sample_interval_us, int window_size_us) {
    int count = 0;
    long start_time = time_time();
    while (time_time() - start_time < window_size_us) {
        if (read_sensor(gpio_pin) == 1) {
            count++;
        }
        gpioDelay(sample_interval_us);
    }
    return count;
}

int validate_threshold(int threshold) {
    if (threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 0;
    }
    return 1;
}

void print_status(int high_reading_count, int threshold) {
    if (high_reading_count > threshold) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s ALERT: High-reading count exceeded threshold (%d > %d)\n", timestamp, high_reading_count, threshold);
    } else {
        printf("Normal: High-reading count (%d) below threshold (%d)\n", high_reading_count, threshold);
    }
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;

    if (argc > 1) {
        char *endptr;
        threshold = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || threshold <= 0) {
            fprintf(stderr, "Error: Invalid threshold value. Using default value (%d).\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    if (!validate_threshold(threshold)) {
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int high_reading_count = count_high_readings(GPIO_PIN, SAMPLE_INTERVAL_US, WINDOW_SIZE_US);
        print_status(high_reading_count, threshold);
        gpioDelay(1000000); // 1 second pause
    }

    gpioTerminate();
    return 0;
}

