#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27
#define RANDOM_CODE_LENGTH 6
#define ACCESS_LOG_FILE "access_log.txt"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    gpioWrite(DOOR_A_GPIO, 0); // Initialize to LOW (locked)
    gpioWrite(DOOR_B_GPIO, 0);

    return 0;
}

int generate_random_code() {
    int code = rand() % 1000000 + 100000; // Generates a number between 100000 and 999999
    return code;
}

int validate_code(const char *input) {
    if (strlen(input) != RANDOM_CODE_LENGTH) {
        return 0;
    }

    for (int i = 0; i < RANDOM_CODE_LENGTH; i++) {
        if (input[i] < '0' || input[i] > '9') {
            return 0;
        }
    }

    return 1;
}

int unlock_door(int gpio) {
    gpioWrite(gpio, 1); // HIGH to unlock
    gpioDelay(5000);    // 5 seconds
    gpioWrite(gpio, 0); // LOW to lock
    return 0;
}

int log_access(int code) {
    FILE *fp = fopen(ACCESS_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, code);
    fclose(fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    int random_code = generate_random_code();
    printf("Generated random code: %d\n", random_code);

    while (!terminate) {
        char input[RANDOM_CODE_LENGTH + 1];
        printf("Enter the 6-digit security code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Error reading input. Clearing buffer...\n");
            fflush(stdin);
            continue;
        }

        input[strcspn(input, "\n")] = 0; // Remove trailing newline

        if (validate_code(input)) {
            if (atoi(input) == random_code) {
                printf("Access granted!\n");
                unlock_door(DOOR_A_GPIO);
                log_access(random_code);
                srand(time(NULL)); // Seed random for a new code
                random_code = generate_random_code();
                printf("New code: %d\n", random_code);
            } else {
                printf("Access denied!\n");
            }
        } else {
            printf("Invalid input. Please enter a 6-digit number.\n");
        }
    }

    gpioWrite(DOOR_A_GPIO, 0);
    gpioWrite(DOOR_B_GPIO, 0);
    gpioTerminate();

    return 0;
}

