// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define SERVER_PORT 12345
#define BUFFER_SIZE 1024
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_data(unsigned short *touch_data);
float map_touch_to_frequency(unsigned short touch_data);
void generate_pwm_signal(float frequency);
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize MPR121
int init_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure electrode sensitivity and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0F) < 0) { // Touch threshold
            fprintf(stderr, "Error: Setting touch threshold failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Setting release threshold failed for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter settings (example values)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // MHD_R
        fprintf(stderr, "Error: Setting MHD_R failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { // NHD_R
        fprintf(stderr, "Error: Setting NHD_R failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { // NCL_R
        fprintf(stderr, "Error: Setting NCL_R failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // FDL_R
        fprintf(stderr, "Error: Setting FDL_R failed\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x2F, 0x01) < 0) { // MHD_T
        fprintf(stderr, "Error: Setting MHD_T failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) { // NHD_T
        fprintf(stderr, "Error: Setting NHD_T failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x31, 0x00) < 0) { // NCL_T
        fprintf(stderr, "Error: Setting NCL_T failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x32, 0x00) < 0) { // FDL_T
        fprintf(stderr, "Error: Setting FDL_T failed\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x8F) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Enabling electrodes failed\n");
        return -1;
    }

    return 0;
}

// Read touch data from MPR121
int read_touch_data(unsigned short *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = ((unsigned short)buf[1] << 8) | (unsigned short)buf[0];
    return 0;
}

// Map touch data to frequency (logarithmic scale)
float map_touch_to_frequency(unsigned short touch_data) {
    // Find the maximum electrode value
    unsigned short max_value = 0;
    for (int i = 0; i < 12; i++) {
        if (touch_data & (1 << i)) {
            max_value = i;
            break;
        }
    }

    // Map the maximum value to a frequency in the range 220-880 Hz
    float frequency = 220.0 * pow(2.0, (float)max_value / 11.0); // Logarithmic scale
    return frequency;
}

// Generate PWM signal
void generate_pwm_signal(float frequency) {
    int range = 1000000 / (int)frequency; // Calculate PWM range
    gpioSetPWMrange(PWM_GPIO, range);
    gpioPWM(PWM_GPIO, range / 2); // 50% duty cycle
}

