void log_frequency(float frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file);
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        if (strncmp(buffer, "MOTION_DETECTED:", 17) == 0) {
            // Check for shared secret
            if (strstr(buffer, "MySecretKey") != NULL) {
                printf("Shared secret found, playing theremin...\n");

                // Open log file
                log_file = fopen(LOG_FILE, "a");
                if (log_file == NULL) {
                    perror("Error opening log file");
                    close(client_socket);
                    return;
                }

                // Play theremin for 5 seconds
                for (int i = 0; i < 50 && !terminate; i++) {
                    unsigned short touch_data;
                    if (read_touch_data(&touch_data) == 0) {
                        float frequency = map_touch_to_frequency(touch_data);
                        generate_pwm_signal(frequency);
                        log_frequency(frequency);
                    } else {
                        fprintf(stderr, "Error reading touch data, stopping PWM\n");
                        gpioPWM(PWM_GPIO, 0); // Stop PWM
                        break;
                    }
                    gpioDelay(20000); // 20ms delay
                }

                // Stop PWM and close log file
                gpioPWM(PWM_GPIO, 0);
                fclose(log_file);

                printf("Theremin playback complete.\n");
            } else {
                fprintf(stderr, "Incorrect shared secret\n");
            }
        }
    }

    if (bytes_received < 0) {
        perror("Error receiving data");
    }

    printf("Client disconnected.\n");
    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM GPIO
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, 440); // Initial frequency
    gpioSetPWMrange(PWM_GPIO, 1000000); // Initial range
    gpioPWM(PWM_GPIO, 0); // Initially off

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Socket creation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d...\n", SERVER_PORT);

    // Accept connections and handle them
    while (!terminate) {
        int addrlen = sizeof(address);
        new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted.\n");
        handle_client(new_socket);
    }

    // Clean up
    close(server_fd);
    i2cClose(i2c_handle);
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    printf("Server shutdown complete.\n");
    return 0;
}

