#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LSM303DLHC_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define GPIO_PIN 17
#define PWM_PERIOD 1000000 // 1 ms

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(struct gpiod_line *line, float magnitude);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;
  if (write(fd, buf, 2) != 2) {
    perror("I2C write failed");
    return -1;
  }
  return 0;
}

// I2C read function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
  if (write(fd, &reg, 1) != 1) {
    perror("I2C write (register select) failed");
    return -1;
  }
  if (read(fd, data, len) != len) {
    perror("I2C read failed");
    return -1;
  }
  return 0;
}

// Magnetometer initialization function
int init_magnetometer(int fd) {
  if (i2c_write_byte(fd, CTRL_REG1_M, 0x18) != 0) {
    fprintf(stderr, "Failed to initialize magnetometer\n");
    return -1;
  }
  return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
  uint8_t data[6];
  if (i2c_read_block(fd, OUT_X_L_M, data, 6) != 0) {
    fprintf(stderr, "Failed to read magnetometer data\n");
    return -1;
  }

  *x = (int16_t)((data[1] << 8) | data[0]);
  *y = (int16_t)((data[3] << 8) | data[2]);
  *z = (int16_t)((data[5] << 8) | data[4]);

  return 0;
}

// Magnetic field magnitude calculation function
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
  return sqrt(x * x + y * y + z * z);
}

// LED brightness setting function using hardware PWM
int set_led_brightness(struct gpiod_line *line, float magnitude) {
  int duty_cycle = (int)((magnitude / 1000.0) * PWM_PERIOD); // Scale magnitude to 0-1000
  if (duty_cycle < 0) duty_cycle = 0;
  if (duty_cycle > PWM_PERIOD) duty_cycle = PWM_PERIOD;

  struct gpiod_line_request_config config;
  memset(&config, 0, sizeof(config));
  config.consumer = "led_pwm";
  config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

  if (gpiod_line_request(line, &config, 0) < 0) {
    perror("Failed to request GPIO line for output");
    return -1;
  }

  struct gpiod_line_value value;
  memset(&value, 0, sizeof(value));
  value.bits[0] = 1; // Set bit 0 to 1 for PWM

  // Generate PWM signal
  for (int i = 0; i < duty_cycle; i++) {
    if (gpiod_line_set_value(line, &value) < 0) {
