    if (gpiod_line_set_value(line, &value) < 0) {
      perror("Failed to set GPIO line value");
      return -1;
    }
    usleep(1); // Adjust delay for desired PWM frequency
  }

  if (gpiod_line_release(line) < 0) {
    perror("Failed to release GPIO line");
    return -1;
  }

  return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
  printf("Caught signal %d, cleaning up...\n", sig);
  if (i2c_fd != -1) {
    close(i2c_fd);
  }
  if (gpio_chip != NULL) {
    gpiod_chip_close(gpio_chip);
  }
  if (gpio_line != NULL) {
    gpiod_line_release(gpio_line);
  }
  exit(0);
}

