// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L registers
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Circular buffer for hard-iron offsets
float x_buffer[100];
float y_buffer[100];
float z_buffer[100];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z);
void print_offset_corrected_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the HMC5883L sensor
int init_hmc5883l() {
    // Configuration Register A: 8-sample averaging, 15 Hz output rate, gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configuration Register B: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode register\n");
        return -1;
    }

    return 0;
}

// Read raw magnetometer data from the HMC5883L
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update hard-iron offsets using a circular buffer
void update_hard_iron_offsets(int16_t x, int16_t y, int16_t z) {
    x_buffer[buffer_index] = (float)x;
    y_buffer[buffer_index] = (float)y;
    z_buffer[buffer_index] = (float)z;

    buffer_index = (buffer_index + 1) % 100;

    // Calculate running averages
    float x_sum = 0.0;
    float y_sum = 0.0;
    float z_sum = 0.0;

    for (int i = 0; i < 100; i++) {
        x_sum += x_buffer[i];
        y_sum += y_buffer[i];
        z_sum += z_buffer[i];
    }

    x_offset = x_sum / 100.0;
    y_offset = y_sum / 100.0;
    z_offset = z_sum / 100.0;
}

// Print offset-corrected data
void print_offset_corrected_data(int16_t x, int16_t y, int16_t z) {
    float x_corrected = (float)x - x_offset;
    float y_corrected = (float)y - y_offset;
    float z_corrected = (float)z - z_offset;

    printf("X: %d, Y: %d, Z: %d, X_corrected: %.2f, Y_corrected: %.2f, Z_corrected: %.2f\n", x, y, z, x_corrected, y_corrected, z_corrected);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L sensor
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        // Read raw magnetometer data
        if (read_hmc5883l(&x, &y, &z) == 0) {
            // Update hard-iron offsets
            update_hard_iron_offsets(x, y, z);

            // Print offset-corrected data
            print_offset_corrected_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

