#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D registers
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define INT1_CFG_A 0x30
#define OUT_X_L_A 0x28

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *gpio_line;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    int16_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t acc_buffer;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_lsm303d(int fd);
int init_gpio(void);
void cleanup(void);
void signal_handler(int sig);
void interrupt_handler(int gpio, int event, uint32_t pins);
void add_to_buffer(circular_buffer_t *buffer, int16_t value);
int16_t read_from_buffer(circular_buffer_t *buffer);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1; // Indicate error
    }
    return result;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// LSM303D initialization function
int init_lsm303d(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_reg(fd, 0x0F);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    if (i2c_write_reg(fd, CTRL_REG1_A, 0x57) != 0) return -1; // 50 Hz ODR, all axes enabled
    if (i2c_write_reg(fd, CTRL_REG4_A, 0x00) != 0) return -1;  // +-2g, sensitivity 0.061 mg/LSB
    if (i2c_write_reg(fd, INT1_CFG_A, 0x2A) != 0) return -1;  // any-axis-high interrupt

