// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, cleaning up and exiting...\n");
}

int main()
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Request GPIO pins
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial state to LOW (solenoids de-energized)
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Main loop
    while (!terminate)
    {
        // Energize solenoid 1
        gpioWrite(SOLENOID_1_PIN, 1);
        gpioWrite(SOLENOID_2_PIN, 0);
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500 ms

        // De-energize solenoid 1
        gpioWrite(SOLENOID_1_PIN, 0);

        // Energize solenoid 2
        gpioWrite(SOLENOID_2_PIN, 1);
        nanosleep((const struct timespec[]){{0, 500000000L}}, NULL); // 500 ms

        // De-energize solenoid 2
        gpioWrite(SOLENOID_2_PIN, 0);
    }

    // Cleanup: Ensure solenoids are de-energized before exiting
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

