#include <signal.h>
#include <time.h>

// Define GPIO pins for door locks
#define DOOR1_PIN 17
#define DOOR2_PIN 27

// Define UART ports
#define PRIMARY_UART "/dev/serial0"
#define SECONDARY_UART "/dev/serial1"

// Define expected 6-digit code
#define EXPECTED_CODE "123456"

// Define timeout in seconds
#define TIMEOUT_SECONDS 5

// Global variables
volatile sig_atomic_t terminate = 0;
int primary_fd = -1;
int secondary_fd = -1;

// Function prototypes
int init_gpio();
int init_uart(const char *device);
int read_serial(int fd, char *buffer, int max_len);
int validate_code(const char *code);
void unlock_doors();
void relock_doors();
void cleanup();
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DOOR1_PIN, PI_OUTPUT);
    gpioSetMode(DOOR2_PIN, PI_OUTPUT);

    gpioWrite(DOOR1_PIN, 0); // Initialize to LOW (locked)
    gpioWrite(DOOR2_PIN, 0);

    return 0;
}

// Initialize UART port
int init_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open UART %s\n", device);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Failed to get termios attributes for %s\n", device);
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        fprintf(stderr, "Failed to set baud rate for %s\n", device);
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Failed to set termios attributes for %s\n", device);
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from serial port with timeout
int read_serial(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SECONDS;
    timeout.tv_usec = 0;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        fprintf(stderr, "select() error\n");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout reading from serial port\n");
        return -1;
    } else {
        int bytes_read = read(fd, buffer, max_len - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            return bytes_read;
        } else {
            return -1; // Error or no data
        }
    }
}

// Validate the received code
int validate_code(const char *code) {
    if (strlen(code) != 6) {
        return 0;
    }

    for (int i = 0; i < 6; i++) {
        if (code[i] < '0' || code[i] > '9') {
            return 0;
        }
    }

    return 1;
}

// Unlock both doors
