    printf("Cleaning up resources...\n");
    if (primary_fd != -1) {
        close(primary_fd);
    }
    if (secondary_fd != -1) {
        close(secondary_fd);
    }
    gpioWrite(DOOR1_PIN, 0);
    gpioWrite(DOOR2_PIN, 0);
    gpioTerminate();
    printf("Cleanup complete\n");
}

