#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define STRIKE_DURATION_MS 1000
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static volatile sig_atomic_t terminate = 0;
static time_t last_motion_time = 0;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
void signal_handler(int sig);
int read_pir_sensor(void);
int control_relay(int state);
void log_event(const char *message);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        terminate = 1;
        log_event("Received shutdown signal. Cleaning up...");
    }
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    // Get PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR line as input
    ret = gpiod_line_request_input(pir_line, "pir_sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input: %s", gpiod_line_request_input_errmsg(ret));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get relay line");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request relay line as output
    ret = gpiod_line_request_output(relay_line, "relay", 0); // Initial state: LOW
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request relay line as output: %s", gpiod_line_request_output_errmsg(ret));
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    log_event("GPIO initialized successfully");
    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // Ensure relay is off
        gpiod_line_release(relay_line);
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    log_event("GPIO cleaned up");
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value: %s", gpiod_line_get_value_errmsg(value));
        return -1; // Indicate error
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set relay value: %s", gpiod_line_set_value_errmsg(ret));
        return -1; // Indicate error
    }
    return 0;
}

// Log events to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

int main(void) {
    int pir_value;
    time_t current_time;
    double time_diff;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open syslog
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Door strike system started");

    // Main loop
    while (!terminate) {
        pir_value = read_pir_sensor();
        if (pir_value < 0) {
            // Error reading PIR sensor, but continue running
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL); // Sleep for 100ms
            continue;
        }

        if (pir_value == 1) {
            // Motion detected
            log_event("Motion detected");

            // Activate relay
            if (control_relay(1) == 0) {
                log_event("Relay activated");

                // Wait for strike duration
                struct timespec strike_duration = {0, STRIKE_DURATION_MS * 1000000L};
                nanosleep(&strike_duration, NULL);

                // Deactivate relay
                if (control_relay(0) == 0) {
                    log_event("Relay deactivated");
                } else {
                    log_event("Failed to deactivate relay");
                }
            } else {
                log_event("Failed to activate relay");
            }

            // Update last motion time
            time(&last_motion_time);

            // Poll for failsafe timeout
            while (!terminate) {
                pir_value = read_pir_sensor();
                if (pir_value < 0) {
                    // Error reading PIR sensor, but continue running
                    nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = 100000000}, NULL); // Sleep for 100ms
                    break;
                }

                if (pir_value == 1) {
                    // Motion still detected
                    break;
                }

                nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = POLL_INTERVAL_MS * 1000000L}, NULL);

                time_t current_time_temp;
                time(&current_time_temp);
                time_t time_diff_temp = difftime(current_time_temp, last_motion_time);

                if (time_diff_temp > FAILSAFE_TIMEOUT_S) {
                    // Failsafe triggered
                    log_event("Failsafe triggered: PIR sensor HIGH for too long");

                    // Deactivate relay
                    if (control_relay(0) == 0) {
                        log_event("Relay deactivated due to failsafe");
                    } else {
                        log_event("Failed to deactivate relay due to failsafe");
                    }
                    break;
                }
            }
        } else {
            // No motion
            nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = POLL_INTERVAL_MS * 1000000L}, NULL);
        }
    }

    // Cleanup and exit
    log_event("Shutting down...");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

