void activate_relay(int relay_id);
void deactivate_relay(int relay_id);
void pause_system();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to activate a relay
void activate_relay(int relay_id) {
    int pin;

    switch (relay_id) {
        case RELAY1:
            pin = RELAY1_PIN;
            break;
        case RELAY2:
            pin = RELAY2_PIN;
            break;
        case RELAY3:
            pin = RELAY3_PIN;
            break;
        case RELAY4:
            pin = RELAY4_PIN;
            break;
        default:
            syslog(LOG_ERR, "Invalid relay ID: %d", relay_id);
            return;
    }

    if (gpioWrite(pin, RELAY_ON) != 0) {
        syslog(LOG_ERR, "Failed to activate relay %d (GPIO %d)", relay_id, pin);
        return;
    }
    syslog(LOG_INFO, "Activated relay %d (GPIO %d)", relay_id, pin);
    current_state = RELAY_ON;
}

