    deactivate_relay(RELAY2);
    deactivate_relay(RELAY3);
    deactivate_relay(RELAY4);

    // Main loop
    while (!terminate) {
        switch (current_state) {
            case RELAY_ON:
                activate_relay(current_relay);
                sleep(ACTIVATION_TIME);
                deactivate_relay(current_relay);
                current_relay++;
