#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Circular buffer size
#define BUFFER_SIZE 10

// Global variables
int i2c_fd = -1;
int running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t accel_buffer;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
int mpu6050_init(int fd);
int read_accel_data(int fd, float *x, float *y, float *z);
void add_to_buffer(circular_buffer_t *cb, float value);
float get_latest_data(circular_buffer_t *cb);
int export_sysfs_file(const char *filename);
int unexport_sysfs_file(const char *filename);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data function
int read_accel_data(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_regs(fd, ACCEL_XOUT_H, data, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes
    raw_x = (int16_t)((data[0] << 8) | data[1]);
    raw_y = (int16_t)((data[2] << 8) | data[3]);
    raw_z = (int16_t)((data[4] << 8) | data[5]);

    // Scale to g units
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get latest data from circular buffer
float get_latest_data(circular_buffer_t *cb) {
    if (cb->count == 0) {
        return 0.0f; // Return 0 if buffer is empty
    }
    int index = (cb->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[index];
}

// Export sysfs file
int export_sysfs_file(const char *filename) {
    FILE *fp = fopen("/sys/class/misc/misc_class/class_dev_attr", "w");
    if (!fp) {
        perror("Failed to open /sys/class/misc/misc_class/class_dev_attr");
        return -1;
    }
    fprintf(fp, "%s", filename);
    fclose(fp);
    return 0;
}

// Unexport sysfs file
int unexport_sysfs_file(const char *filename) {
    FILE *fp = fopen("/sys/class/misc/misc_class/class_dev_attr", "w");
    if (!fp) {
        perror("Failed to open /sys/class/misc/misc_class/class_dev_attr");
        return -1;
    }
    fprintf(fp, "%s", filename);
    fclose(fp);
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    running = 0;
}

int main() {
    // Initialize circular buffer
    accel_buffer.head = 0;
    accel_buffer.count = 0;
    memset(accel_buffer.buffer, 0, sizeof(accel_buffer.buffer));

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Export sysfs file
    if (export_sysfs_file("/sys/kernel/mpu6050_accel/latest") < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Timer setup (using SIGEV_SIGNAL for simplicity)
    struct sigevent sev;
    struct itimerspec its;

    // Configure the sigevent structure
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGUSR1; // Use SIGUSR1 for timer expiration
    sev.sigev_value.sival_ptr = &its;

    // Configure the itimerspec structure
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms (100 Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms

    // Create the timer
    if (timer_create(CLOCK_REALTIME, &sev, NULL) == -1) {
        perror("timer_create");
        close(i2c_fd);
        unexport_sysfs_file("/sys/kernel/mpu6050_accel/latest");
        return 1;
    }

    // Start the timer
    if (timer_settime(0, 0, &its, NULL) == -1) {
        perror("timer_settime");
        close(i2c_fd);
        unexport_sysfs_file("/sys/kernel/mpu6050_accel/latest");
        return 1;
    }

    float x, y, z;
    struct timespec ts;
    char timestamp[30];

    // Main loop
    while (running) {
        if (read_accel_data(i2c_fd, &x, &y, &z) == 0) {
            add_to_buffer(&accel_buffer, x);
            add_to_buffer(&accel_buffer, y);
            add_to_buffer(&accel_buffer, z);

            // Get latest data for sysfs
            float latest_x = get_latest_data(&accel_buffer);
            float latest_y = get_latest_data(&accel_buffer);
            float latest_z = get_latest_data(&accel_buffer);

            // Format timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

            // Write data to sysfs
            FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
            if (fp) {
                fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, latest_x, latest_y, latest_z);
                fclose(fp);
            } else {
                perror("Failed to open sysfs file for writing");
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        // Wait for the timer to expire (which will trigger SIGUSR1)
        pause(); // Wait for a signal
    }

    // Clean up
    timer_delete(0);
    close(i2c_fd);
    unexport_sysfs_file("/sys/kernel/mpu6050_accel/latest");

    return 0;
}

