    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Export sysfs file
    if (export_sysfs_file("/sys/kernel/mpu6050_accel/latest") < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Timer setup (using SIGEV_SIGNAL for simplicity)
    struct sigevent sev;
    struct itimerspec its;

    // Configure the sigevent structure
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGUSR1; // Use SIGUSR1 for timer expiration
    sev.sigev_value.sival_ptr = &its;

    // Configure the itimerspec structure
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms (100 Hz)
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms

    // Create the timer
    if (timer_create(CLOCK_REALTIME, &sev, NULL) == -1) {
        perror("timer_create");
        close(i2c_fd);
        unexport_sysfs_file("/sys/kernel/mpu6050_accel/latest");
        return 1;
    }

    // Start the timer
    if (timer_settime(0, 0, &its, NULL) == -1) {
        perror("timer_settime");
        close(i2c_fd);
        unexport_sysfs_file("/sys/kernel/mpu6050_accel/latest");
        return 1;
    }

    float x, y, z;
    struct timespec ts;
    char timestamp[30];

    // Main loop
    while (running) {
        if (read_accel_data(i2c_fd, &x, &y, &z) == 0) {
            add_to_buffer(&accel_buffer, x);
            add_to_buffer(&accel_buffer, y);
            add_to_buffer(&accel_buffer, z);

            // Get latest data for sysfs
            float latest_x = get_latest_data(&accel_buffer);
            float latest_y = get_latest_data(&accel_buffer);
            float latest_z = get_latest_data(&accel_buffer);

            // Format timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

            // Write data to sysfs
            FILE *fp = fopen("/sys/kernel/mpu6050_accel/latest", "w");
            if (fp) {
                fprintf(fp, "%s,%.4f,%.4f,%.4f\n", timestamp, latest_x, latest_y, latest_z);
                fclose(fp);
            } else {
                perror("Failed to open sysfs file for writing");
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data. Retrying...\n");
        }

        // Wait for the timer to expire (which will trigger SIGUSR1)
        pause(); // Wait for a signal
    }

    // Clean up
    timer_delete(0);
    close(i2c_fd);
    unexport_sysfs_file("/sys/kernel/mpu6050_accel/latest");

    return 0;
}

