// Define GPIO pins for the relays (BCM numbering)
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime number intervals for relay toggling (in seconds)
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int toggle_relay(struct gpiod_line *line);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Turn off all relays
    if (relay1_line) {
        gpiod_line_set_value(relay1_line, 0);
    }
    if (relay2_line) {
        gpiod_line_set_value(relay2_line, 0);
    }
    if (relay3_line) {
        gpiod_line_set_value(relay3_line, 0);
    }
    if (relay4_line) {
        gpiod_line_set_value(relay4_line, 0);
    }

    // Release GPIO lines
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }

    // Release GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to toggle a relay
int toggle_relay(struct gpiod_line *line) {
    int current_value = gpiod_line_get_value(line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading relay value: %d\n", current_value);
        return -1;
    }
    int new_value = (current_value == 0) ? 1 : 0;
    if (gpiod_line_set_value(line, new_value) < 0) {
        fprintf(stderr, "Error setting relay value\n");
        return -1;
    }
    return 0;
}

int main() {
    struct timespec sleep_time1 = {0, INTERVAL1 * 1000000000L}; // 2 seconds
    struct timespec sleep_time2 = {0, INTERVAL2 * 1000000000L}; // 3 seconds
    struct timespec sleep_time3 = {0, INTERVAL3 * 1000000000L}; // 5 seconds
    struct timespec sleep_time4 = {0, INTERVAL4 * 1000000000L}; // 7 seconds

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines for each relay
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0) {
        perror("Error requesting relay1 line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(relay2_line, "relay2", 0) < 0) {
        perror("Error requesting relay2 line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(relay3_line, "relay3", 0) < 0) {
        perror("Error requesting relay3 line as output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        perror("Error requesting relay4 line as output");
        cleanup(0);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle relay 1
        if (toggle_relay(relay1_line) < 0) {
            cleanup(0);
            return 1;
        }
        nanosleep(&sleep_time1, NULL);

        // Toggle relay 2
        if (toggle_relay(relay2_line) < 0) {
            cleanup(0);
            return 1;
        }
        nanosleep(&sleep_time2, NULL);

        // Toggle relay 3
        if (toggle_relay(relay3_line) < 0) {
            cleanup(0);
            return 1;
        }
        nanosleep(&sleep_time3, NULL);

        // Toggle relay 4
        if (toggle_relay(relay4_line) < 0) {
            cleanup(0);
            return 1;
        }
        nanosleep(&sleep_time4, NULL);
    }

    return 0;
}

