#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SOUND_SENSOR_GPIO 17
#define RELAY_GPIO 27
#define SOUND_THRESHOLD 1  // Digital HIGH (1) indicates sound detected
#define ALARM_DURATION 3000 // 3 seconds in milliseconds
#define DEBOUNCE_DELAY 500  // 500 milliseconds debounce delay
#define COOLDOWN_DELAY 1000 // 1 second cooldown delay

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int sound_detected = 0;
    time_t last_alarm_time = 0;
    time_t last_debounce_time = 0;
    time_t last_cooldown_time = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_GPIO, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor_value = gpioRead(SOUND_SENSOR_GPIO);

        if (sensor_value == SOUND_THRESHOLD && !sound_detected) {
            // Sound detected
            time_t current_time = time(NULL);

            // Debounce check
            if (current_time - last_debounce_time > DEBOUNCE_DELAY / 1000.0) {
                sound_detected = 1;
                last_debounce_time = current_time;

                // Check cooldown
                if (current_time - last_alarm_time > COOLDOWN_DELAY / 1000.0) {
                    // Trigger alarm
                    gpioWrite(RELAY_GPIO, 1); // Turn relay ON
                    last_alarm_time = current_time;

                    // Log alarm event
                    log_file = fopen("alarm_log.txt", "a");
                    if (log_file != NULL) {
                        struct tm *timeinfo = localtime(&current_time);
                        char timestamp[20];
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                        fprintf(log_file, "%s: Alarm triggered\n", timestamp);
                        fclose(log_file);
                    } else {
                        fprintf(stderr, "Error opening log file!\n");
                    }

                    gpioDelay(ALARM_DURATION); // Keep relay ON for 3 seconds

                    gpioWrite(RELAY_GPIO, 0); // Turn relay OFF
                    last_alarm_time = current_time;
                }
            }
        } else if (sensor_value != SOUND_THRESHOLD) {
            sound_detected = 0;
        }

        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

