#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Gyroscope sensitivity (degrees/second per LSB) for +/- 250 dps range
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len);
int i2c_write_byte(int fd, unsigned char reg, unsigned char value);
int mpu6050_init(int fd);
int read_gyro_data(int fd, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void callback();
void signal_handler(int sig);
void init_circular_buffer(circular_buffer_t *buffer);
void add_to_circular_buffer(circular_buffer_t *buffer, float x, float y, float z);

// I2C read function
int i2c_read_bytes(int fd, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_byte(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

// MPU-6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2c_write_byte(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "MPU6050 initialization failed: Could not wake up sensor\n");
        return -1;
    }

    // Verify the WHO_AM_I register
    unsigned char who_am_i;
    if (i2c_read_bytes(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "MPU6050 initialization failed: Could not read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 initialization failed: WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
        return -1;
    }

    printf("MPU6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, float *x, float *y, float *z) {
    unsigned char data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_bytes(fd, GYRO_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (data[0] << 8) | data[1];
    raw_y = (data[2] << 8) | data[3];
    raw_z = (data[4] << 8) | data[5];

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Callback function
void callback() {
    printf("Angular velocity threshold exceeded!\n");
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    program_running = 0;
    printf("Exiting program...\n");
}

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add data to the circular buffer
void add_to_circular_buffer(circular_buffer_t *buffer, float x, float y, float z) {
    buffer->x[buffer->head] = x;
    buffer->y[buffer->head] = y;
    buffer->z[buffer->head] = z;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

int main() {
    float x, y, z, magnitude;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init(i2c_fd) != 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    printf("Starting data acquisition...\n");

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Add data to circular buffer
            add_to_circular_buffer(&gyro_buffer, x, y, z);

            // Check if threshold is exceeded
            if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
                callback();
            }

            printf("X: %.2f, Y: %.2f, Z: %.2f, Magnitude: %.2f\n", x, y, z, magnitude);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Delay for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

