#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

int uart_handle;
FILE *log_file;
FILE *error_file;

// Function to log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(error_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(error_file);
}

// Function to read CO2 concentration from MH-Z19B sensor
int read_co2() {
    unsigned char read_command[] = {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[9];
    int i, sum;

    // Send read command
    if (serWrite(uart_handle, (char *)read_command, 9) != 9) {
        log_error("Failed to send read command");
        return -1;
    }

    // Wait for data to be available
    gpioDelay(100000); // 100 ms

    // Read response
    int bytes_read = 0;
    while (bytes_read < 9) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            for (i = 0; i < available; i++) {
                response[bytes_read++] = serReadByte(uart_handle);
            }
        } else {
            gpioDelay(1000); // Wait 1 ms
        }

        if (bytes_read == 9) break;
        if (gpioTick() - now > 1000000) { // 1 second timeout
            log_error("Timeout reading from UART");
            return -1;
        }
    }

    // Validate checksum
    sum = 0;
    for (i = 1; i < 7; i++) {
        sum += response[i];
    }
    int checksum = (response[7] << 8) | response[8];
    if ((checksum & 0xFF) != ((~sum) & 0xFF)) {
        log_error("Checksum mismatch");
        return -1;
    }

    // Extract CO2 concentration
    int co2 = (response[2] << 8) | response[3];
    return co2;
}

// Function to log CO2 data to JSON file
void log_data(int co2_ppm, int error_flag) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03dZ", t);

    fprintf(log_file, "{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, co2_ppm, error_flag);
    fflush(log_file);

    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp, co2_ppm, error_flag);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open UART
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for no flags
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CO2_LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        serClose(uart_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int co2_ppm = read_co2();
        int error_flag = (co2_ppm == -1) ? 1 : 0;
        log_data(co2_ppm, error_flag);

        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

