        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B (0x01)
    config_data[0] = HMC5883L_CONFIG_B;
    config_data[1] = 0x20; // 1.3 Gauss gain
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Configure register C (0x02) - continuous measurement mode
    config_data[0] = HMC5883L_MODE;
    config_data[1] = 0x00; // Continuous measurement mode
    if (i2cWriteDevice(i2c_handle, config_data, 2) != 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the HMC5883L
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    // Combine MSB and LSB for each axis
    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Function to compensate the heading
float compensate_heading(int16_t x, int16_t y) {
    float heading = atan2(y - HARD_IRON_Y_OFFSET, x - HARD_IRON_X_OFFSET) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to update the GPIO pin based on the heading deviation
void update_gpio(float current_heading) {
    float heading_deviation = fabs(current_heading - TARGET_HEADING);
    if (heading_deviation > 10.0) {
        gpioWrite(OUTPUT_PIN, 1); // Set GPIO high
    } else {
        gpioWrite(OUTPUT_PIN, 0); // Set GPIO low
    }
}

// Function to log the heading to the circular buffer
void log_heading(float heading) {
    heading_buffer[buffer_index].heading = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(OUTPUT_PIN, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L
    if (configure_hmc5883l() != 0) {
        fprintf(stderr, "HMC5883L configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (1) {
        // Read data from HMC5883L
        if (read_hmc5883l_data(&x, &y, &z) == 0) {
            // Compensate heading
            heading = compensate_heading(x, y);

            // Update GPIO
            update_gpio(heading);

            // Log heading
            log_heading(heading);

            // Print heading (for debugging)
            printf("Heading: %.2f\n", heading);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup (should not reach here in normal operation due to signal handling)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

