#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define GPIO pins for relays
#define RED_RELAY_PIN 17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN 22

// Define I2C bus and BH1750 address
#define I2C_BUS 1
#define BH1750_ADDR 0x23

// Define lux thresholds
#define RED_THRESHOLD 50
#define GREEN_THRESHOLD 150
#define BLUE_THRESHOLD 300

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_bh1750(int fd, unsigned short *raw_value);
float calculate_lux(unsigned short raw_value);
int set_relay_state(int gpio_pin, int state);
int log_data(FILE *fp, float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C bus
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Read data from BH1750 sensor
int read_bh1750(int fd, unsigned short *raw_value) {
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Calculate lux value
float calculate_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Set relay state using libgpiod
int set_relay_state(int gpio_pin, int state) {
    int ret;
    if (gpio_pin == RED_RELAY_PIN) {
        if (red_line) {
            ret = gpiod_line_set_value(red_line, state);
            if (ret < 0) {
                perror("Error setting red relay state");
                return -1;
            }
        }
    } else if (gpio_pin == GREEN_RELAY_PIN) {
        if (green_line) {
            ret = gpiod_line_set_value(green_line, state);
            if (ret < 0) {
                perror("Error setting green relay state");
                return -1;
            }
        }
    } else if (gpio_pin == BLUE_RELAY_PIN) {
        if (blue_line) {
            ret = gpiod_line_set_value(blue_line, state);
            if (ret < 0) {
                perror("Error setting blue relay state");
                return -1;
            }
        }
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(FILE *fp, float lux, int red_state, int green_state, int blue_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            lux, red_state, green_state, blue_state);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    unsigned short raw_value;
    float lux;
    int red_state = 0;
    int green_state = 0;
    int blue_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    red_line = gpiod_chip_get_line(gpio_chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(gpio_chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(gpio_chip, BLUE_RELAY_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(red_line, "relay", 0) < 0 ||
        gpiod_line_request_output(green_line, "relay", 0) < 0 ||
        gpiod_line_request_output(blue_line, "relay", 0) < 0) {
        perror("Error requesting GPIO line for output");
        cleanup();
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Continuing without sensor.\n");
    }

    // Open log file
    log_file = fopen("lighting_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int any_on = 0;

        // Read lux value
        if (i2c_fd >= 0) {
            if (read_bh1750(i2c_fd, &raw_value) == 0) {
                lux = calculate_lux(raw_value);

                // Set relay states based on lux threshold
                if (lux < RED_THRESHOLD) {
                    red_state = 1;
                    green_state = 0;
                    blue_state = 0;
                    any_on = 1;
                } else if (lux >= RED_THRESHOLD && lux <= GREEN_THRESHOLD) {
                    red_state = 1;
                    green_state = 1;
                    blue_state = 0;
                    any_on = 1;
                } else if (lux >= GREEN_THRESHOLD && lux <= BLUE_THRESHOLD) {
                    red_state = 1;
                    green_state = 1;
                    blue_state = 1;
                    any_on = 1;
                } else {
                    red_state = 1;
                    green_state = 1;
                    blue_state = 1;
                    any_on = 1;
                }

                // Log data
                log_data(log_file, lux, red_state, green_state, blue_state);
            } else {
                fprintf(stderr, "Failed to read lux value. Continuing.\n");
            }
        } else {
            // Log sensor absent
            log_data(log_file, 0.0, 0, 0, 0);
        }

        // Set relay states
        if (set_relay_state(RED_RELAY_PIN, red_state) < 0 ||
            set_relay_state(GREEN_RELAY_PIN, green_state) < 0 ||
            set_relay_state(BLUE_RELAY_PIN, blue_state) < 0) {
            fprintf(stderr, "Failed to set relay state. Continuing.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

