#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Distance range (cm)
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Structure to hold motor control parameters
typedef struct {
    int in1_pin;
    int in2_pin;
    int in3_pin;
    int in4_pin;
    int min_distance;
    int max_distance;
} MotorControlParams;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set motor direction and speed
void set_motor_speed(int in1_pin, int in2_pin, int pwm_duty, int min_distance, int max_distance) {
    int distance = min_distance + (rand() % (max_distance - min_distance + 1));
    int duty_cycle = 255 - (int)(((float)(max_distance - distance) / (float)(max_distance - min_distance)) * 255.0);

    if (distance < 50) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
        gpioPWM(in2_pin, duty_cycle);
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
        gpioPWM(in2_pin, duty_cycle);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Motor control parameters
    MotorControlParams motor_a_params = {MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, MIN_DISTANCE, MAX_DISTANCE};
    MotorControlParams motor_b_params = {MOTOR_B_IN3, MOTOR_B_IN4, MOTOR_A_IN1, MOTOR_A_IN2, MIN_DISTANCE, MAX_DISTANCE};

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency for motor control
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Seed the random number generator
    srand(time(NULL));

    // Main control loop
    while (!terminate) {
        // Control Motor A
        set_motor_speed(motor_a_params.in1_pin, motor_a_params.in2_pin, rand() % 256, MIN_DISTANCE, MAX_DISTANCE);

        // Control Motor B
        set_motor_speed(motor_b_params.in3_pin, motor_b_params.in4_pin, rand() % 256, MIN_DISTANCE, MAX_DISTANCE);

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop motors and cleanup
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    gpioTerminate();

    return 0;
}

