    if (gpioSetMode(MOTOR_PIN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PIN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PIN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PIN4, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "GPIO mode setting failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Register callback functions for button press/release events
    gpioSetAlertFunc(LOCK_BUTTON, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON, button_callback);

    printf("Automatic Door Lock System\n");
    printf("Press LOCK button to lock, UNLOCK button to unlock.\n");

    // Keep the program running
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

