            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1;
}

// I2C write function with exponential backoff retry
int i2c_write_data(int fd, uint8_t reg_addr, uint8_t data) {
    int retries = 0;
    int delay_ms = 10;

    while (retries < 5) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Failed to acquire bus access");
            return -1;
        }

        uint8_t buf[2];
        buf[0] = reg_addr;
        buf[1] = data;

        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("Failed to write data");
            retries++;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU-6050 (set power management register to 0)
    if (i2c_write_data(fd, 0x6B, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2c_write_data(fd, 0x1C, 0x00) < 0) {
        fprintf(stderr, "Failed to configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 deg/s)
    if (i2c_write_data(fd, 0x1B, 0x00) < 0) {
        fprintf(stderr, "Failed to configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
void read_accel_gyro(int fd, float *accel_x, float *accel_y, float *accel_z, float *gyro_x, float *gyro_y, float *gyro_z) {
    uint8_t data[14];

    if (i2c_read_data(fd, 0x3B, data, 14) < 0) {
        fprintf(stderr, "Failed to read accelerometer and gyroscope data\n");
        *accel_x = *accel_y = *accel_z = *gyro_x = *gyro_y = *gyro_z = 0.0f;
        return;
    }

    // Accelerometer data
    int16_t accel_x_raw = (data[0] << 8) | data[1];
    int16_t accel_y_raw = (data[2] << 8) | data[3];
    int16_t accel_z_raw = (data[4] << 8) | data[5];

    // Gyroscope data
    int16_t gyro_x_raw = (data[8] << 8) | data[9];
    int16_t gyro_y_raw = (data[10] << 8) | data[11];
    int16_t gyro_z_raw = (data[12] << 8) | data[13];

    *accel_x = (float)accel_x_raw / ACCEL_SCALE;
    *accel_y = (float)accel_y_raw / ACCEL_SCALE;
    *accel_z = (float)accel_z_raw / ACCEL_SCALE;
    *gyro_x = (float)gyro_x_raw / GYRO_SCALE;
    *gyro_y = (float)gyro_y_raw / GYRO_SCALE;
    *gyro_z = (float)gyro_z_raw / GYRO_SCALE;
}

// Function to calculate pitch angle
float calculate_pitch(float accel_x, float accel_y, float accel_z) {
    return -atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / PI;
}

// Function to calculate roll angle
float calculate_roll(float accel_x, float accel_y, float accel_z) {
    return atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / PI;
}

// Function to set servo angle using PWM
int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = SERVO_NEUTRAL_POSITION + (int)((float)(angle) / 180.0f * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Export PWM channel if not already exported
    char pwm_export_path[64];
    snprintf(pwm_export_path, sizeof(pwm_export_path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    if (access(pwm_export_path, F_OK) == -1) {
        int export_fd = open(pwm_export_path, O_WRONLY);
        if (export_fd == -1) {
            perror("Failed to open PWM export file");
            return -1;
        }
        if (write(export_fd, "0", 1) != 1) {
            perror("Failed to write to PWM export file");
            close(export_fd);
            return -1;
        }
        close(export_fd);
        usleep(100000); // Wait for the sysfs entry to be created
    }

    // Set PWM period
    char pwm_period_path[64];
    snprintf(pwm_period_path, sizeof(pwm_period_path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    int period_fd = open(pwm_period_path, O_WRONLY);
    if (period_fd == -1) {
        perror("Failed to open PWM period file");
        return -1;
    }
    char period_str[16];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD_NS);
    if (write(period_fd, period_str, strlen(period_str)) != strlen(period_str)) {
        perror("Failed to write to PWM period file");
        close(period_fd);
        return -1;
    }
    close(period_fd);

    // Set PWM duty cycle
    char pwm_duty_cycle_path[64];
    snprintf(pwm_duty_cycle_path, sizeof(pwm_duty_cycle_path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    int duty_cycle_fd = open(pwm_duty_cycle_path, O_WRONLY);
    if (duty_cycle_fd == -1) {
        perror("Failed to open PWM duty cycle file");
        return -1;
    }
    char duty_cycle_str[16];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", pulse_width);
    if (write(duty_cycle_fd, duty_cycle_str, strlen(duty_cycle_str)) != strlen(duty_cycle_str)) {
        perror("Failed to write to PWM duty cycle file");
        close(duty_cycle_fd);
        return -1;
    }
    close(duty_cycle_fd);

    return 0;
}

// Function to log data to file
void log_data(float pitch, float roll, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    float accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_angle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read accelerometer and gyroscope data
        read_accel_gyro(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);

        // Calculate pitch and roll
        pitch = calculate_pitch(accel_x, accel_y, accel_z);
        roll = calculate_roll(accel_x, accel_y, accel_z);

        // Map pitch to servo angle (0-180 degrees to 0-1800 us)
        servo_angle = (int)(pitch * (1800.0f / 180.0f));

        // Set servo angle
        if (set_servo_angle(servo_angle) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        // Log data
        log_data(pitch, roll, servo_angle);

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

