#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define TRANSITION_DURATION 1800 // seconds
#define PWM_FREQUENCY 100        // Hz
#define DUTY_RANGE 100

// Relay GPIO pins
const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

// Schedule file path
const char *schedule_file = "lighting_schedule.txt";

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_schedule(const char *filename, int *schedule[], int *num_entries);
int parse_schedule_entry(const char *line, int *hour, int *minute, int *second, int *relay_number, char *state);
int compare_time(int hour, int minute, int second, int current_hour, int current_minute, int current_second);
void set_relay_state(int relay_number, int state);
void fade_lamp(int relay_number, int current_brightness, int target_brightness);
void signal_handler(int signal);

int main() {
    int schedule[100]; // Assuming a maximum of 100 schedule entries
    int num_entries = 0;
    int i;
    time_t current_time;
    struct tm *time_info;
    int hour, minute, second;
    int current_hour, current_minute, current_second;
    char state[10];
    int target_brightness;
    int current_brightness;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    for (i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioWrite(relay_pins[i], 0); // Initially turn off all relays
    }

    // Set PWM frequency
    gpioSetPWMfrequency(relay_pins[0], PWM_FREQUENCY); // Only need to set once

    // Read schedule from file
    if (read_schedule(schedule_file, schedule, &num_entries) != 0) {
        fprintf(stderr, "Error reading schedule file\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        current_hour = time_info->tm_hour;
        current_minute = time_info->tm_min;
        current_second = time_info->tm_sec;

        // Compare current time with schedule entries
        for (i = 0; i < num_entries; i++) {
            if (compare_time(schedule[i * 6][0], schedule[i * 6 + 1][0], schedule[i * 6 + 2][0], current_hour, current_minute, current_second) == 0) {
                // Schedule match, fade lamp
                target_brightness = schedule[i * 6 + 3][0] - '0';
                fade_lamp(schedule[i * 6 + 4][0], 0, target_brightness);
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // Check every second
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated cleanly\n");
    return 0;
}

// Function to read schedule from file
int read_schedule(const char *filename, int *schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return 1;
    }

    char line[256];
    *num_entries = 0;

    while (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%d:%d:%d,%d,%s", &schedule[*num_entries * 6 + 0], &schedule[*num_entries * 6 + 1], &schedule[*num_entries * 6 + 2], &schedule[*num_entries * 6 + 3], schedule[*num_entries * 6 + 4]) == 5) {
            (*num_entries)++;
            if (*num_entries > 100) {
                fprintf(stderr, "Warning: Maximum number of schedule entries reached\n");
                break;
            }
        } else {
            fprintf(stderr, "Warning: Invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

// Function to parse schedule entry
int parse_schedule_entry(const char *line, int *hour, int *minute, int *second, int *relay_number, char *state) {
    if (sscanf(line, "%d:%d:%d,%d,%s", hour, minute, second, relay_number, state) == 5) {
        return 0; // Success
    } else {
        return 1; // Failure
    }
}

// Function to compare current time with schedule entry
int compare_time(int current_hour, int current_minute, int current_second, int schedule_hour, int schedule_minute, int schedule_second) {
    return (current_hour == schedule_hour && current_minute == schedule_minute && current_second == schedule_second);
}

// Function to set relay state
void set_relay_state(int relay_number, int state) {
    int pin = relay_pins[relay_number];
    gpioWrite(pin, state);
    printf("Relay %d set to %d\n", relay_number, state);
}

// Function to fade lamp brightness
void fade_lamp(int relay_number, int current_brightness, int target_brightness) {
    int pin = relay_pins[relay_number];
    int step = (target_brightness - current_brightness) / TRANSITION_DURATION;
    int direction = (step > 0) ? 1 : -1;
    step = abs(step);

    for (int i = 0; i < TRANSITION_DURATION; i++) {
        current_brightness += step * direction;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > DUTY_RANGE) current_brightness = DUTY_RANGE;
        gpioPWM(pin, current_brightness);
        gpioDelay(1000); // 1 second delay
    }
    gpioPWM(pin, target_brightness);
    printf("Lamp %d faded to %d\n", relay_number, target_brightness);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating program...\n", signal);
    terminate = 1;

    // Turn off all relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

