#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 30.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define PWM_RANGE 1000        // PWM range (adjust as needed)
#define TIMEOUT_US 50000       // Timeout for echo pulse (50ms)

// Global variables
volatile unsigned int echo_start_tick = 0;
volatile unsigned int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_sensor();
float get_distance();
float map_distance_to_frequency(float distance);
void generate_pwm_signal(float frequency);
void signal_handler(int signal);
void echo_callback(int gpio, int level, unsigned int tick);

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick)
{
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that the rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 2; // Indicate that the falling edge has been received
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor()
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float get_distance()
{
    echo_start_tick = 0;
    echo_end_tick = 0;
    echo_received = 0;

    trigger_sensor();

    // Wait for echo or timeout
    unsigned int start_time = gpioTick();
    while (echo_received < 2 && (gpioTick() - start_time) < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (echo_received != 2) {
        fprintf(stderr, "Error: No echo received or timeout occurred.\n");
        return -1.0; // Indicate error
    }

    // Calculate pulse width in microseconds
    unsigned int pulse_width = echo_end_tick - echo_start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate error
    }

    // Linear mapping
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp the frequency to the valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to generate the PWM signal for the buzzer
void generate_pwm_signal(float frequency)
{
    if (frequency < 0) {
        gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
        return;
    }

    // Calculate PWM duty cycle (adjust as needed for your buzzer)
    int duty_cycle = (int)((frequency / 1000.0) * PWM_RANGE); // Example calculation

    gpioPWM(BUZZER_PIN, duty_cycle);
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Ctrl+C pressed. Exiting.\n");
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();        // Deinitialize pigpio
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(BUZZER_PIN, PWM_RANGE);

