#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to set the RGB LED color using hardware PWM
void set_rgb_color(float proximity) {
    int red_pwm, green_pwm, blue_pwm;

    // Map proximity value (0.0 to 1.0) to PWM duty cycle (0 to 255)
    red_pwm   = (int)(proximity * 255.0);
    green_pwm = (int)((1.0 - proximity) * 255.0);
    blue_pwm  = 0; // Constant blue component

    // Common anode, so invert PWM values
    red_pwm   = 255 - red_pwm;
    green_pwm = 255 - green_pwm;

    // Set PWM duty cycle for each color
    gpioPWM(RED_PIN,   red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN,  blue_pwm);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(RED_PIN,   1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN,  1000);

    // Register signal handler for SIGINT
    signal(SIGINT,  signal_handler);

    // Main loop
    while (program_running) {
        // Generate a sine wave for proximity value
        float proximity = 0.5 + 0.5 * sin(time(NULL) / 10.0); // Period = 20 seconds

        // Set RGB LED color based on proximity
        set_rgb_color(proximity);

        // Delay for a short period
        gpioDelay(10000); // 10 ms
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

