#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0f

int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

void signal_handler(int sig) {
    stop_flag = 1;
}

int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

int16_t process_gyro_data(uint8_t *data) {
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    return (int16_t)((raw * GYRO_SENSITIVITY) / 131.0f);
}

int main() {
    struct timespec ts;
    int16_t gyro_x, gyro_y, gyro_z;
    uint8_t gyro_data[6];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    if (write_byte(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (write_byte(i2c_fd, GYRO_CONFIG, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    while (!stop_flag) {
        if (read_bytes(i2c_fd, GYRO_XOUT_H, gyro_data, 6) < 0) {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            nanosleep(&(struct timespec){0, 100000000L}, NULL); // 100ms
            continue;
        }

        gyro_x = process_gyro_data(gyro_data);
        gyro_y = process_gyro_data(gyro_data + 2);
        gyro_z = process_gyro_data(gyro_data + 4);

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld, %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, gyro_x, gyro_y, gyro_z);
        fflush(log_file);

        nanosleep(&(struct timespec){0, 100000000L}, NULL); // 100ms
    }

    close(i2c_fd);
    fclose(log_file);
    printf("Program terminated gracefully.\n");
    return 0;
}

