#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequency in Hz, duration in ms)
const unsigned int melody[][2] = {
    {440, 250},   // A4
    {494, 250},   // B4
    {523, 250},   // C5
    {587, 500}    // D5
};

// Define melody length
#define MELODY_LENGTH (sizeof(melody) / sizeof(melody[0]))

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile int playing = 0; // Flag to indicate if the melody is playing
volatile unsigned int last_interrupt_time = 0; // Last interrupt time for debouncing

// Function prototypes
void play_melody(int gpio, int data);
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to play the melody
void play_melody(int gpio, int data) {
    if (!playing) return; // Check if melody is already playing

    for (int i = 0; i < MELODY_LENGTH; i++) {
        gpioHardwarePWM(BUZZER_PIN, melody[i][0], 128); // Play the note
        gpioDelay(melody[i][1] * 1000);                 // Delay for the duration
    }
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop the PWM after the melody
    playing = 0; // Stop the flag
}

// Interrupt handler for the button
void button_interrupt_handler(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned int now = gpioTick();

    // Debounce the button
    if (now - last_interrupt_time < DEBOUNCE_TIME * 1000) {
        return;
    }
    last_interrupt_time = now;

    if (level == 0) { // Button pressed (active low)
        if (playing) {
            // Stop the melody
            playing = 0;
        } else {
            // Start the melody
            playing = 1;
            gpioHardwarePWM(BUZZER_PIN, 0, 0); // Ensure PWM is off before starting
            gpioDelay(1); // Small delay before starting PWM
            gpioHardwarePWM(BUZZER_PIN, 440, 128); // Start with a tone
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for the button
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical doorbell running. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        gpioDelay(100); // Small delay to reduce CPU usage
    }

    return 0;
}

