#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define EVENT_WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3

static volatile sig_atomic_t keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int event_window[EVENT_WINDOW_SIZE] = {0};
static int window_index = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(int value)
{
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, not logging event.\n");
        return -1;
    }

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            free(timestamp);
            return -1;
        }
    }

    fprintf(log_file, "%s,%d\n", timestamp, value);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
    fsync(fileno(log_file)); // Sync the file to disk
    free(timestamp);
    return 0;
}

// Function to check for an earthquake condition
void check_earthquake(int value)
{
    event_window[window_index] = value;
    window_index = (window_index + 1) % EVENT_WINDOW_SIZE;

    int high_count = 0;
    for (int i = 0; i < EVENT_WINDOW_SIZE; i++) {
        if (event_window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= EARTHQUAKE_THRESHOLD) {
        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            printf("EARTHQUAKE ALERT: %s, Vibration detected: %d\n", timestamp, value);
            free(timestamp);
        }
    }
}

int main(int argc, char *argv[])
{
    int timeout_ms = 1000;
    struct gpiod_line_request_config config;
    struct timespec ts;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line request
    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Request the line
    if (gpiod_line_request(line, &config, 0) != 0) {
        perror("Failed to request GPIO line");
        fclose(log_file);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    printf("Vibration sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        // Poll for events with timeout
        ts.tv_sec = 0;
        ts.tv_nsec = timeout_ms * 1000000; // Convert milliseconds to nanoseconds

        int value = gpiod_line_event_wait(line, &ts);
        if (value < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            } else {
                perror("Failed to wait for event");
                break;
            }
        }

        if (value > 0) {
            // Event occurred
            if (log_event(value) != 0) {
                fprintf(stderr, "Failed to log event.\n");
            }
            check_earthquake(value);
        } else {
            // Timeout occurred, no event
        }
    }

    // Clean up
    printf("Cleaning up...\n");
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

