#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_i2c(int address);
int write_byte(int fd, uint8_t reg, uint8_t value);
int read_block(int fd, uint8_t reg, uint8_t *data, int len);
int16_t combine_bytes(uint8_t high, uint8_t low);
float calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z);
float calculate_heading(float x, float y);
void log_data(FILE *fp, float x, float y, float z, float heading);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

// Initialize I2C interface
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Write a byte to a register
int write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Read a block of data from a register
int read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Combine high and low bytes into a 16-bit signed integer
int16_t combine_bytes(uint8_t high, uint8_t low) {
    return (int16_t)((high << 8) | low);
}

// Calibrate raw data
float calibrate_data(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    return (float)(raw_x - X_OFFSET) + (float)(raw_y - Y_OFFSET) + (float)(raw_z - Z_OFFSET);
}

// Calculate compass heading
float calculate_heading(float x, float y) {
    float heading = atan2f(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to CSV file
void log_data(FILE *fp, float x, float y, float z, float heading) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, x, y, z, heading);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LSM303_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Configure magnetometer for continuous conversion and 15 Hz data rate
    if (write_byte(i2c_fd, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to set continuous conversion mode. Exiting.\n");
        close(i2c_fd);
        return 1;
    }
    if (write_byte(i2c_fd, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Failed to set data rate. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    rewind(log_file);

    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;
    float calibrated_x, calibrated_y, calibrated_z, heading;

    // Main loop
    while (!stop_flag) {
        // Read magnetometer data
        if (read_block(i2c_fd, OUT_X_H_M, data, 6) < 0) {
            fprintf(stderr, "Failed to read magnetometer data. Skipping.\n");
            sleep(1);
            continue;
        }

        // Combine bytes
        raw_x = combine_bytes(data[0], data[1]);
        raw_y = combine_bytes(data[2], data[3]);
        raw_z = combine_bytes(data[4], data[5]);

        // Calibrate data
        calibrated_x = calibrate_data(raw_x, raw_y, raw_z);

        // Calculate heading
        heading = calculate_heading(calibrated_x, calibrated_y);

        // Log data
        log_data(log_file, calibrated_x, calibrated_y, calibrated_z, heading);

        // Print to console
        printf("Heading: %.2f degrees\n", heading);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

