#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define ACTIVATION_DURATION_SEC 5
#define GAP_DURATION_SEC 1

// Structure to hold GPIO lines and chip information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_RELAYS];
} gpio_state_t;

// Global variables
FILE *log_file = NULL;
gpio_state_t gpio_state = {0};

// Function prototypes
int initialize_gpio(gpio_state_t *gpio_state);
int activate_relay(gpio_state_t *gpio_state, int relay_number);
int deactivate_relay(gpio_state_t *gpio_state, int relay_number);
int log_event(int relay_number, int moisture_level);
void cleanup_gpio(gpio_state_t *gpio_state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Cleaning up and exiting.\n", sig);
    cleanup_gpio(&gpio_state);
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(gpio_state_t *gpio_state) {
    struct gpiod_line_request_config config;
    int i;

    gpio_state->chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!gpio_state->chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return -1;
    }

    for (i = 0; i < NUM_RELAYS; i++) {
        gpio_state->lines[i] = gpiod_chip_get_line(gpio_state->chip, i);
        if (!gpio_state->lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", i, strerror(errno));
            cleanup_gpio(gpio_state);
            return -1;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "irrigation_system";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        config.flags = 0;

        if (gpiod_line_request(gpio_state->lines[i], &config, 0) != 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", i, strerror(errno));
            cleanup_gpio(gpio_state);
            return -1;
        }

        // Set initial value to 1 (relay OFF)
        if (gpiod_line_set_value(gpio_state->lines[i], 1) != 0) {
            fprintf(stderr, "Error setting initial value for GPIO line %d: %s\n", i, strerror(errno));
            cleanup_gpio(gpio_state);
            return -1;
        }
    }

    return 0;
}

// Activate a relay (drive the line to 0)
int activate_relay(gpio_state_t *gpio_state, int relay_number) {
    if (relay_number < 0 || relay_number >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }

    if (gpiod_line_set_value(gpio_state->lines[relay_number], 0) != 0) {
        fprintf(stderr, "Error setting value for GPIO line %d: %s\n", relay_number, strerror(errno));
        return -1;
    }

    return 0;
}

// Deactivate a relay (drive the line to 1)
int deactivate_relay(gpio_state_t *gpio_state, int relay_number) {
    if (relay_number < 0 || relay_number >= NUM_RELAYS) {
        fprintf(stderr, "Invalid relay number: %d\n", relay_number);
        return -1;
    }

    if (gpiod_line_set_value(gpio_state->lines[relay_number], 1) != 0) {
        fprintf(stderr, "Error setting value for GPIO line %d: %s\n", relay_number, strerror(errno));
        return -1;
    }

    return 0;
}

// Log an event to the log file
int log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    return 0;
}

// Cleanup GPIO lines
void cleanup_gpio(gpio_state_t *gpio_state) {
    int i;

    if (gpio_state->chip) {
        for (i = 0; i < NUM_RELAYS; i++) {
            if (gpio_state->lines[i]) {
                gpiod_line_release(gpio_state->lines[i]);
            }
        }
        gpiod_chip_close(gpio_state->chip);
    }
}

int main() {
    int moisture_level;
    int i;

    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(&gpio_state) != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        fclose(log_file);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (1) {
        // Generate a random moisture level
        moisture_level = rand() % 101;
        printf("Moisture level: %d\n", moisture_level);

        // Check if irrigation is needed
        if (moisture_level < MOISTURE_THRESHOLD) {
            fprintf(stderr, "Moisture level below threshold. Activating relays.\n");
            for (i = 0; i < NUM_RELAYS; i++) {
                // Activate relay
                if (activate_relay(&gpio_state, i) == 0) {
                    // Log the event
                    if (log_event(i, moisture_level) != 0) {
                        fprintf(stderr, "Error logging event for relay %d.\n", i);
                    }

                    // Wait for the activation duration
                    sleep(ACTIVATION_DURATION_SEC);

                    // Deactivate relay
                    if (deactivate_relay(&gpio_state, i) != 0) {
                        fprintf(stderr, "Error deactivating relay %d.\n", i);
                    }

                    // Wait for the gap duration
                    sleep(GAP_DURATION_SEC);
                } else {
                    fprintf(stderr, "Error activating relay %d.\n", i);
                }
            }
        }

        // Wait for 10 seconds
        sleep(10);
    }

    return 0;
}

