#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

int gpio_safe_servo(int gpio, int pulse_width) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error setting servo on GPIO %d, retrying...\n", gpio);
        gpioDelay(100000); // 100ms backoff
        retries--;
    }
    fprintf(stderr, "Failed to set servo on GPIO %d after multiple retries.\n", gpio);
    return -1; // Failure
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int moisture_level = 20;
    int valve_position = 0;
    int nozzle_position = 0;

    while (!terminate) {
        if (moisture_level < 50) {
            printf("Moisture level: %d - Watering...\n", moisture_level);

            if (gpio_safe_servo(VALVE_GPIO, 2000) != 0) {
                fprintf(stderr, "CRITICAL: Failed to open valve!\n");
                terminate = 1; // Stop if valve fails to open
                break;
            }
            valve_position = 2000;

            for (nozzle_position = 0; nozzle_position <= 180 && !terminate; nozzle_position += 45) {
                if (gpio_safe_servo(NOZZLE_GPIO, 1000 + (nozzle_position * 1000 / 90)) != 0) {
                    fprintf(stderr, "Error setting nozzle position %d, continuing...\n", nozzle_position);
                }
                gpioDelay(2000000); // 2 seconds
            }

            if (gpio_safe_servo(VALVE_GPIO, 0) != 0) {
                fprintf(stderr, "WARNING: Failed to close valve!\n");
            }
            valve_position = 0;

        } else {
            printf("Moisture level: %d - Not watering.\n", moisture_level);
        }

        gpioDelay(5000000); // 5 seconds

        moisture_level = (moisture_level + 20) % 100; // Cycle through 20, 40, 60, 80, 100
    }

    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

