#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43

// Sensitivity scale factor for gyroscope (±250 deg/s)
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// File to log data
#define LOG_FILE "gyro_log.txt"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to wake up the MPU-6050
int wake_up_mpu6000(int fd) {
    uint8_t data = 0x00;
    if (write(fd, &data, 1) != 1) {
        perror("Failed to wake up MPU-6050");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[6];
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read gyroscope data");
        return -1;
    }

    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to degrees/second
void convert_to_degrees_per_second(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *x, float *y, float *z) {
    *x = (float)gyro_x / GYRO_SCALE;
    *y = (float)gyro_y / GYRO_SCALE;
    *z = (float)gyro_z / GYRO_SCALE;
}

// Function to log data to file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z) < 0) {
        perror("Failed to write to log file");
        return -1;
    }
    return 0;
}

int main() {
    int16_t gyro_x, gyro_y, gyro_z;
    float x, y, z;
    FILE *fp;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up MPU-6050
    if (wake_up_mpu6000(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert to degrees/second
            convert_to_degrees_per_second(gyro_x, gyro_y, gyro_z, &x, &y, &z);

            // Log data
            if (log_data(fp, x, y, z) != 0) {
                break; // Exit loop if logging fails
            }
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
            // Attempt to re-initialize I2C
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to re-open I2C bus");
                break; // Exit loop if re-initialization fails
            }
            if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
                perror("Failed to re-set I2C slave address");
                break;
            }
            if (wake_up_mpu6000(i2c_fd) < 0) {
                break;
            }
        }

        // Delay for 100ms (10 Hz sampling rate)
        usleep(100000);
    }

    // Close log file
    fclose(fp);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

