#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for L293D driver
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for push-buttons
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define the number of steps for a quarter turn (512 for 28BYJ-48)
#define NUM_STEPS 512

// Define the delay between steps (3 ms)
#define STEP_DELAY 3

// Debounce delay (50 ms)
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void cleanup(void);
void lock_action(void);
void unlock_action(void);
void step_motor(int steps, int direction);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting.\n");
        cleanup();
        exit(0);
    }
}

// Cleanup function to de-energize coils and terminate pigpio
void cleanup(void) {
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
}

// Function to rotate the motor clockwise
void lock_action(void) {
    printf("Locking...\n");
    step_motor(NUM_STEPS, 1); // Clockwise direction
    printf("Locking complete.\n");
}

// Function to rotate the motor counter-clockwise
void unlock_action(void) {
    printf("Unlocking...\n");
    step_motor(NUM_STEPS, -1); // Counter-clockwise direction
    printf("Unlocking complete.\n");
}

// Function to step the motor
void step_motor(int steps, int direction) {
    int i;
    for (i = 0; i < steps; i++) {
        // Full-step sequence (single-coil excitation)
        if (direction > 0) {
            gpioWrite(IN1, 1);
            gpioWrite(IN2, 0);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 0);
        } else {
            gpioWrite(IN1, 0);
            gpioWrite(IN2, 1);
            gpioWrite(IN3, 0);
            gpioWrite(IN4, 0);
        }
        gpioDelay(STEP_DELAY * 1000); // Delay in microseconds
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(IN1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN1 as output\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN2 as output\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN3 as output\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set IN4 as output\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON as input\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON as input\n");
        cleanup();
        return 1;
    }

    // Set pull-up resistors
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on LOCK_BUTTON\n");
        cleanup();
        return 1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on UNLOCK_BUTTON\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Automatic Door Lock Control\n");
    printf("Press LOCK button to lock, UNLOCK button to unlock.\n");

    // Main loop
    while (program_running) {
        // Check for LOCK button press
        if (gpioRead(LOCK_BUTTON) == 0) {
            lock_action();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
        }

        // Check for UNLOCK button press
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            unlock_action();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
        }

        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    cleanup();
    return 0;
}

