#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;
    double start_time, end_time, duration;
    double distance_cm;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10); // 10 us trigger pulse
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width with timeout
        start_time = time_time();
        while (gpioRead(ECHO_PIN) == 0) {
            if (time_time() - start_time > 0.05) { // 50 ms timeout
                fprintf(stderr, "Timeout waiting for rising edge\n");
                fprintf(log_file, "-1\n");
                fflush(log_file);
                continue; // Retry
            }
        }

        start_time = time_time();
        while (gpioRead(ECHO_PIN) == 1) {
            if (time_time() - start_time > 0.05) { // 50 ms timeout
                fprintf(stderr, "Timeout waiting for falling edge\n");
                fprintf(log_file, "-1\n");
                fflush(log_file);
                continue; // Retry
            }
        }

        end_time = time_time();
        duration = end_time - start_time;

        // Calculate distance
        distance_cm = duration * 0.01715;

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the distance
        fprintf(log_file, "%s, %.2f\n", timestamp, distance_cm);
        fflush(log_file);

        printf("Distance: %.2f cm\n", distance_cm);

        gpioDelay(60); // 60 ms guard time
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

