        while (gpioRead(ECHO_PIN) == 1) {
            if (time_time() - start_time > 0.05) { // 50 ms timeout
                fprintf(stderr, "Timeout waiting for falling edge\n");
                fprintf(log_file, "-1\n");
                fflush(log_file);
                continue; // Retry
            }
        }

        end_time = time_time();
        duration = end_time - start_time;

        // Calculate distance
        distance_cm = duration * 0.01715;

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the distance
        fprintf(log_file, "%s, %.2f\n", timestamp, distance_cm);
        fflush(log_file);

        printf("Distance: %.2f cm\n", distance_cm);

        gpioDelay(60); // 60 ms guard time
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

