#define VL53L1X_REG_RESULT_SPAD_NB_DETECTED 0x0046
#define VL53L1X_REG_RESULT_PEAK_SIGNAL_RATE 0x0048
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE 0x0096
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_LSB 0x0097

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_relay(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust as needed)
    char data[2];
    int status;

    // Reset the sensor (software reset)
    data[0] = 0x00;  // Register address
    data[1] = 0x00;  // Value to write
    status = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Corrected function name
    if (status < 0) {
        fprintf(stderr, "Error writing to VL53L1X: %d\n", status);
        return -1;
    }

    // Configure ranging mode and start continuous ranging (example)
    data[0] = 0x0080; // Register address for ranging mode
    data[1] = 0x01;  // Value to write
    status = i2cWriteI2CBlockData(i2c_handle, data[0], data+1, 1); // Corrected function name
    if (status < 0) {
        fprintf(stderr, "Error writing to VL53L1X: %d\n", status);
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L1X sensor
int read_distance(uint16_t *distance) {
    char data[1];
    char result[2];
    int status;

    // Read the MSB of the distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE;
    status = i2cWriteI2CBlockData(i2c_handle, data[0], NULL, 0); // Write register address
    if (status < 0) {
        fprintf(stderr, "Error writing register address for MSB: %d\n", status);
        return -1;
    }
    status = i2cReadI2CBlockData(i2c_handle, data[0], result, 1); // Read MSB
    if (status < 0) {
        fprintf(stderr, "Error reading MSB from VL53L1X: %d\n", status);
        return -1;
    }
    *distance = (uint16_t)result[0];

    // Read the LSB of the distance
    data[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_LSB;
    status = i2cWriteI2CBlockData(i2c_handle, data[0], NULL, 0); // Write register address
    if (status < 0) {
        fprintf(stderr, "Error writing register address for LSB: %d\n", status);
        return -1;
    }
    status = i2cReadI2CBlockData(i2c_handle, data[0], result, 1); // Read LSB
    if (status < 0) {
        fprintf(stderr, "Error reading LSB from VL53L1X: %d\n", status);
        return -1;
    }
    *distance = (*distance << 8) | (uint16_t)result[0]; // Combine MSB and LSB

    return 0;
}

