void control_relay(int state) {
    gpioWrite(GPIO_RELAY, state);
}

int main() {
    uint16_t distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity-based door system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);

            // Control relay based on distance
            if (distance <= DISTANCE_THRESHOLD * 10) { // Convert cm to mm
                control_relay(1); // Open the door
            } else {
                control_relay(0); // Close the door
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and exit
    control_relay(0); // Ensure relay is off on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

