#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

// Sensitivity scale factor for gyroscope (LSB/degree/sec)
#define GYRO_SENSITIVITY 131.0f

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the MPU-6050
int mpu6050_init(int fd)
{
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    if (i2c_write_reg(fd, GYRO_CONFIG, 0) != 0) {
        fprintf(stderr, "Error setting gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int mpu6050_read_gyro(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    uint8_t buf[6];
    uint8_t reg = GYRO_XOUT_H;

    // Write the register address to read from
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of gyroscope data
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw gyroscope data to degrees/second
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *x_dps, float *y_dps, float *z_dps)
{
    *x_dps = (float)gyro_x / GYRO_SENSITIVITY;
    *y_dps = (float)gyro_y / GYRO_SENSITIVITY;
    *z_dps = (float)gyro_z / GYRO_SENSITIVITY;
}

int main()
{
    int fd;
    int16_t gyro_x, gyro_y, gyro_z;
    float x_dps, y_dps, z_dps;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Initialize the MPU-6050
    if (mpu6050_init(fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(fd);
        return 1;
    }

    // Main loop to read and print gyroscope data
    while (!terminate) {
        // Read gyroscope data
        if (mpu6050_read_gyro(fd, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert raw data to degrees/second
            convert_gyro_data(gyro_x, gyro_y, gyro_z, &x_dps, &y_dps, &z_dps);

            // Print the gyroscope data
            printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s\n", x_dps, y_dps, z_dps);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for 100 milliseconds
        usleep(100000);
    }

    // Close the I2C device
    close(fd);

    return 0;
}

