#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int pin, int mode);
int set_pwm_frequency(int pin, int frequency);
int set_pwm_duty_cycle(int pin, int duty_cycle);
void log_event(const char *message);
void sunrise_simulation();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received shutdown signal. Shutting down...");

        // Turn off all relays
        set_pwm_duty_cycle(RELAY1_PIN, 0);
        set_pwm_duty_cycle(RELAY2_PIN, 0);
        set_pwm_duty_cycle(RELAY3_PIN, 0);
        set_pwm_duty_cycle(RELAY4_PIN, 0);

        // Terminate the pigpio library
        gpioTerminate();

        log_event("Shutdown complete. Exiting.");
        exit(0);
    }
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    log_event("pigpio initialised successfully");
    return 0; // Indicate success
}

// Function to set the mode of a GPIO pin
int set_gpio_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", pin);
        return 1; // Indicate failure
    }
    char message[50];
    sprintf(message, "GPIO %d mode set to %d", pin, mode);
    log_event(message);
    return 0; // Indicate success
}

// Function to set the PWM frequency of a GPIO pin
int set_pwm_frequency(int pin, int frequency) {
    if (gpioSetPWMfrequency(pin, frequency) != 0) {
        fprintf(stderr, "Failed to set frequency for pin %d\n", pin);
        return 1; // Indicate failure
    }
    char message[50];
    sprintf(message, "GPIO %d PWM frequency set to %d Hz", pin, frequency);
    log_event(message);
    return 0; // Indicate success
}

// Function to set the PWM duty cycle of a GPIO pin
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set duty cycle for pin %d\n", pin);
        return 1; // Indicate failure
    }
    char message[50];
    sprintf(message, "GPIO %d PWM duty cycle set to %d", pin, duty_cycle);
    log_event(message);
    return 0; // Indicate success
}

// Function to log an event to the log file
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to simulate the sunrise effect
void sunrise_simulation() {
    int duty_cycle;
    for (int i = 0; i <= 255 && program_running; ++i) {
        // Set the duty cycle for all relays simultaneously
        set_pwm_duty_cycle(RELAY1_PIN, i);
        set_pwm_duty_cycle(RELAY2_PIN, i);
        set_pwm_duty_cycle(RELAY3_PIN, i);
        set_pwm_duty_cycle(RELAY4_PIN, i);

        // Log the current state
        char message[100];
        sprintf(message, "Sunrise simulation: Duty cycle = %d", i);
        log_event(message);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Turn off all relays
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    log_event("Sunrise simulation complete");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Set the mode of each GPIO pin to output
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set the PWM frequency to 1 kHz for all relays
    if (set_pwm_frequency(RELAY1_PIN, 1000) != 0 ||
        set_pwm_frequency(RELAY2_PIN, 1000) != 0 ||
        set_pwm_frequency(RELAY3_PIN, 1000) != 0 ||
        set_pwm_frequency(RELAY4_PIN, 1000) != 0) {
        gpioTerminate();
        return 1;
    }

    // Simulate the sunrise effect
    log_event("Starting sunrise simulation");
    sunrise_simulation();

    // Clean up and exit
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

