#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO 8

// Scale factor for gyroscope data
#define GYRO_SCALE 131.0

// File to log data
#define LOG_FILE "gyro_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int reg);
int spi_write_register(int reg, int value);
int read_gyro_data(float *x_rate, float *y_rate, float *z_rate);
void log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);

// Structure to hold gyroscope data
typedef struct {
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;

// Function to read a single register via SPI
int spi_read_register(int reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read operation
    tx[1] = 0x00;       // Dummy byte

    gpioWrite(CS_GPIO, 0); // Assert CS
    int result = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_GPIO, 1); // De-assert CS

    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    return rx[1]; // Return the read value
}

// Function to write a single register via SPI
int spi_write_register(int reg, int value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = value;

    gpioWrite(CS_GPIO, 0); // Assert CS
    int result = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(CS_GPIO, 1); // De-assert CS

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to read gyroscope data
int read_gyro_data(float *x_rate, float *y_rate, float *z_rate) {
    char tx[7], rx[7];
    tx[0] = GYRO_XOUT_H | 0x80; // Read X, Y, and Z

    gpioWrite(CS_GPIO, 0); // Assert CS
    int result = spiXfer(spi_handle, tx, rx, 7);
    gpioWrite(CS_GPIO, 1); // De-assert CS

    if (result != 7) {
        fprintf(stderr, "SPI burst read error: %d\n", result);
        return -1; // Indicate error
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (rx[2] << 8) | rx[1];
    int16_t raw_y = (rx[4] << 8) | rx[3];
    int16_t raw_z = (rx[6] << 8) | rx[5];

    // Convert to degrees per second
    *x_rate = (float)raw_x / GYRO_SCALE;
    *y_rate = (float)raw_y / GYRO_SCALE;
    *z_rate = (float)raw_z / GYRO_SCALE;

    return 0; // Indicate success
}

// Function to log data to file
void log_data(float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Format timestamp with nanoseconds
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

    // Write to log file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS GPIO as output
    gpioSetMode(CS_GPIO, PI_OUTPUT);
    gpioWrite(CS_GPIO, 1); // Initialize CS to high

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&gyro_data.x_rate, &gyro_data.y_rate, &gyro_data.z_rate) == 0) {
            log_data(gyro_data.x_rate, gyro_data.y_rate, gyro_data.z_rate);
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

