#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// GPIO pin for LED
#define LED_PIN 21

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_raw_accel_data(int16_t *x, int16_t *y, int16_t *z);
void calculate_roll_pitch(int16_t x, int16_t y, int16_t z, float *roll, float *pitch);
void control_led(float roll, float pitch);
void log_data(float roll, float pitch);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the sensor
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set accelerometer full-scale range to ±2g
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read raw accelerometer data
int read_raw_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Calculate roll and pitch angles
void calculate_roll_pitch(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    float x_g = (float)x / 16384.0; // Convert to g
    float y_g = (float)y / 16384.0;
    float z_g = (float)z / 16384.0;

    *roll = atan2(y_g, z_g) * 180.0 / M_PI;
    *pitch = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float roll, pitch;

    // Main loop
    while (!terminate) {
        // Read raw accelerometer data
        if (read_raw_accel_data(&x, &y, &z) == 0) {
            // Calculate roll and pitch
            calculate_roll_pitch(x, y, z, &roll, &pitch);

            // Control LED
            control_led(roll, pitch);

            // Log data
            log_data(roll, pitch);

            // Print roll and pitch to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read accelerometer data. Retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

