#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define LED_GPIO_CHIP "gpiochip0"
#define LED_GPIO_PIN 17

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;

// Function prototypes
int i2c_read_register(int fd, unsigned char reg, unsigned char *value);
int i2c_write_register(int fd, unsigned char reg, unsigned char value);
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity);
void log_sensor_data(FILE *fp, unsigned short ambient_light, unsigned short proximity);
void set_led_state(struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C read register function with retry
int i2c_read_register(int fd, unsigned char reg, unsigned char *value) {
    int retries = 3;
    int delay_ms = 10;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register address) failed");
            retries--;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }
        if (read(fd, value, 1) != 1) {
            perror("I2C read failed");
            retries--;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure after retries
}

// I2C write register function with retry
int i2c_write_register(int fd, unsigned char reg, unsigned char value) {
    int retries = 3;
    int delay_ms = 10;
    while (retries > 0) {
        unsigned char buf[2] = {reg, value};
        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(delay_ms * 1000); // Convert ms to microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }
        return 0; // Success
    }
    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure after retries
}

// Read sensor data function
int read_sensor_data(int fd, unsigned short *ambient_light, unsigned short *proximity) {
    unsigned char ambient_light_lsb, ambient_light_msb, proximity_lsb, proximity_msb;

    if (i2c_read_register(fd, AMBIENT_LIGHT_REG, &ambient_light_lsb) != 0) return -1;
    if (i2c_read_register(fd, AMBIENT_LIGHT_REG + 1, &ambient_light_msb) != 0) return -1;
    if (i2c_read_register(fd, PROXIMITY_REG, &proximity_lsb) != 0) return -1;
    if (i2c_read_register(fd, PROXIMITY_REG + 1, &proximity_msb) != 0) return -1;

    *ambient_light = (ambient_light_msb << 8) | ambient_light_lsb;
    *proximity = (proximity_msb << 8) | proximity_lsb;

    return 0;
}

// Log sensor data function
void log_sensor_data(FILE *fp, unsigned short ambient_light, unsigned short proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp); // Ensure data is written to file immediately
}

// Set LED state function
void set_led_state(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set LED state");
    }
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_chip != NULL) {
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(LED_GPIO_CHIP);
    if (gpio_chip == NULL) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line for LED
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO_PIN);
    if (led_line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "biometric_app", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    unsigned short ambient_light, proximity;

    // Main loop
    while (1) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_sensor_data(log_file, ambient_light, proximity);
            set_led_state(led_line, (proximity > 100) ? 1 : 0);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        usleep(100000); // 100 ms
    }

    return 0;
}

