#define ADXRS290_REG_Y_RATE 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Sensitivity (LSB/deg/s)
#define SENSITIVITY 200.0

// Sampling Rate (Hz)
#define SAMPLING_RATE 100

// Delay for 10 ms (microseconds)
#define DELAY_US 10000

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_register(int reg);
int16_t read_gyro_axis(int reg);
void log_data(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
int initialize_spi();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read a register
int read_register(int reg) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (reg << 1) | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    return rx_buf[1];
}

// Function to read gyro axis data
int16_t read_gyro_axis(int reg) {
    int high_byte = read_register(reg);
    int low_byte = read_register(reg + 1);

    if (high_byte < 0 || low_byte < 0) {
        return 0; // Return 0 on error
    }

    return (int16_t)((high_byte << 8) | low_byte);
}

// Function to log data to file
void log_data(int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_us = (ts.tv_sec * 1000000) + ts.tv_nsec / 1000;

    fprintf(fp, "%ld,%d,%d\n", timestamp_us, x_rate, y_rate);
    fflush(fp); // Ensure data is written to disk immediately
}

