        gpioTerminate();
        return 1;
    }

    // Open data file
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(fp, "timestamp_us,X_rate,Y_rate\n"); // Write header

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t x_rate = read_gyro_axis(ADXRS290_REG_X_RATE);
        int16_t y_rate = read_gyro_axis(ADXRS290_REG_Y_RATE);

        log_data(x_rate, y_rate);

        gpioDelay(DELAY_US); // Delay for 10 ms
    }

    // Cleanup
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

