#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_SENSITIVITY 200.0 // LSB/deg/s
#define THRESHOLD 20.0 // deg/s
#define LED_GPIO 17
#define CIRCULAR_BUFFER_SIZE 100

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    struct timespec timestamp[CIRCULAR_BUFFER_SIZE];
    int16_t data[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t gyro_buffer;

// Function prototypes
int init_gpio();
int init_spi();
int read_gyro_data(int16_t *rate_x);
void convert_to_deg_per_second(int16_t raw_data, float *deg_per_second);
void add_to_circular_buffer(struct timespec timestamp, int16_t data);
void check_threshold_and_control_led(float deg_per_second);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

int main() {
    int16_t raw_rate_x;
    float deg_per_second;
    struct timespec ts;

    // Initialize
    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    init_circular_buffer(&gyro_buffer);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&raw_rate_x) == 0) {
            convert_to_deg_per_second(raw_rate_x, &deg_per_second);
            clock_gettime(CLOCK_MONOTONIC, &ts);
            add_to_circular_buffer(ts, raw_rate_x);
            check_threshold_and_control_led(deg_per_second);

            // Print the data (for debugging)
            printf("Timestamp: %ld.%09ld, Raw Rate: %d, Degrees/s: %.2f\n", ts.tv_sec, ts.tv_nsec, raw_rate_x, deg_per_second);
        } else {
            fprintf(stderr, "Failed to read gyro data.\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED
    return 0;
}

int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

int read_gyro_data(int16_t *rate_x) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of address to 1 for read operation
    tx_buf[0] = 0x02 | 0x80; // RATE_XL
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) == 2) {
        *rate_x = (rx_buf[0] << 8) | rx_buf[1];
        return 0;
    } else {
        fprintf(stderr, "SPI transfer failed\n");
        return 1;
    }
}

void convert_to_deg_per_second(int16_t raw_data, float *deg_per_second) {
    *deg_per_second = (float)raw_data / GYRO_SENSITIVITY;
}

void add_to_circular_buffer(struct timespec timestamp, int16_t data) {
    gyro_buffer.timestamp[gyro_buffer.head] = timestamp;
    gyro_buffer.data[gyro_buffer.head] = data;
    gyro_buffer.head = (gyro_buffer.head + 1) % CIRCULAR_BUFFER_SIZE;
    if (gyro_buffer.count < CIRCULAR_BUFFER_SIZE) {
        gyro_buffer.count++;
    }
}

void check_threshold_and_control_led(float deg_per_second) {
    if (abs(deg_per_second) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

