#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 255

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating program...\n", signal);
    program_running = 0;
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration_seconds) {
    int brightness;
    for (int i = 0; i <= duration_seconds * 100 && program_running; ++i) {
        brightness = 255 - (int)((float)i / duration_seconds * 255.0);
        if (brightness < 0) brightness = 0;
        set_lamp_brightness(gpio, brightness);
        gpioDelay(10000); // 10ms delay
    }
    set_lamp_brightness(gpio, 0);
    printf("Lamp on GPIO %d faded out.\n", gpio);
}

int main(int argc, char *argv[]) {
    int duration;

    // Validate the command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        return 1;
    }

    duration = atoi(argv[1]);
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: Fade duration must be a positive integer and less than 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sunset simulation...\n");

    // Fade lamps sequentially
    fade_lamp(LAMP1_GPIO, duration_seconds);
    fade_lamp(LAMP2_GPIO, duration_seconds);
    fade_lamp(LAMP3_GPIO, duration_seconds);

    printf("Sunset simulation complete.\n");

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

