#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays (active-low)
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define ALL_CLEAR_PIN 24

// Function prototypes
void set_traffic_light(int red, int yellow, int green);
void red_state();
void red_yellow_state();
void green_state();
void yellow_state();
void all_clear_state();
void cleanup_handler(int signum);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(ALL_CLEAR_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup_handler);
    signal(SIGTERM, cleanup_handler);

    // Main loop
    while (program_running) {
        red_state();
        red_yellow_state();
        green_state();
        yellow_state();
        all_clear_state();
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

// Function to set the traffic light state
void set_traffic_light(int red, int yellow, int green) {
    gpioWrite(RED_PIN, red);
    gpioWrite(YELLOW_PIN, yellow);
    gpioWrite(GREEN_PIN, green);
    printf("Traffic Light: Red=%d, Yellow=%d, Green=%d\n", red, yellow, green);
}

// Function to represent the red state
void red_state() {
    set_traffic_light(1, 0, 0);
    sleep(10);
}

// Function to represent the red+yellow state
void red_yellow_state() {
    set_traffic_light(1, 1, 0);
    sleep(2);
}

// Function to represent the green state
void green_state() {
    set_traffic_light(0, 0, 1);
    sleep(10);
}

