#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define MPR121_TOUCH_STATUS_REG 0x00
#define MPR121_TOUCH_STATUS_MSB_REG 0x01
#define MPR121_ELECTRODE_CONFIG_REG 0x5D
#define MPR121_TOUCH_THRESHOLD_REG 0x41
#define MPR121_RELEASE_THRESHOLD_REG 0x42
#define MPR121_DEBOUNCE_REG 0x5B
#define MPR121_CHARGE_TIME_REG 0x5C
#define MPR121_RUN_MODE_REG 0x5E

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, exiting...");
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Error setting GPIO mode");
        return -1;
    }
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0); // Bus 1, address 0x5A, no flags
    if (i2c_handle < 0) {
        log_message("Error opening I2C device");
        return -1;
    }
    return 0;
}

// Initialize MPR121
int init_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Error resetting MPR121");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Configure MPR121 for electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG_REG, 0x01) < 0) {
        log_message("Error configuring electrode");
        return -1;
    }

    // Set touch and release thresholds
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD_REG, 0x0A) < 0) {
        log_message("Error setting touch threshold");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD_REG, 0x08) < 0) {
        log_message("Error setting release threshold");
        return -1;
    }

    // Configure debounce and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE_REG, 0x21) < 0) {
        log_message("Error setting debounce");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_CHARGE_TIME_REG, 0x0D) < 0) {
        log_message("Error setting charge time");
        return -1;
    }

    // Set run mode
    if (i2cWriteByteData(i2c_handle, MPR121_RUN_MODE_REG, 0x0D) < 0) {
        log_message("Error setting run mode");
        return -1;
    }

    return 0;
}

// Read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCH_STATUS_REG, buf, 2) != 2) {
        log_message("Error reading touch status");
        return -1;
    }

    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    char message[100];
    snprintf(message, sizeof(message), "Relay toggled to %s", !current_state ? "ON" : "OFF");
    log_message(message);
}

// Log messages to file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        log_message("GPIO initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        log_message("I2C initialization failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() != 0) {
        log_message("MPR121 initialization failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_message("System initialized");

    uint16_t touch_status = 0;
    uint16_t last_touch_status = 0;
    time_t last_touch_time = 0;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status & (1 << 0)) { // Check electrode 0
                time_t current_time = time(NULL);
                if ((touch_status & last_touch_status) == 0 && (last_touch_status & (1 << 0)) == 0) { // New touch on electrode 0
                    if (difftime(current_time, last_touch_time) > 0.1) { // Debounce
                        toggle_relay();
                        last_touch_time = current_time;
                    }
                }
                last_touch_status = touch_status;
            }
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    fclose(log_file);
    gpioTerminate();

    log_message("System exiting");
    return 0;
}

