#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_flame_sensor(int pin);
void activate_alarm(int buzzer_pin, int led_pin);
void deactivate_alarm(int buzzer_pin, int led_pin);
void log_flame_detection(const char *filename);
void signal_handler(int signal);

// Function to read the flame sensor with debouncing
int read_flame_sensor(int pin) {
    int value = gpioRead(pin);
    if (value == 0) { // Flame detected (active low)
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
        if (gpioRead(pin) == 0) { // Re-read after delay
            return 1; // Flame still detected
        }
    }
    return 0; // No flame detected
}

// Function to activate the alarm (buzzer and LED)
void activate_alarm(int buzzer_pin, int led_pin) {
    gpioWrite(buzzer_pin, 1); // Turn on buzzer
    gpioWrite(led_pin, 1);    // Turn on LED
}

// Function to deactivate the alarm (buzzer and LED)
void deactivate_alarm(int buzzer_pin, int led_pin) {
    gpioWrite(buzzer_pin, 0); // Turn off buzzer
    gpioWrite(led_pin, 0);    // Turn off LED
}

// Function to log flame detection events
void log_flame_detection(const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s Flame Detected\n", timestamp);
    fclose(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    deactivate_alarm(BUZZER_PIN, LED_PIN);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

