    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fire Alarm System running...\n");

    // Main loop
    while (running) {
        if (read_flame_sensor(FLAME_SENSOR_PIN)) {
            printf("Flame Detected!\n");
            activate_alarm(BUZZER_PIN, LED_PIN);
            log_flame_detection("flame_log.txt");
            while (read_flame_sensor(FLAME_SENSOR_PIN)) {
                gpioDelay(100000); // Check every 100ms
            }
            deactivate_alarm(BUZZER_PIN, LED_PIN);
        }
        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm(BUZZER_PIN, LED_PIN);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

