#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N Enable Pins
#define ENA 24
#define ENB 25

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Distance Sensor Range
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

// Log File
#define LOG_FILE "balance_log.txt"

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
void signal_handler(int signal);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
int calculate_pid(float tilt_error, float *integral, float *previous_error);
void set_motor_speed(int motor, int speed);
void stop_motors();

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, stopping motors and exiting.\n");
        stop_motors();
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// Log Data Function
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// PID Calculation Function
int calculate_pid(float tilt_error, float *integral, float *previous_error) {
    float proportional = Kp * tilt_error;
    *integral += Ki * tilt_error;
    float derivative = Kd * (tilt_error - *previous_error);
    float output = proportional + *integral + derivative;

    // Clamp the output to -255 and 255
    if (output > 255) {
        output = 255;
    } else if (output < -255) {
        output = -255;
    }

    *previous_error = tilt_error;
    return (int)output;
}

// Set Motor Speed Function
void set_motor_speed(int motor, int speed) {
    if (speed > 255) {
        speed = 255;
    } else if (speed < -255) {
        speed = -255;
    }

    if (motor == 0) { // Motor A
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENA, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, 0);
        }
    } else { // Motor B
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENB, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, 0);
        }
    }
}

// Stop Motors Function
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENA, 0);
    gpioPWM(ENB, 0);
}

int main() {
    float tilt_error;
    float integral = 0.0;
    float previous_error = 0.0;
    float distance;
    int motor_a_speed, motor_b_speed;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Enable PWM on ENA and ENB
    gpioPWM(ENA, 0); // Initialize to 0
    gpioPWM(ENB, 0); // Initialize to 0

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Self-balancing robot simulation started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Simulate tilt error
        tilt_error = (float)(rand() % 2000 - 1000) / 10.0; // Random float between -10.0 and 10.0

        // Simulate distance sensor
        distance = (float)(rand() % (int)((MAX_DISTANCE - MIN_DISTANCE) * 0.5 + MIN_DISTANCE) + MIN_DISTANCE); // Random float between MIN_DISTANCE and MAX_DISTANCE

        // Calculate motor speeds using PID
        motor_a_speed = calculate_pid(tilt_error, &integral, &previous_error);
        motor_b_speed = calculate_pid(tilt_error, &integral, &previous_error);

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            printf("Obstacle detected! Reversing motors.\n");
            motor_a_speed = -50;
            motor_b_speed = -50;
        }

        // Set motor speeds
        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

