#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global variable to store the relay state
int relay_state = 0;

// Function prototypes
int read_touch_sensor();
void toggle_relay();
void debounce_delay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // De-energize the relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to state: %d\n", relay_state);
}

// Function to introduce a debounce delay
void debounce_delay() {
    gpioDelay(50000); // 50 ms delay
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on the touch sensor pin
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Smart Light Switch Simulation running...\nPress Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
            debounce_delay();
        }
        gpioDelay(1000); // Small delay to reduce CPU usage
    }

    return 0; // This line will never be reached due to the infinite loop
}

