#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// ALSA parameters
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 2 // 16-bit samples
#define PERIOD_SIZE 1024

// Global variables
snd_pcm_t *pcm_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(const short *buffer, int buffer_size);
void map_rms_to_rgb(double rms, double sensitivity, int *red, int *green, int *blue);
int set_led_color(int red, int green, int blue);
void signal_handler(int sig);
void cleanup();

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize ALSA audio capture
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format to 16-bit signed little-endian
