#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDR 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Integration time (ATIME) - 154ms
#define TCS34725_INTEGRATIONTIME 0xD5

// Gain (AGAIN) - 60x
#define TCS34725_GAIN 0x03

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable power and ALS
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to enable register: %d\n", i2c_handle);
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATIONTIME) < 0) {
        fprintf(stderr, "Error writing to integration time register: %d\n", i2c_handle);
        return -1;
    }

    // Set gain
    if (i2cWriteByteData(i2c_handle, 0x8F, TCS34725_GAIN) < 0) {
        fprintf(stderr, "Error writing to gain register: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read color data from the TCS34725 sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buffer, 8) < 0) {
        fprintf(stderr, "Error reading color data: %d\n", i2c_handle);
        return -1;
    }

    // Extract the values from the buffer
    *clear = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    *red   = (uint16_t)buffer[2] | ((uint16_t)buffer[3] << 8);
    *green = (uint16_t)buffer[4] | ((uint16_t)buffer[5] << 8);
    *blue  = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);

    return 0;
}

// Function to log data to a CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_tcs34725() < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for writing
    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row
    fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t clear, red, green, blue;

        // Read color data
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            // Log the data
            log_data(clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading color data, setting values to 0\n");
            log_data(0, 0, 0, 0); // Log 0 values on error
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

