#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define SENSOR_PIN 17 // GPIO 17 (physical pin 11)
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char filename[100];
    char log_entry[200];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Motion detected (LOW signal)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

            // Create filename
            snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

            // Create log entry
            snprintf(log_entry, sizeof(log_entry), "%s Motion detected\n", timestamp);

            // Execute raspivid
            int ret = system("raspivid -o " + string(filename) + " -t 5000");
            if (ret == -1) {
                fprintf(stderr, "Error executing raspivid\n");
            } else if (WEXITSTATUS(ret) != 0) {
                fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(ret));
            }

            // Log event
            log_file = fopen(LOG_FILE, "a");
            if (log_file != NULL) {
                fprintf(log_file, "%s", log_entry);
                fclose(log_file);
            } else {
                fprintf(stderr, "Error opening log file\n");
            }

            // Debounce: Wait for 200ms
            gpioDelay(200000); // 200ms
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Clean up
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

