#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL   0x2D
#define DATA_FORMAT 0x31
#define DATAX0      0x32

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// GPIO pin for alarm
#define ALARM_PIN 27

// I2C handle
int i2c_handle;

// Function prototypes
int adxl345_init();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
    exit(0);
}

// ADXL345 initialization function
int adxl345_init() {
    // Set POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    // Set DATA_FORMAT register for ±2g range and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to convert raw acceleration data to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 256.0f;
}

// Function to detect freefall
int detect_freefall(float x, float y, float z) {
    static int freefall_count = 0;
    static time_t freefall_start_time = 0;

    if (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD) {
        freefall_count++;
        if (freefall_count >= (int)(FREEFALL_DURATION * 1000)) { // 100ms intervals
            if (freefall_start_time == 0) {
                freefall_start_time = time(NULL);
            }
            if (time(NULL) - freefall_start_time >= FREEFALL_DURATION) {
                return 1; // Freefall confirmed
            }
        } else {
            freefall_start_time = 0; // Reset timer if not long enough
        }
    } else {
        freefall_count = 0; // Reset count if not in freefall
        freefall_start_time = 0; // Reset timer
    }

    return 0; // Not confirmed
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set GPIO high
    gpioDelay(5000);         // Wait for 5 seconds
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
}

// Function to log freefall event to file
void log_freefall(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening freefall.log file\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure it starts low

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("ADXL345 freefall detection started. Press Ctrl+C to exit.\n");

    int16_t raw_x, raw_y, raw_z;
    float x_g, y_g, z_g;

    while (1) {
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            x_g = convert_to_g(raw_x);
            y_g = convert_to_g(raw_y);
            z_g = convert_to_g(raw_z);

            if (detect_freefall(x_g, y_g, z_g)) {
                printf("Freefall detected!\n");
                trigger_alarm();
                log_freefall(x_g, y_g, z_g);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Read every 100ms
    }

    return 0;
}

