void log_distance(double distance) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    uint64_t timestamp_ns = (uint64_t)tv.tv_sec * 1000000000ULL + (uint64_t)tv.tv_usec * 1000ULL;

    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
