#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Buzzer GPIO
#define BUZZER_GPIO 17

// Default freefall and impact thresholds (in g)
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

// Global variables
int i2c_handle;
double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
double impact_threshold = DEFAULT_IMPACT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int config_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double convert_to_g(int16_t raw_value);
double calculate_magnitude(double x, double y, double z);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    double x;
    double y;
    double z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        if (argc > 2) {
            impact_threshold = atof(argv[2]);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH configuration failed\n");
        cleanup();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    deactivate_buzzer(); // Ensure buzzer is off initially

    int16_t raw_x, raw_y, raw_z;
    accelerometer_data_t accel_data;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            // Convert raw data to g
            accel_data.x = convert_to_g(raw_x);
            accel_data.y = convert_to_g(raw_y);
            accel_data.z = convert_to_g(raw_z);

            // Calculate acceleration magnitude
            magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

            // Freefall detection
            if (magnitude < freefall_threshold) {
                printf("Freefall detected! Magnitude: %.3f g\n", magnitude);
                activate_buzzer();
                gpioDelay(1000); // Buzzer on for 1 second
                deactivate_buzzer();
            }

            // Impact detection
            else if (magnitude > impact_threshold) {
                printf("Impact detected! Magnitude: %.3f g\n", magnitude);
                activate_buzzer();
                gpioDelay(1000); // Buzzer on for 1 second
                deactivate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(10); // Delay for 10ms (100 Hz data rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LIS3DH_ADDR, 0); // Bus 1, address 0x18, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure LIS3DH
int config_lis3dh() {
    // Enable accelerometer, 100 Hz data rate, ±2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }

    // Set full scale range to ±2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return 1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) == 6) {
            // Combine high and low bytes for each axis
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Failed to read acceleration data, retrying...\n");
            retries--;
            gpioDelay(10); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries\n");
    return 1; // Failure
}

// Convert raw data to g
double convert_to_g(int16_t raw_value) {
    return (double)raw_value / 16384.0;
}

// Calculate acceleration magnitude
double calculate_magnitude(double x, double y, double z) {
    return sqrt(x * x + y * y + z * z);
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Set GPIO high
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Set GPIO low
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    deactivate_buzzer(); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

