    int in1, in2, in3, in4;

    if (motor == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor);
        return;
    }

    gpioWrite(in1, (step & 1) ? 1 : 0);
    gpioWrite(in2, (step & 2) ? 1 : 0);
    gpioWrite(in3, (step & 4) ? 1 : 0);
    gpioWrite(in4, (step & 8) ? 1 : 0);
}

// Function to move a motor a specified number of steps
void move_motor(int motor, int steps) {
    int i, step;
    for (i = 0; i < steps && !terminate; i++) {
        step = (i * 4) % 8; // 4-step wave drive
        set_motor_pins(motor, step);
        gpioDelay(STEP_DELAY);
    }
}

// Function to draw a square
void draw_square(int side_length_mm) {
    int steps = (int)(side_length_mm * STEPS_PER_MM);

    // Move right
    printf("Moving right: %d steps\n", steps);
    move_motor(1, steps);

    // Move up
    printf("Moving up: %d steps\n", steps);
    move_motor(2, steps);

    // Move left
    printf("Moving left: %d steps\n", steps);
    move_motor(1, -steps); // Subtract steps to move left

    // Move down
    printf("Moving down: %d steps\n", steps);
    move_motor(2, -steps); // Subtract steps to move down
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    int pins[] = {MOTOR1_IN1, MOTOR1_IN2, MOTOR1_IN3, MOTOR1_IN4, MOTOR2_IN1, MOTOR2_IN2, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Draw a square with 50mm sides
    draw_square(50);

    // Stop motors and terminate pigpio
    printf("Stopping motors and exiting...\n");
    set_motor_pins(1, 0);
    set_motor_pins(2, 0);
    gpioTerminate();

    return 0;
}

