#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH Registers
#define LIS3DH_ADDR_REG 0x20
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Configuration
#define DEFAULT_I2C_ADDR 0x18
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_RATE 10 // Hz
#define SLEEP_TIME_US (1000000 / SAMPLE_RATE) // microseconds

// Global variables
static int i2c_handle = -1;
static float threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDR;
static volatile int running = 1;

// Function prototypes
int init_i2c(int address);
int config_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_event(float x, float y, float z);
void shutdown_system();
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize I2C
int init_i2c(int address) {
    if (address < 0x08 || address > 0x77) {
        fprintf(stderr, "Error: Invalid I2C address: 0x%02X\n", address);
        return -1;
    }

    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        return -1;
    }

    return i2c_handle;
}

// Function to configure the LIS3DH
int config_lis3dh(int i2c_handle) {
    // High-resolution mode, ±2g range, 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG1\n");
        return -1;
    }

    // 100 Hz ODR
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error: Could not write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes, shift right 4 bits, and scale
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x * 0.0009765625f;
    *y = (float)raw_y * 0.0009765625f;
    *z = (float)raw_z * 0.0009765625f;

    return 0;
}

// Function to log an event
void log_event(float x, float y, float z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - X: %.4f g, Y: %.4f g, Z: %.4f g\n", s, x, y, z);
    fclose(fp);
}

// Function to shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        int addr = strtol(argv[1], NULL, 16);
        if (addr >= 0x08 && addr <= 0x77) {
            i2c_address = addr;
        } else {
            fprintf(stderr, "Error: Invalid I2C address: 0x%02X\n", addr);
            return 1;
        }
    }

    if (argc > 2) {
        threshold = strtof(argv[2], NULL);
        if (threshold <= 0) {
            fprintf(stderr, "Error: Invalid threshold value: %.2f\n", threshold);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (config_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    accelerometer_data_t data;

    // Main loop
    while (running) {
        if (read_acceleration(i2c_handle, &data.x, &data.y, &data.z) == 0) {
            // Check for threshold exceedance
            if (fabs(data.x) > threshold || fabs(data.y) > threshold || fabs(data.z) > threshold) {
                log_event(data.x, data.y, data.z);
                shutdown_system();
                break; // Exit loop after shutdown is initiated
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Using default values.\n");
            data.x = 0.0f;
            data.y = 0.0f;
            data.z = 0.0f;
        }

        gpioDelay(SLEEP_TIME_US); // Sleep for the specified sample rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

