#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define CENTER_SENSOR 17
#define RIGHT_SENSOR 27
#define ALERT_PIN 22

// Circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} sensor_reading_t;

// Circular buffer
sensor_reading_t sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void update_buffer(int left, int center, int right);
int check_alert_condition(int center_reading);
void motor_forward();
void motor_left();
void motor_right();
void motor_stop();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        // Update the circular buffer
        update_buffer(left_value, center_value, right_value);

        // Check for alert condition
        if (check_alert_condition(center_value)) {
            gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
            gpioDelay(2000);          // Wait for 2 seconds
            gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW
        }

        // Line-following logic (placeholder)
        if (center_value == 0) {
            motor_forward();
        } else if (left_value == 0) {
            motor_left();
        } else if (right_value == 0) {
            motor_right();
        } else {
            motor_stop();
        }

        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Clean up and exit
    motor_stop();
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to update the circular buffer
void update_buffer(int left, int center, int right) {
    sensor_buffer[buffer_index].left = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check for alert condition (center sensor reads 'no line' for 5 consecutive readings)
int check_alert_condition(int center_reading) {
    static int alert_count = 0;
    static int no_line_count = 0;

    if (center_reading == 1) {
        no_line_count = 0; // Reset counter if line is detected
        alert_count = 0;
    } else {
        no_line_count++;
        if (no_line_count >= 5) {
            alert_count++;
            no_line_count = 0; // Reset no_line_count after checking alert condition
        }
    }

    return (alert_count >= 3); // Require 3 consecutive no-line readings for alert
}

