}
void motor_left() {
    printf("Motor left\n");
}
void motor_right() {
    printf("Motor right\n");
}
void motor_stop() {
    printf("Motor stop\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    program_running = 0; // Set flag to exit main loop
}

