int read_field_raw() {
    int retries = 0;
    int field_raw = -1; // Initialize to an error value

    while (retries < RETRY_COUNT) {
        if (i2cWriteByteData(i2c_handle, CONVERSION_REG, 0x01) != 0) {
            fprintf(stderr, "Error writing to conversion register\n");
            log_event("Error writing to conversion register");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Poll the conversion register until it reads 0x00
        while (i2cReadByte(i2c_handle, CONVERSION_REG) == 0x01 && retries < RETRY_COUNT) {
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries++;
        }

        if (retries >= RETRY_COUNT) {
            fprintf(stderr, "Timeout waiting for conversion\n");
            log_event("Timeout waiting for conversion");
            return -1; // Timeout error
        }

        // Read the MSB and LSB registers
        int msb = i2cReadByteData(i2c_handle, MSB_REG);
        int lsb = i2cReadByteData(i2c_handle, LSB_REG);

        if (msb < 0 || lsb < 0) {
            fprintf(stderr, "Error reading MSB/LSB registers\n");
            log_event("Error reading MSB/LSB registers");
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        field_raw = (msb << 8) | lsb;
        break; // Exit the loop if read is successful
    }

    if (field_raw == -1) {
        fprintf(stderr, "Failed to read field data after multiple retries\n");
        log_event("Failed to read field data after multiple retries");
