#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define MAX_CLIENTS 5
#define BUFFER_SIZE 1024

int server_fd, new_socket;
FILE *log_file;

// Function to log events with timestamps
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signum) {
    char log_message[100];
    sprintf(log_message, "Signal received, shutting down...");
    log_event(log_message);

    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }

    gpioWrite(GPIO_PIN, 0); // Turn off the relay
    gpioTerminate();       // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int addrlen = sizeof(struct sockaddr_in);
    char buffer[BUFFER_SIZE] = {0};
    int valread;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Server started");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially off

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_event("Socket creation failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_event("setsockopt failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event("Bind failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, MAX_CLIENTS) < 0) {
        log_event("Listen failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_event("Listening for connections...");

    // Accept connections in a loop
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            log_event("Accept failed");
            continue; // Continue listening
        }

        log_event("Connection accepted");

        // Handle client connection
        while ((valread = read(new_socket, buffer, BUFFER_SIZE - 1)) > 0) {
            buffer[valread] = '\0'; // Null-terminate the buffer
            char command[50];
            strncpy(command, buffer, sizeof(command) - 1);
            command[sizeof(command) - 1] = '\0'; // Ensure null termination

            // Remove trailing whitespace
            int i = sizeof(command) - 1;
            while (i > 0 && command[i - 1] == ' ') {
                command[i - 1] = '\0';
                i--;
            }

            char log_message[100];
            sprintf(log_message, "Received command: %s", command);
            log_event(log_message);

            if (strcmp(command, "ON") == 0 || strcmp(command, "on") == 0) {
                gpioWrite(GPIO_PIN, 1); // Turn on the relay
                log_event("Relay ON");
            } else if (strcmp(command, "OFF") == 0 || strcmp(command, "off") == 0) {
                gpioWrite(GPIO_PIN, 0); // Turn off the relay
                log_event("Relay OFF");
            } else {
                sprintf(log_message, "Invalid command received: %s", command);
                log_event(log_message);
            }
        }

        if (valread == 0) {
            log_event("Client disconnected");
        } else if (valread < 0) {
            log_event("Read error");
        }

        close(new_socket);
        new_socket = 0; // Reset new_socket for the next connection
    }

    // The following lines will never be reached due to the infinite loop.
    close(server_fd);
    gpioTerminate();
    fclose(log_file);
    return 0;
}

