#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1.0/1500.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_FINAL_XOR 0x00

// Global variables
volatile sig_atomic_t terminate = 0;
FILE *log_file = NULL;
int i2c_handle1 = -1;
int i2c_handle2 = -1;

// Function prototypes
int write_sensor(int handle, const uint8_t *data, int count);
int read_sensor(int handle, uint8_t *data, int count);
float convert_to_ml_min(int16_t raw_value);
uint8_t calculate_crc(const uint8_t *data, int len);
void log_data(float flow1, float flow2);
void set_relay_state(int state);
void signal_handler(int signal);

// Function to write data to the sensor
int write_sensor(int handle, const uint8_t *data, int count) {
    int result = i2cWriteDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to ml/min
float convert_to_ml_min(int16_t raw_value) {
    return (float)raw_value * SCALE_FACTOR;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log data to file
void log_data(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Function to set the relay state
void set_relay_state(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
