#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control duration (seconds)
#define MOTOR_DURATION 5

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 300

// Global variable to track rain state
static volatile int rain_detected = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);

int main() {
    // Open syslog for logging
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Rain-actuated window controller started.");

    // Main loop
    while (1) {
        // Read rain sensor
        int sensor_value = read_rain_sensor();

        // Check for rain detection
        if (sensor_value == 0 && !rain_detected) {
            syslog(LOG_INFO, "Rain detected!");
            close_window();
            rain_detected = 1;
            syslog(LOG_INFO, "Window closing sequence started.");
        } else if (sensor_value == 1 && rain_detected) {
            // Debounce: wait for 3 consecutive dry readings
            int dry_count = 0;
            while (sensor_value == 1 && dry_count < 3) {
                sensor_value = read_rain_sensor();
                if (sensor_value == 1) {
                    dry_count++;
                }
                gpioDelay(200); // Check every 200ms
            }

            if (dry_count >= 3) {
                syslog(LOG_INFO, "Rain stopped!");
                rain_detected = 0;
                stop_motor();
                syslog(LOG_INFO, "Window closing sequence stopped.");
            }
        }

        gpioDelay(200); // Poll every 200ms
    }

    // This point should not be reached due to the signal handler
    return 0;
}

// Function to initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set pull-up resistor on the rain sensor pin
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Ensure motor is initially stopped
    stop_motor();

    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Motor starting...");
    gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
    gpioWrite(MOTOR_IN1_PIN, 1); // Set direction to close
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioDelay(MOTOR_DURATION * 1000); // Run for specified duration
    syslog(LOG_INFO, "Motor stopping...");
    stop_motor();
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

