#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define SERVO_GPIO 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, shutting down...\n");
    gpioServo(SERVO_GPIO, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_GPIO, PI_PUD_UP);

    gpioSetISRFuncEx(LOCK_BUTTON_GPIO, FALLING_EDGE, 0, lock_button_pressed, NULL);
    gpioSetISRFuncEx(UNLOCK_BUTTON_GPIO, FALLING_EDGE, 0, unlock_button_pressed, NULL);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int lock_state = 0; // 0 = unlocked, 1 = locked
    int last_lock_state = 0;

    while (!terminate) {
        int lock_button_state = gpioRead(LOCK_BUTTON_GPIO);
        int unlock_button_state = gpioRead(UNLOCK_BUTTON_GPIO);

        if (lock_button_state == 0 && last_lock_state == 0) {
            gpioServo(SERVO_GPIO, 2000); // Lock
            lock_state = 1;
            last_lock_state = lock_state;
            printf("Door locked\n");
        } else if (unlock_button_state == 0 && last_lock_state == 1) {
            gpioServo(SERVO_GPIO, 1000); // Unlock
            lock_state = 0;
            last_lock_state = lock_state;
            printf("Door unlocked\n");
        }

        gpioDelay(10); // Small delay to reduce CPU usage
    }

    return 0;
}

void lock_button_pressed(int gpio, int level, uint32_t tick) {
    // Debounce logic
    gpioDelay(50); // Wait for button release
    if (gpioRead(LOCK_BUTTON_GPIO) == 1) {
        gpioServo(SERVO_GPIO, 2000); // Lock
        printf("Door locked (debounced)\n");
    }
}

void unlock_button_pressed(int gpio, int level, uint32_t tick) {
    // Debounce logic
    gpioDelay(50); // Wait for button release
    if (gpioRead(UNLOCK_BUTTON_GPIO) == 1) {
        gpioServo(SERVO_GPIO, 1000); // Unlock
        printf("Door unlocked (debounced)\n");
    }
}

