#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_STATUS_REG 0x00
#define ELECTRODE_TOGGLE_DEBOUNCE_MS 200

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// MPR121 Initialization function
int mpr121_init(int i2c_handle) {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, 0x80, 0x63); // Reset command
    if (status < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121 (status = %d)\n", status);
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Configure baseline filtering
    status = i2cWriteByteData(i2c_handle, 0x5C, 0x0F); // MHD
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write MHD (status = %d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5D, 0x0F); // NHD
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write NHD (status = %d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x01); // NCL
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write NCL (status = %d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x5F, 0x01); // FDL
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write FDL (status = %d)\n", status);
        return -1;
    }

    // Set debounce
    status = i2cWriteByteData(i2c_handle, 0x5B, 0x0A); // Debounce
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write debounce (status = %d)\n", status);
        return -1;
    }

    // Set FFI/SFI/CDT
    status = i2cWriteByteData(i2c_handle, 0x2C, 0x01); // FFI
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write FFI (status = %d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x2D, 0x01); // SFI
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write SFI (status = %d)\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, 0x2E, 0x01); // CDT
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write CDT (status = %d)\n", status);
        return -1;
    }

    // Enable electrodes
    status = i2cWriteByteData(i2c_handle, 0x5E, 0x0C); // Enable 12 electrodes
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write electrode enable (status = %d)\n", status);
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    int status;
    uint16_t touch_status;

    status = i2cReadWordData(i2c_handle, TOUCH_STATUS_REG);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read touch status (status = %d)\n", status);
        return -1;
    }
    touch_status = status; // i2cReadWordData returns the data itself

    return touch_status;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    printf("Relay toggled to state: %d\n", !current_state);
}

int main() {
    int touch_status;
    int electrode_0_touched;
    int last_electrode_0_state = 0; // Track the last known state of electrode 0

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0); // Bus 1, address 0x5A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (error code = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 and Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read touch status
        touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Check if electrode 0 is touched (rising edge)
        electrode_0_touched = (touch_status & 0x0001);

        if (electrode_0_touched && !(last_electrode_0_state)) {
            // Debounce
            gpioDelay(ELECTRODE_TOGGLE_DEBOUNCE_MS * 1000); // Convert ms to us

            // Re-read touch status after debounce
            touch_status = read_touch_status(i2c_handle);
            if (touch_status < 0) {
                fprintf(stderr, "Error reading touch status after debounce, exiting...\n");
                break;
            }

            // Verify electrode 0 is still touched after debounce
            electrode_0_touched = (touch_status & 0x0001);
            if (electrode_0_touched) {
                toggle_relay(RELAY_GPIO);
            }
        }

        last_electrode_0_state = electrode_0_touched; // Update last known state

        gpioDelay(50000); // Check every 50ms
    }

    // Cleanup
    printf("Cleaning up resources...\n");
    gpioWrite(RELAY_GPIO, 0); // Set relay to OFF state
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

