#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <stdarg.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/select.h>
#include <gpiod.h>

// Define GPIO pins
#define SERVO_PIN 17
#define PIR_PIN 4

// Define TCP port
#define PORT 5000

// Define servo pulse width limits (in microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000 // 1ms
#define SERVO_MAX_PULSE_WIDTH 2000 // 2ms

// Define servo angle limits (in degrees)
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define PWM period (in microseconds)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Global variables
static int server_fd = -1; // Socket file descriptor
static struct gpiod_chip *chip = NULL; // GPIO chip pointer
static struct gpiod_line *servo_line = NULL; // Servo GPIO line pointer
static struct gpiod_line *pir_line = NULL; // PIR GPIO line pointer
static FILE *log_file = NULL; // Log file pointer
static volatile sig_atomic_t terminate = 0; // Termination flag

// Function prototypes
void log_message(int priority, const char *format, ...);
int init_gpio(void);
void cleanup_gpio(void);
int set_servo_angle(int angle);
int read_pir_sensor(void);
int start_servo_pwm(void);
void stop_servo_pwm(void);
int handle_client(int client_fd);
void signal_handler(int signum);

// Logging function
void log_message(int priority, const char *format, ...)
{
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    vsyslog(priority, format, args);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fprintf(log_file, "\n");
        fflush(log_file);
    }

    va_end(args);
}

// Initialize GPIO
int init_gpio(void)
{
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip)
    {
        log_message(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Get servo GPIO line
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line)
    {
        log_message(LOG_ERR, "Failed to get servo GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get PIR GPIO line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line)
    {
        log_message(LOG_ERR, "Failed to get PIR GPIO line: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        return -1;
    }

    // Request servo GPIO line for output
    ret = gpiod_line_request_output(servo_line, "servo", 0);
    if (ret < 0)
    {
        log_message(LOG_ERR, "Failed to request servo GPIO line for output: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request PIR GPIO line for input
    ret = gpiod_line_request_input(pir_line, "pir");
    if (ret < 0)
    {
        log_message(LOG_ERR, "Failed to request PIR GPIO line for input: %s", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(servo_line);
        gpiod_line_release(pir_line);
        gpiod_line_release(servo_line);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void)
{
    if (servo_line)
    {
        gpiod_line_release(servo_line);
    }
    if (pir_line)
    {
        gpiod_line_release(pir_line);
    }
    if (chip)
    {
        gpiod_chip_close(chip);
    }
}

// Set servo angle using software PWM
int set_servo_angle(int angle)
{
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE)
    {
        log_message(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width in microseconds
    int pulse_width = (int)(((float)(angle) / SERVO_MAX_ANGLE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);

    // Set GPIO line value
    if (gpiod_line_set_value(servo_line, 1) < 0)
    {
        log_message(LOG_ERR, "Failed to set servo GPIO line value: %s", strerror(errno));
        return -1;
    }
    usleep(pulse_width);

