// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 100.0
#define DEFAULT_DURATION 10000

// Global variables
static volatile int running = 1;
static int threshold = DEFAULT_THRESHOLD;
static float scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int tare_offset = 0;

// Function prototypes
int read_hx711();
float calculate_weight(int raw_value, int tare_offset, float scale);
void control_solenoid(int activate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    // Wait for DOUT to go LOW
    int timeout = 1000; // 1 second timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 timeout waiting for data");
        return -1; // Indicate error
    }

    // Read 24 bits
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain selection
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 32-bit integer
    data = data ^ 0x800000; // Convert to signed

    return data;
}

// Function to calculate weight
float calculate_weight(int raw_value, int tare_offset, float scale) {
    return (float)(raw_value - tare_offset) / scale;
}

// Function to control the solenoid lock
void control_solenoid(int activate) {
    gpioWrite(SOLENOID_PIN, activate);
    if (activate) {
        syslog(LOG_INFO, "Solenoid activated for 200ms");
        gpioDelay(200); // 200ms
        gpioWrite(SOLENOID_PIN, 0);
        syslog(LOG_INFO, "Solenoid deactivated");
    }
}

