void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
}

