    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Perform startup tare
    syslog(LOG_INFO, "Performing startup tare...");
    for (i = 0; i < num_readings; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            syslog(LOG_ERR, "Error reading HX711 during tare, exiting");
            cleanup();
            return 1;
        }
        sum += raw_value;
        gpioDelay(1); // Small delay between readings
    }
    tare_offset = sum / num_readings;
    syslog(LOG_INFO, "Startup tare complete, offset: %d", tare_offset);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sum = 0;
        // Average 5 readings
        for (i = 0; i < 5; i++) {
            raw_value = read_hx711();
            if (raw_value == -1) {
                syslog(LOG_ERR, "Error reading HX711, retrying...");
                i--; // Retry the current reading
                gpioDelay(10); // Small delay before retry
            } else {
                sum += raw_value;
            }
            gpioDelay(1); // Small delay between readings
        }

        weight = calculate_weight(sum / 5, tare_offset, scale);
        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        // Control solenoid based on weight threshold
        if (weight > threshold) {
            control_solenoid(1); // Activate solenoid
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

