#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message)
{
    syslog(priority, "%s", message);
}

// Function to set GPIO pin state
void set_gpio_state(int state)
{
    gpioWrite(GPIO_PIN, state);
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "GPIO %d set to %d", GPIO_PIN, state);
    log_message(LOG_INFO, log_message_buffer);
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message)
{
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        char log_message_buffer[100];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Received message: %s", payload);
        log_message(LOG_INFO, log_message_buffer);

        if (strcmp(payload, "ON") == 0) {
            set_gpio_state(1); // Energize relay
        } else if (strcmp(payload, "OFF") == 0) {
            set_gpio_state(0); // De-energize relay
        } else {
            log_message(LOG_ERR, "Invalid payload received. Leaving relay state unchanged.");
        }
    } else {
        log_message(LOG_WARNING, "Empty message received.");
    }
}

// Function to handle MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result)
{
    if (!result) {
        log_message(LOG_INFO, "Connected to MQTT broker.");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            char log_message_buffer[100];
            snprintf(log_message_buffer, sizeof(log_message_buffer), "Subscription failed: %s", mosquitto_strerror(subscribe_result));
            log_message(LOG_ERR, log_message_buffer);
        } else {
            log_message(LOG_INFO, "Subscribed to topic: home/lights/control");
        }
    } else {
        char log_message_buffer[200];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Connection failed: %s", mosquitto_connack_string(result));
        log_message(LOG_ERR, log_message_buffer);
    }
}

// Function to handle MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc)
{
    if (rc != 0) {
        char log_message_buffer[200];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Disconnected unexpectedly with code: %d", rc);
        log_message(LOG_ERR, log_message_buffer);
    }
    log_message(LOG_INFO, "Disconnected from MQTT broker.");
}

// Signal handler for graceful shutdown
void signal_handler(int signum)
{
    running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

int main(int argc, char *argv[])
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_gpio_state(0); // Initialize relay to OFF state

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new Mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create Mosquitto client instance.");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        char log_message_buffer[200];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        log_message(LOG_ERR, log_message_buffer);
        mosquitto_destroy(mosq);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start the MQTT loop in a separate thread
    mosquitto_loop_start(mosq);

    // Main loop to handle signals and reconnect attempts
    while (running) {
        sleep(1);
        if (!mosquitto_is_connected(mosq)) {
            log_message(LOG_WARNING, "Broker disconnected, attempting to reconnect...");
            mosquitto_reconnect(mosq);
        }
    }

    // Clean up resources before exiting
    mosquitto_loop_stop(mosq, false);
    set_gpio_state(0); // Ensure relay is OFF on exit
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioTerminate();
    mosquitto_lib_cleanup();
    closelog();

    return 0;
}

