#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

// Motor B
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

// Encoder A
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

// Encoder B
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

// Target speed (RPM)
#define TARGET_SPEED 50.0

// PI controller parameters
#define Kp 0.5
#define Ki 0.05

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Stall detection time (seconds)
#define STALL_TIME 2.0

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
double last_encoder_a_count = 0.0;
double last_encoder_b_count = 0.0;

// PWM duty cycle limits
#define PWM_MIN 0
#define PWM_MAX 255

// Function prototypes
void set_motor_direction(int motor, int direction);
void set_motor_pwm(int motor, int duty_cycle);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count, double last_count);
double calculate_error(double target_speed, double actual_speed);
double calculate_pi_control(double error, double last_error, double integral);
void signal_handler(int signal);

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT);

    gpioSetMode(ENCODER_A_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_A_B_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_A_PIN, PI_INPUT);
    gpioSetMode(ENCODER_B_B_PIN, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_PWM_PIN, 255);
    gpioSetPWMrange(MOTOR_B_PWM_PIN, 255);

    // Set ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (1)
    {
        // Calculate RPM
        double actual_speed_a = calculate_rpm(encoder_a_count, last_encoder_a_count);
        double actual_speed_b = calculate_rpm(encoder_b_count, last_encoder_b_count);
        last_encoder_a_count = encoder_a_count;
        last_encoder_b_count = encoder_b_count;

        // Calculate error
        double error_a = calculate_error(TARGET_SPEED, actual_speed_a);
        double error_b = calculate_error(TARGET_SPEED, actual_speed_b);

        // Calculate PI control output
        double pi_output_a = calculate_pi_control(error_a, 0, 0); // Integral term is zero, reset on each iteration
        double pi_output_b = calculate_pi_control(error_b, 0, 0); // Integral term is zero, reset on each iteration

        // Anti-windup
        if (pi_output_a > PWM_MAX) pi_output_a = PWM_MAX;
        if (pi_output_a < PWM_MIN) pi_output_a = PWM_MIN;
        if (pi_output_b > PWM_MAX) pi_output_b = PWM_MAX;
        if (pi_output_b < PWM_MIN) pi_output_b = PWM_MIN;

        // Set motor PWM
        set_motor_pwm(0, (int)pi_output_a); // Motor A
        set_motor_pwm(1, (int)pi_output_b); // Motor B

        // Print data
        printf("Motor A: RPM = %.2f, PWM = %d\n", actual_speed_a, (int)pi_output_a);
        printf("Motor B: RPM = %.2f, PWM = %d\n", actual_speed_b, (int)pi_output_b);

        // Stall detection
        if (encoder_a_count == 0 && last_encoder_a_count != 0) {
            fprintf(stderr, "Encoder A stall detected!\n");
        }
        if (encoder_b_count == 0 && last_encoder_b_count != 0) {
            fprintf(stderr, "Encoder B stall detected!\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    return 0;
}

// Set motor direction
void set_motor_direction(int motor, int direction)
{
    if (motor == 0) // Motor A
    {
        gpioWrite(MOTOR_A_DIR_PIN, direction);
    } else if (motor == 1) // Motor B
    {
        gpioWrite(MOTOR_B_DIR_PIN, direction);
    }
}

// Set motor PWM duty cycle
void set_motor_pwm(int motor, int duty_cycle)
{
    if (motor == 0) // Motor A
    {
        gpioPWM(MOTOR_A_PWM_PIN, duty_cycle);
    } else if (motor == 1) // Motor B
    {
        gpioPWM(MOTOR_B_PWM_PIN, duty_cycle);
    }
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (gpio == ENCODER_A_A_PIN)
    {
        encoder_a_count++;
    } else if (gpio == ENCODER_A_B_PIN)
    {
        encoder_a_count--;
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (gpio == ENCODER_B_A_PIN)
    {
        encoder_b_count++;
    } else if (gpio == ENCODER_B_B_PIN)
    {
        encoder_b_count--;
    }
}

// Calculate RPM
double calculate_rpm(int encoder_count, double last_count)
{
    double delta = encoder_count - last_count;
    double time_interval = 100.0; // 100 ms
    double rpm = (delta / 64.0) / (time_interval / 60.0); // 64 ticks per revolution
    return rpm;
}

// Calculate error
double calculate_error(double target_speed, double actual_speed)
{
    double error = target_speed - actual_speed;
    return error;
}

// Calculate PI control output
double calculate_pi_control(double error, double last_error, double integral)
{
    double proportional = Kp * error;
    double integral_term = Ki * integral + Kp * last_error;
    double output = proportional + integral_term;
    return output;
}

// Signal handler
void signal_handler(int signal)
{
    printf("Caught signal %d, stopping motors and exiting...\n", signal);

    // Stop motors
    set_motor_pwm(0, 0);   // Motor A
    set_motor_pwm(1, 0);   // Motor B

    // Release resources
    gpioTerminate();

    exit(0);
}

