// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    unsigned char data[2];
    int lux = -1; // Initialize to an error value
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send One-Time High-Resolution Mode 2 command
        if (i2cWriteByteData(i2c_handle, 0x00, 0x21) != 0) {
            log_data("Error: Failed to send measurement command to BH1750.");
            retries++;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        gpioDelay(180); // Wait for measurement (at least 180ms)

        // Read 2 bytes of data
        if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2) == 2) {
            lux = (data[0] << 8) | data[1];
            break; // Exit retry loop on success
        } else {
            log_data("Error: Failed to read data from BH1750.");
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }

    if (lux == -1) {
        log_data("Error: Failed to read BH1750 after multiple retries.");
        return -1; // Indicate failure
    }

    return lux;
}

// Function to convert raw data to lux
float convert_to_lux(unsigned short raw_data) {
    return (float)raw_data / 1.2;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int lux, relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        log_data("Error: Could not open I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    log_data("System started.");

    // Main loop
    while (!terminate) {
        lux = read_bh1750(i2c_handle);
        if (lux == -1) {
            log_data("Error: Failed to read lux value.");
            control_relay(RELAY_GPIO, 0); // Turn off relay on error
        } else {
            float lux_value = convert_to_lux((unsigned short)lux);
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Lux = %.2f", lux_value);
            log_data(log_message);

            if (lux_value < LUX_THRESHOLD_ON && relay_state == 0) {
                control_relay(RELAY_GPIO, 1);
                relay_state = 1;
                log_data("Relay activated.");
            } else if (lux_value > (LUX_THRESHOLD_OFF + HYSTERESIS) && relay_state == 1) {
                control_relay(RELAY_GPIO, 0);
                relay_state = 0;
                log_data("Relay deactivated.");
            }
        }

        gpioDelay(POLL_INTERVAL);
    }

    // Cleanup
    log_data("System shutting down.");
    control_relay(RELAY_GPIO, 0); // Ensure relay is off on exit
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

