#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_SENSOR_GPIO 4

volatile int relay_state = 0; // 0 = OFF, 1 = ON
volatile int running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        gpioWrite(RELAY_GPIO, 0); // Turn OFF the relay
        gpioTerminate(); // Terminate pigpio
        running = 0;
        exit(0);
    }
}

int main() {
    int rc;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO modes
    rc = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", RELAY_GPIO, rc);
        gpioTerminate();
        return 1;
    }

    rc = gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", TOUCH_SENSOR_GPIO, rc);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_GPIO, 0);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read touch sensor state
        int touch_state = gpioRead(TOUCH_SENSOR_GPIO);

        // Debouncing and state change logic
        if (touch_state == 1) {
            gpioDelay(50000); // 50 ms delay
            if (gpioRead(TOUCH_SENSOR_GPIO) == 1) { // Check if still touched after delay
                relay_state = !relay_state; // Toggle relay state
                gpioWrite(RELAY_GPIO, relay_state);

                // Log relay state change
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

                printf("%s Relay is now %s\n", timestamp, relay_state ? "ON" : "OFF");
            }
        }

        gpioDelay(10000); // Sleep for 10 ms
    }

    return 0;
}

