#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define DEBOUNCE_TIMEOUT 1 // seconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
double current_lpm = 0.0;
int solenoid_state = 1; // 1 = open, 0 = closed
FILE *log_file = NULL;

// Function prototypes
void *flow_sensor_isr(void *arg);
void compute_lpm();
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void *flow_sensor_isr(void *arg) {
    (void)arg; // Suppress unused parameter warning
    pulse_count++;
    return NULL;
}

// Compute LPM and trigger solenoid control
void compute_lpm() {
    pthread_mutex_lock(&pulse_mutex);
    double local_lpm = (double)pulse_count / PULSES_PER_LITER * 60.0;
    current_lpm = local_lpm;
    pulse_count = 0; // Reset pulse count after reading
    pthread_mutex_unlock(&pulse_mutex);

    control_solenoid(current_lpm);
}

// Control the solenoid valve
void control_solenoid(double lpm) {
    static int last_solenoid_state = 1; // Initialize to open state

    if (lpm > LPM_THRESHOLD_HIGH && last_solenoid_state == 1) {
        gpioWrite(SOLENOID_GPIO, 0); // Close solenoid
        last_solenoid_state = 0;
        log_data(current_lpm, last_solenoid_state);
    } else if (lpm < (LPM_THRESHOLD_LOW - HYSTERESIS) && last_solenoid_state == 0) {
        gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
        last_solenoid_state = 1;
        log_data(current_lpm, last_solenoid_state);
    }
}

// Log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Cannot log data.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    printf("Signal received. Shutting down gracefully...\n");

    // Reopen solenoid valve
    gpioWrite(SOLENOID_GPIO, 1);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", SOLENOID_GPIO);
        gpioTerminate();
        return 1;
    }

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_GPIO, 1);
    solenoid_state = 1;

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine (ISR)
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO %d\n", FLOW_SENSOR_GPIO);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        compute_lpm();
        gpioDelay(1000); // Check every 1 second
    }

    return 0; // This line will never be reached due to the infinite loop
}

