#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define DEFAULT_SERVO_FREQUENCY 50
#define DEFAULT_TIMEOUT_ATTEMPTS 1000

// GPIO Pins
#define HX711_DATA 23
#define HX711_SCK 24
#define SERVO_PIN 18

// Global Variables
double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
char server_ip[20] = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;
int servo_frequency = DEFAULT_SERVO_FREQUENCY;
int timeout_attempts = DEFAULT_TIMEOUT_ATTEMPTS;
int socket_fd = -1;

// Function Prototypes
int read_hx711();
double calibrate_weight(int raw_value);
void set_servo_pulse_width(int pulse_width);
void dispense_ingredient(double target_weight);
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int load_configuration();

// HX711 Reading Function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DATA pin to go low
    int attempts = 0;
    while (gpioRead(HX711_DATA) == 1 && attempts < timeout_attempts) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        attempts++;
    }

    if (attempts >= timeout_attempts) {
        fprintf(stderr, "Error: HX711 not ready (DATA pin high for too long).\n");
        log_dispensing_event(0.0, 0.0, "HX711 Timeout");
        return -1; // Indicate error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // 1 us pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // 1 us pulse width
    }

    // 25th pulse for gain setting (Channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // 1 us pulse width
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // 1 us pulse width

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Calibration Function
double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Servo Control Function
void set_servo_pulse_width(int pulse_width) {
    gpioPWM(SERVO_PIN, pulse_width);
}

// Dispensing Function
void dispense_ingredient(double target_weight) {
    int raw_value;
    double actual_weight;
    char error_message[100] = "";

    // Open the servo to dispense
    set_servo_pulse_width(1000); // Start at 1000 us
    gpioDelay(1000); // Wait for servo to move

    // Wait for the load cell to stabilize
    gpioDelay(1000); // Wait 1 second

    raw_value = read_hx711();

    if (raw_value == -1) {
        actual_weight = 0.0;
        strcpy(error_message, "HX711 Error");
    } else {
        actual_weight = calibrate_weight(raw_value);
    }

    // Calculate the error and adjust the servo pulse width
    int error = (int)(target_weight - actual_weight);
    int adjusted_pulse_width = 1000 + (error * 1000 / 100.0); // Map error to 0-1000 range
    if (adjusted_pulse_width < 1000) adjusted_pulse_width = 1000;
    if (adjusted_pulse_width > 2000) adjusted_pulse_width = 2000;

    set_servo_pulse_width(adjusted_pulse_width);
    gpioDelay(500); // Wait for servo to move

    // Log the dispensing event
    log_dispensing_event(target_weight, actual_weight, error_message);

    // Send the actual weight back to the client
    char response[100];
    snprintf(response, sizeof(response), "%.2f\n", actual_weight);
    send(socket_fd, response, strlen(response), 0);
}

// Logging Function
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open dispensing_log.json for writing.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);

    fclose(fp);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop the servo
    set_servo_pulse_width(1500); // Set to center position

    // Close the socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Configuration Loading Function
