int main(int argc, char *argv[]) {
    // Parse command-line argument for debounce time
    int debounceTime = DEBOUNCE_TIME;
    if (argc > 1) {
        char *endptr;
        long val = strtol(argv[1], &endptr, 10);
        if (*endptr == '\0' && val >= 1 && val <= 1000) {
            debounceTime = (int)val;
        } else {
            fprintf(stderr, "Error: Invalid debounce time. Using default value (%dms).\n", DEBOUNCE_TIME);
            debounceTime = DEBOUNCE_TIME;
        }
    }

    // Initialize GPIO
    if (initializeGPIO() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Read touch sensor
        if (readTouchSensor()) {
            // Debounce the touch
            if (debounceTouch() == 1) {
                // Toggle the relay
                toggleRelay();
                logRelayState(relayState);
            }
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10); // 10ms delay
    }

    return 0;
}

// Initialize GPIO pins
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to input mode\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to output mode\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relayState = 0;
    logRelayState(relayState);

    return 0;
}

// Read the touch sensor
int readTouchSensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Debounce the touch sensor
int debounceTouch() {
    int stableHigh = 0;
    int startTime = gpioTick();
    while (gpioRead(TOUCH_SENSOR_PIN) == 1) {
        if (gpioTick() - startTime > debounceTime * 1000) {
            stableHigh = 1;
            break;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    return stableHigh;
}

// Toggle the relay state
void toggleRelay() {
    relayState = !relayState;
    gpioWrite(RELAY_PIN, relayState);
}

// Log the relay state to the console
void logRelayState(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off the relay
    gpioWrite(RELAY_PIN, 0);
    relayState = 0;
    logRelayState(relayState);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

