#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define MIN_PULSE_WIDTH_US 500
#define MAX_PULSE_WIDTH_US 2500
#define ANGLE_INCREMENT 10

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int restore_terminal_settings(const struct termios *original_settings) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, original_settings) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

int main() {
    struct termios original_settings, new_settings;
    int current_angle = 90;
    int pulse_width_us;

    // Save the current terminal settings
    if (tcgetattr(STDIN_FILENO, &original_settings) != 0) {
        perror("tcgetattr");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        restore_terminal_settings(&original_settings);
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-1000000 for microseconds)
    gpioSetPWMrange(SERVO_PIN, 1000000);

    // Initialize new_settings for non-canonical mode
    new_settings = original_settings;
    new_settings.c_lflag &= ~(ICANON | ECHO);

    // Restore terminal settings on exit
    atexit(restore_terminal_settings);

    printf("Enter '+', '-', or 'q' to adjust servo angle. Press 'q' to quit.\n");

    while (!terminate) {
        int ch = getchar();

        if (ch == '+') {
            current_angle += ANGLE_INCREMENT;
            if (current_angle > 180) {
                current_angle = 180;
            }
        } else if (ch == '-') {
            current_angle -= ANGLE_INCREMENT;
            if (current_angle < 0) {
                current_angle = 0;
            }
        } else if (ch == 'q') {
            break;
        }

        // Calculate pulse width in microseconds
        pulse_width_us = MIN_PULSE_WIDTH_US + (int)(((float)(current_angle) / 180.0) * (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US));

        // Set servo pulse width
        if (gpioServo(SERVO_PIN, pulse_width_us) != 0) {
            fprintf(stderr, "Error setting servo pulse width\n");
        }

        printf("Current angle: %d degrees, Pulse width: %d us\n", current_angle, pulse_width_us);
    }

    // Stop PWM pulses
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

