#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_S 5

volatile int pulseCount = 0;
FILE *logFile = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t t = ts.tv_sec;
    struct tm *tm_info = localtime(&t);
    char *timestamp = malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }
    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), 25 - strlen(timestamp), ".%09ldZ", ts.tv_nsec);
    return timestamp;
}

// Function to log the RPM data to a file
int log_rpm_data(const char *timestamp, double rpm_value) {
    if (logFile == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(logFile, "%s,%.2f\n", timestamp, rpm_value);
    fflush(logFile); // Ensure data is written to disk immediately
    return 0;
}

// Function to calculate RPM
double calculate_rpm() {
    return (double)pulseCount / SAMPLE_INTERVAL_S * 60.0;
}

// Function to handle the interrupt
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulseCount++;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Stop the main loop
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer

    // Release the GPIO line
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback

    // Close the chip
    gpioTerminate();

    // Close the log file
    if (logFile != NULL) {
        fclose(logFile);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input with pull-up
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt on rising edge
    gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Wait for 5 seconds
        sleep(SAMPLE_INTERVAL_S);

        // Calculate RPM
        double rpm = calculate_rpm();

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging.\n");
            continue;
        }

        // Log the data
        if (log_rpm_data(timestamp, rpm) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Free the timestamp memory
        free(timestamp);

        // Reset pulse count
        pulseCount = 0;
    }

    return 0;
}

