#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ACTIVE_HIGH 1
#define FAILSAFE_TIMEOUT 10 // seconds
#define POLL_INTERVAL_MS 50

// Global variables
volatile sig_atomic_t program_running = 1;
time_t last_touch_time;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void failsafe_check();
void signal_handler(int signal);
void cleanup();

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize last touch time
    time(&last_touch_time);

    // Main loop
    while (program_running) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Toggle relay
            toggle_relay();

            // Check failsafe
            failsafe_check();
        }

        // Wait for a short interval
        gpioDelay(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

// Read touch sensor
int read_touch_sensor() {
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading GPIO%d\n", TOUCH_SENSOR_PIN);
        return 0; // Return 0 on error to avoid unintended behavior
    }
    return sensor_value;
}

// Toggle relay state
void toggle_relay() {
    int current_relay_state = gpioRead(RELAY_PIN);
    if (current_relay_state < 0) {
        fprintf(stderr, "Error reading GPIO%d\n", RELAY_PIN);
        return;
    }

    gpioWrite(RELAY_PIN, !current_relay_state);
}

// Failsafe check
void failsafe_check() {
    time_t current_time;
    time(&current_time);

    double time_diff = difftime(current_time, last_touch_time);

    if (time_diff > FAILSAFE_TIMEOUT) {
        fprintf(stderr, "Failsafe triggered: Touch sensor HIGH for too long. Relay OFF.\n");
        gpioWrite(RELAY_PIN, 0);
        program_running = 0; // Stop further toggles
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    // Set relay OFF
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
}

