#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_ENABLE_PIN 23
#define VALVE_DIRECTION_PIN 22
#define FLOW_SENSOR_PIN 24

// Define PWM channel
#define PWM_CHANNEL 0

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define target flow rate (L/min)
float target_flow_rate = 0.0;

// Define proportional gain (Kp)
float Kp = 1.0;

// Define pulse accumulator
volatile int pulse_count = 0;

// Define file pointer for logging
FILE *log_file = NULL;

// Define flag for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
float sample_flow_rate();
void set_valve_position(int position);
void log_data(float flow_rate, int valve_position);
int initialize();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Interrupt service routine for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to sample flow rate and return the average over 100 ms
float sample_flow_rate() {
    static int last_pulse_count = 0;
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();
    int pulse_diff = pulse_count - last_pulse_count;
    float flow_rate;

    if (last_tick != 0) {
        uint32_t time_diff = current_tick - last_tick;
        if (time_diff >= 100000) { // 100 ms
            float pulses_per_second = (float)pulse_diff / (time_diff / 1000000.0); // Convert to pulses/second
            flow_rate = pulses_per_second * 60.0 / 450.0; // Convert to L/min
        } else {
            flow_rate = 0.0; // Not enough time has passed
        }
    } else {
        flow_rate = 0.0; // First sample
    }

    last_pulse_count = pulse_count;
    last_tick = current_tick;
    return flow_rate;
}

// Function to set the valve position using PWM
void set_valve_position(int position) {
    if (position < 0) position = 0;
    if (position > 255) position = 255;
    gpioPWM(PWM_CHANNEL, position);
}

// Function to log data to a file
void log_data(float flow_rate, int valve_position) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set VALVE_ENABLE_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(VALVE_DIRECTION_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set VALVE_DIRECTION_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set FLOW_SENSOR_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    if (gpioSetPWMfrequency(PWM_CHANNEL, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Enable the valve
    gpioWrite(VALVE_ENABLE_PIN, 1);
    gpioWrite(VALVE_DIRECTION_PIN, 0); // Set direction to increase PWM for increasing flow

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register interrupt service routine for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for flow sensor\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop PWM
    gpioPWM(PWM_CHANNEL, 0);

    // Disable the valve
    gpioWrite(VALVE_ENABLE_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        char *endptr;
        target_flow_rate = strtof(argv[1], &endptr);
        if (*endptr != '\0' || target_flow_rate <= 0) {
            fprintf(stderr, "Invalid target flow rate. Usage: %s -t <flow_rate_L_min>\n", argv[0]);
            return 1;
        }
    } else {
        fprintf(stderr, "Target flow rate not specified. Usage: %s -t <flow_rate_L_min>\n", argv[0]);
        return 1;
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Sample flow rate
        float flow_rate = sample_flow_rate();

        // Calculate error
        float error = target_flow_rate - flow_rate;

        // Calculate PWM duty cycle
        int valve_position = (int)(Kp * error);

        // Clamp valve position to [0, 255]
        if (valve_position < 0) valve_position = 0;
        if (valve_position > 255) valve_position = 255;

        // Set valve position
        set_valve_position(valve_position);

        // Log data
        log_data(flow_rate, valve_position);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

