// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz
#define SPI_MODE 0

// Define RFID tag pattern (10 bytes)
const unsigned char valid_tag[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rfid_tag(unsigned char *tag_data);
int validate_rfid_tag(const unsigned char *tag_data);
int read_button_state();
void control_locks(int lock1_state, int lock2_state);
void log_event(const char *event_description);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Function to read RFID tag data
int read_rfid_tag(unsigned char *tag_data) {
    char tx_buf[1] = {0x00}; // Dummy data to send
    char rx_buf[10];
    int result;

    result = spiXfer(spi_handle, tx_buf, rx_buf, 10);

    if (result != 10) {
        log_event("SPI read failed");
        return -1; // Indicate failure
    }

    // Copy the received data to the tag_data array
    memcpy(tag_data, rx_buf, 10);
    return 0; // Indicate success
}

// Function to validate RFID tag
int validate_rfid_tag(const unsigned char *tag_data) {
    if (memcmp(tag_data, valid_tag, 10) == 0) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Function to read button state
int read_button_state() {
    return gpioRead(BUTTON_PIN);
}

// Function to control lock states
void control_locks(int lock1_state, int lock2_state) {
    gpioWrite(LOCK_1_PIN, lock1_state);
    gpioWrite(LOCK_2_PIN, lock2_state);
}

// Function to log events
void log_event(const char *event_description) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_description);
    fclose(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable internal pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Two-factor authentication system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        unsigned char tag_data[10];
        int button_state;

        // Read RFID tag
        if (read_rfid_tag(tag_data) == 0) {
            // Validate RFID tag
            if (validate_rfid_tag(tag_data)) {
                // Read button state
                button_state = read_button_state();

                // Check if button is pressed (active-low)
                if (button_state == 0) {
                    // Authentication successful
                    log_event("Authentication successful");

                    // Disengage locks
                    control_locks(0, 0);
                    gpioDelay(5000); // 5 seconds

                    // Re-engage locks
                    control_locks(1, 1);
                    log_event("Locks re-engaged");
                } else {
                    // Button press without valid tag
                    log_event("Button press without valid tag");
                }
            } else {
                // Invalid RFID tag
                log_event("Invalid RFID tag");
            }
        } else {
            // SPI read failure
            log_event("SPI read failure");
        }

        gpioDelay(100); // Small delay to avoid busy-waiting
    }

    // Clean up
    spiClose(spi_handle);
    control_locks(1, 1); // Ensure locks are engaged on exit
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

