#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>
#include <unistd.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)

// Target RPM for both motors
#define TARGET_RPM 60

// PID parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;

pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// GPIO chip
struct gpiod_chip *chip;

// GPIO lines
struct gpiod_line *motor1_ena_line, *motor1_in1_line, *motor1_in2_line;
struct gpiod_line *motor2_enb_line, *motor2_in3_line, *motor2_in4_line;
struct gpiod_line *encoder1_a_line, *encoder1_b_line;
struct gpiod_line *encoder2_a_line, *encoder2_b_line;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid1_state = {0, 0};
PIDState pid2_state = {0, 0};

// Function prototypes
void *encoder_thread(void *arg);
double calculate_pid(double setpoint, double actual_speed, PIDState *pid_state, double dt);
void set_motor_speed(int motor_number, double speed);
void stop_motor(int motor_number);
void log_data(double motor1_rpm, double motor2_rpm, double pid1_p, double pid1_i, double pid1_d, double pid2_p, double pid2_i, double pid2_d, double pid1_output, double pid2_output);
void signal_handler(int sig);

// Function to convert microseconds to seconds
double us_to_s(unsigned int us) {
    return (double)us / 1000000.0;
}

// Encoder thread function
void *encoder_thread(void *arg) {
    int encoder_number = *((int *)arg);
    struct gpiod_line *a_line, *b_line;
    int a_value, b_value;
    int last_a_value = 0;
    int last_b_value = 0;
    int count = 0;

    if (encoder_number == 1) {
        a_line = encoder1_a_line;
        b_line = encoder1_b_line;
    } else {
        a_line = encoder2_a_line;
        b_line = encoder2_b_line;
    }

    while (!terminate) {
        a_value = gpiod_line_get_value(a_line);
        b_value = gpiod_line_get_value(b_line);

        if (a_value < 0 || b_value < 0) {
            fprintf(stderr, "Error reading encoder %d lines\n", encoder_number);
            break;
        }

        if (a_value != last_a_value) {
            if (a_value == b_value) {
                if (encoder_number == 1) {
                    pthread_mutex_lock(&encoder1_mutex);
                    encoder1_count++;
                    pthread_mutex_unlock(&encoder1_mutex);
                } else {
                    pthread_mutex_lock(&encoder2_mutex);
                    encoder2_count++;
                    pthread_mutex_unlock(&encoder2_mutex);
                }
            } else {
                if (encoder_number == 1) {
                    pthread_mutex_lock(&encoder1_mutex);
                    encoder1_count--;
                    pthread_mutex_unlock(&encoder1_mutex);
                } else {
                    pthread_mutex_lock(&encoder2_mutex);
                    encoder2_count--;
                    pthread_mutex_unlock(&encoder2_mutex);
                }
            }
            last_a_value = a_value;
        }
        last_b_value = b_value;
        usleep(1); // Small delay to avoid busy-waiting
    }
    return NULL;
}

// PID controller function
double calculate_pid(double setpoint, double actual_speed, PIDState *pid_state, double dt) {
    double error = setpoint - actual_speed;
    pid_state->integral += error * dt;
    double derivative = (error - pid_state->previous_error) / dt;
    double output = KP * error + KI * pid_state->integral + KD * derivative;
    pid_state->previous_error = error;
    return output;
}

// Motor control function
void set_motor_speed(int motor_number, double speed) {
    int duty_cycle = (int)(speed * 1000000.0 / TARGET_RPM); // Calculate duty cycle

    if (motor_number == 1) {
        if (duty_cycle > 0) {
            gpiod_line_set_value(motor1_in1_line, 1);
            gpiod_line_set_value(motor1_in2_line, 0);
            gpiod_line_set_value(motor1_ena_line, 1);
            usleep(PWM_PERIOD_US - duty_cycle);
            gpiod_line_set_value(motor1_in1_line, 0);
            gpiod_line_set_value(motor1_in2_line, 1);
            gpiod_line_set_value(motor1_ena_line, 1);
            usleep(duty_cycle);
        } else {
            gpiod_line_set_value(motor1_ena_line, 0);
        }
    } else {
        int direction = (duty_cycle > 0) ? 1 : 0;
        duty_cycle = abs(duty_cycle);

        if (duty_cycle > 0) {
            gpiod_line_set_value(motor2_in3_line, direction);
            gpiod_line_set_value(motor2_in4_line, !direction);
            gpiod_line_set_value(motor2_enb_line, 1);
            usleep(duty_cycle);
            gpiod_line_set_value(motor2_enb_line, 0);
        } else {
            gpiod_line_set_value(motor2_enb_line, 0);
        }
    }
}

// Stop motor function
void stop_motor(int motor_number) {
    if (motor_number == 1) {
        gpiod_line_set_value(motor1_ena_line, 0);
    } else {
        gpiod_line_set_value(motor2_enb_line, 0);
    }
}

// Log data function
void log_data(double motor1_rpm, double motor2_rpm, double pid1_p, double pid1_i, double pid1_d, double pid2_p, double pid2_i, double pid2_d, double pid1_output, double pid2_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor2_rpm, pid1_p, pid1_i, pid1_d, pid2_p, pid2_i, pid2_d, pid1_output, pid2_output);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    unsigned int encoder1_last_a_value = 0;
    unsigned int encoder1_last_b_value = 0;
    unsigned int encoder2_last_a_value = 0;
    unsigned int encoder2_last_b_value = 0;
    double dt = 0.1; // Sample time (100 ms)
    struct timespec start_time, current_time;
    double motor1_rpm, motor2_rpm;
    double pid1_output, pid2_output;
    int encoder1_direction, encoder2_direction;
    int encoder1_a_value, encoder1_b_value, encoder2_a_value, encoder2_b_value;
    double actual_speed1, actual_speed2;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines
    motor1_ena_line = gpiod_chip_get_line(chip, MOTOR1_ENA);
    motor1_in1_line = gpiod_chip_get_line(chip, MOTOR1_IN1);
    motor1_in2_line = gpiod_chip_get_line(chip, MOTOR1_IN2);
    motor2_enb_line = gpiod_chip_get_line(chip, MOTOR2_ENB);
    motor2_in3_line = gpiod_chip_get_line(chip, MOTOR2_IN3);
    motor2_in4_line = gpiod_chip_get_line(chip, MOTOR2_IN4);
    encoder1_a_line = gpiod_chip_get_line(chip, ENCODER1_A);
    encoder1_b_line = gpiod_chip_get_line(chip, ENCODER1_B);
    encoder2_a_line = gpiod_chip_get_line(chip, ENCODER2_A);
    encoder2_b_line = gpiod_chip_get_line(chip, ENCODER2_B);

    if (!motor1_ena_line || !motor1_in1_line || !motor1_in2_line || !motor2_enb_line || !motor2_in3_line || !motor2_in4_line || !encoder1_a_line || !encoder1_b_line || !encoder2_a_line || !encoder2_b_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request edge events for encoder A lines
    struct gpiod_line_request_config config;
    config.consumer = "encoder_thread";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request_edge_events(encoder1_a_line, &config) < 0 ||
        gpiod_line_request_edge_events(encoder2_a_line, &config) < 0) {
        perror("Error requesting edge events");
        gpiod_chip_close(chip);
        return 1;
    }

    // Create encoder threads
    pthread_t encoder1_thread, encoder2_thread;
    int encoder1_thread_id, encoder2_thread_id;

    if (pthread_create(&encoder1_thread, NULL, encoder_thread, &encoder1_thread_id) != 0 ||
        pthread_create(&encoder2_thread, NULL, encoder_thread, &encoder2_thread_id) != 0) {
        perror("Error creating encoder thread");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_chip_close(chip);
        return 1;
    }

    // Write log file header
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID1_P,PID1_I,PID1_D,PID2_P,PID2_I,PID2_D,PID1_Output,PID2_Output\n");

    // Initialize PID state
    pid1_state.integral = 0;
    pid1_state.previous_error = 0;
    pid2_state.integral = 0;
    pid2_state.previous_error = 0;

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Main control loop
    while (!terminate) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        dt = us_to_s((current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000);
        start_time = current_time;

        // Calculate actual speed (RPM)
        encoder1_a_value = gpiod_line_get_value(encoder1_a_line);
        encoder1_b_value = gpiod_line_get_value(encoder1_b_line);
        encoder2_a_value = gpiod_line_get_value(encoder2_a_line);
        encoder2_b_value = gpiod_line_get_value(encoder2_b_line);

        if (encoder1_a_value < 0 || encoder1_b_value < 0 || encoder2_a_value < 0 || encoder2_b_value < 0) {
            fprintf(stderr, "Error reading encoder values\n");
            continue;
        }

        if (encoder1_a_value != encoder1_last_a_value || encoder1_b_value != encoder1_last_b_value) {
            encoder1_direction = (encoder1_a_value == encoder1_b_value) ? 1 : -1;
            pthread_mutex_lock(&encoder1_mutex);
            encoder1_count += encoder1_direction;
            pthread_mutex_unlock(&encoder1_mutex);
            encoder1_last_a_value = encoder1_a_value;
            encoder1_last_b_value = encoder1_b_value;
        }

        if (encoder2_a_value != encoder2_last_a_value || encoder2_b_value != encoder2_last_b_value) {
            encoder2_direction = (encoder2_a_value == encoder2_b_value) ? 1 : -1;
            pthread_mutex_lock(&encoder2_mutex);
            encoder2_count += encoder2_direction;
            pthread_mutex_unlock(&encoder2_mutex);
            encoder2_last_a_value = encoder2_a_value;
            encoder2_last_b_value = encoder2_b_value;
        }

        // Calculate RPM (600 pulses per revolution)
        motor1_rpm = (double)encoder1_count * 60.0 / (dt * 1000000.0); // pulses/second to RPM
        motor2_rpm = (double)encoder2_count * 60.0 / (dt * 1000000.0);

        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count = 0;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate actual speed (RPM)
        actual_speed1 = motor1_rpm;
        actual_speed2 = motor2_rpm;

        // Calculate PID outputs
        pid1_output = calculate_pid(TARGET_RPM, actual_speed1, &pid1_state, dt);
        pid2_output = calculate_pid(TARGET_RPM, actual_speed2, &pid2_state, dt);

        // Set motor speeds
        set_motor_speed(1, pid1_output);
        set_motor_speed(2, pid2_output);

        // Log data
        log_data(motor1_rpm, motor2_rpm, KP, KI, KD, KP, KI, KD, pid1_output, pid2_output);

        usleep(10000); // 10 ms delay
    }

    // Stop motors
    stop_motor(1);
    stop_motor(2);

    // Release GPIO lines
    gpiod_line_release(motor1_ena_line);
    gpiod_line_release(motor1_in1_line);
    gpiod_line_release(motor1_in2_line);
    gpiod_line_release(motor2_enb_line);
    gpiod_line_release(motor2_in3_line);
    gpiod_line_release(motor2_in4_line);
    gpiod_line_release(encoder1_a_line);
    gpiod_line_release(encoder1_b_line);
    gpiod_line_release(encoder2_a_line);
    gpiod_line_release(encoder2_b_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close log file
    fclose(log_file);

    // Join encoder threads
    pthread_join(encoder1_thread, NULL);
    pthread_join(encoder2_thread, NULL);

    return 0;
}

