#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down gracefully...\n");
        terminate = 1;
    }
}

// MPR121 Initialization function
int mpr121_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100000); // 100 ms delay

    // Configure Electrode Filtering
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x10) < 0) { //MHDR = 0x01
        fprintf(stderr, "Error: Failed to write MHDT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { //NHDT = 0x01
        fprintf(stderr, "Error: Failed to write NHDT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) { //NFDR = 0x01
        fprintf(stderr, "Error: Failed to write NFDR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x00) < 0) { //NCLR = 0x00
        fprintf(stderr, "Error: Failed to write NCLR\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x60, 0x00) < 0) { //FDLR = 0x00
        fprintf(stderr, "Error: Failed to write FDLR\n");
        return -1;
    }

    // Set Touch and Release Thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch Threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release Threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable Run Mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write ELEPROX_EN\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_0 = i2cReadByteData(i2c_handle, 0x00);
    int touch_status_1 = i2cReadByteData(i2c_handle, 0x01);

    if (touch_status_0 < 0 || touch_status_1 < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_1 << 8) | touch_status_0;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log relay state to file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay is %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            gpioDelay(100000); // 100 ms delay before retry
            continue;
        }

        // Check if any electrode is touched
        if (touch_status > 0) {
            if (relay_state == 0) {
                control_relay(RELAY_GPIO, 1); // Turn relay ON
                relay_state = 1;
                log_relay_state(1);
            }
        } else {
            if (relay_state == 0) {
                //Do nothing
            } else {
                control_relay(RELAY_GPIO, 0); // Turn relay OFF
                relay_state = 0;
                log_relay_state(0);
            }
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

