    }
    if (i2cWriteByteData(i2c_handle, 0x60, 0x00) < 0) { //FDLR = 0x00
        fprintf(stderr, "Error: Failed to write FDLR\n");
        return -1;
    }

    // Set Touch and Release Thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch Threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release Threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable Run Mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write ELEPROX_EN\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_0 = i2cReadByteData(i2c_handle, 0x00);
    int touch_status_1 = i2cReadByteData(i2c_handle, 0x01);

    if (touch_status_0 < 0 || touch_status_1 < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    return (touch_status_1 << 8) | touch_status_0;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log relay state to file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay is %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

