    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
            gpioDelay(100000); // 100 ms delay before retry
            continue;
        }

        // Check if any electrode is touched
        if (touch_status > 0) {
            if (relay_state == 0) {
                control_relay(RELAY_GPIO, 1); // Turn relay ON
                relay_state = 1;
                log_relay_state(1);
            }
        } else {
            if (relay_state == 0) {
                //Do nothing
            } else {
                control_relay(RELAY_GPIO, 0); // Turn relay OFF
                relay_state = 0;
                log_relay_state(0);
            }
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF on exit
    fclose(log_file);
    gpioTerminate();

    return 0;
}

