    unsigned short ac4 = 32741;
    unsigned short ac5 = 32757;
    unsigned short ac6 = 23153;
    short b1 = 6190;
    short b2 = 4;
    short mb = -32768;
    short mc = -8711;
    short md = 2868;

    // Read uncompensated temperature (UT)
    data[0] = 0xF4; // Control register
    data[1] = 0x2E; // Request temperature measurement
    write(fd, data, 2);
    usleep(5000); // Wait 4.5ms

    data[0] = 0xF6; // MSB register
    write(fd, data, 1);
    read(fd, data, 2);
    int ut = (data[0] << 8) | data[1];

    // Read uncompensated pressure (UP)
    data[0] = 0xF4; // Control register
    data[1] = 0x34 + (3 << 6); // Request pressure measurement, OSS = 3
    write(fd, data, 2);
    usleep(26000); // Wait 25.5ms

    data[0] = 0xF6; // MSB register
    write(fd, data, 1);
    read(fd, data, 2);
    int msb = data[0];
    read(fd, data, 1);
    int lsb = data[0];
    int up = ((msb << 16) | (lsb << 8)) >> (8 - 3); // OSS = 3

    // Calculate temperature (Celsius)
    int x1 = ((ut - ac6) * ac5) >> 15;
    int x2 = (mc << 11) / (x1 + md);
    int b5 = x1 + x2;
    float temperature = (b5 + 8) >> 4;
    temperature /= 10.0;

    // Calculate pressure (Pascals)
    int b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6 >> 12)) >> 11;
    x2 = (ac2 * b6) >> 11;
    int x3 = x1 + x2;
    int b3 = (((ac1 * 4 + x3) << 3) + 2) >> 2;
    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * (b6 * b6 >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    unsigned int b4 = (ac4 * (unsigned int)(x3 + 32768)) >> 15;
    unsigned int b7 = ((unsigned int)up - b3) * (50000 >> 3);
    int p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);

    close(fd);

    // BMP280
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("Error setting I2C slave address for BMP280");
        close(fd);
        return -1;
    }

    // BMP280 Calibration Data (Placeholder - replace with actual calibration)
    short dig_T1 = 27504;
    short dig_T2 = 26435;
    short dig_T3 = -1000;
    unsigned short dig_P1 = 36477;
    short dig_P2 = -10685;
    short dig_P3 = 3024;
    short dig_P4 = 2855;
    short dig_P5 = -140;
    short dig_P6 = -7;
    short dig_P7 = 15500;
    short dig_P8 = -14600;
    short dig_P9 = 6000;

    // Set oversampling and mode
    data[0] = 0xF4; // Control register
    data[1] = 0b01100111; // Temperature x1, Pressure x1, Normal mode
    write(fd, data, 2);
    usleep(10000); // Wait for measurement

    // Read temperature
    data[0] = 0xFA; // Temperature MSB
    write(fd, data, 1);
    read(fd, data, 2);
    int raw_temp = (data[0] << 8) | data[1];

    // Read pressure
    data[0] = 0xF7; // Pressure MSB
    write(fd, data, 1);
    read(fd, data, 2);
    int raw_pressure = (data[0] << 8) | data[1];

    // Compensate temperature
    double var1 = (raw_temp / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    double var2 = ((raw_temp / 131072.0 - dig_T1 / 8192.0) * (raw_temp / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    double t_fine = var1 + var2;
    float temperature = t_fine / 5120.0;

    // Compensate pressure
    double var3 = t_fine / 2.0 - 64000.0;
    double var4 = var3 * var3 * dig_P6 / 32768.0;
    double var5 = var4 + var3 * dig_P5 * 2.0;
    double var6 = var5 / 4.0 + dig_P4 * 65536.0;
    double var7 = dig_P3 * var3 * var3 / 524288.0;
    double var8 = dig_P2 * var3 / 524288.0;
    double var9 = dig_P1 + var7 + var8;
    double p = 1048576.0 - raw_pressure;
    p = (p - var6 / 4096.0) * 6250.0 / var9;
    var3 = dig_P9 * p * p / 2147483648.0;
    var4 = p * dig_P8 / 32768.0;
    float pressure = (p + (var3 + var4 + dig_P7) / 16.0) / 100.0; // in hPa

    close(fd);

    return 0;
}

int log_event(const char *valve, int duration_ms, float temperature, float humidity, float pressure) {
    char timestamp[32];
    char log_message[256];

    get_iso8601_timestamp(timestamp, sizeof(timestamp));
    snprintf(log_message, sizeof(log_message), "%s Valve %s activated for %d ms, Temp=%.2f, Humidity=%.2f, Pressure=%.2f\n",
             timestamp, valve, duration_ms, temperature, humidity, pressure);

    if (write(log_fd, log_message, strlen(log_message)) == -1) {
