#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init(int i2c_handle);
int read_touch_status(int i2c_handle);
void toggle_relay(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// MPR121 Initialization function
int mpr121_init(int i2c_handle) {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set MPR121 to stop mode\n");
        return -1;
    }
    gpioDelay(10000); // 10ms

    // Set touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x10) < 0) { // Touch threshold
            fprintf(stderr, "Error: Could not set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) { // Release threshold
            fprintf(stderr, "Error: Could not set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) {
        fprintf(stderr, "Error: Could not set config1 register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Could not set config2 register\n");
        return -1;
    }

    // Enter run mode with ELE_EN = 1
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x20) < 0) {
        fprintf(stderr, "Error: Could not set MPR121 to run mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms for stabilization

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int i2c_handle) {
    int touch_status_l, touch_status_h;

    touch_status_l = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_l < 0) {
        fprintf(stderr, "Error: Could not read touch status L\n");
        return -1;
    }

    touch_status_h = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_h < 0) {
        fprintf(stderr, "Error: Could not read touch status H\n");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to toggle the relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
    printf("Relay toggled to %d\n", !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = read_touch_status(i2c_handle);
        if (touch_status > 0) {
            toggle_relay(RELAY_GPIO);
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

