#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000

static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_motion_time = 0;

// Function to log events with millisecond precision
void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s.%03ld: %s\n", buf, ts.tv_nsec / 1000000, event_type);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to unlock the door
void unlock_door() {
    gpioWrite(RELAY_GPIO, 1); // Activate relay
    log_event("Door unlocked");
    gpioDelay(UNLOCK_DURATION_MS * 1000); // Delay in microseconds
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    log_event("Door locked");
}

// Function to handle motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    unsigned long current_time = (unsigned long)ts.tv_sec * 1000 + (unsigned long)ts.tv_nsec / 1000000;

    if (level == 1) { // Rising edge (motion detected)
        if (current_time - last_motion_time > RATE_LIMIT_MS) {
            unlock_door();
            last_motion_time = current_time;
        } else {
            log_event("Motion detected, rate limited");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback for motion detection
    gpioSetAlertFuncEx(PIR_GPIO, motion_detected_callback, NULL);

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(50 * 1000); // Poll every 50 ms (50000 us)
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

