#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define the number of motors
#define NUM_MOTORS 2

// Define the minimum and maximum durations for a step
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define the minimum and maximum PWM duty cycles
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global flag to signal program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signalHandler(int signum) {
    shutdown = 1;
    printf("\nCaught signal %d, shutting down gracefully...\n", signum);
}

// Function to generate a random PWM duty cycle
int generateRandomDutyCycle() {
    return rand() % (MAX_DUTY_CYCLE + 1);
}

// Function to generate a random duration
int generateRandomDuration() {
    return rand() % (MAX_DURATION + 1) + MIN_DURATION;
}

// Function to play a haptic feedback pattern
void playPattern(int motor1_pin, int motor2_pin, int *duty_cycles, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(motor1_pin, duty_cycles[i]);
        gpioPWM(motor2_pin, duty_cycles[i]);
        gpioDelay(durations[i]);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    for (int i = 0; i < NUM_MOTORS; i++) {
        if (gpioSetMode(i + 17, PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to output mode\n", i + 17);
            gpioTerminate();
            return 1;
        }
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signalHandler);

    printf("Haptic feedback program started. Press Ctrl+C to exit.\n");

    // Main loop to generate and play patterns
    while (!shutdown) {
        // Generate a random number of steps for the pattern
        int num_steps = rand() % 11 + 5; // Between 5 and 15 steps

        // Allocate memory for the duty cycles and durations
        int *duty_cycles = (int *)malloc(num_steps * sizeof(int));
        int *durations = (int *)malloc(num_steps * sizeof(int));

        if (duty_cycles == NULL || durations == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            gpioTerminate();
            return 1;
        }

        // Generate the duty cycles and durations for each step
        for (int i = 0; i < num_steps; i++) {
            duty_cycles[i] = generateRandomDutyCycle();
            durations[i] = generateRandomDuration();
        }

        // Play the pattern
