#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Default calibration values
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_OFFSET 0.0

// Calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Log file name
#define LOG_FILE "weight_log.txt"

// Threshold weight in kg
#define WEIGHT_THRESHOLD 10.0

// Number of readings for startup calibration
#define STARTUP_CALIBRATION_READINGS 100

// Timeout for HX711 read (milliseconds)
#define HX711_TIMEOUT 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Calibration data
static double scale_factor = DEFAULT_SCALE_FACTOR;
static double offset = DEFAULT_OFFSET;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(double weight);
void log_data(double weight);
int load_calibration();
int save_calibration();
void startup_calibration();
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < HX711_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= HX711_TIMEOUT) {
        fprintf(stderr, "Error: HX711 timeout\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage the lock
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Release the lock
    }
}

// Function to log data to a file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.4f\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load calibration data from file
int load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Calibration file not found. Using default values.\n");
        return -1; // Indicate failure to load
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Warning: Invalid calibration data in file. Using default values.\n");
            fclose(fp);
            return -1; // Indicate failure to load
        }
    } else {
        fprintf(stderr, "Warning: Calibration file is empty. Using default values.\n");
        fclose(fp);
        return -1; // Indicate failure to load
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %.4f, offset = %.4f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1; // Indicate failure
    }

    fprintf(fp, "%.4f %.4f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %.4f, offset = %.4f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Function for startup calibration
void startup_calibration() {
    double sum = 0.0;
    for (int i = 0; i < STARTUP_CALIBRATION_READINGS; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 timeout during startup calibration.\n");
            return; // Exit calibration if there's a timeout
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = sum / STARTUP_CALIBRATION_READINGS;
    printf("Startup calibration complete. Offset: %.4f\n", offset);
    save_calibration(); // Save the calibration data
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Release GPIO resources
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is released
    gpioSetMode(SOLENOID_PIN, PI_INPUT); // Set solenoid pin to input
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration data
    if (load_calibration() != 0) {
        // If loading fails, use default values
        printf("Using default calibration values.\n");
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
        gpioTerminate();
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Initially release the lock

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Perform startup calibration
    startup_calibration();

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            double weight = convert_to_weight(raw_value);
            control_solenoid(weight);
            log_data(weight);
            printf("Weight: %.4f kg\n", weight);
        } else {
            fprintf(stderr, "Error: HX711 read failed. Skipping iteration.\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is released
    gpioSetMode(SOLENOID_PIN, PI_INPUT); // Set solenoid pin to input
    fclose(log_file);
    gpioTerminate();

    return 0;
}

