    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY);
    }
    return (low_count >= DEBOUNCE_READINGS) ? 1 : 0; // Return 1 if at least DEBOUNCE_READINGS are LOW
}

