#define LOCK_DURATION_MS 5000
#define WEIGHT_THRESHOLD_KG 5.0
#define TIMEOUT_US 100 // Timeout in microseconds

// Global variables
static volatile int running = 1;
static float calibration_factor = 0.0;

// Function prototypes
int read_hx711();
float calibrate_load_cell();
float calculate_weight(int raw_value, float calibration_factor);
void log_event(float weight);
void control_solenoid(int activate);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the load cell
float calibrate_load_cell() {
    float known_weight_kg;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%f", &known_weight_kg) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1.0;
    }

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: HX711 read error during calibration.\n");
        return -1.0;
    }

    calibration_factor = (float)raw_value / known_weight_kg;

    // Save calibration factor to file
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1.0;
    }

    fprintf(fp, "%f", calibration_factor);
    fclose(fp);

    printf("Calibration complete. Calibration factor: %f\n", calibration_factor);
    return calibration_factor;
}

