    gpioWrite(SOLENOID_PIN, activate);
    if (activate) {
        printf("Solenoid locking...\n");
        gpioDelay(LOCK_DURATION_MS);
        printf("Solenoid unlocking...\n");
    } else {
        printf("Solenoid unlocked.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Ctrl+C pressed. Unlocking solenoid and exiting...\n");
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate();      // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Read calibration factor from file, or calibrate if file doesn't exist
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        printf("Calibration file not found. Calibrating...\n");
        calibration_factor = calibrate_load_cell();
        if (calibration_factor == -1.0) {
            gpioTerminate();
            return 1;
        }
    } else {
        if (fscanf(fp, "%f", &calibration_factor) != 1) {
            fprintf(stderr, "Error: Could not read calibration factor from file.\n");
            fclose(fp);
            gpioTerminate();
            return 1;
        }
        fclose(fp);
        printf("Calibration factor loaded: %f\n", calibration_factor);
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value != -1) {
            float weight = calculate_weight(raw_value, calibration_factor);
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD_KG) {
                log_event(weight);
                control_solenoid(1); // Lock the solenoid
            }
        } else {
            fprintf(stderr, "Error: Failed to read weight.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is unlocked
    gpioTerminate();            // Terminate pigpio
    return 0;
}

