#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 16  // BCM GPIO16
#define RELAY_PIN 20   // BCM GPIO20

// Define log file path
#define LOG_FILE "relay_events.log"

// Global variables
FILE *log_file = NULL;
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_sensor();
int control_relay(int state);
int log_event(int relay_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    exit(0);
}

// Function to read the sensor state
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0; // pigpio functions don't reliably return errors
}

// Function to log relay events
int log_event(int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s Relay is now %s\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring sensor and controlling relay...\n");

    // Main loop
    while (1) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (sensor is active-low)
            if (relay_state == 0) {
                control_relay(1); // Turn relay ON
                log_event(1);
                relay_state = 1;
            }
        } else {
            if (relay_state == 1) {
                control_relay(0); // Turn relay OFF
                log_event(0);
                relay_state = 0;
            }
        }

        gpioDelay(100); // Delay for 100ms
    }

    return 0;
}

