            gpioWrite(BUZZER_PIN, 1); // Activate buzzer
            gpioDelay(2000);          // Wait for 2 seconds
            gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer

            gpioDelay(500); // Debounce delay
        }
        gpioDelay(100); // Check every 100ms
    }

    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

