#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_GPIO 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600
#define MIN_DURATION 1

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, shutting down...\n");
}

int read_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        fprintf(stderr, "Error reading config file\n");
        return -1;
    }

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "\n");

    if (key == NULL || value == NULL) {
        fclose(fp);
        fprintf(stderr, "Invalid config file format\n");
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fclose(fp);
        fprintf(stderr, "Invalid config file format\n");
        return -1;
    }

    char *endptr;
    long dur = strtol(value, &endptr, 10);

    if (*endptr != '\0' || dur < MIN_DURATION || dur > MAX_DURATION) {
        fclose(fp);
        fprintf(stderr, "Invalid duration value\n");
        return -1;
    }

    *duration = (int)dur;
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioWrite(VALVE_GPIO, 0); // Valve off

    int duration;
    if (read_duration(CONFIG_FILE, &duration) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time = time(NULL);
    while (!terminate) {
        if (gpioRead(VALVE_GPIO) == 0) {
            gpioWrite(VALVE_GPIO, 1); // Valve on
            printf("Valve ON\n");
        } else {
            gpioWrite(VALVE_GPIO, 0); // Valve off
            printf("Valve OFF\n");
        }

        time_t current_time = time(NULL);
        double elapsed_time = difftime(current_time, start_time);

        if (elapsed_time >= duration) {
            break;
        }

        sleep(1); // Check every second
    }

    gpioWrite(VALVE_GPIO, 0); // Ensure valve is off
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

