#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

#define MOTOR_A_IN1 22
#define MOTOR_A_IN2 23
#define MOTOR_A_PWM 24

#define MOTOR_B_IN3 26
#define MOTOR_B_IN4 19
#define MOTOR_B_PWM 13

// Define motor speed constants
#define BASE_SPEED 150
#define TURN_SPEED 100

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int gpio_pin);
void set_motor_speed(int motor_a_pwm, int motor_b_pwm);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        terminate = 1;
    }
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active low: 1 if sensor reads LOW
}

// Function to set motor speed and direction
void set_motor_speed(int motor_a_pwm, int motor_b_pwm) {
    gpioPWM(MOTOR_A_PWM, motor_a_pwm);
    gpioPWM(MOTOR_B_PWM, motor_b_pwm);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int motor_a_speed, int motor_b_speed) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", buf, left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to input\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", MOTOR_A_IN1);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", MOTOR_A_IN2);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_A_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", MOTOR_A_PWM);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", MOTOR_B_IN3);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", MOTOR_B_IN4);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output\n", MOTOR_B_PWM);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        if (left_sensor == -1 || middle_sensor == -1 || right_sensor == -1) {
            fprintf(stderr, "Error reading sensor values. Stopping motors.\n");
            set_motor_speed(0, 0);
            log_data(left_sensor, middle_sensor, right_sensor, 0, 0);
            gpioDelay(10000); // 10 ms delay
            continue;
        }

        // Determine motor speeds based on sensor values
        int motor_a_speed = BASE_SPEED;
        int motor_b_speed = BASE_SPEED;

        if (middle_sensor == 1) {
            // Drive straight
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 0) {
            // Turn right
            motor_a_speed = BASE_SPEED;
            motor_b_speed = TURN_SPEED;
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        } else if (right_sensor == 1 && middle_sensor == 0 && left_sensor == 0) {
            // Turn left
            motor_a_speed = TURN_SPEED;
            motor_b_speed = BASE_SPEED;
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        } else {
            // Stop
            set_motor_speed(0, 0);
            log_data(left_sensor, middle_sensor, right_sensor, 0, 0);
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

