        int motor_b_speed = BASE_SPEED;

        if (middle_sensor == 1) {
            // Drive straight
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        } else if (left_sensor == 1 && middle_sensor == 0 && right_sensor == 0) {
            // Turn right
            motor_a_speed = BASE_SPEED;
            motor_b_speed = TURN_SPEED;
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        } else if (right_sensor == 1 && middle_sensor == 0 && left_sensor == 0) {
            // Turn left
            motor_a_speed = TURN_SPEED;
            motor_b_speed = BASE_SPEED;
            set_motor_speed(motor_a_speed, motor_b_speed);
            log_data(left_sensor, middle_sensor, right_sensor, motor_a_speed, motor_b_speed);
        } else {
            // Stop
            set_motor_speed(0, 0);
            log_data(left_sensor, middle_sensor, right_sensor, 0, 0);
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Stop motors
    set_motor_speed(0, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

