#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_bh1750(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read illuminance from BH1750 sensor
float read_bh1750(int i2c_handle) {
    uint8_t buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, HIGH_RES_MODE); // Register address is irrelevant for BH1750
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1.0;
    }

    // Wait for measurement to complete
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to us

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1.0;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(float lux, int relay_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld.%09ld, Lux: %.2f, Relay: %s\n", ts.tv_sec, ts.tv_nsec, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    int result;
    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Grow lamp control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        lux = read_bh1750(i2c_handle);

        if (lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            fprintf(log_file, "Error reading lux value, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        if (lux < LUX_THRESHOLD && relay_state == 0) {
            control_relay(RELAY_GPIO, 1); // Turn on relay
            relay_state = 1;
            log_data(lux, relay_state);
            printf("Lux below threshold, turning on grow lamp.\n");
        } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
            control_relay(RELAY_GPIO, 0); // Turn off relay
            relay_state = 0;
            log_data(lux, relay_state);
            printf("Lux above threshold, turning off grow lamp.\n");
        } else {
            log_data(lux, relay_state);
        }

        gpioDelay(500000); // Check every 0.5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(RELAY_GPIO, 0); // Ensure relay is off on exit
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

