#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int lock_state = 0; // 0: unlocked, 1: locked
    int button_state;
    int servo_pulse_width = 1500; // Initial servo position

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Set servo to initial position
    gpioServo(SERVO_PIN, servo_pulse_width);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        button_state = gpioRead(LOCK_BUTTON_PIN) | (gpioRead(UNLOCK_BUTTON_PIN) << 1);

        if (button_state == 0) {
            // Button pressed (active low)
            if (lock_state == 0) {
                // Unlock
                servo_pulse_width = 2000;
                gpioServo(SERVO_PIN, servo_pulse_width);
                lock_state = 1;
                printf("Door unlocked\n");
            } else {
                // Lock
                servo_pulse_width = 1000;
                gpioServo(SERVO_PIN, servo_pulse_width);
                lock_state = 0;
                printf("Door locked\n");
            }

            gpioDelay(100); // Debounce delay
        }

        // Constrain servo pulse width
        if (servo_pulse_width < 500) servo_pulse_width = 500;
        if (servo_pulse_width > 2500) servo_pulse_width = 2500;
        gpioServo(SERVO_PIN, servo_pulse_width);

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Clean up and terminate
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

