// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    return 0;
}

// Function to activate a vibration motor for a specified duration
void activate_motor(int gpio, int duration_ms)
{
    gpioWrite(gpio, 1); // Turn the motor on
    gpioDelay(duration_ms * 1000); // Delay for the specified duration
    gpioWrite(gpio, 0); // Turn the motor off
}

// Function to run the haptic feedback sequence
void run_haptic_feedback()
{
    while (!terminate)
    {
        // Activate motor 1
        activate_motor(MOTOR1_GPIO, 200);

        // Activate motor 2
        activate_motor(MOTOR2_GPIO, 300);
    }
}

// Function to cleanup GPIO resources before exiting
void cleanup_gpio()
{
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Run the haptic feedback sequence
    run_haptic_feedback();

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

