#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ port
#define ZMQ_PORT 5555

// Define alarm duration (seconds)
#define ALARM_DURATION 1

// Global variables for GPIO and ZeroMQ
struct gpiod_chip *chip;
struct gpiod_line *sound_sensor_line;
struct gpiod_line *alarm_led_line;
void *context = NULL;
void *publisher = NULL;
void *subscriber = NULL;

// Function prototypes
int read_sound_sensor(struct gpiod_line *line);
int publish_sound_alert(void *socket, const char *topic, const char *message);
int subscribe_to_topic(void *socket, const char *topic);
void trigger_alarm(struct gpiod_line *line);
void cleanup(int signal);

// Signal handler for clean shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }

    // Release GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close ZeroMQ sockets and context
    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    exit(0);
}

// Function to read the sound sensor
int read_sound_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading sound sensor");
        return -1;
    }
    return value;
}

// Function to publish a sound alert
int publish_sound_alert(void *socket, const char *topic, const char *message) {
    zmq_msg_t zmq_message;
    int rc;

    zmq_msg_init_size(&zmq_message, strlen(message));
    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    rc = zmq_msg_send(&zmq_message, socket, 0);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        perror("Error sending message");
        return -1;
    }

    return 0;
}

// Function to subscribe to a topic
int subscribe_to_topic(void *socket, const char *topic) {
    zmq_msg_t zmq_message;
    int rc;

    zmq_msg_init_size(&zmq_message, strlen(topic));
    memcpy(zmq_msg_data(&zmq_message), topic, strlen(topic));

    rc = zmq_msg_send(&zmq_message, socket, ZMQ_SNDMORE);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        perror("Error sending subscribe message");
        return -1;
    }

    zmq_msg_init_size(&zmq_message, 0); // Empty message for subscription
    rc = zmq_msg_send(&zmq_message, socket, 0);
    zmq_msg_close(&zmq_message);

    if (rc == -1) {
        perror("Error sending empty message for subscription");
        return -1;
    }

    return 0;
}

// Function to trigger the alarm
void trigger_alarm(struct gpiod_line *line) {
    int rc = gpiod_line_set_value(line, 1); // Set GPIO HIGH
    if (rc < 0) {
        perror("Error setting alarm LED HIGH");
        return;
    }
    sleep(ALARM_DURATION);
    rc = gpiod_line_set_value(line, 0); // Set GPIO LOW
    if (rc < 0) {
        perror("Error setting alarm LED LOW");
    }
}

int main(int argc, char *argv[]) {
    const char *mode = NULL;

    // Check command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor|alarm_node\n");
        return 1;
    }

    mode = argv[1];

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    sound_sensor_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Error getting sound sensor GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    alarm_led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Error getting alarm LED GPIO line");
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "sound_sensor";

    if (gpiod_line_request(sound_sensor_line, &config, 0) < 0) {
        perror("Error requesting sound sensor GPIO line");
        gpiod_line_release(alarm_led_line);
        gpiod_line_release(sound_sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    config.consumer = "alarm_led";
    if (gpiod_line_request(alarm_led_line, &config, 0) < 0) {
        perror("Error requesting alarm LED GPIO line");
        gpiod_line_release(sound_sensor_line);
        gpiod_line_release(alarm_led_line);
