#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR_BASE 0x23
#define BH1750_CMD_HIGH_RES 0x20
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SLEEP_SECONDS 1

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to open an I2C device
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// Function to write a byte to an I2C device
int i2c_write(int fd, int addr, const unsigned char *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x for write: %s\n", addr, strerror(errno));
        return -1;
    }
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C device
int i2c_read(int fd, int addr, unsigned char *buf, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x for read: %s\n", addr, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750 sensor
float read_bh1750(int fd, int addr) {
    unsigned char buf[2];
    unsigned char cmd = BH1750_CMD_HIGH_RES;

    if (i2c_write(fd, addr, &cmd, 1) < 0) {
        return -1.0; // Indicate error
    }

    usleep(180000); // Wait for conversion (180ms)

    if (i2c_read(fd, addr, buf, 2) < 0) {
        return -1.0; // Indicate error
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];
    return (float)raw_value / 1.2;
}

// Function to format sensor data into a string
char* format_sensor_data(sensor_data_t data, char* buffer, size_t buffer_size) {
    snprintf(buffer, buffer_size, "%d,%.2f", data.sensor_id, data.lux);
    return buffer;
}

// Function to format all sensor data into a comma-separated string
char* format_all_sensor_data(sensor_data_t sensor_data[], int num_sensors, char* buffer, size_t buffer_size) {
    buffer[0] = '\0'; // Initialize as empty string
    for (int i = 0; i < num_sensors; i++) {
        char sensor_str[50];
        format_sensor_data(sensor_data[i], sensor_str, sizeof(sensor_str));
        strcat(buffer, sensor_str);
        if (i < num_sensors - 1) {
            strcat(buffer, ";");
        }
    }
    return buffer;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting multicast TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Close socket
    close(sockfd);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Sensor data array
    sensor_data_t sensor_data[4];
    for (int i = 0; i < 4; i++) {
        sensor_data[i].sensor_id = i + 1;
        sensor_data[i].lux = -1.0; // Initialize with error value
    }

    // Main loop
    while (!terminate) {
        char data_string[256];

        // Read sensor data
        for (int i = 0; i < 4; i++) {
            int addr = BH1750_ADDR_BASE + i;
            sensor_data[i].lux = read_bh1750(i2c_open(I2C_BUS, addr), addr);
            if (sensor_data[i].lux < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
                sensor_data[i].lux = -1.0; // Keep error value
            }
        }

        // Format sensor data
        format_all_sensor_data(sensor_data, 4, data_string, sizeof(data_string));

        // Send UDP multicast
        if (send_udp_multicast(data_string) < 0) {
            fprintf(stderr, "Error sending UDP multicast\n");
        }

        // Sleep for 1 second
        sleep(SLEEP_SECONDS);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    for (int i = 0; i < 4; i++) {
        close(i2c_open(I2C_BUS, BH1750_ADDR_BASE + i));
    }

    return 0;
}

