#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_F1DATAH 0x60
#define AS7341_F1DATAL 0x61
#define AS7341_F2DATAH 0x62
#define AS7341_F2DATAL 0x63
#define AS7341_F3DATAH 0x64
#define AS7341_F3DATAL 0x65
#define AS7341_F4DATAH 0x66
#define AS7341_F4DATAL 0x67
#define AS7341_F5DATAH 0x68
#define AS7341_F5DATAL 0x69
#define AS7341_F6DATAH 0x6A
#define AS7341_F6DATAL 0x6B
#define AS7341_F7DATAH 0x6C
#define AS7341_F7DATAL 0x6D
#define AS7341_F8DATAH 0x6E
#define AS7341_F8DATAL 0x6F
#define AS7341_CDATAH 0x70
#define AS7341_CDATAL 0x71
#define AS7341_NIRDATAH 0x72
#define AS7341_NIRDATAL 0x73

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int i2c_read_byte(int reg);
int i2c_write_byte(int reg, int val);
int as7341_init();
int read_spectral_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir);
float calculate_lux(uint16_t *data);
int log_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir, float lux);
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int reg) {
    int result = i2c_smbus_read_byte_data(i2c_fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// I2C write byte function
int i2c_write_byte(int reg, int val) {
    int result = i2c_smbus_write_byte_data(i2c_fd, reg, val);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, val, result);
        return -1;
    }
    return 0;
}

// AS7341 initialization function
int as7341_init() {
    int who_am_i = i2c_read_byte(AS7341_WHO_AM_I);
    if (who_am_i != 0x19) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x19\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_byte(AS7341_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Error powering on sensor\n");
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_write_byte(AS7341_CFG6, 0x00) != 0) {
        fprintf(stderr, "Error configuring SMUX\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_byte(AS7341_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Error enabling spectral measurement\n");
        return -1;
    }

    return 0;
}

// Function to read spectral data
int read_spectral_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir) {
    int result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F1DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F1 data: %d\n", result);
        return -1;
    }
    *f1 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F2DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F2 data: %d\n", result);
        return -1;
    }
    *f2 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F3DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F3 data: %d\n", result);
        return -1;
    }
    *f3 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F4DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F4 data: %d\n", result);
        return -1;
    }
    *f4 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F5DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F5 data: %d\n", result);
        return -1;
    }
    *f5 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F6DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F6 data: %d\n", result);
        return -1;
    }
    *f6 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F7DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F7 data: %d\n", result);
        return -1;
    }
    *f7 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_F8DATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading F8 data: %d\n", result);
        return -1;
    }
    *f8 = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_CDATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading Clear data: %d\n", result);
        return -1;
    }
    *clear = (uint16_t)result;

    result = i2c_smbus_read_word_data(i2c_fd, AS7341_NIRDATAH);
    if (result < 0) {
        fprintf(stderr, "Error reading NIR data: %d\n", result);
        return -1;
    }
    *nir = (uint16_t)result;

    return 0;
}

// Function to calculate lux approximation
float calculate_lux(uint16_t *data) {
    // Simple lux calculation (replace with a more accurate formula if needed)
    return (float)(data[0] + data[1] + data[2] + data[3] + data[4] + data[5] + data[6] + data[7] + data[8] + data[9]) / 10.0;
}

// Function to log data to a CSV file
int log_data(uint16_t *f1, uint16_t *f2, uint16_t *f3, uint16_t *f4, uint16_t *f5, uint16_t *f6, uint16_t *f7, uint16_t *f8, uint16_t *clear, uint16_t *nir, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, f1[0], f1[1], f2[0], f2[1], f3[0], f3[1], f4[0], f4[1], f5[0], f5[1], f6[0], f6[1], f7[0], f7[1], f8[0], f8[1], clear[0], clear[1], nir[0], nir[1], lux);

    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, exiting...\n", sig);
    stop_flag = 1;
}

int main() {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
    float lux;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %d\n", i2c_fd);
        close(i2c_fd);
        return 1;
    }

    // Initialize AS7341 sensor
    if (as7341_init() != 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    // Main loop
    while (!stop_flag) {
        // Read spectral data
        if (read_spectral_data(&f1, &f2, &f3, &f4, &f5, &f6, &f7, &f8, &clear, &nir) == 0) {
            // Calculate lux approximation
            lux = calculate_lux(&f1);

            // Log data
            if (log_data(&f1, &f2, &f3, &f4, &f5, &f6, &f7, &f8, &clear, &nir, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

