#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define DEFAULT_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"

int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int handle, int16_t *x_raw, int16_t *y_raw, int16_t *z_raw);
void convert_to_g(int16_t x_raw, int16_t y_raw, int16_t z_raw, sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t data);
void log_error(const char *message);
void signal_handler(int signal);

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *filename = DEFAULT_FILENAME;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(i2c_address);
    if (i2c_handle < 0) {
        log_error("I2C initialization failed");
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        perror("Error opening data file");
        log_error("Failed to open data file");
        i2cClose(i2c_handle);
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    }
    rewind(data_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    sensor_data_t sensor_data;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &x_raw, &y_raw, &z_raw) == 0) {
            // Convert to g
            convert_to_g(x_raw, y_raw, z_raw, &sensor_data);

            // Log data
            if (log_data(data_file, sensor_data) != 0) {
                log_error("Failed to log data");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        // Wait for the specified interval
        gpioDelay(interval * 1000000); // Convert seconds to microseconds
    }

    return 0;
}

// Initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(I2C_BUS, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor_data(int handle, int16_t *x_raw, int16_t *y_raw, int16_t *z_raw) {
    char buffer[6];
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, 0x28, buffer, 6);
        if (result == 6) {
            *x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", 4 - retries, result);
            log_error("I2C read failed");
            gpioDelay(10000); // 10 ms backoff
            retries--;
        }
    }

    log_error("I2C read failed after multiple retries");
    return -1; // Failure
}

// Convert raw data to g
void convert_to_g(int16_t x_raw, int16_t y_raw, int16_t z_raw, sensor_data_t *data) {
    data->x_g = (float)x_raw * 0.000244;
    data->y_g = (float)y_raw * 0.000244;
    data->z_g = (float)z_raw * 0.000244;
}

// Log data to CSV file
int log_data(FILE *fp, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x_g, data.y_g, data.z_g) < 0) {
        perror("Error writing to data file");
        log_error("Failed to write to data file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Log errors to error log file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (data_file != NULL) {
        fclose(data_file);
    }

    if (error_file != NULL) {
        fclose(error_file);
    }

    gpioTerminate();
    exit(0);
}

