#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
int udp_socket = -1;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    keep_running = 0;
}

int i2c_write(int fd, unsigned char addr, unsigned char *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("I2C_SLAVE failed");
        return -1;
    }
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char addr, unsigned char *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("I2C_SLAVE failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

float read_bh1750(int fd) {
    unsigned char data[2];
    if (i2c_write(fd, BH1750_ADDR, (unsigned char[]){CONTINUOUS_HIGH_RES_MODE}, 1) < 0) {
        fprintf(stderr, "Failed to set continuous high-res mode\n");
        return -1.0f;
    }
    usleep(200000); // Wait for measurement (at least 180ms)
    if (i2c_read(fd, BH1750_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to read data\n");
        return -1.0f;
    }

    unsigned int raw = (data[0] << 8) | data[1];
    return (float)raw / 1.2f;
}

int send_udp_multicast(float lux) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto failed");
        return -1;
    }
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create socket");
        close(i2c_fd);
        return 1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void*)&TTL, sizeof(TTL)) < 0) {
        perror("setsockopt failed");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    while (keep_running) {
        float lux = read_bh1750(i2c_fd);
        if (lux >= 0) {
            if (send_udp_multicast(lux) < 0) {
                fprintf(stderr, "Failed to send UDP multicast\n");
            }
        } else {
            fprintf(stderr, "Failed to read BH1750 sensor\n");
        }
        sleep(1);
    }

    close(i2c_fd);
    close(udp_socket);
    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

