    if (i2c_read(fd, BH1750_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to read data\n");
        return -1.0f;
    }

    unsigned int raw = (data[0] << 8) | data[1];
    return (float)raw / 1.2f;
}

int send_udp_multicast(float lux) {
