#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_MS (TIMEOUT_SEC * 1000)
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int configure_uart(int fd) {
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr failed");
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 0; // Wait for no time (in deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr failed");
        return -1;
    }

    return 0;
}

int read_uart_data(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    ssize_t bytes_read;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("select() failed");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        fprintf(stderr, "UART read timeout\n");
        return 0; // Indicate timeout
    } else {
        // Data is available
        bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("read() failed");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

int parse_data(const char *data, size_t data_len, long *timestamp, float *range) {
    char *token;
    char *rest = data;

    // Get timestamp
    token = strtok_r(rest, ",", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid timestamp format\n");
        return -1;
    }
    *timestamp = strtol(token, NULL, 10);
    if (*timestamp == 0 && errno == ERANGE) {
        fprintf(stderr, "Error: Timestamp out of range\n");
        return -1;
    }

    // Get range
    token = strtok_r(rest, "\n", &rest);
    if (token == NULL) {
        fprintf(stderr, "Error: Invalid range format\n");
        return -1;
    }
    char *endptr;
    *range = strtof(token, &endptr);
    if (*endptr != '\0' && errno == ERANGE) {
        fprintf(stderr, "Error: Range out of range\n");
        return -1;
    }

    return 0;
}

int main() {
    char buffer[BUFFER_SIZE];
    long timestamp;
    float range;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[20];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (uart_fd == -1) {
        perror("open() failed");
        return EXIT_FAILURE;
    }

    if (configure_uart(uart_fd) == -1) {
        close(uart_fd);
        return EXIT_FAILURE;
    }

    printf("UART configured successfully. Monitoring data...\n");

    while (program_running) {
        ssize_t bytes_read = read_uart_data(uart_fd, buffer, BUFFER_SIZE);

        if (bytes_read > 0) {
            if (parse_data(buffer, bytes_read, &timestamp, &range) == 0) {
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
                printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
            } else {
                fprintf(stderr, "Error parsing data: %s\n", buffer);
            }
        } else if (bytes_read == 0) {
            // Timeout occurred, continue to the next iteration
            continue;
        } else {
            // Error reading from UART
            fprintf(stderr, "Error reading from UART\n");
            break;
        }
    }

    close(uart_fd);
    printf("UART closed.\n");

    return EXIT_SUCCESS;
}

