// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port path
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Global variable for the serial file descriptor
int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void emergency_stop(void);
void signal_handler(int signal);
int setup_serial_port(void);
void close_serial_port(void);

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to handle emergency stop
void emergency_stop(void) {
    const char *message = "EMERGENCY STOP!\n";
    if (serial_fd != -1) {
        ssize_t bytes_written = write(serial_fd, message, strlen(message));
        if (bytes_written < 0) {
            fprintf(stderr, "Error writing to serial port: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Serial port not open. Cannot send emergency stop message.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Cleaning up and exiting...\n", signal);
    close_serial_port();
    gpioTerminate();
    exit(0);
}

// Function to set up the serial port
int setup_serial_port(void) {
    serial_fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %s\n", SERIAL_PORT, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(serial_fd);
        serial_fd = -1;
        return -1;
    }

    return 0;
}

// Function to close the serial port
void close_serial_port(void) {
    if (serial_fd != -1) {
        close(serial_fd);
        serial_fd = -1;
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the serial port
    if (setup_serial_port() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_value, middle_value, right_value);

        // Check for emergency stop condition
        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            emergency_stop();
        }

        // Delay for 100ms (10Hz)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    return 0;
}

